local STARTUP_DUPLICATE_GUARD_HASH = 0x17E3FFB8

local function startup_duplicate_guard_log(message)
    if Logger and Logger.LogInfo then
        Logger.LogInfo("[Startup] " .. tostring(message))
    elseif print then
        print("[Startup] " .. tostring(message))
    end
end

if FeatureMgr and FeatureMgr.GetFeature then
    local existingStartupFeature = FeatureMgr.GetFeature(STARTUP_DUPLICATE_GUARD_HASH)
    if existingStartupFeature ~= nil then
        startup_duplicate_guard_log("Duplicate copy blocked. Startup is already running. Unload either the subscribed Startup script or the local Startup.lua copy.")
        return
    end
end

