function startup.normalize_edition_code(value)
    local edition = string.upper(tostring(value or "")):gsub("^%s+", ""):gsub("%s+$", "")
    edition = edition:gsub("BATTLEYE", "BE"):gsub("%s+", " ")
    return edition
end

function startup.get_active_edition_info()
    local edition = ""
    if Cherax and Cherax.GetEdition then
        edition = startup.normalize_edition_code(Cherax.GetEdition())
    end

    if edition == "LE" then return edition, "Legacy", false, true end
    if edition == "EE" then return edition, "Enhanced", false, true end
    if edition == "LE BE" then return edition, "Legacy", true, true end
    if edition == "EE BE" then return edition, "Enhanced", true, true end

    return edition ~= "" and edition or "Unknown", "Unknown", nil, false
end

function startup.is_prime_active_edition()
    local _, _, is_prime, recognized = startup.get_active_edition_info()
    return recognized and is_prime == true
end

function startup.is_enhanced_active_edition()
    local edition = startup.get_active_edition_info()
    return edition == "EE" or edition == "EE BE"
end

function startup.default_battleye_auto_block()
    return not startup.is_prime_active_edition()
end

function startup.default_country_filter_enabled()
    return not startup.is_prime_active_edition()
end

function startup.prime_conservative_auto_removal()
    return startup.is_prime_active_edition()
end

