-- Matchmaking Region scan lab.
-- RGGLI / RGGLIE exact signatures and RIP offsets come from the archived K-Script source.
-- Relaxed variants below are intentionally marked experimental: they only loosen bytes from
-- those known signatures and are accepted only when the RIP target returns the same valid
-- region value (0-7) twice. This helps find small build drift without blindly trusting a hit.
startup.region_scan_patterns = {
    { name = "RGGLI Source", family = "Legacy", confidence = "source", pattern = "37 72 EC 17 72 2D ? ? ? ? ? 64 09", offset = 16 },
    { name = "RGGLI Relaxed A", family = "Legacy", confidence = "experimental", pattern = "37 72 EC ? 72 2D ? ? ? ? ? 64 09", offset = 16 },
    { name = "RGGLI Relaxed B", family = "Legacy", confidence = "experimental", pattern = "37 72 ? ? 72 2D ? ? ? ? ? 64 09", offset = 16 },
    { name = "RGGLI Relaxed C", family = "Legacy", confidence = "experimental", pattern = "37 72 EC 17 ? ? ? ? ? ? ? 64 09", offset = 16 },
    { name = "RGGLI Relaxed D", family = "Legacy", confidence = "experimental", pattern = "37 72 EC 17 72 2D ? ? ? ? ? ? ?", offset = 16 },
    { name = "RGGLI Relaxed E", family = "Legacy", confidence = "experimental", pattern = "? 72 EC 17 72 2D ? ? ? ? ? 64 09", offset = 16 },
    { name = "RGGLIE Source", family = "Enhanced", confidence = "source", pattern = "8C 2D 49 ? ? ? ? 82 23 F5 82 23 FA E2 ? ? ? ? 28 C4 18 7D", offset = 3 },
    { name = "RGGLIE Relaxed A", family = "Enhanced", confidence = "experimental", pattern = "8C 2D 49 ? ? ? ? 82 23 F5 ? ? ? E2 ? ? ? ? 28 C4 18 7D", offset = 3 },
    { name = "RGGLIE Relaxed B", family = "Enhanced", confidence = "experimental", pattern = "8C 2D 49 ? ? ? ? 82 23 F5 82 23 FA E2 ? ? ? ? ? ? ? ?", offset = 3 }
}
startup.region_scan_modules = { "GTA5.exe", "GTA5", "GTA5.exe+0", "GTA5_Enhanced.exe", "GTA5_Enhanced" }
