-- ═══════════════════════════════════════════════════════════════════════════════════
-- utility helpers
-- note: small shared helpers keep the runtime paths readable.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.ensure_save_dir()
    if not FileMgr or not FileMgr.CreateDir then return false end
    FileMgr.CreateDir(startup.lua_dir)
    FileMgr.CreateDir(startup.lua_content_dir)
    FileMgr.CreateDir(startup.storage_dir or startup.save_dir)
    FileMgr.CreateDir(startup.config_dir)
    FileMgr.CreateDir(startup.players_dir)
    FileMgr.CreateDir(startup.diagnostics_dir)
    FileMgr.CreateDir(startup.support_dir)
    return true
end

function startup.raw_file_exists(path)
    local file = io and io.open and io.open(tostring(path or ""), "rb") or nil
    if file then file:close(); return true end
    return false
end

function startup.raw_copy_file(sourcePath, targetPath)
    sourcePath, targetPath = tostring(sourcePath or ""), tostring(targetPath or "")
    if sourcePath == "" or targetPath == "" or not startup.raw_file_exists(sourcePath) then return false end
    local input = io.open(sourcePath, "rb")
    if not input then return false end
    local content = input:read("*a") or ""
    input:close()
    local output = io.open(targetPath, "wb")
    if not output then return false end
    output:write(content)
    output:close()
    return true
end

function startup.raw_remove_file(path)
    path = tostring(path or "")
    if path == "" then return false end
    local ok = direct_call(function() os.remove(path) end)
    if FileMgr and FileMgr.DeleteFile then direct_call(function() FileMgr.DeleteFile(path) end) end
    return ok
end

function startup.migrate_legacy_storage()
    startup.ensure_save_dir()
    local migrated = {}

    local function move_if_needed(sourcePath, targetPath, label, deleteSource)
        sourcePath, targetPath = tostring(sourcePath or ""), tostring(targetPath or "")
        if sourcePath == "" or targetPath == "" or sourcePath == targetPath or not startup.raw_file_exists(sourcePath) then return false end
        if not startup.raw_file_exists(targetPath) then
            if not startup.raw_copy_file(sourcePath, targetPath) then return false end
            migrated[#migrated + 1] = tostring(label or targetPath)
        end
        if deleteSource ~= false and startup.raw_file_exists(targetPath) then startup.raw_remove_file(sourcePath) end
        return true
    end

    -- Startup.ini is kept at the Startup root. If Cherax creates a fresh legacy copy,
    -- prefer that current file over an older stored copy, then remove the duplicate.
    local function move_startup_ini(sourcePath)
        sourcePath = tostring(sourcePath or "")
        if sourcePath == "" or sourcePath == startup.StartupIniFile or not startup.raw_file_exists(sourcePath) then return false end
        if not startup.raw_copy_file(sourcePath, startup.StartupIniFile) then return false end
        startup.raw_remove_file(sourcePath)
        migrated[#migrated + 1] = "Startup.ini"
        return true
    end
    move_startup_ini(startup.legacy_startup_ini_file)
    move_startup_ini(startup.legacy_startup_ini_content_file)
    move_startup_ini(startup.legacy_startup_ini_root_file)

    -- Build 051 used a flat Startup folder. Build 052 sorts those files into subfolders.
    local flat = startup.storage_dir
    local flatPairs = {
        { flat .. "\\config.lua", startup.config_file, "Config\\config.lua" },
        { flat .. "\\saved_players.lua", startup.RidHistoryFile, "Players\\saved_players.lua" },
        { flat .. "\\player_events.log", startup.RidEventLogFile, "Players\\player_events.log" },
        { flat .. "\\support_events.log", startup.SupportEventsFile, "Diagnostics\\support_events.log" },
        { flat .. "\\startup_boot_trace.log", startup.BootTraceFile, "Diagnostics\\startup_boot_trace.log" },
        { flat .. "\\startup_boot_status.txt", startup.BootStatusFile, "Diagnostics\\startup_boot_status.txt" },
        { flat .. "\\startup_last_checkpoint.txt", startup.LastCheckpointFile, "Diagnostics\\startup_last_checkpoint.txt" },
        { flat .. "\\SUPPORT_INFO.txt", startup.SupportInfoFile, "Support\\SUPPORT_INFO.txt" },
        { flat .. "\\UPLOAD_SUPPORT.txt", startup.SupportUploadInfoFile, "Support\\UPLOAD_SUPPORT.txt" },
        { startup.lua_dir .. "\\Startup_Support.zip", startup.SupportZipPath, "Support\\Startup_Support.zip" },
        { startup.lua_dir .. "\\Startup_Support.tmp", startup.SupportZipTempPath, "Support\\Startup_Support.tmp" },
        { startup.lua_dir .. "\\Startup_Support.previous", startup.SupportZipBackupPath, "Support\\Startup_Support.previous" }
    }
    for _, pair in ipairs(flatPairs) do move_if_needed(pair[1], pair[2], pair[3], true) end

    -- Prefer the old primary config, then the old fallback config, only when no organized config exists.
    if not startup.raw_file_exists(startup.config_file) then
        if not move_if_needed(startup.legacy_config_file, startup.config_file, "Config\\config.lua", true) then
            move_if_needed(startup.legacy_fallback_config_file, startup.config_file, "Config\\config.lua", true)
        end
    end
    if startup.raw_file_exists(startup.config_file) then
        startup.raw_remove_file(startup.legacy_config_file)
        startup.raw_remove_file(startup.legacy_fallback_config_file)
    end

    local legacyPairs = {
        { startup.legacy_save_dir .. "\\SUPPORT_INFO.txt", startup.SupportInfoFile, "Support\\SUPPORT_INFO.txt" },
        { startup.legacy_save_dir .. "\\UPLOAD_SUPPORT.txt", startup.SupportUploadInfoFile, "Support\\UPLOAD_SUPPORT.txt" },
        { startup.legacy_save_dir .. "\\support_events.log", startup.SupportEventsFile, "Diagnostics\\support_events.log" },
        { startup.legacy_save_dir .. "\\startup_boot_trace.log", startup.BootTraceFile, "Diagnostics\\startup_boot_trace.log" },
        { startup.legacy_save_dir .. "\\startup_boot_status.txt", startup.BootStatusFile, "Diagnostics\\startup_boot_status.txt" },
        { startup.legacy_save_dir .. "\\startup_last_checkpoint.txt", startup.LastCheckpointFile, "Diagnostics\\startup_last_checkpoint.txt" },
        { startup.legacy_rid_history_file, startup.RidHistoryFile, "Players\\saved_players.lua" },
        { startup.legacy_rid_history_local_file, startup.RidHistoryFile, "Players\\saved_players.lua" },
        { startup.legacy_save_dir .. "\\player_events.log", startup.RidEventLogFile, "Players\\player_events.log" }
    }
    for _, pair in ipairs(legacyPairs) do move_if_needed(pair[1], pair[2], pair[3], true) end

    -- Exactly one cached logo name is kept at Startup\Public_Urinal.png.
    move_if_needed(startup.legacy_public_urinal_icon_path, startup.public_urinal_icon_path, "Public_Urinal.png", true)
    local oldContentLogo = startup.legacy_save_dir .. "\\Public_Urinal.png"
    move_if_needed(oldContentLogo, startup.public_urinal_icon_path, "Public_Urinal.png", true)
    if startup.raw_file_exists(startup.public_urinal_icon_path) then
        startup.raw_remove_file(startup.legacy_public_urinal_icon_path)
        startup.raw_remove_file(oldContentLogo)
    end

    if #migrated > 0 then
        startup.log("Startup storage organized under Cherax\\Lua\\Startup: " .. table.concat(migrated, ", "))
    end
    return true
end

function startup.stow_startup_ini()
    startup.ensure_save_dir()
    local sources = {
        startup.legacy_startup_ini_file,
        startup.legacy_startup_ini_content_file,
        startup.legacy_startup_ini_root_file
    }
    for _, sourcePath in ipairs(sources) do
        sourcePath = tostring(sourcePath or "")
        if sourcePath ~= "" and sourcePath ~= startup.StartupIniFile and startup.raw_file_exists(sourcePath) then
            if startup.raw_copy_file(sourcePath, startup.StartupIniFile) then
                startup.raw_remove_file(sourcePath)
                if startup.support_log_event_quiet then
                    startup.support_log_event_quiet("STARTUP_INI_STOWED", "source=" .. sourcePath .. " | target=" .. tostring(startup.StartupIniFile))
                end
            end
        end
    end
end

function startup.log(msg)
    if Logger and Logger.LogInfo then
        Logger.LogInfo("[" .. startup.name .. "] " .. tostring(msg))
    elseif Logger and Logger.Log then
        Logger.Log(eLogColor.LIGHTCYAN, startup.name, tostring(msg))
    end
end

function startup.log_colored(msg, kind)
    local text = tostring(msg or "")
    if Logger and Logger.Log and eLogColor then
        local color = nil
        if kind == "success" then color = eLogColor.LIGHTGREEN or eLogColor.LIGHTCYAN
        elseif kind == "error" then color = eLogColor.LIGHTRED
        elseif kind == "warning" then color = eLogColor.YELLOW or eLogColor.LIGHTCYAN
        else color = eLogColor.LIGHTCYAN end
        if color ~= nil then
            local sender = startup.cleanBootConsoleActive == true and "" or startup.name
            local ok = direct_call(function() Logger.Log(color, sender, text) end)
            if ok then return end
        end
    end
    startup.log(text)
end

function startup.log_verbose(msg, kind)
    if startup.s and startup.s.verboseStartupLogs == true then
        startup.log_colored(msg, kind or "info")
    end
end

-- Always uses Startup as the sender, even while the clean boot banner is active.
-- Reserved for short user-facing status lines that must never merge into raw output.
function startup.log_named_colored(msg, kind)
    local text = tostring(msg or "")
    if Logger and Logger.Log and eLogColor then
        local color = nil
        if kind == "success" then color = eLogColor.LIGHTGREEN or eLogColor.LIGHTCYAN
        elseif kind == "error" then color = eLogColor.LIGHTRED
        elseif kind == "warning" then color = eLogColor.YELLOW or eLogColor.LIGHTCYAN
        else color = eLogColor.LIGHTCYAN end
        if color ~= nil then
            local ok = pcall(function() Logger.Log(color, startup.name or "Startup", text) end)
            if ok then return true end
        end
    end
    startup.log(text)
    return false
end

function startup.console_raw(text, kind)
    local value = tostring(text or "")
    if Logger and Logger.Log and eLogColor then
        local color = nil
        if kind == "success" then color = eLogColor.LIGHTGREEN or eLogColor.GREEN or eLogColor.LIGHTCYAN or eLogColor.CYAN
        elseif kind == "error" then color = eLogColor.LIGHTRED or eLogColor.RED
        elseif kind == "warning" then color = eLogColor.YELLOW or eLogColor.LIGHTCYAN or eLogColor.CYAN
        else color = eLogColor.LIGHTCYAN or eLogColor.CYAN end
        if color ~= nil then
            -- Cherax may silently discard colored logger calls that use an empty
            -- sender. Always provide Startup as the sender so banners and summary
            -- lines are guaranteed to appear in the visible console.
            local ok = pcall(function()
                Logger.Log(color, startup.name or "Startup", value)
            end)
            if ok then return true end
        end
    end
    startup.log(value)
    return false
end

function startup.toast_quiet(msg, ms)
    ms = ms or 4500
    if GUI and GUI.AddToast then GUI.AddToast(startup.name, tostring(msg), ms) end
    startup.s.lastStatus = tostring(msg)
end

function startup.console_raw_block(text)
    local value = tostring(text or "")
    local printed = false

    local rawMethods = {
        function()
            if Logger and Logger.LogRaw then Logger.LogRaw(value); return true end
        end,
        function()
            if Logger and Logger.Raw then Logger.Raw(value); return true end
        end,
        function()
            if Logger and Logger.LogInfoRaw then Logger.LogInfoRaw(value); return true end
        end,
        function()
            if print then print(value); return true end
        end
    }

    for _, method in ipairs(rawMethods) do
        local ok, result = pcall(method)
        if ok and result == true then
            printed = true
            break
        end
    end

    if printed then return true end
    startup.console_raw("\n" .. value, "info")
    return false
end

function startup.print_console_banner()
    if startup.consoleBannerPrinted == true then return end
    startup.consoleBannerPrinted = true

    local separator = "============================================================"
    local logo = [[███████╗████████╗ █████╗ ██████╗ ████████╗██╗   ██╗██████╗ 
██╔════╝╚══██╔══╝██╔══██╗██╔══██╗╚══██╔══╝██║   ██║██╔══██╗
███████╗   ██║   ███████║██████╔╝   ██║   ██║   ██║██████╔╝
╚════██║   ██║   ██╔══██║██╔══██╗   ██║   ██║   ██║██╔═══╝ 
███████║   ██║   ██║  ██║██║  ██║   ██║   ╚██████╔╝██║     
╚══════╝   ╚═╝   ╚═╝  ╚═╝╚═╝  ╚═╝   ╚═╝    ╚═════╝ ╚═╝     ]]

    -- Startup uses a distinct terminal palette while following DriftGod's
    -- proven raw ANSI approach: violet dividers, aqua identity, gold tagline,
    -- blue community details, green release details, and clean white labels.
    local violet = "\27[38;5;93m"
    local aqua = "\27[38;5;45m"
    local gold = "\27[38;5;220m"
    local blue = "\27[38;5;39m"
    local green = "\27[38;5;82m"
    local white = "\27[97m"
    local reset = "\27[0m"

    local banner = "\n\n"
        .. violet .. separator .. "\n\n"
        .. aqua .. logo .. "\n\n"
        .. gold .. "Startup - From Launch to Lobby." .. "\n\n"
        .. white .. "Developed By: " .. violet .. tostring(startup.developer or "Public_Urinal") .. "\n"
        .. white .. "Discord: " .. blue .. tostring(startup.console_discord or "animusx1337") .. "\n\n"
        .. white .. "Version: " .. green .. tostring(startup.console_version or "v1.0.11") .. "\n"
        .. white .. "Build: " .. gold .. tostring(startup.build_number or "Unknown") .. "\n"
        .. white .. "Last Updated: " .. aqua .. tostring(startup.build_date or "Unknown") .. "\n\n"
        .. violet .. separator .. "\n\n"
        .. green .. "Happy Gaming " .. violet .. "ツ" .. reset .. "\n"

    startup.console_raw_block(banner)
end

function startup.print_readiness_summary_block(force)
    if startup.consoleBannerPrinted ~= true then return false end

    local enhanced = startup.is_enhanced_active_edition()
    local alreadyPrinted = startup.consoleNatSummaryPrinted == true
        and ((not enhanced) or startup.consoleRegionSummaryPrinted == true)
    if alreadyPrinted and force ~= true then return true end

    local state = startup.nat_scan or {}
    local found = tonumber(state.lastFoundCount or 0) or 0
    local total = tonumber(state.lastTotalCount or 0) or 0
    if total <= 0 then return false end

    if enhanced then
        local cache = startup.advertise_region_cache or {}
        if not cache.feature and not cache.hash then return false end
    end

    local gold = "\27[38;5;220m"
    local green = "\27[38;5;82m"
    local red = "\27[38;5;196m"
    local reset = "\27[0m"
    local resultColor = found > 0 and green or red

    local block = gold .. "NAT Patterns... found " .. resultColor
        .. tostring(found) .. "/" .. tostring(total) .. gold .. "!" .. reset

    if enhanced then
        -- Keep the two readiness lines inside one raw terminal write. This avoids
        -- Cherax inserting extra spacing between separate raw logger calls.
        block = block .. "\n\n"
            .. gold .. "Enhanced Advertise Region types... found "
            .. green .. "8/8" .. gold .. "!" .. reset
            .. "\n\n\n\n"
        startup.consoleRegionSummaryPrinted = true
    else
        block = block .. "\n\n\n\n"
    end

    startup.consoleNatSummaryPrinted = true
    startup.console_raw_block(block)
    return true
end

function startup.print_nat_pattern_summary(force)
    return startup.print_readiness_summary_block(force)
end

function startup.print_advertise_region_summary(force)
    return startup.print_readiness_summary_block(force)
end

function startup.toast_colored(msg, ms, kind)
    ms = ms or 4500
    if GUI and GUI.AddToast then
        GUI.AddToast(startup.name, tostring(msg), ms)
    end
    startup.s.lastStatus = tostring(msg)
    startup.log_colored(msg, kind or "info")
end

function startup.toast(msg, ms)
    ms = ms or 4500
    if GUI and GUI.AddToast then
        GUI.AddToast(startup.name, tostring(msg), ms)
    end
    startup.s.lastStatus = tostring(msg)
    startup.log(msg)
end

function startup.error(msg)
    if Logger and Logger.LogError then
        Logger.LogError("[" .. startup.name .. "] " .. tostring(msg))
    elseif Logger and Logger.Log then
        Logger.Log(eLogColor.LIGHTRED, startup.name, tostring(msg))
    end
    if GUI and GUI.AddToast then
        GUI.AddToast(startup.name .. " Error", tostring(msg), 7500)
    end
    startup.s.lastStatus = "Error: " .. tostring(msg)
end


function startup.yield(ms)
    if Script and Script.Yield then
        Script.Yield(ms or 0)
    elseif g_util and g_util.yield then
        g_util.yield(ms or 0)
    end
end

function startup.now()
    if MISC and MISC.GET_GAME_TIMER then
        return MISC.GET_GAME_TIMER()
    end
    return math.floor(os.clock() * 1000)
end

function startup.hash(name)
    return Utils.Joaat("ST_STARTUP_" .. tostring(name))
end

function startup.get_file_name(path)
    path = tostring(path or "")
    return path:match("([^\\/]+)$") or path
end

function startup.normalize_path(path)
    return string.lower(tostring(path or ""))
end

function startup.is_startup_lua(path)
    return string.lower(startup.get_file_name(path)) == "startup.lua"
end

function startup.path_exists_in_list(list, path)
    local wanted = startup.normalize_path(path)
    for _, existing in ipairs(list) do
        if startup.normalize_path(existing) == wanted then
            return true
        end
    end
    return false
end

function startup.bool_text(value)
    if value then return "ON" end
    return "OFF"
end

function startup.format_seconds(ms)
    return tostring(math.floor((ms or 0) / 1000)) .. "s"
end

function startup.clamp_float(value, minValue, maxValue)
    value = tonumber(value or minValue) or minValue
    if value < minValue then value = minValue end
    if value > maxValue then value = maxValue end
    return value
end

function startup.clamp_int(value, minValue, maxValue)
    value = math.floor(tonumber(value or minValue) or minValue)
    if value < minValue then value = minValue end
    if value > maxValue then value = maxValue end
    return value
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- time and world
-- note: day and night modes share the same cherax clock controls.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.time_feature = startup.time_feature or {
    hourFeature = nil,
    minuteFeature = nil,
    lastResolveMs = 0,
    lastResolveSummary = "Cherax Hour / Minute sliders not resolved yet."
}
startup.time_feature_natives = {
    SET_CLOCK_TIME = 0x47C3B5848C3E45D8,
    ADVANCE_CLOCK_TIME_TO = 0xC8CA9670B9D83B3B,
    GET_CLOCK_HOURS = 0x25223CA6B4D20B7F,
    GET_CLOCK_MINUTES = 0x13D2B8ADD79640F2,
    GET_CLOCK_SECONDS = 0x494E97C2EF27C470,
    NETWORK_OVERRIDE_CLOCK_TIME = 0xE679E3E06E363892
}

function startup.read_clock()
    if not Natives or not Natives.InvokeInt then return nil, nil, nil end
    return tonumber(Natives.InvokeInt(startup.time_feature_natives.GET_CLOCK_HOURS)) or 0,
        tonumber(Natives.InvokeInt(startup.time_feature_natives.GET_CLOCK_MINUTES)) or 0,
        tonumber(Natives.InvokeInt(startup.time_feature_natives.GET_CLOCK_SECONDS)) or 0
end

function startup.is_night_for_always_day(hour)
    hour = tonumber(hour) or 12
    return hour >= 22 or hour < 5
end

function startup.is_day_for_always_night(hour)
    hour = tonumber(hour) or 12
    return hour >= 5 and hour < 22
end

function startup.read_feature_name(feature)
    if not feature then return "" end
    local names = {}
    local value = feature:GetName(false)
    if value then names[#names + 1] = tostring(value) end
    local value = feature:GetName(true)
    if value then names[#names + 1] = tostring(value) end
    if feature.Name then names[#names + 1] = tostring(feature.Name) end
    return table.concat(names, " | ")
end

function startup.get_feature_by_name_quiet(name)
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil end
    return FeatureMgr.GetFeatureByName(name)
end

function startup.find_cherax_time_slider(wanted)
    local names = wanted == "hour"
        and { "Hour", "Hours", "Time Hour", "Clock Hour", "World Hour", "Set Hour" }
        or  { "Minute", "Minutes", "Time Minute", "Clock Minute", "World Minute", "Set Minute" }
    for _, name in ipairs(names) do
        local feature = startup.get_feature_by_name_quiet(name)
        if feature then
            return feature, "GetFeatureByName('" .. tostring(name) .. "') -> " .. tostring(startup.read_feature_name(feature))
        end
    end
    return nil, "No exact " .. tostring(wanted) .. " slider match"
end

function startup.resolve_cherax_time_sliders(force)
    local ms = startup.now()
    local state = startup.time_feature
    if not force and state.hourFeature and state.minuteFeature then return true end
    if not force and (ms - (state.lastResolveMs or 0)) < 5000 then
        return state.hourFeature ~= nil and state.minuteFeature ~= nil
    end
    state.lastResolveMs = ms
    local hourFeature, hourDetails = startup.find_cherax_time_slider("hour")
    local minuteFeature, minuteDetails = startup.find_cherax_time_slider("minute")
    state.hourFeature = hourFeature
    state.minuteFeature = minuteFeature
    state.lastResolveSummary = tostring(hourDetails) .. " | " .. tostring(minuteDetails)
    return hourFeature ~= nil and minuteFeature ~= nil
end

function startup.set_time_feature_value(feature, value)
    if not feature then return false end
    value = tonumber(value) or 0
    local applied = false
    if feature.SetIntValue then
        feature:SetIntValue(value)
        applied = true
    end
    if feature.SetValue then
        feature:SetValue(value)
        applied = true
    end
    if feature.TriggerCallback then
        feature:TriggerCallback()
        applied = true
    end
    return applied
end

function startup.set_clock_via_cherax_sliders(hour, minute)
    if not startup.resolve_cherax_time_sliders(false) then
        return false, startup.time_feature.lastResolveSummary
    end
    local minuteOk1 = startup.set_time_feature_value(startup.time_feature.minuteFeature, minute or 0)
    startup.yield(50)
    local hourOk = startup.set_time_feature_value(startup.time_feature.hourFeature, hour or 5)
    startup.yield(50)
    local minuteOk2 = startup.set_time_feature_value(startup.time_feature.minuteFeature, minute or 0)
    return minuteOk1 or hourOk or minuteOk2, startup.time_feature.lastResolveSummary
end

function startup.set_clock_native_fallback(hour, minute, second)
    if not Natives or not Natives.InvokeVoid then return false end
    hour, minute, second = tonumber(hour) or 5, tonumber(minute) or 0, tonumber(second) or 0
    Natives.InvokeVoid(startup.time_feature_natives.NETWORK_OVERRIDE_CLOCK_TIME, hour, minute, second)
    Natives.InvokeVoid(startup.time_feature_natives.ADVANCE_CLOCK_TIME_TO, hour, minute, second)
    Natives.InvokeVoid(startup.time_feature_natives.SET_CLOCK_TIME, hour, minute, second)
    return true
end

function startup.set_always_day_time(reason, forceExact)
    local targetHour = tonumber(startup.s.alwaysDayTargetHour or 5) or 5
    local targetMinute = tonumber(startup.s.alwaysDayTargetMinute or 0) or 0
    local beforeHour, beforeMinute = startup.read_clock()
    if beforeHour and not forceExact and not startup.is_night_for_always_day(beforeHour) then
        startup.s.alwaysDayLastStatus = ("No skip needed. Current time %02d:%02d."):format(beforeHour, beforeMinute or 0)
        startup.s.alwaysDaySkipping = false
        return true
    end
    local usedSliders, sliderDetails = startup.set_clock_via_cherax_sliders(targetHour, targetMinute)
    startup.yield(250)
    local verifyHour, verifyMinute = startup.read_clock()
    local verified = verifyHour and verifyHour == targetHour and (verifyMinute or 0) == targetMinute
    if not verified then
        startup.set_clock_native_fallback(targetHour, targetMinute, 0)
        startup.yield(150)
        verifyHour, verifyMinute = startup.read_clock()
        verified = verifyHour and verifyHour == targetHour and (verifyMinute or 0) == targetMinute
    end
    local beforeText = beforeHour and ("%02d:%02d"):format(beforeHour, beforeMinute or 0) or "unknown"
    local afterText = verifyHour and ("%02d:%02d"):format(verifyHour, verifyMinute or 0) or "unknown"
    local method = usedSliders and "Cherax Hour / Minute sliders" or "native fallback"
    if verified then
        startup.s.alwaysDayLastStatus = ("%s -> %s via %s"):format(beforeText, afterText, method)
    else
        startup.s.alwaysDayLastStatus = ("Attempted %s -> %02d:%02d, verified %s | %s"):format(beforeText, targetHour, targetMinute, afterText, tostring(sliderDetails or "no slider details"))
    end
    startup.s.alwaysDaySkipping = false
    return verified
end

function startup.start_always_day_skip(reason, forceExact)
    if startup.s.alwaysDaySkipping then return end
    startup.s.alwaysDaySkipping = true
    startup.s.alwaysDayLastSkipMs = startup.now()
    if Script and Script.QueueJob then
        Script.QueueJob(function()
            startup.set_always_day_time(reason, forceExact)
        end)
    else
        startup.set_always_day_time(reason, forceExact)
    end
end

function startup.update_always_day()
    if not startup.s.alwaysDayEnabled or startup.s.alwaysDaySkipping then return end
    local ms = startup.now()
    if (ms - (startup.s.alwaysDayLastCheckMs or 0)) < (startup.s.alwaysDayScanMs or 5000) then return end
    startup.s.alwaysDayLastCheckMs = ms
    if (ms - (startup.s.alwaysDayLastSkipMs or 0)) < 15000 then return end
    local h, m = startup.read_clock()
    if not h then
        startup.s.alwaysDayLastStatus = "Could not read game clock."
        return
    end
    if startup.is_night_for_always_day(h) then
        startup.start_always_day_skip(("detected %02d:%02d"):format(h, m or 0), false)
    else
        startup.s.alwaysDayLastStatus = ("Watching. Current time %02d:%02d."):format(h, m or 0)
    end
end

function startup.set_always_night_time(reason, forceExact)
    local targetHour = tonumber(startup.s.alwaysNightTargetHour or 22) or 22
    local targetMinute = tonumber(startup.s.alwaysNightTargetMinute or 0) or 0
    local beforeHour, beforeMinute = startup.read_clock()
    if beforeHour and not forceExact and not startup.is_day_for_always_night(beforeHour) then
        startup.s.alwaysNightLastStatus = ("No skip needed. Current time %02d:%02d."):format(beforeHour, beforeMinute or 0)
        startup.s.alwaysNightSkipping = false
        return true
    end
    local usedSliders, sliderDetails = startup.set_clock_via_cherax_sliders(targetHour, targetMinute)
    startup.yield(250)
    local verifyHour, verifyMinute = startup.read_clock()
    local verified = verifyHour and verifyHour == targetHour and (verifyMinute or 0) == targetMinute
    if not verified then
        startup.set_clock_native_fallback(targetHour, targetMinute, 0)
        startup.yield(150)
        verifyHour, verifyMinute = startup.read_clock()
        verified = verifyHour and verifyHour == targetHour and (verifyMinute or 0) == targetMinute
    end
    local beforeText = beforeHour and ("%02d:%02d"):format(beforeHour, beforeMinute or 0) or "unknown"
    local afterText = verifyHour and ("%02d:%02d"):format(verifyHour, verifyMinute or 0) or "unknown"
    local method = usedSliders and "Cherax Hour / Minute sliders" or "native fallback"
    if verified then
        startup.s.alwaysNightLastStatus = ("%s -> %s via %s"):format(beforeText, afterText, method)
    else
        startup.s.alwaysNightLastStatus = ("Attempted %s -> %02d:%02d, verified %s | %s"):format(beforeText, targetHour, targetMinute, afterText, tostring(sliderDetails or "no slider details"))
    end
    startup.s.alwaysNightSkipping = false
    return verified
end

function startup.start_always_night_skip(reason, forceExact)
    if startup.s.alwaysNightSkipping then return end
    startup.s.alwaysNightSkipping = true
    startup.s.alwaysNightLastSkipMs = startup.now()
    if Script and Script.QueueJob then
        Script.QueueJob(function()
            startup.set_always_night_time(reason, forceExact)
        end)
    else
        startup.set_always_night_time(reason, forceExact)
    end
end

function startup.update_always_night()
    if not startup.s.alwaysNightEnabled or startup.s.alwaysNightSkipping then return end
    local ms = startup.now()
    if (ms - (startup.s.alwaysNightLastCheckMs or 0)) < (startup.s.alwaysDayScanMs or 5000) then return end
    startup.s.alwaysNightLastCheckMs = ms
    if (ms - (startup.s.alwaysNightLastSkipMs or 0)) < 15000 then return end
    local h, m = startup.read_clock()
    if not h then
        startup.s.alwaysNightLastStatus = "Could not read game clock."
        return
    end
    if startup.is_day_for_always_night(h) then
        startup.start_always_night_skip(("detected %02d:%02d"):format(h, m or 0), false)
    else
        startup.s.alwaysNightLastStatus = ("Watching. Current time %02d:%02d."):format(h, m or 0)
    end
end

