function startup.is_scripted_music_playing()
    local music = false
    local scripted = false
    local oneshot = false
    local playtime = 0
    if Natives and Natives.InvokeBool then
    music = Natives.InvokeBool(0x845FFC3A4FEEFA3E) == true -- AUDIO_IS_MUSIC_PLAYING
    scripted = Natives.InvokeBool(0x2DD39BF3E2F9C47F) == true -- AUDIO_IS_SCRIPTED_MUSIC_PLAYING
    oneshot = Natives.InvokeBool(0xA097AB275061FB21) == true -- IS_MUSIC_ONESHOT_PLAYING
    end
    if Natives and Natives.InvokeInt then
    playtime = Natives.InvokeInt(0xE7A0D23DC414507B) or 0 -- GET_MUSIC_PLAYTIME
    end
    return music, scripted, oneshot, playtime
end

function startup.kill_event_music_pulse(reason, forceLog)
    if not startup.s.muteEventMusicEnabled then return false end
    if not Natives or not Natives.InvokeBool or not Natives.InvokeVoid then
        startup.s.lastEventMusicStatus = "Natives unavailable"
        return false
    end
    local music, scripted, oneshot, playtime = startup.is_scripted_music_playing()
    local anyHit = false
    for _, eventName in ipairs(startup.event_music_cancel_events) do
        if Natives.InvokeBool(0x5B17A90291133DA5, eventName) == true then anyHit = true end
    end
    for _, eventName in ipairs(startup.event_music_kill_events) do
        if Natives.InvokeBool(0x706D57B0F50DA710, eventName) == true then anyHit = true end
    end
    Natives.InvokeVoid(0xBAC7FC81A75EC1A1)
    for _, sceneName in ipairs(startup.event_music_scenes) do
        Natives.InvokeVoid(0xDFE8422B3B94E688, sceneName)
    end
    startup.s.lastEventMusicStatus = "Pulse: music=" .. tostring(music) ..
        " scripted=" .. tostring(scripted) ..
        " oneshot=" .. tostring(oneshot) ..
        " playtime=" .. tostring(playtime) ..
        " hit=" .. tostring(anyHit) ..
        " reason=" .. tostring(reason or "loop")
    if startup.s.verboseStartupLogs then startup.log_colored("[Event Music] " .. startup.s.lastEventMusicStatus, "info") end
    return anyHit or music or scripted or oneshot
end

function startup.install_event_music_muter_loop()
    if startup.s.eventMusicLoopInstalled then return end
    startup.s.eventMusicLoopInstalled = true
    if Script and Script.RegisterLooped then
        Script.RegisterLooped(function()
            if startup and startup.s and startup.s.muteEventMusicEnabled then
                local now = startup.now()
                local pulseMs = tonumber(startup.s.eventMusicPulseMs or 1000) or 1000
                if now - (startup.s.eventMusicLastPulseMs or 0) >= pulseMs then
                    startup.s.eventMusicLastPulseMs = now
                    startup.kill_event_music_pulse("loop", false)
                end
            end
        end)
        if startup.s.verboseStartupLogs then
            startup.log("Event Music Muter loop installed.")
        end
    else
        startup.s.lastEventMusicStatus = "Script.RegisterLooped unavailable"
        startup.log("Event Music Muter loop not installed: Script.RegisterLooped unavailable.")
    end
end

