    natTypeSource = "Not checked",
    matchmakingRegion = "Automatic",
    advertiseRegion = "Unknown",
    friendNames = {},
    lastFriendsUpdateMs = 0,
    speakers = {},
    speakerNames = {},
    debugLine = ""
}
startup.hud_network_native = {
    NETWORK_GET_HOST_PLAYER_INDEX = 0x8251FB94DC4FDFC8,
    NETWORK_GET_HOST_OF_SCRIPT = 0x1D6A14F1F9A736FC,
    NETWORK_GET_FRIEND_COUNT = 0x203F1CFD823B27A4,
    NETWORK_GET_FRIEND_NAME = 0xE11EBBB2A783FE8B,
    NETWORK_IS_FRIEND_IN_MULTIPLAYER = 0x57005C18827F3A28
}
