    NETWORK_PLAYER_HAS_HEADSET = 0x3FB99A8B08D18FD6,
    NETWORK_GET_PLAYER_LOUDNESS = 0x21A1684A25C2867F,
    NETWORK_HAS_HEADSET = 0xE870F9F1F7B4F1FA,
    NETWORK_IS_PUSH_TO_TALK_ACTIVE = 0xC0D2AF00BCC234CA,
    PLAYER_ID = 0x4F8644AF03D0E0D6
}

function startup.native_bool(hash, ...)
    if not Natives or not Natives.InvokeBool then return false, "Natives.InvokeBool unavailable" end
    return Natives.InvokeBool(hash, ...) == true, nil
end

function startup.native_int(hash, ...)
    if not Natives or not Natives.InvokeInt then return nil, "Natives.InvokeInt unavailable" end
    return tonumber(Natives.InvokeInt(hash, ...)), nil
end

function startup.native_float(hash, ...)
    if not Natives or not Natives.InvokeFloat then return 0.0, "Natives.InvokeFloat unavailable" end
    return tonumber(Natives.InvokeFloat(hash, ...)) or 0.0, nil
end

function startup.get_local_player_id_candidates()
    local out = {}
    local seen = {}
    local function add(v)
        v = tonumber(v)
        if v ~= nil and v >= 0 and v <= 31 and not seen[v] then
            seen[v] = true
            out[#out + 1] = v
        end
    end
    if GTA and GTA.GetLocalPlayerId then
        add(GTA.GetLocalPlayerId())
    end
    local nativeId = startup.native_int(startup.voice_native.PLAYER_ID)
    add(nativeId)
    return out
end

function startup.is_local_player_id(playerId)
    local wanted = tonumber(playerId)
    if wanted == nil then return false end
    wanted = math.floor(wanted)
    for _, localId in ipairs(startup.get_local_player_id_candidates()) do
        if tonumber(localId) == wanted then return true end
    end
    if Players and Players.GetById then
        local player = Players.GetById(wanted)
        if player and player.IsLocalPlayer then
            return player:IsLocalPlayer() == true
        end
    end
    return false
end

function startup.get_player_name_safe(playerId)
    local name = nil
    if Players and Players.GetName then
        name = Players.GetName(playerId)
    end
    if name and tostring(name) ~= "" then return tostring(name) end
    for _, localId in ipairs(startup.get_local_player_id_candidates()) do
        if tonumber(playerId) == tonumber(localId) then return "You" end
    end
    return "Player " .. tostring(playerId)
end

function startup.get_voice_player_ids()
    local ids = {}
    local seen = {}
    local function add(v)
        v = tonumber(v)
        if v ~= nil and v >= 0 and v <= 31 and not seen[v] then
            seen[v] = true
            ids[#ids + 1] = v
        end
    end
    for _, localId in ipairs(startup.get_local_player_id_candidates()) do add(localId) end
    local players = nil
    if Players and Players.Get then
        local ok, result = direct_call(function() return Players.Get(ePlayerListSort.PLAYER_ID, "") end)
        if ok then players = result end
    end
    if players then
        local pairsWorked = direct_call(function()
            for _, playerId in pairs(players) do add(playerId) end
        end)
        -- Some Cherax builds return indexable userdata instead of a plain Lua table.
        -- Probe both zero- and one-based slots; add() deduplicates IDs.
        if not pairsWorked or #ids <= 1 then
            for index = 0, 31 do
                local okIndex, playerId = direct_call(function() return players[index] end)
                if okIndex then add(playerId) end
            end
            for index = 1, 32 do
                local okIndex, playerId = direct_call(function() return players[index] end)
                if okIndex then add(playerId) end
            end
        end
    end
    table.sort(ids)
    return ids
end

function startup.update_voice_speakers(force)
    local now = startup.now()
    if not force and now - (startup.hud_cache.lastVoiceUpdateMs or 0) < 120 then return end
    startup.hud_cache.lastVoiceUpdateMs = now
    local activeNames = {}
    local activeIds = {}
    local headsetNames = {}
    local localDebug = {}
    local scanDebug = {}
    for _, playerId in ipairs(startup.get_voice_player_ids()) do
        local talking, talkErr = startup.native_bool(startup.voice_native.NETWORK_IS_PLAYER_TALKING, playerId)
        local headset, headsetErr = startup.native_bool(startup.voice_native.NETWORK_PLAYER_HAS_HEADSET, playerId)
        local loudness, loudErr = startup.native_float(startup.voice_native.NETWORK_GET_PLAYER_LOUDNESS, playerId)
        local loudValue = tonumber(loudness or 0.0) or 0.0
        local loudActive = loudValue > (tonumber(startup.s.voiceNativeLoudnessThreshold or 0.001) or 0.001)
        local name = startup.get_player_name_safe(playerId)
        local localPlayer = false
        local hasLocalHeadset = false
        local pushToTalk = false
        local pttActive = false
        for _, localId in ipairs(startup.get_local_player_id_candidates()) do
            if tonumber(localId) == tonumber(playerId) then
                localPlayer = true
                hasLocalHeadset = startup.native_bool(startup.voice_native.NETWORK_HAS_HEADSET)
                pushToTalk = startup.native_bool(startup.voice_native.NETWORK_IS_PUSH_TO_TALK_ACTIVE)
                pttActive = (startup.s.voiceUseLocalPttAsTalking ~= false) and pushToTalk == true
                localDebug[#localDebug + 1] = string.format(
                    "self id=%s talk=%s headset=%s localHeadset=%s ptt=%s pttFallback=%s loud=%.4f",
                    tostring(playerId),
                    talking and "true" or "false",
                    headset and "true" or "false",
                    hasLocalHeadset and "true" or "false",
                    pushToTalk and "true" or "false",
                    pttActive and "true" or "false",
                    loudValue
                )
            end
        end
        scanDebug[#scanDebug + 1] = string.format(
            "%s[%s] talk=%s headset=%s ptt=%s loud=%.4f%s%s%s",
            tostring(name),
            tostring(playerId),
            talking and "true" or "false",
            headset and "true" or "false",
            (localPlayer and pushToTalk) and "true" or "false",
            loudValue,
            talkErr and (" talkErr=" .. tostring(talkErr)) or "",
            headsetErr and (" headsetErr=" .. tostring(headsetErr)) or "",
            loudErr and (" loudErr=" .. tostring(loudErr)) or ""
        )
        if headset then headsetNames[#headsetNames + 1] = name end
        if talking or loudActive or pttActive then
            activeIds[playerId] = true
            startup.hud_cache.speakerNames[playerId] = { name = name, lastMs = now }
        elseif startup.hud_cache.speakerNames[playerId] and now - (startup.hud_cache.speakerNames[playerId].lastMs or 0) <= (startup.s.voiceSpeakerHoldMs or 1600) then
            activeIds[playerId] = true
        end
    end
    local compact = {}
    for playerId, data in pairs(startup.hud_cache.speakerNames or {}) do
        if activeIds[playerId] and data and data.name then
            compact[#compact + 1] = { id = playerId, name = data.name }
        end
    end
    table.sort(compact, function(a, b) return tostring(a.name) < tostring(b.name) end)
    for _, entry in ipairs(compact) do
        activeNames[#activeNames + 1] = entry.name
    end
    startup.hud_cache.speakers = activeNames
    startup.s.voiceLastNativeStatus = "Voice HUD active"
end

function startup.get_session_host_name()
    if not Natives or not Natives.InvokeInt then return "Unknown", -1 end
    local playerId = tonumber(Natives.InvokeInt(startup.hud_network_native.NETWORK_GET_HOST_PLAYER_INDEX))
    if playerId == nil or playerId < 0 or playerId > 31 then return "Unknown", -1 end
    return startup.get_player_name_safe(playerId), playerId
end

function startup.get_script_host_name()
    if not Natives or not Natives.InvokeInt then return "Unknown", -1 end
    local playerId = tonumber(Natives.InvokeInt(startup.hud_network_native.NETWORK_GET_HOST_OF_SCRIPT, "freemode", -1, 0))
    if playerId == nil or playerId < 0 or playerId > 31 then return "Unknown", -1 end
    return startup.get_player_name_safe(playerId), playerId
end

function startup.normalize_host_queue(rawQueue)
    local ordered = {}
    if rawQueue == nil then return ordered end

    local seen = {}
    local function add(position, value)
        local playerId = tonumber(value)
        if playerId == nil or playerId < 0 or playerId > 31 or seen[playerId] then return end
        seen[playerId] = true
        ordered[#ordered + 1] = { position = tonumber(position), playerId = playerId }
    end

    -- Cherax documents Players.Get(HOST_QUEUE, search) as a player list, but some
    -- returned containers/lists are zero-based. pairs() preserves the numeric key so
    -- we can sort it ourselves instead of relying on Lua's 1-based ipairs().
    local okPairs = direct_call(function()
        for key, value in pairs(rawQueue) do add(key, value) end
    end)

    -- Fallback for indexable userdata/containers that do not expose __pairs. Probe
    -- the small player-list range directly; duplicate player IDs are discarded above.
    if not okPairs or #ordered == 0 then
        for index = 0, 31 do
            local okIndex, value = direct_call(function() return rawQueue[index] end)
            if okIndex then add(index, value) end
        end
        for index = 1, 32 do
            local okIndex, value = direct_call(function() return rawQueue[index] end)
            if okIndex then add(index, value) end
        end
    end

    table.sort(ordered, function(a, b)
        local ap, bp = a.position, b.position
        if ap ~= nil and bp ~= nil and ap ~= bp then return ap < bp end
        if ap ~= nil and bp == nil then return true end
        if ap == nil and bp ~= nil then return false end
        return a.playerId < b.playerId
    end)
    return ordered
end

function startup.get_next_host_name(currentHostPlayerId)
    startup.hud_cache.hostQueueStatus = "Unavailable"
    startup.hud_cache.hostQueueCount = 0
    if not Players or not Players.Get or not ePlayerListSort or ePlayerListSort.HOST_QUEUE == nil then
        return "Unknown", -1
    end

    local ok, rawQueue = direct_call(function()
        return Players.Get(ePlayerListSort.HOST_QUEUE, "")
    end)
    if not ok or rawQueue == nil then
        startup.hud_cache.hostQueueStatus = ok and "Empty" or "Players.Get HOST_QUEUE failed"
        return "Unknown", -1
    end

    local queue = startup.normalize_host_queue(rawQueue)
    startup.hud_cache.hostQueueCount = #queue
    if #queue == 0 then
        startup.hud_cache.hostQueueStatus = "No queue entries"
        return "Unknown", -1
    end

    local hostId = tonumber(currentHostPlayerId)
    if hostId ~= nil and hostId >= 0 and hostId <= 31 then
        for index, entry in ipairs(queue) do
            if entry.playerId == hostId then
                local nextEntry = queue[index + 1]
                if nextEntry then
                    startup.hud_cache.hostQueueStatus = "Resolved after current host"
                    return startup.get_player_name_safe(nextEntry.playerId), nextEntry.playerId
                end
                startup.hud_cache.hostQueueStatus = "Current host is last queue entry"
                return "None", -1
            end
        end
    end

    -- Some Cherax builds may expose HOST_QUEUE as the pending queue only and omit
    -- the current host. In that case the first valid entry is the next host.
    local first = queue[1]
    if first then
        startup.hud_cache.hostQueueStatus = "Resolved from first pending entry"
        return startup.get_player_name_safe(first.playerId), first.playerId
    end
    startup.hud_cache.hostQueueStatus = "No valid next host"
    return "Unknown", -1
end

function startup.nat_type_label(value)
    local natValue = tonumber(value)
    local names = { [0] = "Open", [1] = "Moderate", [2] = "Strict" }
    if natValue ~= nil and names[natValue] then return names[natValue], natValue end
    return nil, natValue
end

function startup.nat_memory_label(value)
    local natValue = tonumber(value)
    local names = { [1] = "Open", [2] = "Moderate", [3] = "Strict" }
    if natValue ~= nil and names[natValue] then return names[natValue], natValue end
    return nil, natValue
end

function startup.read_nat_type_from_gamer_info(info, sourceLabel)
    if info == nil then return nil, nil end
    local ok, raw = direct_call(function() return info.NatType end)
    if not ok or raw == nil then return nil, nil end
    local label, numeric = startup.nat_type_label(raw)
    if label then return label, tostring(sourceLabel or "GamerInfo") .. ".NatType=" .. tostring(numeric) end
    return nil, tostring(sourceLabel or "GamerInfo") .. ".NatType unsupported=" .. tostring(raw)
end

function startup.read_nat_type_from_pattern_address()
    local state = startup.nat_scan or {}
    local address = tonumber(state.address)
    if not address or address == 0 or not Memory or not Memory.ReadInt then return nil, nil end
    local ok, value = direct_call(Memory.ReadInt, address)
    if not ok or value == nil then
        state.lastStatus = "Memory.ReadInt failed"
        state.address = nil
        return nil, nil
    end
    local label, numeric = startup.nat_memory_label(value)
    state.lastValue = numeric
    if not label then
        state.lastStatus = "Pattern pointer returned unsupported value " .. tostring(value)
        return nil, nil
    end
    state.lastStatus = "Ready: " .. label
    return label, "Pattern " .. tostring(state.patternName or "Unknown") .. " / " .. tostring(state.moduleName ~= "" and state.moduleName or "default") .. " value=" .. tostring(numeric)
end

function startup.request_nat_pattern_scan(reason, force)
    local state = startup.nat_scan or {}
    startup.nat_scan = state
    if state.address and force ~= true then return false end
    if startup.patternScanBootCompleted == true and force ~= true then return false end
    local now = startup.now()
    local last = tonumber(state.lastAttemptMs or 0) or 0
    if force ~= true and now - last < 15000 then return false end

    local edition = select(1, startup.get_active_edition_info())
    state.lastRequestReason = tostring(reason or "unspecified")
    state.lastStatus = "Scan queued: " .. state.lastRequestReason
    startup.pendingNatScan = true
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("NAT_SCAN_QUEUED", "edition=" .. tostring(edition)
            .. " reason=" .. state.lastRequestReason
            .. " override=" .. tostring(startup.s.natOverrideMode or "Original"))
    end
    return true
end

function startup.queue_nat_rescan(reason)
    local state = startup.nat_scan or {}
    startup.nat_scan = state
    local mode = tostring(startup.s.natOverrideMode or "Original")
    local oldAddress = tonumber(state.address)
    local originalValue = tonumber(state.originalValue)

    if mode ~= "Original" and oldAddress and oldAddress ~= 0 and originalValue and Memory and Memory.WriteInt then
        Memory.WriteInt(oldAddress, originalValue)
    end

    state.address = nil
    state.patternName = ""
    state.moduleName = ""
    state.lastValue = nil
    state.matches = {}
    state.autoRetryCount = 0
    state.nextAutoRetryMs = 0
    state.localPlayerId = nil
    state.localPlayerSource = "Rescan requested"
    state.nextLocalPlayerProbeMs = 0
    if mode == "Original" then state.originalValue = nil end
    startup.patternScanBootCompleted = false
    startup.pendingNatOverrideApply = false

    local queued = startup.request_nat_pattern_scan(reason or "manual rescan", true)
    if queued then
        startup.toast("NAT rescan queued. Detailed results will appear in the Cherax log.", 3500)
    end
    return queued
end

function startup.run_nat_pattern_scan()
    local state = startup.nat_scan
    state.lastAttemptMs = startup.now()
    state.address = nil
    state.patternName = ""
    state.moduleName = ""
    state.lastValue = nil
    state.matches = {}

    local edition = select(1, startup.get_active_edition_info())
    local requestReason = tostring(state.lastRequestReason or "startup")
    startup.pendingNatScan = false

    if not Memory or not Memory.Scan or not Memory.Rip or not Memory.ReadInt then
        state.lastStatus = "Memory.Scan/Rip/ReadInt unavailable"
        startup.log_colored("Pattern scan unavailable.", "error")
        if startup.support_log_event_quiet then startup.support_log_event_quiet("PATTERN_SCAN_FAILED", "Memory.Scan/Rip/ReadInt unavailable") end
        return false
    end

    local function scan(pattern, moduleName)
        if moduleName == nil then return direct_call(Memory.Scan, pattern) end
        return direct_call(Memory.Scan, pattern, moduleName)
    end

    local function evaluate(def, hit, moduleName)
        hit = tonumber(hit)
        if not hit or hit == 0 then return nil end
        local ripAt = hit + (tonumber(def.offset or 6) or 6)
        local okRip, address = direct_call(Memory.Rip, ripAt)
        address = tonumber(address)
        if not okRip or not address or address == 0 then return nil end
        local okRead, value = direct_call(Memory.ReadInt, address)
        if not okRead then return nil end
        local label, numeric = startup.nat_memory_label(value)
        if not label then return nil end
        return {
            address = address,
            patternName = tostring(def.name or "Unknown"),
            moduleName = tostring(moduleName or "default"),
            value = numeric,
            label = label
        }
    end

    local firstMatch = nil
    local foundCount = 0
    local enhanced = startup.is_enhanced_active_edition()
    local eligible = {}
    for _, def in ipairs(startup.nat_scan_patterns or {}) do
        local name = tostring(def.name or "")
        local isEnhancedPattern = name:find("Enhanced", 1, true) ~= nil
        if (enhanced and isEnhancedPattern) or ((not enhanced) and (not isEnhancedPattern)) then
            eligible[#eligible + 1] = def
        end
    end
    local totalCount = #eligible
    state.lastTotalCount = totalCount
    for _, def in ipairs(eligible) do
        local match = nil
        if startup.boot_diag_checkpoint then startup.boot_diag_checkpoint("NAT_PATTERN_SCAN", "name=" .. tostring(def.name) .. " module=default", true) end
        local okDefault, hitDefault = scan(def.pattern, nil)
        if okDefault then match = evaluate(def, hitDefault, nil) end
        if not match then
            for _, moduleName in ipairs(startup.nat_scan_modules or {}) do
                if startup.boot_diag_checkpoint then startup.boot_diag_checkpoint("NAT_PATTERN_SCAN", "name=" .. tostring(def.name) .. " module=" .. tostring(moduleName), true) end
                local okModule, hitModule = scan(def.pattern, moduleName)
                if okModule then match = evaluate(def, hitModule, moduleName) end
                if match then break end
                if Script and Script.Yield then Script.Yield(0) end
            end
        end

        if match then
            foundCount = foundCount + 1
            state.matches[#state.matches + 1] = match
            if not firstMatch then firstMatch = match end
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("PATTERN_FOUND", "name=" .. tostring(def.name) .. " module=" .. tostring(match.moduleName) .. " nat=" .. tostring(match.label) .. " value=" .. tostring(match.value))
            end
        else
            if startup.support_log_event_quiet then startup.support_log_event_quiet("PATTERN_NOT_FOUND", "name=" .. tostring(def.name)) end
        end
    end

    if firstMatch then
        state.address = firstMatch.address
        state.patternName = firstMatch.patternName
        state.moduleName = firstMatch.moduleName
        state.lastValue = firstMatch.value
        if state.originalValue == nil and tostring(startup.s.natOverrideMode or "Original") == "Original" then
            state.originalValue = firstMatch.value
        end
        state.lastStatus = "Pattern ready: " .. tostring(firstMatch.label)
        state.autoRetryCount = 0
        state.nextAutoRetryMs = 0
        startup.patternScanBootCompleted = true
        state.lastFoundCount = foundCount
        startup.print_nat_pattern_summary(false)
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("PATTERN_SCAN_COMPLETE", "found=" .. tostring(foundCount) .. "/" .. tostring(totalCount) .. " active=" .. tostring(firstMatch.patternName) .. " nat=" .. tostring(firstMatch.label) .. " module=" .. tostring(firstMatch.moduleName))
        end
        return true
    end

    state.lastStatus = startup.is_prime_active_edition()
        and "No known NAT pattern matched; Prime will retry after GTA Online is ready"
        or "No known NAT pattern matched"
    startup.patternScanBootCompleted = true
    state.lastFoundCount = 0
    startup.print_nat_pattern_summary(false)
    if startup.support_log_event_quiet then startup.support_log_event_quiet("PATTERN_SCAN_FAILED", "found=0/" .. tostring(totalCount)) end
    return false
end

function startup.process_pending_nat_scan()
    if startup.pendingNatScan ~= true or startup.natScanJobQueued == true then return end
    startup.pendingNatScan = false
    startup.natScanJobQueued = true

    local function job()
        -- Clear the gate before scanning so a native error cannot permanently wedge
        -- the rescan button. This job is isolated from Startup's main worker.
        startup.natScanJobQueued = false
        local found = startup.run_nat_pattern_scan()
        if found then
            if tostring(startup.s.natOverrideMode or "Original") ~= "Original" then
                startup.pendingNatOverrideApply = true
            end
            if startup.update_hud_cache then startup.update_hud_cache(true) end
            if startup.update_support_snapshot then startup.update_support_snapshot(true, "nat-rescan-complete") end
        else
        end
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

function startup.maybe_retry_prime_nat_scan()
    if not startup.is_prime_active_edition() then return end
    if startup.s.showNatTypeHud ~= true then return end
    if startup.nat_scan and startup.nat_scan.address then return end
    if startup.pendingNatScan == true or startup.natScanJobQueued == true then return end
    if not startup.s.initialized then return end
    if not startup.is_gta_online_session_ready or not startup.is_gta_online_session_ready() then return end

    local state = startup.nat_scan or {}
    local now = startup.now()
    local retryCount = tonumber(state.autoRetryCount or 0) or 0
    local maxRetries = 8
    if retryCount >= maxRetries then
        if tostring(state.lastStatus or ""):find("Prime retry limit", 1, true) == nil then
            state.lastStatus = "Prime retry limit reached; use Rescan NAT Pattern"
        end
        return
    end
    if now < (tonumber(state.nextAutoRetryMs or 0) or 0) then return end

    retryCount = retryCount + 1
    state.autoRetryCount = retryCount
    state.nextAutoRetryMs = now + 15000
    state.lastStatus = "Prime online NAT retry " .. tostring(retryCount) .. "/" .. tostring(maxRetries) .. " queued"
    startup.request_nat_pattern_scan("Prime online retry " .. tostring(retryCount), true)
end

function startup.nat_override_target_value(mode)
    mode = tostring(mode or "Original")
    if mode == "Open" then return 1 end
    if mode == "Moderate" then return 2 end
    if mode == "Strict" then return 3 end
    return tonumber(startup.nat_scan and startup.nat_scan.originalValue or nil)
end

function startup.request_nat_override_apply(reason)
    startup.pendingNatOverrideApply = true
    startup.s.natOverrideLastStatus = "NAT override queued" .. (reason and (": " .. tostring(reason)) or "")
    if (not startup.nat_scan or not startup.nat_scan.address) and startup.patternScanBootCompleted == true then
        startup.pendingNatOverrideApply = false
        startup.s.natOverrideLastStatus = "No NAT pattern pointer. Use Rescan NAT Pattern."
    end
end

function startup.apply_nat_override_now()
    local state = startup.nat_scan or {}
    local mode = tostring(startup.s.natOverrideMode or "Original")
    local address = tonumber(state.address)
    if not address or address == 0 then
        startup.s.natOverrideLastStatus = "No NAT pattern pointer. Use Rescan NAT Pattern."
        return false
    end
    if not Memory or not Memory.WriteInt or not Memory.ReadInt then
        startup.s.natOverrideLastStatus = "Memory.WriteInt/ReadInt unavailable."
        return false
    end

    local okBefore, beforeValue = direct_call(Memory.ReadInt, address)
    local beforeLabel = okBefore and startup.nat_memory_label(beforeValue) or nil
    if state.originalValue == nil then
        if okBefore and beforeLabel then state.originalValue = tonumber(beforeValue) end
    end

    local target = startup.nat_override_target_value(mode)
    if target == nil then
        startup.s.natOverrideLastStatus = "Original NAT value was not captured. Rescan required."
        return false
    end

    local okWrite, writeErr = direct_call(Memory.WriteInt, address, target)
    if not okWrite then
        startup.s.natOverrideLastStatus = "NAT write failed: " .. tostring(writeErr)
        startup.log_colored("[NAT Override] Unable to apply " .. tostring(mode) .. ".", "error")
        return false
    end
    if Script and Script.Yield then Script.Yield(50) end
    local okRead, verify = direct_call(Memory.ReadInt, address)
    local verifyLabel = okRead and startup.nat_memory_label(verify) or nil
    if not okRead or tonumber(verify) ~= tonumber(target) then
        startup.s.natOverrideLastStatus = "NAT write could not be verified."
        startup.log_colored("[NAT Override] Could not verify the requested change.", "error")
        return false
    end

    state.lastValue = tonumber(verify)
    state.lastStatus = "Ready: " .. tostring(verifyLabel or mode)
    startup.s.natOverrideLastVerified = tostring(verifyLabel or mode)
    local changed = tonumber(beforeValue) ~= tonumber(verify)
    local fromLabel = tostring(beforeLabel or "Unknown")
    local toLabel = tostring(verifyLabel or mode or "Unknown")
    if mode == "Original" then
        startup.s.natOverrideLastStatus = "Restored original NAT: " .. tostring(verifyLabel or verify)
        if changed then
            startup.log_colored("[NAT Override] Restored from " .. fromLabel .. " to " .. toLabel .. "!", "success")
        end
    else
        startup.s.natOverrideLastStatus = "Applied: " .. mode .. " (in-memory)"
        if changed then
            startup.log_colored("[NAT Override] Applied from " .. fromLabel .. " to " .. toLabel .. "!", "success")
        end
    end
    return true
end

function startup.process_pending_nat_override()
    if startup.pendingNatOverrideApply ~= true or startup.natOverrideJobQueued == true then return end
    if not startup.nat_scan or not startup.nat_scan.address then
        if startup.patternScanBootCompleted == true then
            startup.pendingNatOverrideApply = false
            startup.s.natOverrideLastStatus = "No NAT pattern pointer. Use Rescan NAT Pattern."
        end
        return
    end
    startup.pendingNatOverrideApply = false
    startup.natOverrideJobQueued = true
    local function job()
        local ok, err = direct_call(startup.apply_nat_override_now)
        if not ok then
            startup.s.natOverrideLastStatus = "NAT override error: " .. tostring(err)
            startup.log_colored("[NAT Override] Unexpected error while applying the change.", "error")
        end
        startup.natOverrideJobQueued = false
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

function startup.restore_nat_override_on_unload()
    local state = startup.nat_scan or {}
    local address = tonumber(state.address)
    local original = tonumber(state.originalValue)
    if not address or not original or not Memory or not Memory.WriteInt then return false end
    local ok = direct_call(Memory.WriteInt, address, original)
    if ok then
        return true
    end
    return false
end

function startup.get_local_net_game_player_for_nat()
    if not Players or not Players.GetById then
        return nil, nil, "Players.GetById unavailable"
    end

    local state = startup.nat_scan or {}
    local checked = {}

    local function probe(playerId, source, requireLocalFlag)
        playerId = tonumber(playerId)
        if playerId == nil or playerId < 0 or playerId > 31 or checked[playerId] then return nil end
        checked[playerId] = true

        local okPlayer, player = direct_call(function() return Players.GetById(playerId) end)
        if not okPlayer or not player then return nil end

        local localFlag = nil
        local okLocal, result = direct_call(function() return player:IsLocalPlayer() end)
        if okLocal then localFlag = result == true end

        if requireLocalFlag == true and localFlag ~= true then return nil end
        if requireLocalFlag ~= true and localFlag == false then return nil end

        state.localPlayerId = playerId
        state.localPlayerSource = tostring(source or "player id") .. (localFlag == true and " / IsLocalPlayer" or "")
        state.nextLocalPlayerProbeMs = 0
        return player, playerId, state.localPlayerSource
    end

    local cachedId = tonumber(state.localPlayerId)
    if cachedId ~= nil then
        local player, playerId, source = probe(cachedId, "cached local player", false)
        if player then return player, playerId, source end
    end

    for _, candidateId in ipairs(startup.get_local_player_id_candidates()) do
        local player, playerId, source = probe(candidateId, "local player id", false)
        if player then return player, playerId, source end
    end

    -- Prime can expose the local player object even when the normal local-ID helpers
    -- are incomplete. Probe the small GTA player-ID range and trust only the object
    -- that explicitly reports IsLocalPlayer(). Throttle a failed full-range probe so
    -- opening the Matchmaking UI cannot cause 32 player lookups every render frame.
    local now = startup.now()
    if now < (tonumber(state.nextLocalPlayerProbeMs or 0) or 0) then
        return nil, nil, tostring(state.localPlayerSource or "Local player probe cooling down")
    end
    state.nextLocalPlayerProbeMs = now + 2000
    for playerId = 0, 31 do
        local player, resolvedId, source = probe(playerId, "Prime player scan", true)
        if player then return player, resolvedId, source end
    end

    state.localPlayerSource = "Local CNetGamePlayer not resolved"
    return nil, nil, state.localPlayerSource
end

function startup.read_nat_type_from_local_player()
    local player, playerId, playerSource = startup.get_local_net_game_player_for_nat()
    if not player then return nil, tostring(playerSource or "Local player unavailable") end

    local okInfo, gamerInfo = direct_call(function() return player:GetGamerInfo() end)
    if okInfo and gamerInfo then
        local label, source = startup.read_nat_type_from_gamer_info(gamerInfo, "GetGamerInfo")
        if label then
            return label, tostring(playerSource or "local player") .. " / " .. tostring(source)
        end
    end

    local okPi, playerInfo = direct_call(function() return player.PlayerInfo end)
    if okPi and playerInfo then
        local okNet, netData = direct_call(function() return playerInfo.NetData end)
        if okNet and netData then
            local label, source = startup.read_nat_type_from_gamer_info(netData, "PlayerInfo.NetData")
            if label then
                return label, tostring(playerSource or "local player") .. " / " .. tostring(source)
            end
        end
    end

    return nil, tostring(playerSource or "local player") .. " / NAT field unavailable for player " .. tostring(playerId or "?")
end

function startup.get_local_nat_type()
    startup.hud_cache.natTypeSource = "Unavailable"

    -- When an override is selected, prefer the pattern pointer because it is the value
    -- Startup actually writes. GamerInfo may continue reporting the pre-override classification.
    if tostring(startup.s.natOverrideMode or "Original") ~= "Original" then
        local overrideLabel, overrideSource = startup.read_nat_type_from_pattern_address()
        if overrideLabel then
            startup.hud_cache.natTypeSource = "Override / " .. tostring(overrideSource or "pattern")
            return overrideLabel
        end
        startup.request_nat_pattern_scan("override HUD read", false)
    end

    local localLabel, localSource = startup.read_nat_type_from_local_player()
    if localLabel then
        startup.hud_cache.natTypeSource = tostring(localSource or "Local GamerInfo")
        return localLabel
    end

    local memoryLabel, memorySource = startup.read_nat_type_from_pattern_address()
    if memoryLabel then
        startup.hud_cache.natTypeSource = memorySource
        return memoryLabel
    end

    startup.request_nat_pattern_scan("HUD read fallback", false)
    local scanStatus = tostring(startup.nat_scan and startup.nat_scan.lastStatus or "NAT unavailable")
    startup.hud_cache.natTypeSource = tostring(localSource or "Local player NAT unavailable") .. " / " .. scanStatus
    return "Unknown"
end

function startup.region_memory_label(value)
    local v = tonumber(value)
    if v ~= nil and startup.region_names[v] then return startup.region_names[v], v end
    return nil, v
end

local function startup_region_trim(v)
    return tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "")
end

function startup.probe_matchmaking_region_features()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    state.featureProbeResults = {}
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil end
    for _, featureName in ipairs(startup.region_feature_probe_names or {}) do
        local okGet, feature = direct_call(FeatureMgr.GetFeatureByName, featureName)
        if okGet and feature then
            local label = nil
            if feature.GetList and feature.GetListIndex then
                local okList, list = direct_call(function() return feature:GetList() end)
                local okIdx, idx = direct_call(function() return feature:GetListIndex() end)
                idx = okIdx and tonumber(idx) or nil
                if okList and type(list) == "table" and idx ~= nil then
                    local candidate = list[idx + 1] or list[idx]
                    if candidate ~= nil and startup_region_trim(candidate) ~= "" then label = startup_region_trim(candidate) end
                end
            end
            if not label and feature.GetStringValue then
                local okStr, value = direct_call(function() return feature:GetStringValue() end)
                if okStr and startup_region_trim(value) ~= "" then label = startup_region_trim(value) end
            end
            state.featureProbeResults[#state.featureProbeResults + 1] = {name=featureName, label=label or "<found; unreadable>"}
            if label then
                if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_FEATURE_FALLBACK", "feature="..featureName.." label="..label) end
                return label, "Cherax feature: " .. featureName
            end
        end
    end
    return nil
end

local startup_region_europe_codes = {
    AL=true,AD=true,AT=true,BE=true,BA=true,BG=true,HR=true,CY=true,CZ=true,DK=true,EE=true,FI=true,FR=true,DE=true,GR=true,HU=true,
    IS=true,IE=true,IT=true,XK=true,LV=true,LI=true,LT=true,LU=true,MT=true,MD=true,MC=true,ME=true,NL=true,MK=true,NO=true,PL=true,
    PT=true,RO=true,SM=true,RS=true,SK=true,SI=true,ES=true,SE=true,CH=true,GB=true,UK=true,VA=true
}
local startup_region_africa_codes = {
    DZ=true,AO=true,BJ=true,BW=true,BF=true,BI=true,CV=true,CM=true,CF=true,TD=true,KM=true,CG=true,CD=true,CI=true,DJ=true,EG=true,GQ=true,
    ER=true,SZ=true,ET=true,GA=true,GM=true,GH=true,GN=true,GW=true,KE=true,LS=true,LR=true,LY=true,MG=true,MW=true,ML=true,MR=true,MU=true,
    MA=true,MZ=true,NA=true,NE=true,NG=true,RW=true,ST=true,SN=true,SC=true,SL=true,SO=true,ZA=true,SS=true,SD=true,TZ=true,TG=true,TN=true,
    UG=true,ZM=true,ZW=true
}
local startup_region_cis_codes = {RU=true,BY=true,KZ=true,KG=true,TJ=true,TM=true,UZ=true,AM=true,AZ=true}
local startup_region_us_west_states = {AK=true,AZ=true,CA=true,CO=true,HI=true,ID=true,MT=true,NV=true,NM=true,OR=true,UT=true,WA=true,WY=true}

function startup.estimate_region_from_local_ipinfo()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    state.localIpInfo = {}
    if not Players or not Players.GetIPInfo then return nil end
    local localIds = startup.get_local_player_id_candidates and startup.get_local_player_id_candidates() or {}
    for _, candidate in ipairs(localIds or {}) do
        local playerId = tonumber(candidate)
        if playerId ~= nil and playerId >= 0 and playerId <= 31 then
            local okInfo, info = direct_call(Players.GetIPInfo, playerId)
            if okInfo and type(info) == "table" then
                local safe, parts = {}, {}
                for k,v in pairs(info) do safe[tostring(k)] = tostring(v) end
                state.localIpInfo = safe
                for k,v in pairs(safe) do parts[#parts+1] = tostring(k).."="..tostring(v) end
                table.sort(parts)
                if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_LOCAL_IPINFO", table.concat(parts, " | ")) end

                local code = startup_region_trim(info.countryCode or info.country_code or info.cc):upper()
                local country = startup_region_trim(info.country or info.countryName or info.country_name):lower()
                local subdivision = startup_region_trim(info.regionCode or info.region_code or info.stateCode or info.state_code or info.region or info.state):upper()
                local lon = tonumber(info.longitude or info.lon or info.lng)
                local lat = tonumber(info.latitude or info.latiude or info.lat)
                local city = startup_region_trim(info.city):lower()
                local countryMissing = country == "" or country == "na" or country == "n/a" or country == "unknown"
                local cityMissing = city == "" or city == "na" or city == "n/a" or city == "unknown"
                local coordinatesMissing = (lon == nil or lon == 0) and (lat == nil or lat == 0)
                if countryMissing and cityMissing and coordinatesMissing then
                    if startup.support_log_event_quiet then
                        startup.support_log_event_quiet("REGION_GEO_REJECTED", "reason=empty_placeholder countryCode="..tostring(code).." country="..tostring(country).." city="..tostring(city).." lat="..tostring(lat).." lon="..tostring(lon))
                    end
                    return nil
                end
                local label = nil
                if code == "JP" or country == "japan" then label = "Japan"
                elseif code == "CN" or code == "HK" or code == "MO" or code == "TW" or country == "china" then label = "China"
                elseif code == "AU" or code == "NZ" then label = "Australia"
                elseif startup_region_cis_codes[code] then label = "CIS"
                elseif startup_region_africa_codes[code] then label = "Africa"
                elseif startup_region_europe_codes[code] then label = "Europe"
                elseif code == "US" then
                    local abbr = subdivision:match("([A-Z][A-Z])$") or subdivision
                    if startup_region_us_west_states[abbr] then label = "USA (West)"
                    elseif abbr ~= "" and #abbr <= 3 then label = "USA (East)"
                    elseif lon then label = lon <= -104 and "USA (West)" or "USA (East)" end
                end
                if label then
                    if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_GEO_ESTIMATE", "label="..label.." countryCode="..code.." subdivision="..subdivision.." lon="..tostring(lon)) end
                    return label, "Local IP geolocation estimate"
                end
                return nil
            end
        end
    end
    return nil
end

function startup.run_region_structural_probes()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    state.heuristicCandidates = {}
    state.heuristicCorroborated = false
    if not Memory or not Memory.Scan or not Memory.Rip or not Memory.ReadInt then return nil end
    local byAddress = {}
    local function raw_scan(pattern, moduleName)
        local ok, hit
        if moduleName == nil then ok, hit = direct_call(Memory.Scan, pattern)
        else ok, hit = direct_call(Memory.Scan, pattern, moduleName) end
        hit = ok and tonumber(hit) or nil
        return hit and hit ~= 0 and hit or nil
    end
    local modules = {false, "GTA5.exe", "GTA5", "GTA5.exe+0", "GTA5_Enhanced.exe", "GTA5_Enhanced"}
    for _, def in ipairs(startup.region_structural_probes or {}) do
        local hit, moduleLabel = nil, "default"
        for _, moduleName in ipairs(modules) do
            hit = raw_scan(def.pattern, moduleName == false and nil or moduleName)
            if hit then moduleLabel = moduleName == false and "default" or tostring(moduleName); break end
            if Script and Script.Yield then Script.Yield(0) end
        end
        if hit then
            for _, off in ipairs(def.offsets or {}) do
                local okRip, addr = direct_call(Memory.Rip, hit + tonumber(off or 0))
                addr = okRip and tonumber(addr) or nil
                if addr and addr ~= 0 then
                    local ok1, v1 = direct_call(Memory.ReadInt, addr)
                    local ok2, v2 = direct_call(Memory.ReadInt, addr)
                    v1, v2 = ok1 and tonumber(v1) or nil, ok2 and tonumber(v2) or nil
                    if v1 ~= nil and v1 == v2 and startup.region_names[v1] then
                        local key = string.format("%X", addr)
                        local row = byAddress[key] or {address=addr, value=v1, label=startup.region_names[v1], probes={}, count=0}
                        row.count = row.count + 1
                        row.probes[#row.probes+1] = def.name .. "@" .. tostring(off) .. "/" .. tostring(moduleLabel)
                        byAddress[key] = row
                    end
                end
            end
        end
    end
    local best = nil
    for _, row in pairs(byAddress) do
        state.heuristicCandidates[#state.heuristicCandidates+1] = row
        if not best or row.count > best.count then best = row end
    end
    table.sort(state.heuristicCandidates, function(a,b) return (a.count or 0) > (b.count or 0) end)
    if best and (best.count or 0) >= 2 then
        state.heuristicCorroborated = true
        if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_HEURISTIC_CORROBORATED", "address=0x"..string.format("%X",best.address).." value="..tostring(best.value).." label="..tostring(best.label).." probes="..table.concat(best.probes, ",")) end
        return best.label, "Corroborated read-only structural probe"
    end
    if best and startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_HEURISTIC_SINGLE", "address=0x"..string.format("%X",best.address).." value="..tostring(best.value).." label="..tostring(best.label).." count="..tostring(best.count)) end
    return nil
end

function startup.run_region_pattern_scan()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan
    state.address, state.patternName, state.moduleName, state.lastValue = nil, "", "", nil
    state.activeConfidence = ""
    state.matches = {}
    state.probeResults = {}
    state.fallbackLabel, state.fallbackSource = nil, nil
    state.featureProbeResults, state.localIpInfo = {}, {}
    state.heuristicCandidates, state.heuristicCorroborated = {}, false
    state.lastAttemptMs = startup.now()

    if not Memory or not Memory.Scan or not Memory.Rip or not Memory.ReadInt then
        state.lastStatus = "Memory API unavailable"
        startup.log_colored("Pattern scan unavailable.", "error")
        return false
    end

    local enhanced = startup.is_enhanced_active_edition()
    local preferredFamily = enhanced and "Enhanced" or "Legacy"

    -- Prefer the active edition, but intentionally scan the other source family afterward.
    -- This is a diagnostic lab: current GTA builds can move code between old signatures.
    local eligible = {}
    for _, def in ipairs(startup.region_scan_patterns or {}) do
        if tostring(def.family) == preferredFamily then eligible[#eligible + 1] = def end
    end
    for _, def in ipairs(startup.region_scan_patterns or {}) do
        if tostring(def.family) ~= preferredFamily then eligible[#eligible + 1] = def end
    end

    startup.log_colored("Scanning for patterns...", "info")

    local function scan_raw(pattern, moduleName)
        if moduleName == nil then
            local ok, hit = direct_call(Memory.Scan, pattern)
            return ok and tonumber(hit) or nil, "default"
        end

        -- Cherax builds/scripts have used both argument orders in the wild. Try the
        -- current Startup/Essentials order first, then the alternate order safely.
        local okA, hitA = direct_call(Memory.Scan, pattern, moduleName)
        hitA = okA and tonumber(hitA) or nil
        if hitA and hitA ~= 0 then return hitA, tostring(moduleName) .. " (pattern,module)" end

        local okB, hitB = direct_call(Memory.Scan, moduleName, pattern)
        hitB = okB and tonumber(hitB) or nil
        if hitB and hitB ~= 0 then return hitB, tostring(moduleName) .. " (module,pattern)" end
        return nil, tostring(moduleName)
    end

    local function validate_hit(def, hit, moduleLabel)
        if not hit or hit == 0 then return nil, "not_found" end
        local ripAt = hit + (tonumber(def.offset) or 3)
        local okRip, address = direct_call(Memory.Rip, ripAt)
        address = okRip and tonumber(address) or nil
        if not address or address == 0 then return nil, "rip_failed" end

        local ok1, value1 = direct_call(Memory.ReadInt, address)
        value1 = ok1 and tonumber(value1) or nil
        local label1, numeric1 = startup.region_memory_label(value1)
        if not label1 then return nil, "invalid_value:" .. tostring(value1) end

        if Script and Script.Yield then Script.Yield(0) end
        local ok2, value2 = direct_call(Memory.ReadInt, address)
        value2 = ok2 and tonumber(value2) or nil
        if not ok2 or value2 ~= numeric1 then return nil, "unstable_read:" .. tostring(value1) .. "/" .. tostring(value2) end

        return {
            address=address, hit=hit, ripAt=ripAt, patternName=def.name,
            moduleName=moduleLabel or "default", value=numeric1, label=label1,
            family=tostring(def.family or "Unknown"), confidence=tostring(def.confidence or "experimental")
        }, "valid"
    end

    local found = 0
    for _, def in ipairs(eligible) do
        if startup.boot_diag_checkpoint then
            startup.boot_diag_checkpoint("REGION_PATTERN_SCAN", "name=" .. tostring(def.name) .. " family=" .. tostring(def.family), true)
        end

        local match, resultReason = nil, "not_found"
        local hit, moduleLabel = scan_raw(def.pattern, nil)
        if hit then match, resultReason = validate_hit(def, hit, moduleLabel) end

        if not match then
            for _, moduleName in ipairs(startup.region_scan_modules or {}) do
                local moduleHit, label = scan_raw(def.pattern, moduleName)
                if moduleHit then
                    local candidate, why = validate_hit(def, moduleHit, label)
                    if candidate then match, resultReason = candidate, why; break end
                    resultReason = why or resultReason
                end
                if Script and Script.Yield then Script.Yield(0) end
            end
        end

        if match then
            found = found + 1
            state.matches[#state.matches + 1] = match
            state.probeResults[#state.probeResults + 1] = {
                name=def.name, family=def.family, confidence=def.confidence, result="valid",
                label=match.label, value=match.value, moduleName=match.moduleName
            }
            local suffix = match.confidence == "source" and "" or " candidate"
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGION_PATTERN_FOUND",
                    "name=" .. tostring(def.name) .. " family=" .. tostring(def.family) ..
                    " confidence=" .. tostring(def.confidence) .. " region=" .. tostring(match.label) ..
                    " value=" .. tostring(match.value) .. " module=" .. tostring(match.moduleName) ..
                    " hit=0x" .. string.format("%X", tonumber(match.hit or 0) or 0) ..
                    " rip=0x" .. string.format("%X", tonumber(match.ripAt or 0) or 0) ..
                    " address=0x" .. string.format("%X", tonumber(match.address or 0) or 0))
            end
        else
            state.probeResults[#state.probeResults + 1] = {
                name=def.name, family=def.family, confidence=def.confidence, result=resultReason or "not_found"
            }
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGION_PATTERN_NOT_FOUND",
                    "name=" .. tostring(def.name) .. " family=" .. tostring(def.family) ..
                    " confidence=" .. tostring(def.confidence) .. " result=" .. tostring(resultReason))
            end
        end
    end

    -- Choose source-backed + active-edition candidates first, then source-backed cross-edition,
    -- then experimental active-edition candidates, then any remaining validated candidate.
    local function score(match)
        local n = 0
        if tostring(match.family) == preferredFamily then n = n + 100 end
        if tostring(match.confidence) == "source" then n = n + 50 end
        return n
    end
    table.sort(state.matches, function(a,b) return score(a) > score(b) end)

    local active = state.matches[1]
    if active then
        state.address, state.patternName, state.moduleName, state.lastValue = active.address, active.patternName, active.moduleName, active.value
        state.activeConfidence = tostring(active.confidence or "")
        if state.originalValue == nil then state.originalValue = active.value end
        state.lastStatus = "Ready: " .. tostring(active.label) .. " via " .. tostring(active.patternName)
        startup.log_colored("Patterns " .. tostring(found) .. "/" .. tostring(#eligible) .. " found!", "success")
        if active.confidence ~= "source" then
            startup.log_colored("Region pointer is experimental; verify with a temporary region change and restore Original after testing.", "warning")
        end
        return true
    end

    startup.log_colored("Patterns 0/" .. tostring(#eligible) .. " found!", "warning")
    startup.log_colored("No current Matchmaking Region signature matched; checking read-only fallbacks...", "warning")

    local featureLabel, featureSource = startup.probe_matchmaking_region_features()
    if featureLabel then
        state.fallbackLabel, state.fallbackSource = featureLabel, featureSource
        state.lastStatus = "Read-only fallback: " .. tostring(featureLabel) .. " via " .. tostring(featureSource)
        startup.log_colored("Region fallback: " .. tostring(featureLabel) .. " | " .. tostring(featureSource) .. ".", "success")
        return true
    end

    local heuristicLabel, heuristicSource = startup.run_region_structural_probes()
    if heuristicLabel then
        state.fallbackLabel, state.fallbackSource = heuristicLabel, heuristicSource
        state.lastStatus = "Read-only candidate: " .. tostring(heuristicLabel) .. " via structural probes"
        startup.log_colored("Region read-only candidate: " .. tostring(heuristicLabel) .. " | corroborated structural probes.", "warning")
        startup.log_colored("Region writes remain disabled until a current full signature is recovered.", "warning")
        return true
    end

    local geoLabel, geoSource = startup.estimate_region_from_local_ipinfo()
    if geoLabel then
        state.fallbackLabel, state.fallbackSource = geoLabel, geoSource
        state.lastStatus = "Estimated: " .. tostring(geoLabel) .. " via local IP geolocation"
        startup.log_colored("Region estimate: " .. tostring(geoLabel) .. " | local IP geolocation (read-only).", "warning")
        return true
    end

    state.lastStatus = "No current Region signature or safe fallback available"
    startup.log_colored("Matchmaking Region unavailable on this build; current signatures need updating.", "warning")
    return false
end


function startup.run_region_deep_scan()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    state.address, state.patternName, state.moduleName, state.lastValue = nil, "", "", nil
    state.activeConfidence = ""
    state.matches, state.probeResults = {}, {}
    state.fallbackLabel, state.fallbackSource = nil, nil
    state.featureProbeResults, state.localIpInfo = {}, {}
    state.heuristicCandidates, state.heuristicCorroborated = {}, false
    state.lastAttemptMs = startup.now()

    local deep = {
        running=true, totalCodes=#(startup.region_deep_scan_patterns or {}),
        totalMethods=#(startup.region_deep_scan_offsets or {}), codesCompleted=0,
        methodChecks=0, hits=0, validReads=0, stoppedEarly=false,
        bestCodeCount=0, bestMethodCount=0, bestLabel="", bestAddress=""
    }
    state.deepScan = deep

    if not Memory or not Memory.Scan or not Memory.Rip or not Memory.ReadInt then
        deep.running = false
        state.lastStatus = "Deep Region Scan unavailable: Memory API missing"
        startup.log_colored("Deep Region Scan unavailable: Memory API missing.", "error")
        return false
    end

    local patterns = startup.region_deep_scan_patterns or {}
    local offsets = startup.region_deep_scan_offsets or {}
    if #patterns ~= 50 or #offsets ~= 20 then
        deep.running = false
        state.lastStatus = "Deep Region Scan definition mismatch"
        startup.log_colored("Deep Region Scan definition mismatch; expected 50 codes x 20 methods.", "error")
        return false
    end

    local enhanced = startup.is_enhanced_active_edition()
    local preferredFamily = enhanced and "Enhanced" or "Legacy"
    local ordered = {}
    for _, def in ipairs(patterns) do if tostring(def.family) == preferredFamily then ordered[#ordered+1] = def end end
    for _, def in ipairs(patterns) do if tostring(def.family) ~= preferredFamily then ordered[#ordered+1] = def end end

    -- Read-only corroboration sources are collected before the code scan. They do not
    -- make a pointer writable by themselves; they only help distinguish a likely region
    -- value from random stable integers in the 0-7 range.
    local expectedLabels = {}
    local featureLabel, featureSource = startup.probe_matchmaking_region_features()
    if featureLabel then expectedLabels[tostring(featureLabel)] = tostring(featureSource or "Cherax feature") end
    local geoLabel, geoSource = startup.estimate_region_from_local_ipinfo()
    if geoLabel then expectedLabels[tostring(geoLabel)] = tostring(geoSource or "Local IP geolocation") end

    local function scan_once(pattern, moduleName, alternate)
        local ok, hit
        if moduleName == nil then
            ok, hit = direct_call(Memory.Scan, pattern)
        elseif alternate then
            ok, hit = direct_call(Memory.Scan, moduleName, pattern)
        else
            ok, hit = direct_call(Memory.Scan, pattern, moduleName)
        end
        hit = ok and tonumber(hit) or nil
        return hit and hit ~= 0 and hit or nil
    end

    local function collect_hits(def)
        -- One signature hit per code keeps the lab bounded at 50 x 20 = 1,000
        -- resolver checks maximum. Module names and both known argument orders are
        -- tried sequentially until the first non-zero hit is found.
        local hit = scan_once(def.pattern, nil, false)
        if hit then return {{hit=hit, moduleName="default"}} end
        for _, moduleName in ipairs(startup.region_scan_modules or {}) do
            hit = scan_once(def.pattern, moduleName, false)
            if hit then return {{hit=hit, moduleName=tostring(moduleName).." (pattern,module)"}} end
            hit = scan_once(def.pattern, moduleName, true)
            if hit then return {{hit=hit, moduleName=tostring(moduleName).." (module,pattern)"}} end
            if Script and Script.Yield then Script.Yield(0) end
        end
        return {}
    end

    local byAddress = {}
    local function register_candidate(def, hitRow, offset, address, value, label)
        local key = string.format("%X", address)
        local row = byAddress[key]
        if not row then
            row = {
                address=address, value=value, label=label, family=tostring(def.family or "Unknown"),
                moduleName=tostring(hitRow.moduleName or "default"), hit=hitRow.hit,
                codeNames={}, methodNames={}, codeCount=0, methodCount=0,
                sourceExact=false, corroboratedBy=nil
            }
            byAddress[key] = row
        end
        if not row.codeNames[def.name] then row.codeNames[def.name]=true; row.codeCount=row.codeCount+1 end
        local methodName = "RIP+"..tostring(offset)
        if not row.methodNames[methodName] then row.methodNames[methodName]=true; row.methodCount=row.methodCount+1 end
        if def.sourceExact == true then row.sourceExact = true end
        row.corroboratedBy = expectedLabels[tostring(label)] or row.corroboratedBy
        deep.validReads = deep.validReads + 1
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_DEEP_CANDIDATE",
                "code="..tostring(def.name).." family="..tostring(def.family)..
                " method="..methodName.." label="..tostring(label).." value="..tostring(value)..
                " hit=0x"..string.format("%X", tonumber(hitRow.hit or 0) or 0)..
                " address=0x"..string.format("%X", tonumber(address or 0) or 0)..
                " module="..tostring(hitRow.moduleName or "default"))
        end
        return row
    end

    local function is_strong(row)
        if not row then return false end
        if row.sourceExact == true then return true end
        -- Broad scan discoveries become writable only when multiple code variants converge
        -- and an independent read-only source reports the same region label.
        return row.codeCount >= 3 and row.methodCount >= 1 and row.corroboratedBy ~= nil
    end

    local function best_candidate()
        local best, bestScore = nil, -1
        for _, row in pairs(byAddress) do
            local score = row.codeCount * 100 + row.methodCount
            if row.family == preferredFamily then score = score + 50 end
            if row.corroboratedBy then score = score + 500 end
            if row.sourceExact then score = score + 2000 end
            if score > bestScore then best, bestScore = row, score end
        end
        return best
    end

    startup.log_colored("Deep Region Scan started: 50 codes x 20 resolver methods.", "info")
    startup.log_colored("This manual scan is read-only until a result is strongly corroborated.", "warning")
    state.lastStatus = "Deep scan running: 0/50 codes"
    startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_DEEP_SCAN_BEGIN", "codes=50 methods=20 preferred="..preferredFamily)
    end

    local stopRow = nil
    for index, def in ipairs(ordered) do
        deep.codesCompleted = index
        state.lastStatus = "Deep scan running: "..tostring(index).."/50 | "..tostring(def.name)
        startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
        startup.log_colored("Region code "..tostring(index).."/50: "..tostring(def.name).."...", "info")
        if startup.boot_diag_checkpoint then
            startup.boot_diag_checkpoint("REGION_DEEP_CODE", "index="..index.." name="..tostring(def.name), true)
        end

        local hits = collect_hits(def)
        deep.hits = deep.hits + #hits
        local validForCode = 0
        for _, hitRow in ipairs(hits) do
            for _, offset in ipairs(offsets) do
                deep.methodChecks = deep.methodChecks + 1
                local okRip, address = direct_call(Memory.Rip, tonumber(hitRow.hit) + tonumber(offset))
                address = okRip and tonumber(address) or nil
                if address and address ~= 0 then
                    local ok1, v1 = direct_call(Memory.ReadInt, address)
                    v1 = ok1 and tonumber(v1) or nil
                    local label = v1 ~= nil and startup.region_names[v1] or nil
                    if label then
                        if Script and Script.Yield then Script.Yield(0) end
                        local ok2, v2 = direct_call(Memory.ReadInt, address)
                        if Script and Script.Yield then Script.Yield(0) end
                        local ok3, v3 = direct_call(Memory.ReadInt, address)
                        v2, v3 = ok2 and tonumber(v2) or nil, ok3 and tonumber(v3) or nil
                        if v2 == v1 and v3 == v1 then
                            register_candidate(def, hitRow, offset, address, v1, label)
                            validForCode = validForCode + 1
                        end
                    end
                end
                if Script and Script.Yield then Script.Yield(0) end
            end
        end

        if #hits == 0 then
            startup.log_colored("Region code "..tostring(index).."/50: no signature hit.", "error")
        elseif validForCode == 0 then
            startup.log_colored("Region code "..tostring(index).."/50: hit found, but no stable Region pointer.", "warning")
        else
            startup.log_colored("Region code "..tostring(index).."/50: "..tostring(validForCode).." stable Region read(s).", "success")
        end
        state.probeResults[#state.probeResults+1] = {
            name=def.name, family=def.family, confidence="deep",
            result=(#hits == 0 and "no_hit" or (validForCode > 0 and ("stable_reads:"..validForCode) or "no_valid_pointer"))
        }
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_DEEP_CODE",
                "index="..index.." name="..tostring(def.name).." family="..tostring(def.family)..
                " hits="..tostring(#hits).." stableReads="..tostring(validForCode)..
                " methodChecks="..tostring(deep.methodChecks))
        end

        local currentBest = best_candidate()
        if currentBest then
            deep.bestCodeCount = currentBest.codeCount
            deep.bestMethodCount = currentBest.methodCount
            deep.bestLabel = tostring(currentBest.label or "")
            deep.bestAddress = "0x"..string.format("%X", tonumber(currentBest.address or 0) or 0)
        end
        if is_strong(currentBest) then
            stopRow = currentBest
            deep.stoppedEarly = true
            startup.log_colored("Strong Region candidate corroborated; stopping the deep scan early.", "success")
            break
        end
        if Script and Script.Yield then Script.Yield(1) end
    end

    local best = stopRow or best_candidate()
    deep.running = false

    if best and is_strong(best) then
        state.address = best.address
        state.patternName = "Deep Scan ("..tostring(best.codeCount).." codes)"
        state.moduleName = best.moduleName
        state.lastValue = best.value
        state.activeConfidence = best.sourceExact and "source" or "deep-corroborated"
        if state.originalValue == nil then state.originalValue = best.value end
        state.matches = {{
            address=best.address, hit=best.hit, patternName=state.patternName,
            moduleName=best.moduleName, value=best.value, label=best.label,
            family=best.family, confidence=state.activeConfidence,
            codeCount=best.codeCount, methodCount=best.methodCount
        }}
        state.lastStatus = "Ready: "..tostring(best.label).." via Deep Region Scan"
        startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
        startup.log_colored("Deep Region Scan found a corroborated pointer: "..tostring(best.label)..".", "success")
        startup.log_colored("Evidence: "..tostring(best.codeCount).." code(s), "..tostring(best.methodCount).." resolver method(s)"..
            (best.corroboratedBy and (", "..tostring(best.corroboratedBy)) or "")..".", "success")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_DEEP_SCAN_SUCCESS",
                "label="..tostring(best.label).." value="..tostring(best.value)..
                " address=0x"..string.format("%X", tonumber(best.address or 0) or 0)..
                " codes="..tostring(best.codeCount).." methods="..tostring(best.methodCount)..
                " corroboration="..tostring(best.corroboratedBy or "source exact")..
                " stoppedEarly="..tostring(deep.stoppedEarly))
        end
        return true
    end

    if best then
        state.fallbackLabel = best.label
        state.fallbackSource = "Deep scan candidate: "..tostring(best.codeCount).." code(s), "..tostring(best.methodCount).." method(s); read-only"
        state.lastStatus = "Deep scan found an uncorroborated read-only candidate: "..tostring(best.label)
        startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
        startup.log_colored("Deep Region Scan found a possible "..tostring(best.label).." pointer, but it is not corroborated.", "warning")
        startup.log_colored("Region writes remain disabled. Create a Support ZIP so we can inspect the candidate.", "warning")
    else
        state.lastStatus = "Deep scan completed: no stable Region pointer found"
        startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
        startup.log_colored("Deep Region Scan completed all 50 codes; no stable Region pointer was found.", "warning")
    end

    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_DEEP_SCAN_END",
            "codesCompleted="..tostring(deep.codesCompleted).." methodChecks="..tostring(deep.methodChecks)..
            " hits="..tostring(deep.hits).." stableReads="..tostring(deep.validReads)..
            " bestLabel="..tostring(deep.bestLabel).." bestCodes="..tostring(deep.bestCodeCount)..
            " bestMethods="..tostring(deep.bestMethodCount).." stoppedEarly="..tostring(deep.stoppedEarly))
    end

    -- Existing safe fallbacks still run after the full manual lab when no writable pointer exists.
    if not state.fallbackLabel then
        local fallbackFeature, fallbackFeatureSource = featureLabel, featureSource
        if fallbackFeature then
            state.fallbackLabel, state.fallbackSource = fallbackFeature, fallbackFeatureSource
            state.lastStatus = "Read-only fallback: "..tostring(fallbackFeature).." via "..tostring(fallbackFeatureSource)
            return true
        end
        local heuristicLabel, heuristicSource = startup.run_region_structural_probes()
        if heuristicLabel then
            state.fallbackLabel, state.fallbackSource = heuristicLabel, heuristicSource
            state.lastStatus = "Read-only candidate: "..tostring(heuristicLabel).." via structural probes"
            return true
        end
        if geoLabel then
            state.fallbackLabel, state.fallbackSource = geoLabel, geoSource
            state.lastStatus = "Estimated: "..tostring(geoLabel).." via local IP geolocation"
            return true
        end
    end
    return state.fallbackLabel ~= nil
end


-- Build 056 manual Legacy IDB scan.
-- This replaces blind wildcard expansion on LE with real dump-derived anchors. It can prove
-- that the current executable still contains the modern region matchmaking code and recover
-- the MMATTR_REGION string/token addresses, but it deliberately never assigns state.address.
function startup.run_region_dump_scan()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    state.address, state.patternName, state.moduleName, state.lastValue = nil, "", "", nil
    state.activeConfidence = ""
    state.matches, state.probeResults = {}, {}
    state.fallbackLabel, state.fallbackSource = nil, nil
    state.featureProbeResults, state.localIpInfo = {}, {}
    state.lastAttemptMs = startup.now()

    local anchors = startup.region_dump_scan_anchors or {}
    local scan = {
        running=true, totalAnchors=#anchors, anchorsCompleted=0, hits=0,
        mmattrTarget="", forceTokenTarget="", mmattrCorroborated=false,
        forceTokenCorroborated=false, mappingFound=false, compatible=false,
        lastStatus="Running"
    }
    state.dumpScan = scan

    if not Memory or not Memory.Scan then
        scan.running = false
        scan.lastStatus = "Memory.Scan unavailable"
        state.lastStatus = "Legacy IDB scan unavailable: Memory.Scan missing"
        startup.log_colored("Legacy IDB Region Scan unavailable: Memory.Scan missing.", "error")
        return false
    end

    local function scan_once(pattern, moduleName, alternate)
        local ok, hit
        if moduleName == nil then
            ok, hit = direct_call(Memory.Scan, pattern)
        elseif alternate then
            ok, hit = direct_call(Memory.Scan, moduleName, pattern)
        else
            ok, hit = direct_call(Memory.Scan, pattern, moduleName)
        end
        hit = ok and tonumber(hit) or nil
        return hit and hit ~= 0 and hit or nil
    end

    local function find_hit(pattern)
        local hit = scan_once(pattern, nil, false)
        if hit then return hit, "default" end
        for _, moduleName in ipairs({"GTA5.exe", "GTA5", "GTA5.exe+0"}) do
            hit = scan_once(pattern, moduleName, false)
            if hit then return hit, tostring(moduleName).." (pattern,module)" end
            hit = scan_once(pattern, moduleName, true)
            if hit then return hit, tostring(moduleName).." (module,pattern)" end
            if Script and Script.Yield then Script.Yield(0) end
        end
        return nil, ""
    end

    local groupTargets = { mmattr_string={}, force_region_token={} }
    local function register_target(group, target)
        if not groupTargets[group] or not target or target == 0 then return end
        local key = string.format("%X", target)
        local row = groupTargets[group][key]
        if not row then row={address=target,count=0}; groupTargets[group][key]=row end
        row.count = row.count + 1
    end
    local function best_target(group)
        local best
        for _, row in pairs(groupTargets[group] or {}) do
            if not best or row.count > best.count then best = row end
        end
        return best
    end

    startup.log_colored("Legacy IDB Region Scan started: "..tostring(#anchors).." real dump-derived anchors.", "info")
    startup.log_colored("This scan is read-only. It will not enable Region writes.", "warning")
    state.lastStatus = "Legacy IDB scan running: 0/"..tostring(#anchors)
    startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_IDB_SCAN_BEGIN", "edition=Legacy anchors="..tostring(#anchors))
    end

    for index, def in ipairs(anchors) do
        scan.anchorsCompleted = index
        state.lastStatus = "Legacy IDB scan running: "..tostring(index).."/"..tostring(#anchors)
        startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
        local hit, moduleName = find_hit(def.pattern)
        local target
        if hit then
            scan.hits = scan.hits + 1
            if def.group == "region_mapping" then scan.mappingFound = true end
            if def.ripOffset ~= nil and Memory.Rip then
                local okRip, value = direct_call(Memory.Rip, hit + tonumber(def.ripOffset or 0))
                target = okRip and tonumber(value) or nil
                if target and target ~= 0 then register_target(def.group, target) end
            end
            startup.log_colored(tostring(def.name).." found!", "success")
        else
            startup.log_colored(tostring(def.name).." not found!", "error")
        end
        state.probeResults[#state.probeResults+1] = {
            name=tostring(def.name), family="Legacy IDB", result=hit and "found" or "not_found",
            hit=hit, target=target, moduleName=moduleName
        }
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_IDB_ANCHOR",
                "index="..tostring(index).." name="..tostring(def.name).." group="..tostring(def.group or "anchor")..
                " result="..tostring(hit and "found" or "not_found")..
                " hit="..tostring(hit and ("0x"..string.format("%X", hit)) or "none")..
                " target="..tostring(target and ("0x"..string.format("%X", target)) or "none")..
                " module="..tostring(moduleName or ""))
        end
        if Script and Script.Yield then Script.Yield(1) end
    end

    local mmattr = best_target("mmattr_string")
    local force = best_target("force_region_token")
    scan.mmattrCorroborated = mmattr ~= nil and tonumber(mmattr.count or 0) >= 2
    scan.forceTokenCorroborated = force ~= nil and tonumber(force.count or 0) >= 3
    scan.mmattrTarget = mmattr and ("0x"..string.format("%X", mmattr.address)) or ""
    scan.forceTokenTarget = force and ("0x"..string.format("%X", force.address)) or ""
    scan.compatible = scan.mappingFound and scan.mmattrCorroborated and scan.forceTokenCorroborated
    scan.running = false

    if scan.compatible then
        state.patternName = "Legacy IDB matchmaking anchors"
        state.moduleName = "current Legacy executable"
        state.activeConfidence = "dump-verified-read-only"
        state.lastStatus = "Legacy IDB region code verified: "..tostring(scan.hits).."/"..tostring(#anchors).." anchors. Writable field not yet identified."
        scan.lastStatus = state.lastStatus
        startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
        startup.log_colored("Legacy matchmaking region code verified from the IDA dump!", "success")
        startup.log_colored("MMATTR_REGION target: "..tostring(scan.mmattrTarget).." | Force-region initializer reference: "..tostring(scan.forceTokenTarget)..".", "success")
        startup.log_colored("The live writable Region field is not proven yet, so override remains disabled.", "warning")
    else
        state.lastStatus = "Legacy IDB scan matched "..tostring(scan.hits).."/"..tostring(#anchors).." anchors; current executable differs from the dump."
        scan.lastStatus = state.lastStatus
        startup.s.matchmakingRegionOverrideLastStatus = state.lastStatus
        startup.log_colored("Legacy IDB Region Scan matched "..tostring(scan.hits).."/"..tostring(#anchors).." anchors.", scan.hits > 0 and "warning" or "error")
        startup.log_colored("A current-build Legacy dump may be needed if the core anchors do not corroborate.", "warning")
    end

    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_IDB_SCAN_END",
            "hits="..tostring(scan.hits).."/"..tostring(#anchors)..
            " mapping="..tostring(scan.mappingFound)..
            " mmattrCorroborated="..tostring(scan.mmattrCorroborated).." mmattrTarget="..tostring(scan.mmattrTarget)..
            " forceCorroborated="..tostring(scan.forceTokenCorroborated).." forceTarget="..tostring(scan.forceTokenTarget)..
            " compatible="..tostring(scan.compatible))
    end

    -- Keep the existing read-only fallbacks for a visible label. They do not make the
    -- dump-derived code anchors writable.
    local featureLabel, featureSource = startup.probe_matchmaking_region_features()
    if featureLabel then
        state.fallbackLabel, state.fallbackSource = featureLabel, featureSource
    else
        local geoLabel, geoSource = startup.estimate_region_from_local_ipinfo()
        if geoLabel then state.fallbackLabel, state.fallbackSource = geoLabel, geoSource end
    end
    return scan.compatible or state.fallbackLabel ~= nil
end


-- Build 057 Legacy live Region field trace.
-- The Support ZIP proved that all eight modern Legacy matchmaking anchors match the current
-- executable. This second stage uses those verified addresses to inspect a small, bounded set
-- of IDB-guided projections and in-module pointers. It is strictly read-only and never assigns
-- region_scan.address. A trace result is evidence for the next build, not permission to write.
function startup.run_legacy_region_live_trace()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    local dump = state.dumpScan or {}
    local ref = startup.region_idb_reference or {}
    local trace = {
        running=true, phase="PE section map", rootsScanned=0, pointerPaths=0,
        stableCandidates=0, corroborated=false, bestAddress="", bestValue=nil,
        bestLabel="", bestSources=0, bestSection="", lastStatus="Running",
        moduleBase="", sectionCount=0, sectionMapStatus="Not mapped", ripTargets=0,
        writableRoots=0, externalRoots=0, objectRoots=0, rejectedExecutable=0,
        rejectedReadOnly=0, delayedStable=0, candidates={}, sections={}, consumerRoots={},
        xrefs={}, dataRoots={}, objectRootRows={}
    }
    state.runtimeTrace = trace

    if dump.compatible ~= true then
        trace.running = false
        trace.lastStatus = "Skipped: Legacy IDB anchors are not corroborated"
        return false
    end
    if not Memory or not Memory.ReadInt then
        trace.running = false
        trace.lastStatus = "Unavailable: Memory.ReadInt missing"
        startup.log_colored("Legacy live Region trace unavailable: Memory.ReadInt missing.", "error")
        return false
    end

    local function hex(value)
        value = tonumber(value)
        return value and ("0x"..string.format("%X", value)) or "none"
    end
    local function parse_hex(value)
        if type(value) == "number" then return value end
        local textValue = tostring(value or "")
        local parsed = tonumber(textValue:match("^0[xX]([0-9A-Fa-f]+)$"), 16)
        return parsed or tonumber(value)
    end
    local function u32(value)
        value = tonumber(value)
        if value == nil then return nil end
        if value < 0 then return value + 4294967296 end
        return value
    end
    local readCounter = 0
    local function maybe_yield()
        readCounter = readCounter + 1
        if readCounter % 96 == 0 and Script and Script.Yield then Script.Yield(0) end
    end
    local function read_int(address)
        address = tonumber(address)
        if not address or address <= 0 then return nil end
        local ok, value = direct_call(Memory.ReadInt, address)
        maybe_yield()
        return ok and tonumber(value) or nil
    end
    local function read_u32(address)
        if Memory.ReadUInt then
            local ok, value = direct_call(Memory.ReadUInt, address)
            maybe_yield()
            if ok and value ~= nil then return tonumber(value) end
        end
        return u32(read_int(address))
    end
    local function read_u16(address)
        if Memory.ReadUShort then
            local ok, value = direct_call(Memory.ReadUShort, address)
            maybe_yield()
            if ok and value ~= nil then return tonumber(value) end
        end
        if Memory.ReadShort then
            local ok, value = direct_call(Memory.ReadShort, address)
            maybe_yield()
            if ok and value ~= nil then
                value=tonumber(value); if value and value < 0 then value=value+65536 end
                return value
            end
        end
        local a = nil
        if Memory.ReadUByte then
            local ok,v=direct_call(Memory.ReadUByte,address); maybe_yield(); if ok then a=tonumber(v) end
        end
        local b = nil
        if Memory.ReadUByte then
            local ok,v=direct_call(Memory.ReadUByte,address+1); maybe_yield(); if ok then b=tonumber(v) end
        end
        return a and b and (a+b*256) or nil
    end
    local function read_u8(address)
        if Memory.ReadUByte then
            local ok, value = direct_call(Memory.ReadUByte, address)
            maybe_yield()
            if ok and value ~= nil then return tonumber(value) end
        end
        if Memory.ReadByte then
            local ok, value = direct_call(Memory.ReadByte, address)
            maybe_yield()
            if ok and value ~= nil then
                value=tonumber(value); if value and value < 0 then value=value+256 end
                return value
            end
        end
        return nil
    end
    local function read_pointer(address)
        address=tonumber(address)
        if not address then return nil end
        if Memory.ReadLong then
            local ok, value = direct_call(Memory.ReadLong, address)
            maybe_yield()
            value = ok and tonumber(value) or nil
            if value and value > 0 and value < 140737488355328 then return value end
        end
        local lo, hi = read_u32(address), read_u32(address + 4)
        if lo == nil or hi == nil then return nil end
        local value = lo + hi * 4294967296
        if value > 0 and value < 140737488355328 then return value end
        return nil
    end
    local function stable_int(address)
        local a,b,c=read_int(address),read_int(address),read_int(address)
        if a ~= nil and a == b and b == c then return a end
        return nil
    end
    local function plausible_pointer(address)
        address=tonumber(address)
        return address ~= nil and address >= 65536 and address < 140737488355328 and address % 4 == 0
    end

    -- Parse the live PE section table. Build 057 accidentally elevated a value eight bytes
    -- before a code pointer. A valid region field must never live in an executable section.
    local moduleBase
    if Memory.GetBaseAddress then
        for _, moduleName in ipairs({"GTA5.exe", "GTA5", ""}) do
            local ok, value
            if moduleName == "" then ok,value=direct_call(Memory.GetBaseAddress)
            else ok,value=direct_call(Memory.GetBaseAddress,moduleName) end
            value=ok and tonumber(value) or nil
            if value and value > 0 then moduleBase=value; break end
        end
    end
    local sections, imageEnd = {}, nil
    local function characteristic_set(value, flag)
        value=u32(value)
        if value == nil then return false end
        return math.floor(value / flag) % 2 == 1
    end
    local function parse_sections(base)
        if not base then return false,"Memory.GetBaseAddress failed" end
        local peOffset=read_u32(base+0x3C)
        if not peOffset or peOffset <= 0 or peOffset > 0x2000 then return false,"Invalid PE header offset" end
        local nt=base+peOffset
        local signature=read_u32(nt)
        if signature ~= 0x4550 then return false,"PE signature missing" end
        local sectionCount=read_u16(nt+6)
        local optionalSize=read_u16(nt+20)
        if not sectionCount or sectionCount < 1 or sectionCount > 32 or not optionalSize then return false,"Invalid PE section count" end
        local sectionTable=nt+24+optionalSize
        for index=0,sectionCount-1 do
            local rowAddress=sectionTable+index*40
            local chars={}
            for j=0,7 do
                local byte=read_u8(rowAddress+j)
                if not byte or byte == 0 then break end
                chars[#chars+1]=string.char(byte)
            end
            local name=table.concat(chars)
            local virtualSize=read_u32(rowAddress+8) or 0
            local virtualAddress=read_u32(rowAddress+12) or 0
            local rawSize=read_u32(rowAddress+16) or 0
            local characteristics=read_u32(rowAddress+36) or 0
            local size=math.max(virtualSize,rawSize)
            local section={
                name=name ~= "" and name or ("section"..tostring(index)),
                start=base+virtualAddress, finish=base+virtualAddress+size,
                virtualSize=virtualSize, characteristics=characteristics,
                executable=characteristic_set(characteristics,0x20000000),
                readable=characteristic_set(characteristics,0x40000000),
                writable=characteristic_set(characteristics,0x80000000)
            }
            sections[#sections+1]=section
            if not imageEnd or section.finish > imageEnd then imageEnd=section.finish end
            trace.sections[#trace.sections+1]={name=section.name,start=hex(section.start),finish=hex(section.finish),executable=section.executable,writable=section.writable}
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGION_PE_SECTION",
                    "name="..section.name.." start="..hex(section.start).." finish="..hex(section.finish)..
                    " executable="..tostring(section.executable).." readable="..tostring(section.readable)..
                    " writable="..tostring(section.writable))
            end
        end
        return true,"Mapped "..tostring(#sections).." PE sections"
    end
    local sectionOk,sectionStatus=parse_sections(moduleBase)
    trace.moduleBase=hex(moduleBase)
    trace.sectionCount=#sections
    trace.sectionMapStatus=sectionStatus
    local function classify(address)
        address=tonumber(address)
        for _,section in ipairs(sections) do
            if address and address >= section.start and address < section.finish then
                return section,section.name
            end
        end
        if moduleBase and imageEnd and address and address >= moduleBase and address < imageEnd then
            return {name="module-gap",executable=false,writable=false,readable=true},"module-gap"
        end
        return {name="external",executable=false,writable=true,readable=true,external=true},"external"
    end

    local probeByName, consumerRoots = {}, {}
    for _,row in ipairs(state.probeResults or {}) do if row.name then probeByName[tostring(row.name)]=row end end
    for name,_ in pairs(ref.consumerHits or {}) do
        local row=probeByName[name]
        if row and tonumber(row.hit) then consumerRoots[#consumerRoots+1]={name=name,address=tonumber(row.hit)} end
    end
    table.sort(consumerRoots,function(a,b) return a.address < b.address end)
    trace.rootsScanned=#consumerRoots
    for _,row in ipairs(consumerRoots) do
        trace.consumerRoots[#trace.consumerRoots+1]={name=tostring(row.name or "Consumer"),address=hex(row.address)}
    end

    local expectedLabel=tostring(state.fallbackLabel or "")
    local expectedValue=startup.region_value_by_label[expectedLabel]
    startup.log_colored("Legacy live Region xref trace started from the verified 8/8 IDB anchors.","info")
    startup.log_colored("PE sections are enforced; executable/read-only candidates cannot be promoted.","info")
    startup.log_colored("Trace is read-only; no candidate can enable Region writes in this build.","warning")
    state.lastStatus="Legacy xref trace running"
    startup.s.matchmakingRegionOverrideLastStatus=state.lastStatus
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_LIVE_TRACE_BEGIN",
            "version=2 roots="..tostring(#consumerRoots).." moduleBase="..hex(moduleBase)..
            " peMapped="..tostring(sectionOk).." sections="..tostring(#sections)..
            " expected="..tostring(expectedLabel ~= "" and expectedLabel or "none"))
    end

    -- Decode common x64 RIP-relative LEA/MOV references around the verified consumers.
    local registerNames={"RAX","RCX","RDX","RBX","RSP","RBP","RSI","RDI","R8","R9","R10","R11","R12","R13","R14","R15"}
    local function decode_rip(address)
        local b0,b1,b2,b3=read_u8(address),read_u8(address+1),read_u8(address+2),read_u8(address+3)
        if not b0 then return nil end
        local rex,opcode,modrm,dispAddress,length,prefixLength,kind
        if b0 >= 0x40 and b0 <= 0x4F and b1 then
            rex,opcode,modrm,prefixLength=b0,b1,b2,1
            if opcode==0x8D or opcode==0x8B or opcode==0x89 then
                dispAddress,length=address+3,7
                kind=opcode==0x8D and "LEA" or (opcode==0x8B and "MOV_LOAD" or "MOV_STORE")
            end
        elseif b0==0x8D or b0==0x8B or b0==0x89 then
            rex,opcode,modrm,prefixLength=0,b0,b1,0
            dispAddress,length=address+2,6
            kind=opcode==0x8D and "LEA" or (opcode==0x8B and "MOV_LOAD" or "MOV_STORE")
        elseif b0==0xC7 and b1==0x05 then
            rex,opcode,modrm,prefixLength=0,b0,b1,0
            dispAddress,length=address+2,10
            kind="MOV_IMMEDIATE"
        elseif b0==0xF3 and b1==0x0F and (b2==0x10 or b2==0x11) then
            rex,opcode,modrm,prefixLength=0,b2,b3,2
            dispAddress,length=address+4,8
            kind=b2==0x10 and "SSE_LOAD" or "SSE_STORE"
        elseif b0==0x0F and (b1==0x10 or b1==0x11) then
            rex,opcode,modrm,prefixLength=0,b1,b2,1
            dispAddress,length=address+3,7
            kind=b1==0x10 and "SSE_LOAD" or "SSE_STORE"
        end
        if not modrm or math.floor(modrm/64) ~= 0 or modrm % 8 ~= 5 or not dispAddress then return nil end
        local displacement=read_int(dispAddress)
        if displacement==nil then return nil end
        local register=math.floor(modrm/8)%8
        if rex and math.floor(rex/4)%2==1 then register=register+8 end
        return {instruction=address,target=address+length+displacement,length=length,kind=kind,register=registerNames[register+1] or tostring(register)}
    end

    local xrefs,seenXref={},{}
    for _,root in ipairs(consumerRoots) do
        for offset=-0x180,0x1C0 do
            local decoded=decode_rip(root.address+offset)
            if decoded and plausible_pointer(decoded.target) then
                local key=hex(decoded.instruction)..":"..hex(decoded.target)..":"..decoded.kind
                if not seenXref[key] then
                    seenXref[key]=true
                    decoded.source=root.name; decoded.sourceOffset=offset
                    local section,sectionName=classify(decoded.target)
                    decoded.section=sectionName; decoded.executable=section.executable; decoded.writable=section.writable; decoded.external=section.external==true
                    xrefs[#xrefs+1]=decoded
                    if startup.support_log_event_quiet then
                        startup.support_log_event_quiet("REGION_LIVE_TRACE_XREF",
                            "source="..root.name.." sourceOffset="..tostring(offset).." instruction="..hex(decoded.instruction)..
                            " kind="..decoded.kind.." register="..decoded.register.." target="..hex(decoded.target)..
                            " section="..sectionName.." executable="..tostring(decoded.executable).." writable="..tostring(decoded.writable))
                    end
                end
            end
        end
        if Script and Script.Yield then Script.Yield(1) end
    end
    trace.ripTargets=#xrefs
    for _,row in ipairs(xrefs) do
        trace.xrefs[#trace.xrefs+1]={
            source=tostring(row.source or ""), instruction=hex(row.instruction), target=hex(row.target),
            kind=tostring(row.kind or ""), register=tostring(row.register or ""), section=tostring(row.section or ""),
            executable=row.executable==true, writable=row.writable==true, external=row.external==true
        }
    end

    local dataRoots,objectRoots={},{}
    local dataRootMap,objectRootMap={},{}
    local function add_data_root(address,source,kind,weight)
        address=tonumber(address); if not plausible_pointer(address) then return end
        local section,sectionName=classify(address)
        if section.executable then trace.rejectedExecutable=trace.rejectedExecutable+1; return end
        if not section.writable and not section.external then trace.rejectedReadOnly=trace.rejectedReadOnly+1; return end
        local key=hex(address)
        local row=dataRootMap[key]
        if not row then
            row={address=address,sources={},sourceCount=0,section=sectionName,kind=kind or "data",weight=tonumber(weight) or 1}
            dataRootMap[key]=row; dataRoots[#dataRoots+1]=row
            if section.external then trace.externalRoots=trace.externalRoots+1 else trace.writableRoots=trace.writableRoots+1 end
        end
        source=tostring(source or kind or "root")
        if not row.sources[source] then row.sources[source]=true; row.sourceCount=row.sourceCount+1 end
    end
    local function add_object_root(address,source,kind,weight)
        address=tonumber(address); if not plausible_pointer(address) then return end
        local section,sectionName=classify(address)
        if section.executable then trace.rejectedExecutable=trace.rejectedExecutable+1; return end
        if not section.external and not section.writable then trace.rejectedReadOnly=trace.rejectedReadOnly+1; return end
        local key=hex(address)
        local row=objectRootMap[key]
        if not row then
            row={address=address,sources={},sourceCount=0,section=sectionName,kind=kind or "object",weight=tonumber(weight) or 1}
            objectRootMap[key]=row; objectRoots[#objectRoots+1]=row
        end
        source=tostring(source or kind or "object")
        if not row.sources[source] then row.sources[source]=true; row.sourceCount=row.sourceCount+1 end
    end

    for _,xref in ipairs(xrefs) do
        if not xref.executable and (xref.writable or xref.external) then
            add_data_root(xref.target,xref.source..":"..xref.kind,xref.kind,6)
        end
        if xref.kind=="MOV_LOAD" then
            local pointer=read_pointer(xref.target)
            if plausible_pointer(pointer) then
                add_object_root(pointer,xref.source..":"..xref.register,"MOV_LOAD pointer",xref.register=="RBX" and 12 or 7)
            end
        elseif xref.kind=="LEA" and not xref.executable and (xref.writable or xref.external) then
            add_object_root(xref.target,xref.source..":"..xref.register,"LEA object",xref.register=="RBX" and 10 or 5)
        end
    end

    local candidates={}
    local function register_candidate(address,value,source,detail,weight,layoutHint)
        address,value=tonumber(address),tonumber(value)
        if not address or not startup.region_names[value] then return end
        local section,sectionName=classify(address)
        if section.executable then trace.rejectedExecutable=trace.rejectedExecutable+1; return end
        if not section.writable and not section.external then trace.rejectedReadOnly=trace.rejectedReadOnly+1; return end
        local key=hex(address)
        local row=candidates[key]
        if not row then
            row={address=address,value=value,label=startup.region_names[value],sources={},sourceCount=0,score=0,details={},section=sectionName,layoutHint=false}
            candidates[key]=row
        end
        if row.value~=value then return end
        source=tostring(source or "candidate")
        if not row.sources[source] then row.sources[source]=true; row.sourceCount=row.sourceCount+1 end
        row.details[#row.details+1]=tostring(detail or source)
        row.score=row.score+(tonumber(weight) or 1)
        if layoutHint then row.layoutHint=true; row.score=row.score+8 end
        if expectedValue~=nil and value==expectedValue then row.matchesExpected=true; row.score=row.score+2 end
        if value~=0 then row.score=row.score+1 end
    end
    local function inspect_values(base,fromOffset,toOffset,source,weight,layoutCenter)
        for offset=fromOffset,toOffset,4 do
            local address=base+offset
            local value=stable_int(address)
            if value~=nil and startup.region_names[value] then
                local layoutHint=layoutCenter and math.abs(offset-layoutCenter)<=0x30
                register_candidate(address,value,source,"field="..string.format("%+d",offset),weight,layoutHint)
            end
        end
    end

    for _,root in ipairs(dataRoots) do
        inspect_values(root.address,-0x40,0x100,"Data:"..root.section..":"..root.kind,root.weight,nil)
        for offset=-0x20,0x80,8 do
            local pointer=read_pointer(root.address+offset)
            if plausible_pointer(pointer) then add_object_root(pointer,"Data pointer:"..root.section,"data-pointer",5) end
        end
    end

    -- Follow a bounded set of object pointers. Consumer B/C/D explicitly operate on an
    -- object member at +0x160, so that neighborhood receives a layout hint but remains read-only.
    local objectIndex=1
    while objectIndex<=#objectRoots and objectIndex<=48 do
        local root=objectRoots[objectIndex]
        inspect_values(root.address,-0x40,0x100,"Object:"..root.kind,root.weight,nil)
        inspect_values(root.address+0x160,-0x80,0x100,"Object+0x160:"..root.kind,root.weight+4,0)
        local memberPointer=read_pointer(root.address+0x160)
        if plausible_pointer(memberPointer) then add_object_root(memberPointer,"Member+0x160:"..root.kind,"member-pointer",8) end
        if objectIndex<=24 then
            for offset=0,0x220,8 do
                local pointer=read_pointer(root.address+offset)
                if plausible_pointer(pointer) then
                    local targetSection=classify(pointer)
                    if not targetSection.executable then add_object_root(pointer,"Object chain:"..root.kind,"object-chain",3) end
                end
            end
        end
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_LIVE_TRACE_OBJECT",
                "index="..tostring(objectIndex).." address="..hex(root.address).." section="..tostring(root.section)..
                " kind="..tostring(root.kind).." sources="..tostring(root.sourceCount))
        end
        objectIndex=objectIndex+1
        if Script and Script.Yield then Script.Yield(0) end
    end
    trace.objectRoots=math.min(#objectRoots,48)
    trace.pointerPaths=#dataRoots+#objectRoots
    for _,row in ipairs(dataRoots) do
        trace.dataRoots[#trace.dataRoots+1]={address=hex(row.address),section=tostring(row.section or ""),kind=tostring(row.kind or "data"),sourceCount=tonumber(row.sourceCount or 0) or 0,weight=tonumber(row.weight or 0) or 0}
    end
    for index,row in ipairs(objectRoots) do
        if index>48 then break end
        trace.objectRootRows[#trace.objectRootRows+1]={address=hex(row.address),section=tostring(row.section or ""),kind=tostring(row.kind or "object"),sourceCount=tonumber(row.sourceCount or 0) or 0,weight=tonumber(row.weight or 0) or 0}
    end

    local ordered={}
    for _,row in pairs(candidates) do ordered[#ordered+1]=row end
    table.sort(ordered,function(a,b)
        if a.sourceCount~=b.sourceCount then return a.sourceCount>b.sourceCount end
        if a.layoutHint~=b.layoutHint then return a.layoutHint==true end
        if a.score~=b.score then return a.score>b.score end
        return a.address<b.address
    end)

    -- Delayed stability rejects transient counters/flags that happened to equal 0-7 during
    -- the first millisecond of the trace.
    local delayed={}
    for index,row in ipairs(ordered) do
        if index>24 then break end
        local stable=true
        for _=1,4 do
            if Script and Script.Yield then Script.Yield(125) end
            if read_int(row.address)~=row.value then stable=false; break end
        end
        if stable then delayed[#delayed+1]=row end
    end
    ordered=delayed
    trace.delayedStable=#ordered
    trace.stableCandidates=#ordered
    for index,row in ipairs(ordered) do
        if index>24 then break end
        local sourceNames={}; for name in pairs(row.sources) do sourceNames[#sourceNames+1]=name end; table.sort(sourceNames)
        trace.candidates[#trace.candidates+1]={address=hex(row.address),numericAddress=row.address,value=row.value,label=row.label,sources=row.sourceCount,score=row.score,section=row.section,layoutHint=row.layoutHint,sourceNames=table.concat(sourceNames,";")}
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_LIVE_TRACE_CANDIDATE",
                "rank="..tostring(index).." address="..hex(row.address).." value="..tostring(row.value)..
                " label="..row.label.." section="..tostring(row.section).." sources="..tostring(row.sourceCount)..
                " expectedMatch="..tostring(row.matchesExpected==true).." layoutHint="..tostring(row.layoutHint==true)..
                " score="..tostring(row.score).." sourceNames="..table.concat(sourceNames,";"))
        end
    end

    local best=ordered[1]
    if best then
        trace.bestAddress=hex(best.address); trace.bestValue=best.value; trace.bestLabel=best.label
        trace.bestSources=best.sourceCount; trace.bestSection=best.section
        -- Still read-only. This only marks a candidate as useful for a controlled follow-up.
        trace.corroborated=(best.sourceCount>=2 and best.layoutHint==true)
    end
    trace.running=false
    trace.phase="Complete"
    if best and trace.corroborated then
        trace.lastStatus="Promising data candidate: "..best.label.." at "..hex(best.address).." (read-only)"
        state.lastStatus=trace.lastStatus
        startup.log_colored("Promising live Region data candidate: "..best.label.." at "..hex(best.address)..".","warning")
        startup.log_colored("It is in "..tostring(best.section).." memory and remains read-only pending a controlled change test.","warning")
    elseif best then
        trace.lastStatus="Found "..tostring(#ordered).." writable/heap 0-7 fields; none independently proven"
        state.lastStatus=trace.lastStatus
        startup.log_colored("Legacy xref trace found "..tostring(#ordered).." writable/heap 0-7 fields; none are proven yet.","warning")
        startup.log_colored("Detailed xrefs, PE sections, objects, and candidates were saved to Support diagnostics.","info")
    else
        trace.lastStatus="No stable writable/heap Region field candidate found"
        state.lastStatus=trace.lastStatus
        startup.log_colored("Legacy xref trace rejected all code/read-only false candidates and found no safe data candidate.","warning")
        startup.log_colored("Detailed xrefs and object paths were saved to Support diagnostics.","info")
    end
    local mode=tostring(startup.s.matchmakingRegionOverrideMode or "Original")
    if mode~="Original" then
        startup.s.matchmakingRegionOverrideLastStatus="Requested "..mode.."; not applied because the writable field is not proven. "..trace.lastStatus
    else
        startup.s.matchmakingRegionOverrideLastStatus=trace.lastStatus
    end
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_LIVE_TRACE_END",
            "version=2 peMapped="..tostring(sectionOk).." sections="..tostring(#sections)..
            " xrefs="..tostring(trace.ripTargets).." writableRoots="..tostring(trace.writableRoots)..
            " externalRoots="..tostring(trace.externalRoots).." objects="..tostring(trace.objectRoots)..
            " rejectedExecutable="..tostring(trace.rejectedExecutable).." rejectedReadOnly="..tostring(trace.rejectedReadOnly)..
            " delayedStable="..tostring(trace.delayedStable).." corroborated="..tostring(trace.corroborated)..
            " bestAddress="..tostring(trace.bestAddress).." bestValue="..tostring(trace.bestValue)..
            " bestLabel="..tostring(trace.bestLabel).." bestSection="..tostring(trace.bestSection)..
            " reads="..tostring(readCounter))
    end
    state.address=nil
    state.activeConfidence="dump-verified-xref-trace-read-only"
    return trace.corroborated or #ordered>0
end


-- Build 062 Legacy Matchmaking Request Trace.
-- The previous broad candidate-write lab proved that many nearby integers were writable but did
-- not prove that any one controlled matchmaking. Build 062 therefore performs no Region writes.
-- It observes twenty independently sourced paths and any new heap objects that appear while one
-- controlled public-session request is started, then ranks only fields whose values/pointers move
-- during the actual matchmaking window.

-- Build 065 exact Legacy netMatchMakingForceRegion sysParam field/value probe.
-- The Build 062 request trace proved that broad request-object observation was too noisy:
-- it saw no field changes and ranked a pre-existing object merely because it was first noticed.
-- The uploaded IDA database provides the exact rage::sysParam field layout and named globals. Their current
-- addresses are recovered from the verified Consumer B reference to the live CMsgJoinRequest
-- data-table anchor, then by exact same-table sibling offsets. Build 065 reads the unaligned
-- m_Next field and dereferences bounded m_Name/m_Desc/m_Value strings. It remains read-only.
function startup.run_legacy_exact_region_sysparam_probe()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    local dump = state.dumpScan or {}
    local trace = state.runtimeTrace or {}
    local ref = startup.region_idb_reference or {}
    local layout = ref.sysParamLayout or {name=0x00,desc=0x08,value=0x10,index=0x18,next=0x1C,required=0x24}
    local probe = {
        running=true, relocation="", relocationSources=0, objectAddress="",
        forceAimAddress="", forceLanguageAddress="", regionBiasAddress="", joinRequestAddress="",
        objectSection="", objectsCompared=0, fieldsCaptured=0, candidateCount=0,
        bestOffset="", bestAddress="", bestValue=nil, bestScore=0,
        valuePointer="", rawValuePointer="", valueText="", valueNumber=nil, valueLabel="", valueCapacity=0,
        valueDecodeMode="", nameText="", nameDecodeMode="", layoutVerified=false, projectionVerified=false,
        tokenXrefVerified=false, tokenPointerHit="", tokenCandidateAddress="", tokenPattern="",
        projectedObjectAddress="", chainNodes=0, lastStatus="Running", results={}, snapshots={}
    }
    state.exactParamProbe = probe
    state.requestLab = state.requestLab or {}
    state.requestLab.running = false
    state.requestLab.phase = "Disabled"
    state.requestLab.lastStatus = "Disabled in Build 065; replaced by the exact sysParam field/value probe."

    local function hex(value)
        value=tonumber(value)
        return value and ("0x"..string.format("%X",value)) or "none"
    end
    local function parse_address(value)
        if type(value)=="number" then return value end
        local raw=tostring(value or "")
        return tonumber(raw:match("^0[xX]([0-9A-Fa-f]+)$"),16) or tonumber(value)
    end
    local function clean_text(value)
        value=tostring(value or "")
        value=value:gsub("[\r\n\t]"," "):gsub("|","/")
        if #value>160 then value=value:sub(1,157).."..." end
        return value
    end
    local function fail(message,event)
        probe.running=false
        probe.lastStatus=tostring(message)
        state.lastStatus=probe.lastStatus
        startup.s.matchmakingRegionOverrideLastStatus=probe.lastStatus
        startup.log_colored(probe.lastStatus,"error")
        if startup.support_log_event_quiet then startup.support_log_event_quiet(event or "REGION_EXACT_PARAM_ERROR",probe.lastStatus) end
        return false
    end
    if dump.compatible~=true then return fail("Exact Force Region probe skipped: the eight Legacy IDB anchors are not corroborated.") end
    if not Memory or not Memory.ReadInt or not Memory.ReadLong then return fail("Exact Force Region probe unavailable: Memory.ReadInt/ReadLong is missing.") end

    -- Code and data moved by different amounts between the uploaded IDB and the current
    -- executable. Resolve the live CMsgJoinRequest::AutoId data anchor from Consumer B,
    -- then use only exact same-table sibling distances for the four named sysParam globals.
    local rowsByName={}
    for _,row in ipairs(state.probeResults or {}) do
        if row and row.name then rowsByName[tostring(row.name)]=row end
    end
    local consumerB=rowsByName["Legacy force-region consumer B"]
    local consumerBHit=consumerB and tonumber(consumerB.hit) or nil
    if not consumerBHit then return fail("Exact Force Region probe could not recover the verified Consumer B runtime hit.") end

    local joinVotes={}
    for _,xref in ipairs(trace.xrefs or {}) do
        if tostring(xref.source or "")=="Legacy force-region consumer B" and tostring(xref.kind or "")=="LEA" and xref.writable==true then
            local instruction=parse_address(xref.instruction)
            local target=parse_address(xref.target)
            local sourceOffset=instruction and (instruction-consumerBHit) or nil
            if target and (sourceOffset==338 or sourceOffset==339) then
                local key=hex(target)
                local vote=joinVotes[key]
                if not vote then vote={address=target,count=0,offsets={}}; joinVotes[key]=vote end
                vote.count=vote.count+1; vote.offsets[#vote.offsets+1]=sourceOffset
            end
        end
    end
    local joinBest
    for _,vote in pairs(joinVotes) do if not joinBest or vote.count>joinBest.count then joinBest=vote end end
    if not joinBest or tonumber(joinBest.count or 0)<1 then return fail("Exact Force Region probe could not resolve the live CMsgJoinRequest AutoId data anchor.") end

    local dataDelta=joinBest.address-tonumber(ref.joinRequestAutoId or 0)
    probe.relocation=hex(dataDelta)
    probe.relocationSources=joinBest.count
    local addresses={
        {key="forceRegion",label="Force Region",ida=ref.forceRegionObject},
        {key="forceAim",label="Force Aim",ida=ref.forceAimObject},
        {key="forceLanguage",label="Force Language",ida=ref.forceLanguageObject},
        {key="regionBias",label="Region Bias",ida=ref.regionBiasObject},
        {key="joinRequest",label="Join Request AutoId",ida=ref.joinRequestAutoId}
    }
    for _,row in ipairs(addresses) do row.runtime=tonumber(row.ida) and (tonumber(row.ida)+dataDelta) or nil end
    local objectByKey={}; for _,row in ipairs(addresses) do objectByKey[row.key]=row end
    probe.objectAddress=hex(objectByKey.forceRegion and objectByKey.forceRegion.runtime)
    probe.projectedObjectAddress=probe.objectAddress
    probe.forceAimAddress=hex(objectByKey.forceAim and objectByKey.forceAim.runtime)
    probe.forceLanguageAddress=hex(objectByKey.forceLanguage and objectByKey.forceLanguage.runtime)
    probe.regionBiasAddress=hex(objectByKey.regionBias and objectByKey.regionBias.runtime)
    probe.joinRequestAddress=hex(objectByKey.joinRequest and objectByKey.joinRequest.runtime)

    local sections={}
    for _,row in ipairs(trace.sections or {}) do
        sections[#sections+1]={name=tostring(row.name or "section"),start=parse_address(row.start),finish=parse_address(row.finish),executable=row.executable==true,writable=row.writable==true,readable=row.readable~=false}
    end
    local function classify(address)
        address=tonumber(address)
        for _,section in ipairs(sections) do
            if address and section.start and section.finish and address>=section.start and address<section.finish then
                return section.name,section.executable,section.writable,section.readable
            end
        end
        return "external",false,true,true
    end
    local section,executable,writable=classify(objectByKey.forceRegion.runtime)
    probe.objectSection=section
    if executable or not writable or tostring(section)=="external" then return fail("Exact Force Region object resolved outside mapped writable data memory: "..tostring(section)..".") end
    for _,row in ipairs(addresses) do
        local rowSection,rowExecutable,rowWritable=classify(row.runtime)
        if rowExecutable or not rowWritable or tostring(rowSection)~=tostring(section) then
            return fail("Exact Force Region sibling layout crossed an unsafe section at "..tostring(row.label)..": "..tostring(rowSection)..".")
        end
    end
    if objectByKey.forceRegion.runtime-objectByKey.joinRequest.runtime~=0x8C0 or
       objectByKey.forceAim.runtime-objectByKey.joinRequest.runtime~=0x40 or
       objectByKey.regionBias.runtime-objectByKey.forceLanguage.runtime~=0x70 then
        return fail("Exact Force Region object layout failed the IDA sibling-distance checks.")
    end

    local function call_read(name,address)
        local fn=Memory and Memory[name]
        if not fn then return nil end
        local ok,value=direct_call(fn,address)
        return ok and value or nil
    end
    local function stable_read(name,address)
        local a,b,c=call_read(name,address),call_read(name,address),call_read(name,address)
        if a~=nil and a==b and b==c then return a end
        return nil
    end
    local function plausible_pointer(value)
        value=tonumber(value)
        return value and value>=65536 and value<140737488355328
    end
    local function read_u8(address)
        local value=stable_read("ReadUByte",address)
        if value==nil then value=stable_read("ReadByte",address) end
        value=tonumber(value)
        if value and value<0 then value=value+256 end
        return value
    end
    local function read_cstring(address,maxLen)
        address=tonumber(address); maxLen=math.max(1,math.min(tonumber(maxLen or 96) or 96,192))
        if not plausible_pointer(address) then return nil,0,false end
        local out={}
        for i=0,maxLen-1 do
            local byte=read_u8(address+i)
            if byte==nil then return nil,#out,false end
            if byte==0 then return table.concat(out),#out,true end
            if byte<32 or byte>126 then return nil,#out,false end
            out[#out+1]=string.char(byte)
            if Script and Script.Yield and i>0 and i%24==0 then Script.Yield(1) end
        end
        return table.concat(out),#out,false
    end
    local function bytes_hex(address,count)
        local out={}; count=math.max(0,math.min(tonumber(count or 0) or 0,48))
        for i=0,count-1 do
            local byte=read_u8(address+i)
            out[#out+1]=byte and string.format("%02X",byte) or "??"
        end
        return table.concat(out," ")
    end
    local function numeric_text(text)
        text=tostring(text or ""):gsub("^%s+",""):gsub("%s+$","")
        if text:match("^[+-]?%d+$") then return tonumber(text) end
        return nil
    end
    local function decode_string_field(rawPointer,maxLen)
        rawPointer=tonumber(rawPointer)
        if not plausible_pointer(rawPointer) then return nil,nil,"invalid",0,false end
        local direct,directLen,directTerminated=read_cstring(rawPointer,maxLen)
        if direct~=nil then return direct,rawPointer,"direct",directLen,directTerminated end
        local indirect=stable_read("ReadLong",rawPointer)
        if plausible_pointer(indirect) then
            local text,textLen,textTerminated=read_cstring(indirect,maxLen)
            if text~=nil then return text,indirect,"indirect",textLen,textTerminated end
        end
        return nil,rawPointer,"unreadable",0,false
    end

    local objectKeys={"forceRegion","forceAim","forceLanguage","regionBias"}
    local snapshots={}
    for _,key in ipairs(objectKeys) do
        local object=objectByKey[key]
        local base=tonumber(object.runtime)
        local snap={key=key,label=object.label,address=base}
        snap.namePtr=stable_read("ReadLong",base+layout.name)
        snap.descPtr=stable_read("ReadLong",base+layout.desc)
        snap.valuePtr=stable_read("ReadLong",base+layout.value)
        snap.index=stable_read("ReadInt",base+layout.index)
        snap.nextPtr=stable_read("ReadLong",base+layout.next) -- unaligned by design
        snap.required=read_u8(base+layout.required)
        snap.nameText,snap.nameResolvedPtr,snap.nameDecodeMode,snap.nameLength,snap.nameTerminated=decode_string_field(snap.namePtr,96)
        snap.descText,snap.descResolvedPtr,snap.descDecodeMode,snap.descLength,snap.descTerminated=decode_string_field(snap.descPtr,160)
        snap.valueText,snap.valueResolvedPtr,snap.valueDecodeMode,snap.valueLength,snap.valueTerminated=decode_string_field(snap.valuePtr,32)
        snap.valueNumber=numeric_text(snap.valueText)
        snap.nameSection=select(1,classify(snap.namePtr))
        snap.descSection=select(1,classify(snap.descPtr))
        snap.valueSection=select(1,classify(snap.valuePtr))
        snap.nextSection=select(1,classify(snap.nextPtr))
        local valueBytesAt=tonumber(snap.valueResolvedPtr or snap.valuePtr)
        snap.valueBytes=plausible_pointer(valueBytesAt) and bytes_hex(valueBytesAt,16) or ""
        snap.valueCapacity=0
        if plausible_pointer(valueBytesAt) then
            for i=0,31 do
                local b=read_u8(valueBytesAt+i)
                if b==nil then break end
                snap.valueCapacity=i+1
                if b==0 and i>=1 then break end
            end
        end
        snapshots[key]=snap; probe.snapshots[#probe.snapshots+1]=snap
        probe.objectsCompared=probe.objectsCompared+1
        probe.fieldsCaptured=probe.fieldsCaptured+6
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_EXACT_PARAM_FIELDS",
                "name="..object.label.." object="..hex(base).." section="..tostring(select(1,classify(base)))..
                " m_Name="..hex(snap.namePtr).." nameResolved="..hex(snap.nameResolvedPtr).." nameMode="..tostring(snap.nameDecodeMode)..
                " nameSection="..tostring(snap.nameSection).." nameText="..clean_text(snap.nameText)..
                " m_Desc="..hex(snap.descPtr).." descResolved="..hex(snap.descResolvedPtr).." descMode="..tostring(snap.descDecodeMode)..
                " descSection="..tostring(snap.descSection).." descText="..clean_text(snap.descText)..
                " m_Value="..hex(snap.valuePtr).." valueResolved="..hex(snap.valueResolvedPtr).." valueMode="..tostring(snap.valueDecodeMode)..
                " valueSection="..tostring(snap.valueSection).." valueText="..clean_text(snap.valueText)..
                " valueNumber="..tostring(snap.valueNumber).." valueBytes="..tostring(snap.valueBytes).." valueCapacity="..tostring(snap.valueCapacity)..
                " m_Index="..tostring(snap.index).." m_Next="..hex(snap.nextPtr).." nextSection="..tostring(snap.nextSection)..
                " m_Required="..tostring(snap.required))
        end
        if Script and Script.Yield then Script.Yield(1) end
    end

    local regionSnap=snapshots.forceRegion

    -- The Build 064 snapshot showed that a same-table address can land on valid writable
    -- data without actually being a rage::sysParam. As a second independent route, scan
    -- for an exact 64-bit pointer to the corroborated Force Region identifier. If the
    -- pointer is the m_Name field of a sysParam, its surrounding exact IDA fields must
    -- validate before it can replace the projected candidate. This remains read-only.
    local function pointer_pattern(address)
        address=tonumber(address)
        if not plausible_pointer(address) then return nil end
        local bytes={}
        for _=1,8 do
            local byte=address%256
            bytes[#bytes+1]=string.format("%02X",byte)
            address=math.floor(address/256)
        end
        return table.concat(bytes," ")
    end
    local function scan_exact_pattern(pattern)
        if not pattern or not Memory or not Memory.Scan then return nil,"Memory.Scan unavailable" end
        local attempts={
            function() return Memory.Scan(pattern) end,
            function() return Memory.Scan(pattern,"GTA5.exe") end,
            function() return Memory.Scan("GTA5.exe",pattern) end
        }
        local lastError="not found"
        for _,fn in ipairs(attempts) do
            local ok,rawValue=direct_call(fn)
            local value=ok and tonumber(rawValue) or nil
            if value and value~=0 then return value,nil end
            if not ok then lastError=tostring(rawValue) end
        end
        return nil,lastError
    end
    local tokenAddress=parse_address(dump.forceTokenTarget)
    probe.tokenPattern=pointer_pattern(tokenAddress) or ""
    local tokenPointerHit,tokenScanError=scan_exact_pattern(probe.tokenPattern)
    probe.tokenPointerHit=hex(tokenPointerHit)
    local tokenCandidates={}
    if tokenPointerHit then
        for _,candidateBase in ipairs({tokenPointerHit,tokenPointerHit-layout.desc,tokenPointerHit-layout.value}) do
            candidateBase=tonumber(candidateBase)
            local candidateSection,candidateExecutable,candidateWritable=classify(candidateBase)
            local snap={key="forceRegionTokenXref",label="Force Region token xref",address=candidateBase}
            snap.namePtr=stable_read("ReadLong",candidateBase+layout.name)
            snap.descPtr=stable_read("ReadLong",candidateBase+layout.desc)
            snap.valuePtr=stable_read("ReadLong",candidateBase+layout.value)
            snap.index=stable_read("ReadInt",candidateBase+layout.index)
            snap.nextPtr=stable_read("ReadLong",candidateBase+layout.next)
            snap.required=read_u8(candidateBase+layout.required)
            snap.nameText,snap.nameResolvedPtr,snap.nameDecodeMode=decode_string_field(snap.namePtr,96)
            snap.descText,snap.descResolvedPtr,snap.descDecodeMode=decode_string_field(snap.descPtr,160)
            snap.valueText,snap.valueResolvedPtr,snap.valueDecodeMode=decode_string_field(snap.valuePtr,32)
            snap.valueNumber=numeric_text(snap.valueText)
            local indexOk=tonumber(snap.index)~=nil and tonumber(snap.index)>=-1 and tonumber(snap.index)<=1000000
            local requiredOk=tonumber(snap.required)==0 or tonumber(snap.required)==1
            local nameTokenMatch=tonumber(snap.namePtr)==tonumber(tokenAddress)
            local pointerOk=plausible_pointer(snap.valueResolvedPtr or snap.valuePtr)
            snap.tokenScore=(nameTokenMatch and 80 or 0)+(indexOk and 10 or 0)+(requiredOk and 10 or 0)+(pointerOk and 5 or 0)
            snap.tokenValid=nameTokenMatch and indexOk and requiredOk and pointerOk and candidateWritable and not candidateExecutable
            snap.valueCapacity=0
            local tokenValueAddress=tonumber(snap.valueResolvedPtr or snap.valuePtr)
            if plausible_pointer(tokenValueAddress) then
                for i=0,31 do
                    local byte=read_u8(tokenValueAddress+i)
                    if byte==nil then break end
                    snap.valueCapacity=i+1
                    if byte==0 and i>=1 then break end
                end
            end
            tokenCandidates[#tokenCandidates+1]=snap
            if startup.support_log_event_quiet then
                startup.support_log_event_quiet("REGION_EXACT_TOKEN_XREF",
                    "token="..hex(tokenAddress).." pattern="..tostring(probe.tokenPattern).." hit="..hex(tokenPointerHit)..
                    " candidate="..hex(candidateBase).." section="..tostring(candidateSection).." writable="..tostring(candidateWritable)..
                    " namePtr="..hex(snap.namePtr).." nameTokenMatch="..tostring(nameTokenMatch).." nameText="..clean_text(snap.nameText)..
                    " valuePtr="..hex(snap.valuePtr).." valueResolved="..hex(snap.valueResolvedPtr).." valueText="..clean_text(snap.valueText)..
                    " valueNumber="..tostring(snap.valueNumber).." index="..tostring(snap.index).." required="..tostring(snap.required)..
                    " next="..hex(snap.nextPtr).." score="..tostring(snap.tokenScore).." valid="..tostring(snap.tokenValid))
            end
        end
        table.sort(tokenCandidates,function(a,b) return tonumber(a.tokenScore or 0)>tonumber(b.tokenScore or 0) end)
        if tokenCandidates[1] and tokenCandidates[1].tokenValid then
            regionSnap=tokenCandidates[1]
            snapshots.forceRegion=regionSnap
            probe.tokenXrefVerified=true
            probe.tokenCandidateAddress=hex(regionSnap.address)
            probe.objectAddress=probe.tokenCandidateAddress
            probe.objectSection=tostring(select(1,classify(regionSnap.address)))
            probe.snapshots[#probe.snapshots+1]=regionSnap
            probe.objectsCompared=probe.objectsCompared+1
            probe.fieldsCaptured=probe.fieldsCaptured+6
        end
    elseif startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_EXACT_TOKEN_XREF",
            "token="..hex(tokenAddress).." pattern="..tostring(probe.tokenPattern).." hit=none error="..clean_text(tokenScanError))
    end

    probe.nameText=tostring(regionSnap.nameText or "")
    probe.nameDecodeMode=tostring(regionSnap.nameDecodeMode or "")
    probe.rawValuePointer=hex(regionSnap.valuePtr)
    probe.valuePointer=hex(regionSnap.valueResolvedPtr or regionSnap.valuePtr)
    probe.valueDecodeMode=tostring(regionSnap.valueDecodeMode or "")
    probe.valueText=tostring(regionSnap.valueText or "")
    probe.valueNumber=regionSnap.valueNumber
    probe.valueLabel=regionSnap.valueNumber~=nil and tostring(startup.region_names[regionSnap.valueNumber] or (regionSnap.valueNumber==-1 and "Original" or "")) or ""
    probe.valueCapacity=tonumber(regionSnap.valueCapacity or 0) or 0
    local normalizedName=probe.nameText:lower():gsub("[^a-z0-9]","")
    local nameMatches=normalizedName:find("netmatchmakingforceregion",1,true)~=nil or normalizedName:find("forceregion",1,true)~=nil
    local tokenNameMatches=tokenAddress~=nil and tonumber(regionSnap.namePtr)==tonumber(tokenAddress)
    local indexPlausible=tonumber(regionSnap.index)~=nil and tonumber(regionSnap.index)>=-1 and tonumber(regionSnap.index)<=1000000
    local requiredPlausible=tonumber(regionSnap.required)==0 or tonumber(regionSnap.required)==1
    probe.layoutVerified=(nameMatches or tokenNameMatches) and indexPlausible and requiredPlausible and plausible_pointer(regionSnap.valueResolvedPtr or regionSnap.valuePtr)
    probe.projectionVerified=probe.layoutVerified and not probe.tokenXrefVerified and probe.objectAddress==probe.projectedObjectAddress

    -- Walk only a short, loop-protected m_Next chain. This validates that +0x1C is the
    -- unaligned linked-list pointer from the IDA type, without scanning arbitrary memory.
    local seen={}; local nextPtr=tonumber(regionSnap.nextPtr)
    for depth=1,8 do
        if not plausible_pointer(nextPtr) or seen[nextPtr] then break end
        seen[nextPtr]=true
        local chainNamePtr=stable_read("ReadLong",nextPtr+layout.name)
        local chainValuePtr=stable_read("ReadLong",nextPtr+layout.value)
        local chainIndex=stable_read("ReadInt",nextPtr+layout.index)
        local chainNext=stable_read("ReadLong",nextPtr+layout.next)
        local chainRequired=read_u8(nextPtr+layout.required)
        local chainName,chainNameResolved,chainNameMode=decode_string_field(chainNamePtr,80)
        local chainValue,chainValueResolved,chainValueMode=decode_string_field(chainValuePtr,24)
        probe.chainNodes=depth
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("REGION_EXACT_PARAM_CHAIN",
                "depth="..depth.." object="..hex(nextPtr).." section="..tostring(select(1,classify(nextPtr)))..
                " name="..clean_text(chainName).." nameResolved="..hex(chainNameResolved).." nameMode="..tostring(chainNameMode)..
                " value="..clean_text(chainValue).." valueResolved="..hex(chainValueResolved).." valueMode="..tostring(chainValueMode)..
                " index="..tostring(chainIndex).." required="..tostring(chainRequired).." next="..hex(chainNext))
        end
        nextPtr=tonumber(chainNext)
        if Script and Script.Yield then Script.Yield(1) end
    end

    local candidates={}
    local resolvedValueAddress=tonumber(regionSnap.valueResolvedPtr or regionSnap.valuePtr)
    if probe.layoutVerified and regionSnap.valueNumber~=nil and regionSnap.valueNumber>=-1 and regionSnap.valueNumber<=7 and plausible_pointer(resolvedValueAddress) then
        candidates[1]={offset="m_Value",address=resolvedValueAddress,value=regionSnap.valueNumber,text=regionSnap.valueText,score=100}
        probe.bestOffset="m_Value"
        probe.bestAddress=hex(resolvedValueAddress)
        probe.bestValue=regionSnap.valueNumber
        probe.bestScore=100
    end
    probe.results=candidates
    probe.candidateCount=#candidates
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_EXACT_PARAM_VALUE",
            "object="..probe.objectAddress.." projectedObject="..probe.projectedObjectAddress.." projectionVerified="..tostring(probe.projectionVerified)..
            " tokenXrefVerified="..tostring(probe.tokenXrefVerified).." tokenPointerHit="..probe.tokenPointerHit.." tokenCandidate="..probe.tokenCandidateAddress..
            " layoutVerified="..tostring(probe.layoutVerified)..
            " name="..clean_text(probe.nameText).." nameMode="..tostring(probe.nameDecodeMode)..
            " rawValuePtr="..probe.rawValuePointer.." valuePtr="..probe.valuePointer.." valueMode="..tostring(probe.valueDecodeMode)..
            " valueText="..clean_text(probe.valueText).." valueNumber="..tostring(probe.valueNumber)..
            " valueLabel="..tostring(probe.valueLabel).." valueCapacity="..tostring(probe.valueCapacity).." candidates="..#candidates)
    end

    probe.running=false
    if #candidates>0 then
        local route=probe.tokenXrefVerified and "token xref" or "IDA projection"
        probe.lastStatus="Force Region sysParam "..route.." validated; m_Value is '"..clean_text(probe.valueText).."' ("..tostring(probe.valueLabel)..") at "..probe.valuePointer..". Read-only."
        startup.log_colored("Legacy Force Region sysParam "..route.." validated at "..probe.objectAddress..".","success")
        startup.log_colored("m_Value resolves to '"..clean_text(probe.valueText).."' ("..tostring(probe.valueLabel)..") at "..probe.valuePointer..".","warning")
        startup.log_colored("No Region write was attempted. Create a Support ZIP for the field and linked-list diagnostics.","info")
        state.activeConfidence="dump-verified-sysparam-value-read-only"
    elseif probe.layoutVerified then
        local route=probe.tokenXrefVerified and "token xref" or "IDA projection"
        probe.lastStatus="Force Region sysParam "..route.." validated at "..probe.objectAddress..", but m_Value was empty or non-numeric. Read-only."
        startup.log_colored("Legacy Force Region sysParam "..route.." validated at "..probe.objectAddress..".","success")
        startup.log_colored("m_Value pointer: "..probe.valuePointer.." | text: '"..clean_text(probe.valueText).."'.","warning")
        startup.log_colored("The exact fields and short m_Next chain were saved to Support diagnostics. No write was attempted.","info")
        state.activeConfidence="dump-verified-sysparam-layout-read-only"
    else
        probe.lastStatus="The IDA sibling projection at "..probe.objectAddress.." did not decode as netMatchMakingForceRegion; it was rejected. Read-only."
        startup.log_colored("Legacy IDA sibling projection reached "..probe.objectAddress..", but its sysParam fields did not validate.","warning")
        startup.log_colored("Decoded name: '"..clean_text(probe.nameText).."' | m_Value: '"..clean_text(probe.valueText).."'.","warning")
        startup.log_colored("The direct/indirect field diagnostics were saved. No Region write was attempted.","info")
        state.activeConfidence="dump-verified-sysparam-projection-rejected"
    end
    state.lastStatus=probe.lastStatus
    state.address=nil
    startup.s.matchmakingRegionOverrideLastStatus=probe.lastStatus
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_EXACT_PARAM_END",
            "relocation="..probe.relocation.." sources="..probe.relocationSources.." forceRegion="..probe.objectAddress..
            " forceAim="..probe.forceAimAddress.." forceLanguage="..probe.forceLanguageAddress.." regionBias="..probe.regionBiasAddress..
            " joinRequest="..probe.joinRequestAddress.." section="..probe.objectSection.." objects="..probe.objectsCompared..
            " fields="..probe.fieldsCaptured.." projectedObject="..probe.projectedObjectAddress.." projectionVerified="..tostring(probe.projectionVerified)..
            " tokenXrefVerified="..tostring(probe.tokenXrefVerified).." tokenPointerHit="..probe.tokenPointerHit.." tokenCandidate="..probe.tokenCandidateAddress..
            " layoutVerified="..tostring(probe.layoutVerified)..
            " name="..clean_text(probe.nameText).." nameMode="..tostring(probe.nameDecodeMode)..
            " rawValuePointer="..probe.rawValuePointer.." valuePointer="..probe.valuePointer.." valueMode="..tostring(probe.valueDecodeMode)..
            " valueText="..clean_text(probe.valueText).." valueNumber="..tostring(probe.valueNumber)..
            " valueLabel="..tostring(probe.valueLabel).." valueCapacity="..tostring(probe.valueCapacity).." chainNodes="..tostring(probe.chainNodes)..
            " candidates="..probe.candidateCount.." bestOffset="..probe.bestOffset.." bestAddress="..probe.bestAddress..
            " bestValue="..tostring(probe.bestValue).." bestScore="..probe.bestScore.." status="..probe.lastStatus)
    end
    return true
end

function startup.run_legacy_region_request_lab()
    if startup.regionProductionHidden == true then
        return false
    end
    local state=startup.region_scan or {}
    local trace=state.runtimeTrace or {}
    local mode=tostring(startup.s.matchmakingRegionOverrideMode or "Original")
    local lab={
        running=true,totalMethods=20,methodsCompleted=0,watchAddresses=0,pointerRoots=0,
        dynamicObjects=0,changes=0,regionChanges=0,sessionStarted=false,sessionLoaded=false,
        targetLabel=mode,expectedLabel=tostring(state.fallbackLabel or ""),bestAddress="",
        bestScore=0,bestSource="",phase="Preparing",lastStatus="Preparing request trace",results={}
    }
    state.requestLab=lab
    state.applyLab=state.applyLab or {}
    state.applyLab.running=false
    state.applyLab.lastStatus="Disabled in Build 065; retained only as inactive historical code."

    local function hex(value)
        value=tonumber(value)
        return value and ("0x"..string.format("%X",value)) or "none"
    end
    local function parse_address(value)
        if type(value)=="number" then return value end
        local raw=tostring(value or "")
        return tonumber(raw:match("^0[xX]([0-9A-Fa-f]+)$"),16) or tonumber(value)
    end
    local function yield_ms(ms)
        if Script and Script.Yield then Script.Yield(tonumber(ms) or 0) end
    end
    local function read_int(address)
        if not Memory or not Memory.ReadInt then return nil end
        local ok,value=direct_call(Memory.ReadInt,tonumber(address))
        return ok and tonumber(value) or nil
    end
    local function read_pointer(address)
        if not Memory or not Memory.ReadLong then return nil end
        local ok,value=direct_call(Memory.ReadLong,tonumber(address))
        value=ok and tonumber(value) or nil
        if value and value>=65536 and value<140737488355328 then return value end
        return nil
    end
    local function stable_int(address)
        local a,b,c=read_int(address),read_int(address),read_int(address)
        return a~=nil and a==b and b==c and a or nil
    end
    local sections={}
    for _,row in ipairs(trace.sections or {}) do
        sections[#sections+1]={
            name=tostring(row.name or "section"),start=parse_address(row.start),finish=parse_address(row.finish),
            executable=row.executable==true,writable=row.writable==true
        }
    end
    local function classify(address)
        address=tonumber(address)
        for _,section in ipairs(sections) do
            if address and section.start and section.finish and address>=section.start and address<section.finish then
                return section.name,section.executable,section.writable,false
            end
        end
        return "external",false,true,true
    end
    local function readable_candidate(address)
        local section,executable,writable,external=classify(address)
        if executable then return false,section end
        return writable or external,section
    end

    if not startup.is_gta_online_session_ready or not startup.is_gta_online_session_ready() then
        lab.running=false
        lab.phase="Skipped"
        lab.lastStatus="Enter GTA Online before running the Legacy Matchmaking Request Trace."
        startup.s.matchmakingRegionOverrideLastStatus=lab.lastStatus
        startup.regionExperimentLock=false
        startup.log_colored(lab.lastStatus,"warning")
        if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_LAB_END","result=skipped reason=not-online") end
        return false
    end
    if not Memory or not Memory.ReadInt then
        lab.running=false; lab.phase="Error"; lab.lastStatus="Memory.ReadInt unavailable"
        startup.regionExperimentLock=false
        startup.log_colored("Region Request Trace unavailable: Memory.ReadInt missing.","error")
        return false
    end

    local methods={}
    for index=1,5 do methods[#methods+1]={kind="candidate",index=index,name="Trace candidate rank "..tostring(index)} end
    for index=1,5 do methods[#methods+1]={kind="data",index=index,name="Writable data root "..tostring(index)} end
    for index=1,5 do methods[#methods+1]={kind="object",index=index,name="Object +0x160 path "..tostring(index)} end
    local consumers={"Legacy force-region consumer A","Legacy force-region consumer B","Legacy force-region consumer C","Legacy force-region consumer D","Legacy force-region consumer E"}
    for index,name in ipairs(consumers) do methods[#methods+1]={kind="consumer",index=index,consumer=name,name="Consumer xref path "..string.char(64+index)} end

    local watched,watchRows={},{}
    local pointerRoots,pointerMap={},{}
    local function add_watch(address,source,methodIndex,dynamic)
        address=tonumber(address)
        if not address or address<65536 or address>=140737488355328 then return nil end
        local allowed,section=readable_candidate(address)
        if not allowed then return nil end
        local key=hex(address)
        local row=watched[key]
        if not row then
            if #watchRows>=420 then return nil end
            row={address=address,key=key,section=section,sources={},methods={},dynamic=dynamic==true,
                baseline=read_int(address),last=nil,changes=0,regionChanges=0,observed={},
                firstChangeMs=nil,lastChangeMs=nil,seenExpected=false,seenTarget=false,
                valueAtLoaded=nil,finalValue=nil,score=0}
            row.last=row.baseline
            watched[key]=row; watchRows[#watchRows+1]=row
        end
        row.sources[tostring(source or "unknown")]=true
        if methodIndex then row.methods[tonumber(methodIndex) or 0]=true end
        if dynamic then row.dynamic=true end
        return row
    end
    local function add_pointer_root(address,source,methodIndex)
        address=tonumber(address)
        if not address or address<65536 or address>=140737488355328 then return end
        local aligned=address-(address%8)
        for delta=-8,8,8 do
            local candidate=aligned+delta
            local key=hex(candidate)
            if not pointerMap[key] and #pointerRoots<96 then
                pointerMap[key]=true
                pointerRoots[#pointerRoots+1]={address=candidate,key=key,source=tostring(source or "root"),method=methodIndex,last=read_pointer(candidate),seen={}}
            end
        end
    end
    local function scan_ints(base,fromOffset,toOffset,source,methodIndex)
        base=tonumber(base); if not base then return end
        for offset=fromOffset,toOffset,4 do
            local address=base+offset
            local value=stable_int(address)
            if value~=nil and startup.region_names[value] then add_watch(address,tostring(source).." offset="..string.format("%+d",offset),methodIndex,false) end
        end
    end

    for methodIndex,method in ipairs(methods) do
        local before=#watchRows
        if method.kind=="candidate" then
            local row=(trace.candidates or {})[method.index]
            if row then add_watch(parse_address(row.numericAddress or row.address),"trace candidate "..tostring(method.index).." "..tostring(row.sourceNames or ""),methodIndex,false) end
        elseif method.kind=="data" then
            local row=(trace.dataRoots or {})[method.index]
            local root=row and parse_address(row.address) or nil
            if root then
                scan_ints(root,-0x60,0x140,"data root "..tostring(method.index).." "..tostring(row.kind or ""),methodIndex)
                add_pointer_root(root,"data root "..tostring(method.index),methodIndex)
            end
        elseif method.kind=="object" then
            local row=(trace.objectRootRows or {})[method.index]
            local root=row and parse_address(row.address) or nil
            if root then
                scan_ints(root,-0x40,0x260,"object root "..tostring(method.index),methodIndex)
                scan_ints(root+0x160,-0x100,0x180,"object root "..tostring(method.index).." +0x160",methodIndex)
                add_pointer_root(root,"object root "..tostring(method.index),methodIndex)
                add_pointer_root(root+0x160,"object member root "..tostring(method.index),methodIndex)
            end
        elseif method.kind=="consumer" then
            for _,xref in ipairs(trace.xrefs or {}) do
                if tostring(xref.source or "")==tostring(method.consumer) then
                    local target=parse_address(xref.target)
                    if target then
                        scan_ints(target,-0x60,0x140,method.consumer.." "..tostring(xref.kind or "xref"),methodIndex)
                        add_pointer_root(target,method.consumer.." "..tostring(xref.kind or "xref"),methodIndex)
                    end
                end
            end
        end
        lab.methodsCompleted=methodIndex
        local added=#watchRows-before
        lab.results[#lab.results+1]={method=methodIndex,name=method.name,watchAdded=added}
        if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_METHOD","method="..methodIndex.." name="..method.name.." watchAdded="..added.." totalWatch="..#watchRows) end
        yield_ms(10)
    end

    local expectedValue=startup.region_value_by_label[tostring(state.fallbackLabel or "")]
    local targetValue=startup.region_value_by_label[mode]
    lab.watchAddresses=#watchRows
    lab.pointerRoots=#pointerRoots
    lab.phase="Baseline"
    startup.regionExperimentLock=true
    startup.regionExperimentSessionStarted=false
    startup.log_colored("Legacy Matchmaking Request Trace started: 20 paths, "..#watchRows.." watched fields, "..#pointerRoots.." pointer roots.","warning")
    startup.log_colored("This build performs no Region writes. One controlled public-session request will start automatically.","info")
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("REGION_REQUEST_LAB_BEGIN","version=3 methods=20 watched="..#watchRows.." pointerRoots="..#pointerRoots.." selected="..mode.." targetValue="..tostring(targetValue).." expected="..tostring(state.fallbackLabel or "").." expectedValue="..tostring(expectedValue))
    end

    local startMs=startup.now()
    local eventLogCount=0
    local dynamicScanned={}
    local sessionMarker=tonumber(startup.s.lastSessionChangeMs or 0) or 0
    local sessionLoadedAt=nil
    local function source_text(row)
        local out={}
        for source in pairs(row.sources or {}) do out[#out+1]=source end
        table.sort(out)
        return table.concat(out,";")
    end
    local function scan_dynamic_object(pointer,rootSource,methodIndex,elapsed)
        pointer=tonumber(pointer)
        if not pointer or pointer<4294967296 or pointer>=140737488355328 or (pointer%8)~=0 then return end
        local allowed=readable_candidate(pointer)
        if not allowed then return end
        if read_int(pointer)==nil and read_int(pointer+8)==nil then return end
        local key=hex(pointer)
        if dynamicScanned[key] or lab.dynamicObjects>=64 then return end
        dynamicScanned[key]=true
        lab.dynamicObjects=lab.dynamicObjects+1
        local added=0
        for offset=0,0x3C0,4 do
            local address=pointer+offset
            local value=read_int(address)
            if value~=nil and startup.region_names[value] then
                if add_watch(address,"dynamic "..rootSource.." object="..key.." offset="..string.format("+0x%X",offset),methodIndex,true) then added=added+1 end
            end
        end
        if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_POINTER_OBJECT","elapsedMs="..elapsed.." root="..tostring(rootSource).." pointer="..key.." regionFieldsAdded="..added) end
    end
    local function sample(phase,elapsed)
        for _,root in ipairs(pointerRoots) do
            local pointer=read_pointer(root.address)
            if pointer and pointer~=root.last then
                local previous=root.last
                root.last=pointer
                if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_POINTER_CHANGE","phase="..phase.." elapsedMs="..elapsed.." root="..root.key.." source="..root.source.." old="..hex(previous).." new="..hex(pointer)) end
                scan_dynamic_object(pointer,root.source,root.method,elapsed)
            elseif pointer then
                scan_dynamic_object(pointer,root.source,root.method,elapsed)
            end
        end
        for _,row in ipairs(watchRows) do
            local value=read_int(row.address)
            if value~=nil then
                row.observed[value]=true
                if value~=row.last then
                    local old=row.last
                    row.last=value
                    row.changes=row.changes+1
                    row.firstChangeMs=row.firstChangeMs or elapsed
                    row.lastChangeMs=elapsed
                    lab.changes=lab.changes+1
                    if startup.region_names[value] then
                        row.regionChanges=row.regionChanges+1
                        lab.regionChanges=lab.regionChanges+1
                        if expectedValue~=nil and value==expectedValue then row.seenExpected=true end
                        if targetValue~=nil and value==targetValue then row.seenTarget=true end
                    end
                    if eventLogCount<180 and startup.support_log_event_quiet then
                        eventLogCount=eventLogCount+1
                        startup.support_log_event_quiet("REGION_REQUEST_CHANGE","phase="..phase.." elapsedMs="..elapsed.." address="..row.key.." section="..tostring(row.section).." dynamic="..tostring(row.dynamic).." old="..tostring(old).." new="..tostring(value).." label="..tostring(startup.region_names[value] or "non-region").." source="..source_text(row))
                    end
                end
            end
        end
    end

    for _=1,10 do sample("baseline",startup.now()-startMs); yield_ms(100) end
    lab.phase="Starting session"
    startup.regionExperimentInternalStart=true
    startup.regionExperimentSessionStarted=true
    local startOk,startErr=direct_call(function()
        startup.apply_session_type()
        yield_ms(500)
        startup.start_session(true)
    end)
    startup.regionExperimentInternalStart=false
    lab.sessionStarted=startOk
    local requestStart=startup.now()
    if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_SESSION_START","ok="..tostring(startOk).." error="..tostring(startErr).." route="..tostring(startup.s.sessionType or "").." selected="..mode) end
    if not startOk then
        lab.running=false; lab.phase="Error"; lab.lastStatus="Session start failed: "..tostring(startErr)
        startup.regionExperimentLock=false
        startup.s.matchmakingRegionOverrideLastStatus=lab.lastStatus
        startup.log_colored("Legacy Matchmaking Request Trace could not start the controlled session: "..tostring(startErr),"error")
        return false
    end

    lab.phase="Watching matchmaking request"
    for _=1,260 do
        local elapsed=startup.now()-requestStart
        sample(sessionLoadedAt and "post-load" or "request",elapsed)
        local changedAt=tonumber(startup.s.lastSessionChangeMs or 0) or 0
        if not sessionLoadedAt and changedAt>sessionMarker then
            sessionLoadedAt=elapsed
            lab.sessionLoaded=true
            lab.phase="Session loaded; collecting tail"
            for _,row in ipairs(watchRows) do row.valueAtLoaded=read_int(row.address) end
            if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_SESSION_LOADED","elapsedMs="..elapsed.." watched="..#watchRows.." dynamicObjects="..lab.dynamicObjects.." changes="..lab.changes) end
        end
        if sessionLoadedAt and elapsed-sessionLoadedAt>=5000 then break end
        yield_ms(100)
    end

    local ranked={}
    for _,row in ipairs(watchRows) do
        row.finalValue=read_int(row.address)
        local score=0
        if row.dynamic then score=score+25 end
        if row.changes>0 then score=score+math.min(30,row.changes*6) end
        if row.firstChangeMs and row.firstChangeMs>=0 and row.firstChangeMs<=6000 then score=score+20 end
        if row.seenExpected then score=score+30 end
        if row.seenTarget and targetValue~=expectedValue then score=score+8 end
        if row.valueAtLoaded~=nil and expectedValue~=nil and row.valueAtLoaded==expectedValue then score=score+20 end
        if row.finalValue~=nil and expectedValue~=nil and row.finalValue==expectedValue then score=score+12 end
        local sourceCount=0 for _ in pairs(row.sources or {}) do sourceCount=sourceCount+1 end
        score=score+math.min(12,sourceCount*2)
        if tostring(row.section)==".data" then score=score-8 end
        row.score=score
        if row.changes>0 or row.dynamic or row.seenExpected then ranked[#ranked+1]=row end
    end
    table.sort(ranked,function(a,b)
        if a.score~=b.score then return a.score>b.score end
        if a.changes~=b.changes then return a.changes>b.changes end
        return a.address<b.address
    end)
    lab.results={}
    for index,row in ipairs(ranked) do
        if index>30 then break end
        local result={rank=index,address=row.key,score=row.score,baseline=row.baseline,loaded=row.valueAtLoaded,final=row.finalValue,changes=row.changes,dynamic=row.dynamic,source=source_text(row)}
        lab.results[#lab.results+1]=result
        if index==1 then lab.bestAddress=row.key; lab.bestScore=row.score; lab.bestSource=result.source end
        if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_CANDIDATE","rank="..index.." address="..row.key.." score="..row.score.." section="..tostring(row.section).." dynamic="..tostring(row.dynamic).." baseline="..tostring(row.baseline).." loaded="..tostring(row.valueAtLoaded).." final="..tostring(row.finalValue).." changes="..tostring(row.changes).." firstChangeMs="..tostring(row.firstChangeMs).." lastChangeMs="..tostring(row.lastChangeMs).." seenExpected="..tostring(row.seenExpected).." seenTarget="..tostring(row.seenTarget).." source="..result.source) end
    end

    lab.running=false
    lab.phase="Complete"
    startup.regionExperimentLock=false
    if #ranked>0 then
        lab.lastStatus="Request trace completed: "..lab.changes.." field change(s), "..lab.dynamicObjects.." dynamic object(s), best="..tostring(lab.bestAddress).." score="..tostring(lab.bestScore)..". No memory was written."
        startup.log_colored("Legacy Matchmaking Request Trace completed: "..lab.changes.." field change(s), "..lab.dynamicObjects.." dynamic object(s).","success")
        startup.log_colored("Best read-only request candidate: "..tostring(lab.bestAddress)..". Create a Support ZIP for the ranked trace.","info")
    else
        lab.lastStatus="Request trace completed, but no watched Region-range field changed during matchmaking. No memory was written."
        startup.log_colored(lab.lastStatus,"warning")
    end
    startup.s.matchmakingRegionOverrideLastStatus=lab.lastStatus
    state.address=nil
    state.activeConfidence="dump-verified-session-request-trace-read-only"
    if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_LAB_END","version=3 methodsCompleted="..lab.methodsCompleted.." watched="..lab.watchAddresses.." pointerRoots="..lab.pointerRoots.." dynamicObjects="..lab.dynamicObjects.." changes="..lab.changes.." regionChanges="..lab.regionChanges.." sessionStarted="..tostring(lab.sessionStarted).." sessionLoaded="..tostring(lab.sessionLoaded).." ranked="..#ranked.." bestAddress="..tostring(lab.bestAddress).." bestScore="..tostring(lab.bestScore).." status="..lab.lastStatus) end
    return #ranked>0
end

function startup.queue_region_pattern_rescan(reason)
    if startup.regionProductionHidden == true then
        startup.regionRescanJobQueued = false
        return false
    end
    if startup.regionRescanJobQueued == true then
        startup.s.matchmakingRegionOverrideLastStatus = "Region rescan already running."
        return false
    end
    local now = startup.now()
    local last = tonumber(startup.region_scan and startup.region_scan.lastAttemptMs or 0) or 0
    if last > 0 and (now - last) < 5000 then
        startup.s.matchmakingRegionOverrideLastStatus = "Region scan cooldown; try again in a few seconds."
        return false
    end
    startup.regionRescanJobQueued = true
    startup.s.matchmakingRegionOverrideLastStatus = "Region rescan queued" .. (reason and (": " .. tostring(reason)) or "")
    local function job()
        local mode = tostring(startup.s.matchmakingRegionOverrideMode or "Original")
        -- Restore the launch value before rediscovering the pointer so an active spoof does
        -- not get mistaken for the new original value.
        if mode ~= "Original" then direct_call(startup.restore_matchmaking_region_override_on_unload) end
        startup.region_scan.address = nil
        startup.region_scan.patternName = ""
        startup.region_scan.moduleName = ""
        startup.region_scan.lastValue = nil
        startup.region_scan.originalValue = nil
        local enhanced = startup.is_enhanced_active_edition()
        local scanFunction = enhanced and startup.run_region_deep_scan or startup.run_region_dump_scan
        local ok, err = direct_call(scanFunction)
        if not ok then
            startup.region_scan.lastStatus = "Pattern scan error: " .. tostring(err)
            elseif not enhanced and startup.region_scan.dumpScan and startup.region_scan.dumpScan.compatible == true then
            local traceOk, traceResult = direct_call(startup.run_legacy_region_live_trace)
            if not traceOk then
                startup.region_scan.runtimeTrace = startup.region_scan.runtimeTrace or {}
                startup.region_scan.runtimeTrace.running = false
                startup.region_scan.runtimeTrace.lastStatus = "Trace error: "..tostring(traceResult)
                startup.region_scan.lastStatus = "Legacy live trace error: "..tostring(traceResult)
                startup.log_colored("Legacy live Region trace failed: "..tostring(traceResult), "error")
                if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_LIVE_TRACE_ERROR", tostring(traceResult)) end
            else
                local probeOk, probeErr = direct_call(startup.run_legacy_exact_region_sysparam_probe)
                if not probeOk then
                    startup.region_scan.exactParamProbe = startup.region_scan.exactParamProbe or {}
                    startup.region_scan.exactParamProbe.running = false
                    startup.region_scan.exactParamProbe.lastStatus = "Exact sysParam probe error: "..tostring(probeErr)
                    startup.s.matchmakingRegionOverrideLastStatus = startup.region_scan.exactParamProbe.lastStatus
                    startup.log_colored("Legacy exact Force Region sysParam probe failed: "..tostring(probeErr), "error")
                    if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_EXACT_PARAM_ERROR", tostring(probeErr)) end
                end
            end
        end
        if ok and startup.region_scan.address and mode ~= "Original" then
            startup.pendingRegionOverrideApply = true
        elseif mode ~= "Original" and not startup.region_scan.address then
            startup.pendingRegionOverrideApply = false
            local exactStatus = startup.region_scan.exactParamProbe and startup.region_scan.exactParamProbe.lastStatus
            local traceStatus = startup.region_scan.runtimeTrace and startup.region_scan.runtimeTrace.lastStatus or startup.region_scan.lastStatus
            if exactStatus and exactStatus ~= "Not run" and exactStatus ~= "Running" then
                startup.s.matchmakingRegionOverrideLastStatus = tostring(exactStatus)
            else
                startup.s.matchmakingRegionOverrideLastStatus = "Requested "..mode.."; not applied because the writable field is not proven. "..tostring(traceStatus or "")
            end
        end
        startup.regionRescanJobQueued = false
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
    return true
end

function startup.apply_matchmaking_region_override_now()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    local address = tonumber(state.address)
    if not address or address == 0 or not Memory or not Memory.WriteInt or not Memory.ReadInt then
        if state.fallbackLabel then
            startup.s.matchmakingRegionOverrideLastStatus = "Region is read-only (" .. tostring(state.fallbackSource or "fallback") .. "). Current writable signature not found."
        else
            startup.s.matchmakingRegionOverrideLastStatus = "Region pattern pointer unavailable."
        end
        return false
    end
    if state.originalValue == nil then
        local okRead, current = direct_call(Memory.ReadInt, address)
        local label = okRead and startup.region_memory_label(current) or nil
        if label then state.originalValue = tonumber(current) end
    end
    local mode = tostring(startup.s.matchmakingRegionOverrideMode or "Original")
    local target = mode == "Original" and tonumber(state.originalValue) or startup.region_value_by_label[mode]
    if target == nil then startup.s.matchmakingRegionOverrideLastStatus = "Original region was not captured."; return false end
    local okWrite, err = direct_call(Memory.WriteInt, address, target)
    if not okWrite then startup.s.matchmakingRegionOverrideLastStatus = "Region write failed: "..tostring(err); return false end
    if Script and Script.Yield then Script.Yield(50) end
    local okVerify, verify = direct_call(Memory.ReadInt, address)
    local label = okVerify and startup.region_memory_label(verify) or nil
    if not okVerify or tonumber(verify) ~= tonumber(target) then startup.s.matchmakingRegionOverrideLastStatus = "Region write could not be verified."; return false end
    state.lastValue = tonumber(verify)
    startup.s.matchmakingRegionOverrideLastVerified = tostring(label or verify)
    startup.s.matchmakingRegionOverrideLastStatus = mode == "Original" and ("Restored original region: "..tostring(label or verify)) or ("Applied: "..mode.." (in-memory)")
    if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_OVERRIDE", "mode="..mode.." value="..tostring(verify).." verified="..tostring(label or "Unknown")) end
    return true
end

function startup.request_matchmaking_region_override_apply()
    if startup.regionProductionHidden == true then
        startup.pendingRegionOverrideApply = false
        return false
    end
    local mode = tostring(startup.s.matchmakingRegionOverrideMode or "Original")
    if startup.region_scan and startup.region_scan.address then
        startup.pendingRegionOverrideApply = true
        return true
    end
    startup.pendingRegionOverrideApply = false
    if mode == "Original" then
        startup.s.matchmakingRegionOverrideLastStatus = "Original selected. No writable Region field is active."
    else
        local traceStatus = startup.region_scan and startup.region_scan.runtimeTrace and startup.region_scan.runtimeTrace.lastStatus or "Run Rescan Region Pattern for read-only diagnostics."
        startup.s.matchmakingRegionOverrideLastStatus = "Requested "..mode.."; not applied because the writable field is not proven. "..tostring(traceStatus)
    end
    return false
end

function startup.process_pending_matchmaking_region_override()
    if startup.regionProductionHidden == true then
        startup.pendingRegionOverrideApply = false
        return false
    end
    if startup.pendingRegionOverrideApply ~= true or startup.regionOverrideJobQueued == true then return end
    if not startup.region_scan or not startup.region_scan.address then return end
    startup.pendingRegionOverrideApply = false
    startup.regionOverrideJobQueued = true
    local function job()
        local ok, err = direct_call(startup.apply_matchmaking_region_override_now)
        if not ok then startup.s.matchmakingRegionOverrideLastStatus = "Region override error: "..tostring(err) end
        startup.regionOverrideJobQueued = false
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

function startup.restore_matchmaking_region_override_on_unload()
    if startup.regionProductionHidden == true then
        return false
    end
    local state = startup.region_scan or {}
    local address, original = tonumber(state.address), tonumber(state.originalValue)
    if not address or original == nil or not Memory or not Memory.WriteInt then return false end
    return direct_call(Memory.WriteInt, address, original) == true
end

function startup.get_matchmaking_region_label()
    if startup.region_scan and startup.region_scan.address and Memory and Memory.ReadInt then
        local ok, value = direct_call(Memory.ReadInt, startup.region_scan.address)
        local label = ok and startup.region_memory_label(value) or nil
        if label then return label end
    end
    if startup.region_scan and startup.region_scan.fallbackLabel then
        return tostring(startup.region_scan.fallbackLabel)
    end
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return "Automatic" end
    local featureNames = { "Matchmaking Region", "Matchmaking Region Override", "Matchmaking Region Spoof" }
    for _, featureName in ipairs(featureNames) do
        local feature = FeatureMgr.GetFeatureByName(featureName)
        if feature then
            if feature.GetList and feature.GetListIndex then
                local list = feature:GetList()
                local index = tonumber(feature:GetListIndex() or 0) or 0
                if type(list) == "table" then
                    local label = list[index + 1]
                    if label and tostring(label) ~= "" then return tostring(label) end
                end
            end
            if feature.GetStringValue then
                local value = tostring(feature:GetStringValue() or "")
                if value ~= "" then return value end
            end
        end
    end
    return "Automatic"
end

function startup.get_rockstar_friends_in_gta()
    -- "NETWORK_IS_FRIEND_IN_MULTIPLAYER" means the friend is playing GTA multiplayer,
    -- not necessarily that they are in our current session. Build a current-session name
    -- set first, then intersect the Rockstar friend list with that live roster.
    local names = {}
    if not Natives or not Natives.InvokeInt or not Natives.InvokeString then return names end

    local sessionNames = {}
    for _, playerId in ipairs(startup.get_voice_player_ids()) do
        local playerName = tostring(startup.get_player_name_safe(playerId) or "")
        playerName = playerName:gsub("^%s+", ""):gsub("%s+$", "")
        if playerName ~= "" then
            sessionNames[string.lower(playerName)] = playerName
        end
    end

    local count = tonumber(Natives.InvokeInt(startup.hud_network_native.NETWORK_GET_FRIEND_COUNT) or 0) or 0
    count = startup.clamp_int(count, 0, 500)
    local seen = {}
    for friendIndex = 0, count - 1 do
        local friendName = tostring(Natives.InvokeString(startup.hud_network_native.NETWORK_GET_FRIEND_NAME, friendIndex) or "")
        friendName = friendName:gsub("^%s+", ""):gsub("%s+$", "")
        local key = string.lower(friendName)
        local sessionName = sessionNames[key]
        if friendName ~= "" and sessionName and not seen[key] then
            seen[key] = true
            names[#names + 1] = sessionName
        end
    end

    table.sort(names, function(a, b) return string.lower(a) < string.lower(b) end)
    return names
end

startup.friend_lookup_cache = startup.friend_lookup_cache or { at=0, names={} }
function startup.is_name_current_friend(name)
    local key = string.lower(tostring(name or ""))
    if key == "" then return false end
    local now = startup.now()
    if now - (tonumber(startup.friend_lookup_cache.at or 0) or 0) > 1000 then
        local set = {}
        for _, friendName in ipairs(startup.get_rockstar_friends_in_gta()) do set[string.lower(tostring(friendName or ""))] = true end
        startup.friend_lookup_cache.names = set
        startup.friend_lookup_cache.at = now
    end
    return startup.friend_lookup_cache.names[key] == true
end

function startup.is_player_current_friend(playerId)
    return startup.is_name_current_friend(startup.get_player_name_safe(playerId))
end

function startup.friend_hud_lines(names)
    local lines = {}
    local current = ""
    local maxChars = 44
    for _, name in ipairs(names or {}) do
        local item = tostring(name or "")
        if item ~= "" then
            local candidate = current == "" and item or (current .. ", " .. item)
            if current ~= "" and string.len(candidate) > maxChars then
                lines[#lines + 1] = current
                current = item
            else
                current = candidate
            end
        end
    end
    if current ~= "" then lines[#lines + 1] = current end
    return lines
end

function startup.update_hud_cache(force)
    local now = startup.now()
    if not force and now - (startup.hud_cache.lastUpdateMs or 0) < 1000 then return end
    startup.hud_cache.lastUpdateMs = now
    startup.hud_cache.connected = startup.get_session_player_count()
    startup.hud_cache.isPrime = startup.is_prime_active_edition()

    if startup.s.showPrimeHostHud or startup.s.showNextHostHud then
        startup.hud_cache.hostName, startup.hud_cache.hostPlayerId = startup.get_session_host_name()
    else
        startup.hud_cache.hostName, startup.hud_cache.hostPlayerId = "Unknown", -1
    end

    if startup.s.showScriptHostHud then
        startup.hud_cache.scriptHostName, startup.hud_cache.scriptHostPlayerId = startup.get_script_host_name()
    else
        startup.hud_cache.scriptHostName, startup.hud_cache.scriptHostPlayerId = "Unknown", -1
    end

    if startup.s.showNextHostHud then
        startup.hud_cache.nextHostName, startup.hud_cache.nextHostPlayerId = startup.get_next_host_name(startup.hud_cache.hostPlayerId)
    else
        startup.hud_cache.nextHostName, startup.hud_cache.nextHostPlayerId = "Unknown", -1
    end

    startup.hud_cache.natType = startup.s.showNatTypeHud and startup.get_local_nat_type() or "Unknown"
    startup.hud_cache.matchmakingRegion = "Automatic"
    if startup.s.showAdvertiseRegionHud and startup.is_enhanced_active_edition() and startup.get_advertise_region_label then
        startup.hud_cache.advertiseRegion = startup.get_advertise_region_label(false)
    else
        startup.hud_cache.advertiseRegion = "Unknown"
    end

    if startup.s.showFriendsHud then
        if force or now - (startup.hud_cache.lastFriendsUpdateMs or 0) >= 5000 then
            startup.hud_cache.lastFriendsUpdateMs = now
            startup.hud_cache.friendNames = startup.get_rockstar_friends_in_gta()
        end
    else
        startup.hud_cache.friendNames = {}
    end

    startup.update_voice_speakers(force)
end

-- Keep HUD placement visually consistent on ultrawide displays.
-- GTA text Y/scale are height-oriented, but a raw normalized X drifts farther right
-- as the aspect ratio widens. 16:9 remains unchanged; wider screens are corrected
-- back to the same perceived horizontal placement.
function startup.get_hud_horizontal_scale()
    if not Natives or not Natives.InvokeFloat then return 1.0 end
    local aspect = tonumber(Natives.InvokeFloat(0xF1307EF624A80D87, true) or 0) or 0
    local reference = 16.0 / 9.0
    if aspect <= reference or aspect <= 0 then return 1.0 end
    local scale = reference / aspect
    return startup.clamp_float(scale, 0.55, 1.0)
end

function startup.get_effective_hud_x(x)
    x = tonumber(x or startup.s.sessionInfoHudX or 0.169) or 0.169
    return x * startup.get_hud_horizontal_scale()
end

function startup.draw_hud_text(text, x, y, scale, r, g, b, a, font)
    if not startup.s.sessionInfoHudEnabled then return end
    if not Natives or not Natives.InvokeVoid then
        startup.s.lastHudStatus = "Natives unavailable"
        return
    end
    text = tostring(text or "")
    x = tonumber(x or 0.169) or 0.169
    y = tonumber(y or 0.941) or 0.941
    scale = tonumber(scale or 0.30) or 0.30
    r = tonumber(r or 255) or 255
    g = tonumber(g or 255) or 255
    b = tonumber(b or 255) or 255
    a = tonumber(a or 200) or 200
    font = tonumber(font or 4) or 4
    Natives.InvokeVoid(0x66E0276CC5F6B9DA, font)
    Natives.InvokeVoid(0x07C837F9A01C34C9, 0.0, scale + 0.0)
    Natives.InvokeVoid(0xBE6B23FFA53FB442, r, g, b, a)
    Natives.InvokeVoid(0xC02F4DBFB51D988B, false)
    if startup.s.sessionInfoHudShadow then
        Natives.InvokeVoid(0x1CA3E9EAC9D93E5E)
        Natives.InvokeVoid(0x2513DFB0FB8400FE)
    end
    Natives.InvokeVoid(0x25FBB336DF1804CB, "STRING")
    Natives.InvokeVoid(0x6C188BE134E074AA, text)
    Natives.InvokeVoid(0xCD015E5BB0D96A57, x + 0.0, y + 0.0)
end

function startup.draw_hud_rect(x, y, width, height, r, g, b, a)
    if not startup.s.sessionInfoHudEnabled then return end
    if not Natives or not Natives.InvokeVoid then return end
    x = tonumber(x or 0.0) or 0.0
    y = tonumber(y or 0.0) or 0.0
    width = math.max(0.001, tonumber(width or 0.20) or 0.20)
    height = math.max(0.001, tonumber(height or 0.04) or 0.04)
    Natives.InvokeVoid(0x3A618A217E5154F0, x + (width * 0.5), y + (height * 0.5), width, height,
        tonumber(r or 0) or 0, tonumber(g or 0) or 0, tonumber(b or 0) or 0, tonumber(a or 150) or 150, false)
end

function startup.clamp01(value)
    value = tonumber(value or 0) or 0
    if value < 0 then return 0 end
    if value > 1 then return 1 end
    return value
end

function startup.ease_out_cubic(value)
    local t = startup.clamp01(value)
    local inv = 1 - t
    return 1 - (inv * inv * inv)
end

function startup.ease_in_cubic(value)
    local t = startup.clamp01(value)
    return t * t * t
end

function startup.get_session_player_count()
    local count = 0
    local players = nil
    if Players and Players.Get then
        players = Players.Get(ePlayerListSort.PLAYER_ID, "")
    end
    if not players then
        return 0
    end
    for _, playerId in pairs(players) do
        if playerId ~= nil then
            count = count + 1
        end
    end
    return count
end

startup.session_activity = startup.session_activity or { entries = {}, knownPlayers = {}, sequence = 0, recent = {} }
startup.hud_simulation = startup.hud_simulation or { startedMs = 0, stage = 0, cycle = 0 }

function startup.session_activity_native_text(kind, name, reason)
    name = tostring(name or "Unknown")
    reason = tostring(reason or "")
    if kind == "joining" then
        return name .. " is joining..."
    elseif kind == "blocked" then
        local text = "~r~Blocked " .. name .. " joining...~s~"
        if reason ~= "" then text = text .. "~n~~o~Reason: " .. reason .. "~s~" end
        return text
    elseif kind == "left" then
        return name .. " left."
    elseif kind == "kicking" then
        local text = "~o~Kicking: " .. name .. "~s~"
        if reason ~= "" then text = text .. "~n~~o~Reason: " .. reason .. "~s~" end
        return text
    elseif kind == "kicked" then
        local text = "~r~Kicked " .. name .. "~s~"
        if reason ~= "" then text = text .. "~n~~o~Reason: " .. reason .. "~s~" end
        return text
    end
    return name
end

function startup.post_native_session_feed(kind, name, reason)
    if startup.s.playerModUiEnabled == false then return false end
    if startup.s.sessionActivityUseNativeFeed == false then return false end
    if kind == "left" and startup.s.sessionActivityPostLeave ~= true then return false end
    if not Script or not Script.QueueJob or not Natives or not Natives.InvokeVoid or not Natives.InvokeInt then return false end
    local text = startup.session_activity_native_text(kind, name, reason)
    if text == "" then return false end
    Script.QueueJob(function()
        Natives.InvokeVoid(0x202709F4C58A0424, "STRING")
        Natives.InvokeVoid(0x6C188BE134E074AA, text)
        Natives.InvokeInt(0x2ED7843F8F801023, false, false)
    end)
    return true
end

function startup.session_activity_is_duplicate(kind, name, reason)
    local now = startup.now()
    local key = string.lower(tostring(kind or "") .. "|" .. tostring(name or "") .. "|" .. tostring(reason or ""))
    local last = tonumber(startup.session_activity.recent[key] or 0) or 0
    startup.session_activity.recent[key] = now
    for recentKey, recentMs in pairs(startup.session_activity.recent) do
        if now - (tonumber(recentMs or 0) or 0) > 10000 then startup.session_activity.recent[recentKey] = nil end
    end
    return last > 0 and (now - last) < 1800
end

function startup.session_activity_record(kind, name, reason, holdMs)
    name = tostring(name or "Unknown"):gsub("^%s+", ""):gsub("%s+$", "")
    reason = tostring(reason or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then name = "Unknown" end
    if startup.session_activity_is_duplicate(kind, name, reason) then return end
    startup.post_native_session_feed(kind, name, reason)
    startup.session_activity.sequence = (startup.session_activity.sequence or 0) + 1
    local now = startup.now()
    local ttl = tonumber(holdMs or startup.s.sessionActivityHoldMs or 7000) or 7000
    startup.session_activity.entries[#startup.session_activity.entries + 1] = {
        id = startup.session_activity.sequence,
        kind = tostring(kind or "info"),
        name = name,
        reason = reason,
        createdMs = now,
        expiresMs = now + ttl,
        renderY = nil
    }
    local maxKeep = math.max(1, tonumber(startup.s.sessionActivityMaxEntries or 5) or 5)
    while #startup.session_activity.entries > maxKeep do table.remove(startup.session_activity.entries, 1) end
end

function startup.session_activity_prune()
    local now = startup.now()
    local kept = {}
    for _, entry in ipairs(startup.session_activity.entries or {}) do
        if entry and (entry.expiresMs or 0) > now then kept[#kept + 1] = entry end
    end
    startup.session_activity.entries = kept
end

function startup.session_activity_player_name(playerId)
    playerId = tonumber(playerId)
    if playerId ~= nil and startup.session_activity.knownPlayers[playerId] then
        return startup.session_activity.knownPlayers[playerId]
    end
    if playerId ~= nil then
        local name = startup.get_player_name_safe(playerId)
        if name and name ~= "" and not string.find(name, "Player ", 1, true) then
            startup.session_activity.knownPlayers[playerId] = name
            return name
        end
    end
    return playerId ~= nil and ("Player " .. tostring(playerId)) or "Unknown player"
end

function startup.session_activity_refresh_known_players()
    if not Players or not Players.Get then return end
    local players = Players.Get(ePlayerListSort.PLAYER_ID, "")
    if not players then return end
    for _, playerId in pairs(players) do
        local id = tonumber(playerId)
        if id ~= nil then
            local name = startup.get_player_name_safe(id)
            if name and name ~= "" then startup.session_activity.knownPlayers[id] = name end
        end
    end
end

function startup.session_activity_content(entry)
    if not entry then return "", "", {185,185,185} end
    if entry.kind == "joining" then
        return tostring(entry.name) .. " is joining...", "", {100, 200, 255}
    elseif entry.kind == "blocked" then
        return "Blocked " .. tostring(entry.name) .. " joining...", entry.reason ~= "" and ("Reason: " .. tostring(entry.reason)) or "", {255, 90, 90}
    elseif entry.kind == "left" then
        return tostring(entry.name) .. " left", "", {185, 185, 185}
    elseif entry.kind == "kicking" then
        return "Kicking: " .. tostring(entry.name), entry.reason ~= "" and ("Reason: " .. tostring(entry.reason)) or "", {255, 185, 80}
    elseif entry.kind == "kicked" then
        return "Kicked " .. tostring(entry.name), entry.reason ~= "" and ("Reason: " .. tostring(entry.reason)) or "", {255, 120, 70}
    end
    return tostring(entry.name), tostring(entry.reason or ""), {220,220,220}
end

function startup.session_activity_lines()
    startup.session_activity_prune()
    local lines = {}
    for _, entry in ipairs(startup.session_activity.entries or {}) do
        local primary, secondary, color = startup.session_activity_content(entry)
        lines[#lines + 1] = { text = primary, color = color }
        if secondary ~= "" then lines[#lines + 1] = { text = secondary, color = {255, 185, 80} } end
    end
    return lines
end

function startup.session_activity_entry_height(entry, scale)
    local _, secondary = startup.session_activity_content(entry)
    local lineGap = math.max(0.020, (tonumber(scale or 0.30) or 0.30) * 0.075)
    if secondary ~= "" then return lineGap * 1.92 end
    return lineGap * 1.20
end

function startup.render_session_activity_feed(x, bottomY, scale, textAlpha)
    if not startup.s.showSessionActivityHud then return 0 end
    if startup.s.sessionActivityUseNativeFeed ~= false then return 0 end
    startup.session_activity_prune()
    local entries = startup.session_activity.entries or {}
    if #entries == 0 then return 0 end

    local now = startup.now()
    local renderScale = tonumber(scale or 0.30) or 0.30
    local enterMs = math.max(100, tonumber(startup.s.sessionActivityEnterMs or 420) or 420)
    local fadeMs = math.max(200, tonumber(startup.s.sessionActivityFadeMs or 900) or 900)
    local boxAlpha = math.max(0, math.min(230, tonumber(startup.s.sessionActivityBoxAlpha or 155) or 155))
    local animated = startup.s.sessionActivityAnimated ~= false
    local horizontalScale = startup.get_hud_horizontal_scale()
    local gap = 0.004
    local cursorBottom = bottomY
    local targets = {}
    local minBoxWidth = 0.135 * horizontalScale
    local maxBoxWidth = 0.235 * horizontalScale
    local charUnit = (0.0032 + (renderScale * 0.0014)) * horizontalScale

    for i = #entries, 1, -1 do
        local entry = entries[i]
        local height = startup.session_activity_entry_height(entry, renderScale)
        local targetTop = cursorBottom - height
        targets[i] = { y = targetTop, h = height }
        cursorBottom = targetTop - gap
    end

    for i, entry in ipairs(entries) do
        local target = targets[i]
        local age = math.max(0, now - (entry.createdMs or now))
        local remain = math.max(0, (entry.expiresMs or now) - now)
        local enterT = animated and startup.ease_out_cubic(age / enterMs) or 1.0
        local fadeT = remain < fadeMs and startup.clamp01(remain / fadeMs) or 1.0
        if animated and remain < fadeMs then fadeT = 1.0 - startup.ease_in_cubic(1.0 - fadeT) end
        local opacity = math.min(enterT, fadeT)

        if entry.renderY == nil then
            entry.renderY = target.y + (animated and 0.016 or 0.0)
        end
        if animated then
            entry.renderY = entry.renderY + ((target.y - entry.renderY) * 0.16)
        else
            entry.renderY = target.y
        end

        local primary, secondary, color = startup.session_activity_content(entry)
        local longestText = math.max(string.len(primary or ""), string.len(secondary or ""), string.len("Connected Players: 28"))
        local boxWidth = math.max(minBoxWidth, math.min(maxBoxWidth, 0.060 + (longestText * charUnit)))
        local slideX = animated and ((1.0 - enterT) * (-0.012 * horizontalScale)) or 0.0
        if animated and remain < fadeMs then slideX = slideX + ((1.0 - fadeT) * (-0.010 * horizontalScale)) end
        local boxX = x - (0.004 * horizontalScale) + slideX
        local drawAlpha = math.floor((tonumber(textAlpha or 200) or 200) * opacity)
        local bgAlpha = math.floor(boxAlpha * opacity)

        startup.draw_hud_rect(boxX, entry.renderY, boxWidth, target.h, 5, 5, 8, bgAlpha)
        startup.draw_hud_rect(boxX, entry.renderY, 0.003 * horizontalScale, target.h, color[1], color[2], color[3], math.floor(220 * opacity))
        startup.draw_hud_text(primary, boxX + (0.009 * horizontalScale), entry.renderY + 0.0035, renderScale, color[1], color[2], color[3], drawAlpha, 4)
        if secondary ~= "" then
            local lineGap = math.max(0.020, renderScale * 0.075)
            startup.draw_hud_text(secondary, boxX + (0.009 * horizontalScale), entry.renderY + 0.0035 + lineGap, renderScale * 0.90, 255, 185, 80, drawAlpha, 4)
        end
    end

    return math.max(0, bottomY - cursorBottom)
end

function startup.update_hud_simulation()
    if not startup.s.hudSimulationEnabled then return end
    local now = startup.now()
    if (startup.hud_simulation.startedMs or 0) <= 0 then
        startup.hud_simulation.startedMs = now
        startup.hud_simulation.stage = 0
    end

    local elapsed = now - startup.hud_simulation.startedMs
    local cycleMs = 11000 + math.max(3000, tonumber(startup.s.sessionActivityHoldMs or 7000) or 7000) + 1500
    if elapsed >= cycleMs then
        startup.hud_simulation.startedMs = now
        startup.hud_simulation.stage = 0
        startup.hud_simulation.cycle = (startup.hud_simulation.cycle or 0) + 1
        startup.session_activity.entries = {}
        elapsed = 0
    end

    local stages = {
        { at = 450, kind = "joining", name = "Kian_Fischy", reason = "" },
        { at = 2500, kind = "joining", name = "Battleye_User", reason = "" },
        { at = 3900, kind = "blocked", name = "Battleye_User", reason = "Battleye Emulator" },
        { at = 6500, kind = "left", name = "Friendly_Player", reason = "" },
        { at = 8500, kind = "joining", name = "CrashTester", reason = "" },
        { at = 9900, kind = "blocked", name = "CrashTester", reason = "Crash Type V2" }
    }
    while (startup.hud_simulation.stage or 0) < #stages do
        local nextIndex = (startup.hud_simulation.stage or 0) + 1
        local item = stages[nextIndex]
        if elapsed < item.at then break end
        startup.session_activity_record(item.kind, item.name, item.reason, startup.s.sessionActivityHoldMs)
        startup.hud_simulation.stage = nextIndex
    end
end

function startup.run_hud_simulation()
    startup.s.playerModUiEnabled = true
    startup.set_feature_bool_silently(startup.h.PlayerModUiToggle, true)
    startup.s.hudSimulationEnabled = true
    startup.s.sessionInfoHudEnabled = true
    startup.s.showSessionActivityHud = true
    startup.hud_cache.connected = 28
    startup.session_activity.entries = {}
    startup.hud_simulation.startedMs = startup.now()
    startup.hud_simulation.stage = 0
    startup.hud_simulation.cycle = 0
    startup.toast("Notification feed demo started. GTA native feed mode will stack with natural GTA notifications automatically.", 5000)
end

function startup.stop_hud_simulation()
    startup.s.hudSimulationEnabled = false
    startup.session_activity.entries = {}
    startup.hud_simulation.startedMs = 0
    startup.hud_simulation.stage = 0
    startup.update_hud_cache(true)
    startup.toast("HUD Simulation disabled. Live session data restored.", 3000)
end

