function startup.apply_config(data)
    if type(data) ~= "table" then return end
    startup.s.firstRunWelcomeCompleted = data.firstRunWelcomeCompleted == true
    startup.s.firstRunWelcomeCompletedAt = tonumber(data.firstRunWelcomeCompletedAt or 0) or 0
    if data.firstRunInstallPending == true then
        startup.s.firstRunInstallPending = true
    elseif data.firstRunWelcomeCompleted == false
        and tostring(data.onboardingSetupVersion or "") == ""
        and tostring(data.settingsFile or "") == "" then
        -- Recover an interrupted Build 027-style first run whose config file already exists.
        startup.s.firstRunInstallPending = true
    else
        startup.s.firstRunInstallPending = false
    end
    startup.s.onboardingSetupVersion = tostring(data.onboardingSetupVersion or "")
    startup.s.lastAcknowledgedStartupBuild = tostring(data.lastAcknowledgedStartupBuild or "")
    startup.s.settingsProfileSelectionConfirmed = data.settingsProfileSelectionConfirmed == true
    startup.s.verboseStartupLogs = data.verboseStartupLogs == true
    startup.s.muteEventMusicEnabled = data.muteEventMusicEnabled ~= false
    startup.s.eventMusicPulseMs = tonumber(data.eventMusicPulseMs or startup.s.eventMusicPulseMs) or startup.s.eventMusicPulseMs
    startup.s.alwaysDayEnabled = data.alwaysDayEnabled ~= false
    startup.s.alwaysDayTargetHour = startup.clamp_int(data.alwaysDayTargetHour or startup.s.alwaysDayTargetHour, 0, 23)
    startup.s.alwaysDayTargetMinute = startup.clamp_int(data.alwaysDayTargetMinute or startup.s.alwaysDayTargetMinute, 0, 59)
    startup.s.alwaysDayScanMs = startup.clamp_int(data.alwaysDayScanMs or startup.s.alwaysDayScanMs, 1000, 60000)
    startup.s.alwaysNightEnabled = data.alwaysNightEnabled == true
    startup.s.alwaysNightTargetHour = startup.clamp_int(data.alwaysNightTargetHour or startup.s.alwaysNightTargetHour, 0, 23)
    startup.s.alwaysNightTargetMinute = startup.clamp_int(data.alwaysNightTargetMinute or startup.s.alwaysNightTargetMinute, 0, 59)
    if startup.s.alwaysNightEnabled then startup.s.alwaysDayEnabled = false end
    startup.s.settingsFile = data.settingsFile or startup.s.settingsFile
    startup.s.themeFile = data.themeFile or startup.s.themeFile
    startup.s.lastRandomThemeFile = data.lastRandomThemeFile or startup.s.lastRandomThemeFile
    startup.s.sessionType = data.sessionType or startup.s.sessionType
