    startup.sync_feature_states()

    -- Refresh the existing dynamic Lua/theme rows without removing or recreating
    -- FeatureMgr entries. Mutating the feature registry while ClickGUI is rendering can
    -- invalidate its tab coroutine on some Cherax builds.
    if startup.refresh_lua_file_list then startup.refresh_lua_file_list() end
    for _, entry in ipairs(startup.s.luaFiles or {}) do
        startup.s.luaFileStates[entry.path] = false
        local feature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(entry.hash) or nil
        if feature and feature.SetBoolValue then feature:SetBoolValue(false) end
    end
    if startup.refresh_theme_file_list then startup.refresh_theme_file_list() end
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        local key = entry.key or entry.name
        startup.s.themeFileStates[key] = true
        local feature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(entry.hash) or nil
        if feature and feature.SetBoolValue then feature:SetBoolValue(true) end
    end
    startup.save_config(false)

    if startup.apply_start_session_hotkey then startup.apply_start_session_hotkey(false) end
    startup.toast("Startup settings reset to defaults.", 3000)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- feature helpers
-- note: direct cherax feature helpers keep registration and syncing consistent.
-- ═══════════════════════════════════════════════════════════════════════════════════
if Feature then
    function Feature:GetListIndexByString(str)
        local list = self:GetList()
        if not list then return nil end
        for key, value in ipairs(list) do
            if value == str then
                return key - 1
            end
        end
        return nil
    end
    function Feature:SetListIndexByString(str)
        local list = self:GetList()
        if not list then return self end
        for key, value in ipairs(list) do
            if value == str then
                self:SetListIndex(key - 1)
                return self
            end
        end
        return self
    end
end

function startup.get_feature_by_hash_safe(hash)
    if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return nil end
    local ok, feature = direct_call(function() return FeatureMgr.GetFeature(hash) end)
    if ok then return feature end
    return nil
end

function startup.find_feature_by_possible_names(names)
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil, nil end
    for _, name in ipairs(names or {}) do
        local ok, feature = direct_call(function() return FeatureMgr.GetFeatureByName(name) end)
        if ok and feature then return feature, name end
    end
    return nil, nil
end

function startup.restore_nat_hud_feature_state(reason)
    local wanted = startup.s.showNatTypeHud ~= false
    startup.s.showNatTypeHud = wanted
    local wasSyncing = startup.s.syncingFeatureStates == true
    startup.s.syncingFeatureStates = true
    startup.set_feature_bool_silently(startup.h and startup.h.ShowNatTypeHud, wanted)
    if startup.h and startup.h.ShowAdvertiseRegionHud then
        startup.set_feature_bool_silently(startup.h.ShowAdvertiseRegionHud, startup.s.showAdvertiseRegionHud == true)
    end
    startup.s.syncingFeatureStates = wasSyncing
    if wanted and startup.update_hud_cache then startup.update_hud_cache(true) end
    startup.s.pendingNatHudRestore = false
    startup.s.lastNatHudRestoreReason = tostring(reason or "Startup state restored")
    return wanted
end

function startup.process_pending_nat_hud_restore()
    if startup.s.pendingNatHudRestore ~= true then return end
    startup.restore_nat_hud_feature_state("after Cherax settings load")
    startup.save_config(false)
end

function startup.set_feature_bool_silently(hashOrFeature, value)
    local feature = nil
    if type(hashOrFeature) == "number" then
        feature = FeatureMgr.GetFeature(hashOrFeature)
    else
        -- Some reset/sync paths already hold the Feature object. Never feed a
        -- Feature object back into FeatureMgr.GetFeature; Cherax can terminate the
        -- ClickGUI tab coroutine when that happens.
        feature = hashOrFeature
    end
    if feature and feature.SetBoolValue then
        feature:SetBoolValue(value == true)
    end
end

function startup.resolve_feature_silently(hashOrFeature)
    if hashOrFeature == nil then return nil end
    if type(hashOrFeature) == "number" then
        return FeatureMgr.GetFeature(hashOrFeature)
    end
    return hashOrFeature
end

function startup.set_feature_int_silently(hashOrFeature, value)
    local feature = startup.resolve_feature_silently(hashOrFeature)
    if feature then
        value = math.floor(tonumber(value or 0) or 0)
        if feature.SetIntValue then
            feature:SetIntValue(value)
        elseif feature.SetFloatValue then
            feature:SetFloatValue(value)
        end
    end
end

function startup.set_feature_float_silently(hashOrFeature, value)
    local feature = startup.resolve_feature_silently(hashOrFeature)
    if feature then
        value = tonumber(value or 0.0) or 0.0
        if feature.SetFloatValue then
            feature:SetFloatValue(value)
        elseif feature.SetIntValue then
            feature:SetIntValue(math.floor(value))
        end
    end
end

function startup.set_feature_string_silently(hashOrFeature, value)
    local feature = startup.resolve_feature_silently(hashOrFeature)
    if not feature then return false end
    if feature.SetStringValue then
        feature:SetStringValue(tostring(value or ""))
        return true
    end
    return false
end

function startup.set_feature_list_string_silently(hashOrFeature, value)
    local feature = startup.resolve_feature_silently(hashOrFeature)
    if not feature then return false end
    local list = startup.get_feature_list_safe(feature)
    if type(list) ~= "table" then return false end
    local wanted = tostring(value or "")
    for index, label in ipairs(list) do
        if tostring(label) == wanted then
            if feature.SetListIndex then feature:SetListIndex(index - 1) end
            return true
        end
    end
    return false
end

