function startup.find_int_feature_by_names(names, preferredHash)
    local feature = startup.get_feature_by_hash_safe(preferredHash)
    if feature and (feature.SetIntValue or feature.SetValue) then
        return feature, "hash " .. tostring(preferredHash)
    end
    local matchedName
    feature, matchedName = startup.find_feature_by_possible_names(names)
    if feature and (feature.SetIntValue or feature.SetValue) then return feature, matchedName end
    return nil, nil
end

function startup.set_int_feature_by_names(names, value, preferredHash)
    local feature, matchedName = startup.find_int_feature_by_names(names, preferredHash)
    if not feature then
        startup.s.advertiseCountResolution = "Unavailable"
        startup.s.lastAdvertiseStatus = "Advertise Count unavailable; Advertise Session remains active"
        return false
    end
    local ok = direct_call(function()
        if feature.SetIntValue then feature:SetIntValue(value) elseif feature.SetValue then feature:SetValue(value) end
        if feature.TriggerCallback then feature:TriggerCallback() elseif feature.OnClick then feature:OnClick() end
    end)
    if not ok then
        startup.s.advertiseCountResolution = "Resolved but callback failed"
        return false
    end
    startup.s.advertiseCountFeatureName = matchedName
    startup.s.advertiseCountResolution = tostring(matchedName or "Resolved")
    return true
end

function startup.invoke_feature_action(feature)
    if not feature then return false end
    if feature.OnClick then feature:OnClick(); return true end
    if feature.TriggerCallback then feature:TriggerCallback(); return true end
    if feature.Click then feature:Click(); return true end
    if feature.Execute then feature:Execute(); return true end
    return false
end

function startup.click_start_session_feature()
    local hash = startup.feature_hash and startup.feature_hash.START_SESSION or 3364415752
    local feature = startup.get_feature_by_hash_safe(hash)
    if feature then
        local okAction, actionResult = direct_call(startup.invoke_feature_action, feature)
        if okAction and actionResult == true then
            startup.s.lastSessionFlowStatus = "Triggered Cherax Start Session by feature hash"
            startup.toast("Clicked Start Session.", 2500)
            return true
        end
    end
    if FeatureMgr and FeatureMgr.TriggerFeatureCallback then
        local ok, result = direct_call(function() return FeatureMgr.TriggerFeatureCallback(hash) end)
        if ok and result ~= false then
            startup.s.lastSessionFlowStatus = "Triggered Cherax Start Session callback by hash"
            startup.toast("Clicked Start Session.", 2500)
            return true
        end
    end
    local fallbackNames = { "Start New Session", "Session Starter", "Start Session Starter" }
    local fallback, matchedName = startup.find_feature_by_possible_names(fallbackNames)
    if fallback then
        local okAction, actionResult = direct_call(startup.invoke_feature_action, fallback)
        if okAction and actionResult == true then
            startup.s.lastSessionFlowStatus = "Triggered session starter fallback: " .. tostring(matchedName)
            startup.toast("Clicked " .. tostring(matchedName) .. ".", 2500)
            return true
        end
    end
    startup.s.lastSessionFlowStatus = "Cherax Start Session feature unavailable"
    startup.error("Could not trigger Cherax Start Session feature (hash " .. tostring(hash) .. ").")
    return false
end

function startup.click_feature_by_names(names)
    local feature, matchedName = startup.find_feature_by_possible_names(names)
    if not feature then
        startup.error("Could not find button feature. Tried: " .. table.concat(names, ", "))
        return false
    end
    local okAction, actionResult = direct_call(startup.invoke_feature_action, feature)
    if not okAction or actionResult ~= true then
        startup.error("Feature has no callable button action: " .. tostring(matchedName))
        return false
    end
    startup.toast("Clicked " .. matchedName .. ".", 2500)
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- theme scanner
-- note: recursively discovers clickgui themes and preserves enabled choices.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.get_relative_path(path, root)
    local full = tostring(path or ""):gsub("/", "\\")
    local base = tostring(root or ""):gsub("/", "\\")
    if full == "" or base == "" then
        return startup.get_file_name(full)
    end
    local fullLower = string.lower(full)
    local baseLower = string.lower(base)
    if string.sub(fullLower, 1, #baseLower) == baseLower then
        local rel = string.sub(full, #base + 1):gsub("^[\\/]+", "")
        if rel and rel ~= "" then
            return rel
        end
    end
    return startup.get_file_name(full)
end

function startup.get_theme_meta(path)
    local bestRelative = nil
    for _, root in ipairs(startup.theme_dirs or {}) do
        local rel = startup.get_relative_path(path, root)
        if rel and rel ~= "" and rel ~= startup.get_file_name(path) then
            bestRelative = rel
            break
        end
        bestRelative = bestRelative or rel
    end
    local relative = bestRelative or startup.get_file_name(path)
    local folder = relative:match("^(.*)[/\\][^/\\]+$") or "ClickGUI Root"
    if folder == "" then folder = "ClickGUI Root" end
    return {
        fileName = startup.get_file_name(path),
        relative = relative,
        folder = folder,
        key = string.lower(relative),
        displayName = startup.get_file_name(path),
        loadName = relative
    }
end

function startup.find_theme_files()
    local found = {}
    for _, folderPath in ipairs(startup.theme_dirs or {}) do
        local files = FileMgr.FindFiles(folderPath, ".json", true)
        for _, path in ipairs(files or {}) do
            if not startup.path_exists_in_list(found, path) then found[#found + 1] = path end
        end
    end
    table.sort(found, function(a, b)
        local ma, mb = startup.get_theme_meta(a), startup.get_theme_meta(b)
        return string.lower(ma.relative or ma.fileName) < string.lower(mb.relative or mb.fileName)
    end)
    return found
end

function startup.refresh_theme_file_list()
    local files = startup.find_theme_files()
    startup.s.themeFiles = {}
    startup.theme_list = {}
    for index, path in ipairs(files) do
        local meta = startup.get_theme_meta(path)
        local key = meta.key or string.lower(meta.relative or meta.fileName)
        if startup.s.themeFileStates[key] == nil then
            if startup.s.themeFileStates[meta.fileName] ~= nil then
                startup.s.themeFileStates[key] = startup.s.themeFileStates[meta.fileName]
            else
                startup.s.themeFileStates[key] = true
            end
        end
        local entry = {
            index = index,
            path = path,
            name = meta.fileName,
            fileName = meta.fileName,
            relative = meta.relative,
            folder = meta.folder,
            key = key,
            displayName = meta.displayName,
            loadName = meta.loadName,
            hash = startup.hash("THEME_ON_STARTUP_" .. tostring(key))
        }
        table.insert(startup.s.themeFiles, entry)
        table.insert(startup.theme_list, entry.relative or entry.name)
    end
    if #startup.s.themeFiles > 0 then
        startup.s.lastThemeStatus = "Found " .. tostring(#startup.s.themeFiles) .. " theme file(s), including subfolders"
    else
        startup.s.lastThemeStatus = "No theme .json files found in Theme\\ClickGUI or its subfolders"
    end
end

function startup.count_enabled_themes()
    local count = 0
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        local key = entry.key or entry.name
        if startup.s.themeFileStates[key] ~= false then
            count = count + 1
        end
    end
    return count
end

function startup.get_enabled_theme_files()
    startup.refresh_theme_file_list()
    local enabled = {}
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        local key = entry.key or entry.name
        if startup.s.themeFileStates[key] ~= false then
            table.insert(enabled, entry.loadName or entry.relative or entry.name)
        end
    end
    return enabled
end

function startup.find_theme_entry(themeFile)
    local wanted = tostring(themeFile or "")
    local wantedLower = string.lower(wanted)
    local wantedFile = string.lower(startup.get_file_name(wanted))
    for _, entry in ipairs(startup.s.themeFiles or {}) do
        if string.lower(tostring(entry.loadName or "")) == wantedLower
            or string.lower(tostring(entry.relative or "")) == wantedLower
            or string.lower(tostring(entry.name or "")) == wantedLower
            or string.lower(tostring(entry.key or "")) == wantedLower
            or string.lower(startup.get_file_name(entry.name or "")) == wantedFile then
            return entry
        end
    end
    return nil
end

function startup.get_theme_load_candidates(themeFile)
    local candidates = {}
    local function add(value)
        value = tostring(value or "")
        if value == "" then return end
        for _, existing in ipairs(candidates) do
            if string.lower(existing) == string.lower(value) then
                return
            end
        end
        table.insert(candidates, value)
        local forward = value:gsub("\\", "/")
        if forward ~= value then add(forward) end
        local back = value:gsub("/", "\\")
        if back ~= value then add(back) end
    end
    local entry = startup.find_theme_entry(themeFile)
    add(themeFile)
    if entry then
        add(entry.loadName)
        add(entry.relative)
        add(entry.name)
        add(startup.get_file_name(entry.name))
        add(startup.get_file_name(entry.relative))
    else
        add(startup.get_file_name(themeFile))
    end
    return candidates
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- startup automation
-- note: loads settings, themes, and the selected online session in order.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.find_feature_by_names(names)
    if not FeatureMgr then return nil, nil end

    if FeatureMgr.GetFeatureByName then
        for _, name in ipairs(names or {}) do
            local feature = FeatureMgr.GetFeatureByName(name)
            if feature then return feature, name end
        end
    end

    if not FeatureMgr.GetAllFeatures then return nil, nil end
    local features = FeatureMgr.GetAllFeatures()
    if type(features) ~= "table" then return nil, nil end

    for _, feature in pairs(features) do
        local feature_name = startup.read_feature_name(feature):lower()
        for _, name in ipairs(names or {}) do
            if feature_name:find(tostring(name):lower(), 1, true) then
                return feature, feature_name
            end
        end
    end
    return nil, nil
end

function startup.find_settings_name_feature()
    local feature, name = startup.find_feature_by_names({
        "Settings Name",
        "Setting Name",
        "Settings File Name",
        "Save Settings As",
        "Save Name"
    })
    if feature and (feature.SetStringValue or feature.SetValue) then return feature, name end

    if not FeatureMgr or not FeatureMgr.GetAllFeatures then return nil, nil end
    local features = FeatureMgr.GetAllFeatures()
    if type(features) ~= "table" then return nil, nil end
    for _, candidate in pairs(features) do
        local candidate_name = startup.read_feature_name(candidate):lower()
        local looks_like_name = candidate_name:find("name", 1, true)
            and (candidate_name:find("settings", 1, true) or candidate_name:find("save", 1, true))
        if looks_like_name and candidate.SetStringValue then
            return candidate, candidate_name
        end
    end
    return nil, nil
end

function startup.find_save_settings_feature()
    local feature, name = startup.find_feature_by_names({
        "Save Settings",
        "Save Current Settings",
        "Save Setting"
    })
    if feature and (feature.TriggerCallback or feature.OnClick) then return feature, name end
    return nil, nil
end

function startup.settings_profile_name_from_value(value)
    if type(value) == "table" then
        value = value.name or value.Name or value.label or value.Label or value.value or value.Value or value.file or value.File or value.filename or value.FileName
    end
    local name = tostring(value or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return "" end
    name = name:gsub("/", "\\")
    name = name:match("([^\\]+)$") or name
    return name
end

function startup.settings_feature_list()
    -- Use Cherax's official hash-based list API for the built-in Settings selector.
    -- This returns the saved profile names without reading native feature userdata,
    -- probing Load Settings, scanning all features, or using protected calls.
    if not FeatureMgr or not FeatureMgr.GetFeatureList then return nil end
    local list = FeatureMgr.GetFeatureList(startup.feature_hash.SETTINGS)
    if type(list) == "table" then return list end
    return nil
end

function startup.settings_profile_names_match(left, right)
    local function normalize(value)
        local name = startup.settings_profile_name_from_value(value):lower()
        if name:sub(-5) == ".json" then name = name:sub(1, -6) end
        return name
    end
    local a, b = normalize(left), normalize(right)
    return a ~= "" and a == b
end

function startup.settings_profile_list_index(list, wanted)
    if type(list) ~= "table" then return nil end
    local zeroBased = list[0] ~= nil
    for key, value in pairs(list) do
        if startup.settings_profile_names_match(value, wanted) then
            local numericKey = tonumber(key)
            if numericKey == nil then return nil end
            return zeroBased and numericKey or (numericKey - 1)
        end
    end
    return nil
end

function startup.settings_profile_table_stats(value)
    local stats = {
        valueType = type(value),
        total = 0,
        numeric = 0,
        stringKeys = 0,
        minNumeric = nil,
        maxNumeric = nil,
        sample = {}
    }
    if value == nil then return stats end

    -- FileMgr.FindFiles is documented as a table, but current Cherax builds expose
    -- a native userdata wrapper that still supports ordinary ipairs iteration.
    -- Keep this decoder limited strictly to FileMgr results. Do not inspect fields,
    -- methods, or arbitrary feature userdata.
    local index = 0
    for _, item in ipairs(value) do
        index = index + 1
        stats.total = stats.total + 1
        stats.numeric = stats.numeric + 1
        if stats.minNumeric == nil then stats.minNumeric = 1 end
        stats.maxNumeric = index
        if #stats.sample < 4 then
            stats.sample[#stats.sample + 1] = tostring(item or "")
        end
    end
    return stats
end

function startup.settings_profile_path_is_under_settings(path, settingsDir)
    local full = tostring(path or ""):gsub("/", "\\")
    local dir = tostring(settingsDir or ""):gsub("/", "\\"):gsub("\\+$", "")
    if full == "" or dir == "" then return false end
    local lowerFull = full:lower()
    local lowerDir = dir:lower()
    return lowerFull:sub(1, #lowerDir + 1) == lowerDir .. "\\"
        or lowerFull == lowerDir
end

function startup.build_settings_profile_probe_plan()
    local root = tostring(startup.menu_root or ""):gsub("/", "\\"):gsub("\\+$", "")
    local exact = tostring(startup.cherax_settings_dir or (root .. "\\Settings")):gsub("/", "\\"):gsub("\\+$", "")
    local userProfile = os and os.getenv and tostring(os.getenv("USERPROFILE") or "") or ""
    local oneDrive = os and os.getenv and tostring(os.getenv("OneDrive") or "") or ""
    local homeDrive = os and os.getenv and tostring(os.getenv("HOMEDRIVE") or "") or ""
    local homePath = os and os.getenv and tostring(os.getenv("HOMEPATH") or "") or ""
    local home = homeDrive .. homePath

    return {
        { "Exact .json nonrecursive", exact, ".json", false, false },
        { "Exact .json recursive", exact, ".json", true, false },
        { "Exact json nonrecursive", exact, "json", false, false },
        { "Exact json recursive", exact, "json", true, false },
        { "Exact wildcard nonrecursive", exact, "*.json", false, false },
        { "Exact wildcard recursive", exact, "*.json", true, false },
        { "Exact uppercase nonrecursive", exact, ".JSON", false, false },
        { "Exact uppercase recursive", exact, ".JSON", true, false },
        { "Exact all-files nonrecursive", exact, "", false, false },
        { "Exact all-files recursive", exact, "", true, false },
        { "Exact trailing slash nonrecursive", exact .. "\\", ".json", false, false },
        { "Exact trailing slash recursive", exact .. "\\", ".json", true, false },
        { "Exact forward slash nonrecursive", exact:gsub("\\", "/"), ".json", false, false },
        { "Exact forward slash recursive", exact:gsub("\\", "/"), ".json", true, false },
        { "Menu root .json recursive", root, ".json", true, true },
        { "Menu root json recursive", root, "json", true, true },
        { "Menu root wildcard recursive", root, "*.json", true, true },
        { "Menu root all-files recursive", root, "", true, true },
        { "Root Settings .json nonrecursive", root .. "\\Settings", ".json", false, false },
        { "Root Settings .json recursive", root .. "\\Settings", ".json", true, false },
        { "Settings Profiles nonrecursive", root .. "\\Settings\\Profiles", ".json", false, false },
        { "Settings Profiles recursive", root .. "\\Settings\\Profiles", ".json", true, false },
        { "Settings Saved nonrecursive", root .. "\\Settings\\Saved", ".json", false, false },
        { "Settings Saved recursive", root .. "\\Settings\\Saved", ".json", true, false },
        { "Root Profiles recursive", root .. "\\Profiles", ".json", true, false },
        { "Root Profile recursive", root .. "\\Profile", ".json", true, false },
        { "Root Setting recursive", root .. "\\Setting", ".json", true, false },
        { "USERPROFILE Documents candidate", userProfile ~= "" and (userProfile .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false },
        { "OneDrive Documents candidate", oneDrive ~= "" and (oneDrive .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false },
        { "HOMEDRIVE HOMEPATH candidate", home ~= "" and (home .. "\\Documents\\Cherax\\Settings") or "", ".json", true, false }
    }
end

function startup.refresh_settings_profiles(runDeepDiagnostics)
    local profiles, seen, sources = {}, {}, {}
    local diagnosticLines = {}
    local exactSettingsDir = tostring(startup.cherax_settings_dir or ""):gsub("/", "\\"):gsub("\\+$", "")

    local function diagnostic(line)
        diagnosticLines[#diagnosticLines + 1] = tostring(line or "")
    end

    local function add(value, source, allowNoExtension)
        local name = startup.settings_profile_name_from_value(value)
        if name == "" then return false end
        local lower = name:lower()
        local isJson = lower:sub(-5) == ".json"
        if not isJson and allowNoExtension ~= true then return false end
        if not isJson and allowNoExtension == true and lower:find("%.") then return false end
        if not seen[lower] then
            seen[lower] = true
            profiles[#profiles + 1] = name
            if source and source ~= "" then sources[source] = true end
            return true
        end
        return false
    end

    local function add_files(files, source, settingsOnly)
        if files == nil then return 0, 0 end
        local raw, accepted = 0, 0

        -- Current Cherax returns FileMgr.FindFiles as userdata even though the API
        -- documents a table. The wrapper is safely iterable with ipairs, exactly as
        -- Startup's working theme scanner already does. This avoids the old dangerous
        -- generic userdata decoder that caused blank Cherax menu labels.
        for _, path in ipairs(files) do
            raw = raw + 1
            if settingsOnly ~= true or startup.settings_profile_path_is_under_settings(path, exactSettingsDir) then
                if add(path, source, false) then accepted = accepted + 1 end
            end
        end
        return raw, accepted
    end

    local function run_probe(index, probe, emitLine)
        local label, dir, extension, recursive, settingsOnly = probe[1], probe[2], probe[3], probe[4], probe[5]
        dir = tostring(dir or "")
        if dir == "" or not FileMgr or not FileMgr.FindFiles then
            if emitLine then diagnostic(string.format("%02d/30 %s | skipped | dir=%s", index, label, dir ~= "" and dir or "<empty>")) end
            return
        end
        local before = #profiles
        local files = FileMgr.FindFiles(dir, extension, recursive == true)
        local stats = startup.settings_profile_table_stats(files)
        local raw, accepted = add_files(files, "probe:" .. label, settingsOnly == true)
        if emitLine then
            local sample = #stats.sample > 0 and table.concat(stats.sample, " || ") or "<none>"
            diagnostic(string.format(
                "%02d/30 %s | type=%s raw=%d accepted=%d new=%d keys=%d numeric=%d range=%s..%s dir=%s ext=%s recursive=%s sample=%s",
                index, label, stats.valueType, raw, accepted, #profiles - before, stats.total, stats.numeric,
                tostring(stats.minNumeric), tostring(stats.maxNumeric), dir, extension == "" and "<empty>" or extension,
                tostring(recursive == true), sample))
        end
    end

    -- Cherax selector is retained only as an additional source. It must never stop
    -- filesystem discovery because some builds expose only the current profile here.
    local settingsList = startup.settings_feature_list()
    if type(settingsList) == "table" then
        for _, value in pairs(settingsList) do add(value, "settings-selector", true) end
    end
    if FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
        add(FeatureMgr.GetCurrentFeatureListString(startup.feature_hash.SETTINGS), "settings-current", true)
    end

    -- Core probes run on every refresh. The menu-root recursive probe is important:
    -- some Cherax builds do not enumerate correctly when FindFiles receives the
    -- Settings directory directly, but do return every JSON from the menu root.
    local plan = startup.build_settings_profile_probe_plan()
    local coreIndexes = { 1, 2, 3, 5, 11, 13, 15, 20, 22, 24 }
    local coreDone = {}
    for _, index in ipairs(coreIndexes) do
        coreDone[index] = true
        run_probe(index, plan[index], runDeepDiagnostics == true)
    end

    -- A manual refresh requests the complete 30-probe report. These probes also
    -- contribute any additional JSON files they find.
    if runDeepDiagnostics == true then
        for index, probe in ipairs(plan) do
            if not coreDone[index] then run_probe(index, probe, true) end
        end
    end

    -- Windows directory enumeration is a second independent source. It is always
    -- merged, even when the Cherax selector already returned default.json.
    if io and io.popen and exactSettingsDir ~= "" then
        local commands = {
            { "DIR JSON recursive", 'dir /b /s /a-d "' .. exactSettingsDir .. '\\*.json" 2>nul' },
            { "DIR all recursive", 'dir /b /s /a-d "' .. exactSettingsDir .. '\\*" 2>nul' },
            { "WHERE JSON recursive", 'where /r "' .. exactSettingsDir .. '" *.json 2>nul' }
        }
        for commandIndex, command in ipairs(commands) do
            local before = #profiles
            local raw = 0
            local pipe = io.popen(command[2])
            if pipe then
                for line in pipe:lines() do
                    raw = raw + 1
                    add(line, "shell:" .. command[1], commandIndex == 2)
                end
                pipe:close()
            end
            if runDeepDiagnostics == true then
                diagnostic("Shell " .. tostring(commandIndex) .. "/3 " .. command[1] .. " | raw=" .. tostring(raw) .. " new=" .. tostring(#profiles - before) .. " | command=" .. command[2])
            end
        end
    elseif runDeepDiagnostics == true then
        diagnostic("Shell 0/3 | io.popen unavailable or Settings path empty")
    end

    table.sort(profiles, function(a, b) return string.lower(a) < string.lower(b) end)
    startup.s.settingsProfiles = profiles
    startup.s.settingsProfilesLastRefreshMs = startup.now()

    local sourceNames = {}
    for source in pairs(sources) do sourceNames[#sourceNames + 1] = source end
    table.sort(sourceNames)
    if #profiles > 0 then
        startup.s.settingsProfilesStatus = tostring(#profiles) .. " saved profile" .. (#profiles == 1 and "" or "s") .. " found."
    else
        startup.s.settingsProfilesStatus = "No saved settings profiles found."
    end

    if runDeepDiagnostics == true then
        startup.log("[Settings Debug] BEGIN 30-probe report")
        startup.log("[Settings Debug] edition=" .. tostring(startup.get_active_edition_info()) .. " | menuRoot=" .. tostring(startup.menu_root or "") .. " | settingsDir=" .. exactSettingsDir)
        startup.log("[Settings Debug] FileMgr=" .. tostring(type(FileMgr)) .. " | FindFiles=" .. tostring(FileMgr and type(FileMgr.FindFiles) or "nil") .. " | io.popen=" .. tostring(io and type(io.popen) or "nil"))
        for _, line in ipairs(diagnosticLines) do startup.log("[Settings Debug] " .. line) end
        startup.log("[Settings Debug] profiles=" .. tostring(#profiles) .. " | names=" .. (#profiles > 0 and table.concat(profiles, ", ") or "<none>"))
        startup.log("[Settings Debug] sources=" .. (#sourceNames > 0 and table.concat(sourceNames, ", ") or "<none>"))
        startup.log("[Settings Debug] END 30-probe report")
        startup.s.settingsProfilesLastDiagnostic = table.concat(diagnosticLines, "\n")
    elseif startup.s.verboseStartupLogs then
        startup.log("Settings profiles refreshed | count=" .. tostring(#profiles) .. " | sources=" .. (#sourceNames > 0 and table.concat(sourceNames, ",") or "none"))
    end

    if startup.popup_flow and startup.popup_flow.active and startup.popup_flow.stage == "setup" then
        local wanted = tostring(startup.popup_flow.settingsFile or "")
        local valid = false
        for _, name in ipairs(profiles) do
            if startup.settings_profile_names_match(name, wanted) then valid = true break end
        end
        if not valid then
            local current = tostring(startup.s.settingsFile or "")
            for _, name in ipairs(profiles) do
                if startup.settings_profile_names_match(name, current) then
                    startup.popup_flow.settingsFile = name
                    valid = true
                    break
                end
            end
        end
        if not valid and #profiles == 1 then startup.popup_flow.settingsFile = profiles[1] end
    end
    return profiles
end

function startup.queue_settings_profile_refresh(showToast, runDebug)
    local manual = showToast == true
    local debugRequested = runDebug == true
    if startup.s.pendingSettingsProfileRefresh == true then
        if debugRequested then startup.s.settingsProfilesDebugRequested = true end
        if manual then startup.s.settingsProfilesRefreshToastPending = true end
        startup.s.settingsProfilesStatus = "Saved-settings refresh already queued..."
        return false
    end

    startup.s.pendingSettingsProfileRefresh = true
    startup.s.settingsProfilesDebugRequested = debugRequested
    startup.s.settingsProfilesRefreshToastPending = manual
    startup.s.settingsProfilesRefreshQueuedAtMs = startup.now()
    startup.s.settingsProfilesStatus = "Refreshing saved Cherax settings..."
    if manual then
        -- Log once instead of stacking identical GUI toasts such as "(7)".
        startup.log("Refreshing saved Cherax settings...")
    end
    return true
end

function startup.process_pending_settings_profile_refresh()
    if startup.s.pendingSettingsProfileRefresh ~= true then return end
    startup.s.pendingSettingsProfileRefresh = false
    local runDebug = startup.s.settingsProfilesDebugRequested == true
    startup.s.settingsProfilesDebugRequested = false
    local profiles = startup.refresh_settings_profiles(runDebug)
    local elapsed = startup.now() - (tonumber(startup.s.settingsProfilesRefreshQueuedAtMs or 0) or 0)
    startup.s.settingsProfilesRefreshQueuedAtMs = 0

    if startup.s.settingsProfilesRefreshToastPending == true then
        startup.s.settingsProfilesRefreshToastPending = false
        startup.toast("Saved settings refreshed: " .. tostring(#profiles) .. " profile" .. (#profiles == 1 and "" or "s") .. " found.", 3500)
    elseif startup.s.verboseStartupLogs then
        startup.log("Settings profile refresh complete | count=" .. tostring(#profiles) .. " | elapsedMs=" .. tostring(elapsed))
    end
end

function startup.settings_profile_exists(name)
    if tostring(name or "") == "" then return false end
    for _, profile in ipairs(startup.s.settingsProfiles or {}) do
        if startup.settings_profile_names_match(profile, name) then return true end
    end
    return false
end

function startup.select_settings_profile(name, saveNow)
    name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if name == "" then return false end
    startup.s.settingsFile = name
    startup.s.settingsProfileSelectionConfirmed = true
    if saveNow and startup.s.initialized then startup.s.pendingSettingsSelectionSave = true end
    return true
end

function startup.process_pending_settings_selection_save()
    if startup.s.pendingSettingsSelectionSave ~= true then return end
    startup.s.pendingSettingsSelectionSave = false
    startup.save_config(false)
end

function startup.apply_settings_file(forceWhileOnline)
    local forceOnline = forceWhileOnline == true
    if not startup.s.autoLoadSettings and not forceOnline then
        startup.s.lastStatus = "Auto-Load Settings is OFF."
        return false
    end

    local onlineActive = startup.is_gta_online_session_ready and startup.is_gta_online_session_ready() == true
    if onlineActive and not forceOnline then
        startup.s.lastStatus = "Settings Safety: skipped automatic profile load because GTA Online is already active."
        startup.toast_quiet("Settings load skipped online to protect your character and Lua state.", 4500)
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SETTINGS_LOAD_SKIPPED_ONLINE", "profile=" .. tostring(startup.s.settingsFile or ""))
        end
        return false
    end

    if onlineActive and forceOnline then
        startup.log_verbose("[Settings Safety] Manual online settings load requested.", "warning")
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SETTINGS_LOAD_FORCED_ONLINE", "profile=" .. tostring(startup.s.settingsFile or ""))
        end
    end

    local selected = tostring(startup.s.settingsFile or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if selected == "" then
        startup.s.lastStatus = "No Cherax settings profile selected."
        return false
    end

    local settingsList = startup.settings_feature_list()
    local settingsIndex = startup.settings_profile_list_index(settingsList, selected)
    if settingsIndex ~= nil and FeatureMgr and FeatureMgr.SetFeatureListIndex then
        FeatureMgr.SetFeatureListIndex(startup.feature_hash.SETTINGS, settingsIndex)
    elseif #(startup.s.settingsProfiles or {}) > 0 and not startup.settings_profile_exists(selected) then
        startup.s.lastStatus = "Selected Cherax settings profile was not found: " .. selected
        startup.error("Could not find saved settings profile: " .. selected)
        return false
    end

    if not FeatureMgr or not FeatureMgr.LoadSettings then
        startup.error("Cherax LoadSettings is unavailable.")
        return false
    end
    local desiredNatHudState = startup.s.showNatTypeHud ~= false
    local desiredNatHudConfigured = startup.s.natHudUserConfigured == true
    local desiredRegionHudState = startup.s.showAdvertiseRegionHud == true
    local desiredRegionHudConfigured = startup.s.advertiseRegionHudUserConfigured == true
    local wasSyncing = startup.s.syncingFeatureStates == true
    startup.s.syncingFeatureStates = true
    local okCall, ok = direct_call(function() return FeatureMgr.LoadSettings(selected) end)
    startup.s.syncingFeatureStates = wasSyncing
    startup.s.showNatTypeHud = desiredNatHudState
    startup.s.natHudUserConfigured = desiredNatHudConfigured
    startup.s.showAdvertiseRegionHud = desiredRegionHudState
    startup.s.advertiseRegionHudUserConfigured = desiredRegionHudConfigured
    if okCall and ok ~= nil and ok ~= false then
        startup.s.lastStatus = "Loaded settings: " .. selected
        startup.toast_colored("Loaded settings: " .. selected, 3000, "success")
        startup.s.pendingNatHudRestore = true
        return true
    end
    if not okCall then
        startup.s.lastStatus = "Could not load settings safely: " .. selected
        startup.error("Could not load settings safely: " .. selected)
    else
        startup.error("Could not load settings: " .. selected)
    end
    return false
end

function startup.apply_settings_file_manual()
    return startup.apply_settings_file(true)
end

function startup.get_random_theme_file()
    local themes = startup.get_enabled_theme_files()
    if #themes <= 0 then
        startup.s.lastThemeStatus = "No startup themes enabled"
        return startup.s.themeFile or startup.s.lastRandomThemeFile or "Old_Original.json"
    end
    local seed = startup.now() + os.time() + math.floor(os.clock() * 100000)
    math.randomseed(seed)
    local selected = themes[math.random(1, #themes)] or themes[1]
    -- if possible, avoid picking the exact same theme twice in a row.
    if #themes > 1 and selected == startup.s.lastRandomThemeFile then
        for _ = 1, 6 do
            local retry = themes[math.random(1, #themes)] or selected
            if retry ~= startup.s.lastRandomThemeFile then
                selected = retry
                break
            end
        end
    end
    return selected
end

function startup.set_theme_file(themeFile, saveNow)
    startup.s.themeFile = tostring(themeFile or "Old_Original.json")
    startup.s.lastRandomThemeFile = startup.s.themeFile
    if saveNow and startup.s.initialized then
        startup.save_config(false)
    end
end

-- Manual theme buttons are rendered inside Cherax ClickGUI / ImGui callbacks.
-- Those callbacks must never yield or invoke a theme reload mid-frame. They only set
-- this request; Startup's main scripting worker performs the actual load safely.
startup.pendingThemeLoad = false
startup.pendingThemeLoadManual = false
startup.pendingThemeLoadReason = ""

function startup.queue_theme_load(manual_request, reason)
    startup.pendingThemeLoad = true
    startup.pendingThemeLoadManual = manual_request == true
    startup.pendingThemeLoadReason = tostring(reason or (manual_request == true and "manual request" or "automatic request"))
    startup.s.lastThemeStatus = "Theme load queued: " .. tostring(startup.s.themeFile or "Not selected")
    return true
end

function startup.apply_theme_file(manual_request)
    startup.refresh_theme_file_list()
    if not startup.s.autoLoadTheme and manual_request ~= true then
        startup.s.lastThemeStatus = "Auto-Load Theme OFF"
        return false
    end
    if startup.s.randomThemeOnStartup then
        startup.set_theme_file(startup.get_random_theme_file(), false)
    elseif not startup.s.themeFile or startup.s.themeFile == "" then
        startup.set_theme_file("Old_Original.json", false)
    end
    local themeFeature = FeatureMgr.GetFeature(startup.feature_hash.THEMES)
    if not themeFeature then
        startup.error("Themes feature not found.")
        startup.s.lastThemeStatus = "Themes feature not found"
        return false
    end
    local selectedTheme = nil
    local index = nil
    for _, candidate in ipairs(startup.get_theme_load_candidates(startup.s.themeFile)) do
        index = themeFeature:GetListIndexByString(candidate)
        if index ~= nil then
            selectedTheme = candidate
            break
        end
    end
    if index == nil or not selectedTheme then
        startup.error("Theme option not found: " .. tostring(startup.s.themeFile))
        startup.s.lastThemeStatus = "Theme not found: " .. tostring(startup.s.themeFile)
        return false
    end
    themeFeature:SetListIndexByString(selectedTheme)
    startup.s.themeFile = selectedTheme
    startup.yield(250)
    local loadThemeFeature = FeatureMgr.GetFeature(startup.feature_hash.LOAD_THEME)
    if loadThemeFeature then
        if loadThemeFeature.OnClick then
            loadThemeFeature:OnClick()
        elseif loadThemeFeature.TriggerCallback then
            loadThemeFeature:TriggerCallback()
        end
    else
        startup.error("Load Theme feature not found.")
        startup.s.lastThemeStatus = "Load Theme feature not found"
        return false
    end
    startup.s.lastThemeStatus = "Loaded theme: " .. startup.s.themeFile
    startup.save_config(false)
    startup.toast_quiet("Loaded theme: " .. startup.s.themeFile, 3000)
    return true
end

function startup.process_pending_theme_load()
    if startup.pendingThemeLoad ~= true then return end

    local manual_request = startup.pendingThemeLoadManual == true
    local reason = tostring(startup.pendingThemeLoadReason or "queued request")
    startup.pendingThemeLoad = false
    startup.pendingThemeLoadManual = false
    startup.pendingThemeLoadReason = ""

    local ok, result = direct_call(function()
        return startup.apply_theme_file(manual_request)
    end)
    if not ok then
        startup.s.lastThemeStatus = "Theme load failed: " .. tostring(result)
        startup.error("Queued theme load failed: " .. tostring(result))
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("THEME_LOAD_ERROR", "reason=" .. reason .. " | error=" .. tostring(result))
        end
        return false
    end

    if startup.support_log_event_quiet then
        startup.support_log_event_quiet(
            result == true and "THEME_LOAD_OK" or "THEME_LOAD_SKIPPED",
            "reason=" .. reason .. " | theme=" .. tostring(startup.s.themeFile or "") .. " | status=" .. tostring(startup.s.lastThemeStatus or "")
        )
    end
    return result == true
end

function startup.get_feature_list_safe(feature)
    if not feature or not feature.GetList then return nil end
    local list = feature:GetList()
    return type(list) == "table" and list or nil
end

function startup.list_contains_text(list, wanted)
    if type(list) ~= "table" then return false end
    local target = string.lower(tostring(wanted or ""))
    for _, value in ipairs(list) do
        if string.lower(tostring(value or "")) == target then
            return true
        end
    end
    return false
end

function startup.get_current_feature_list_string_safe(hash)
    local value = nil
    if FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
    value = FeatureMgr.GetCurrentFeatureListString(hash)
    end
    if value ~= nil and tostring(value) ~= "" then
        return tostring(value)
    end
    local feature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(hash) or nil
    if not feature then return nil end
    local list = startup.get_feature_list_safe(feature)
    local index = nil
    if feature.GetListIndex then index = feature:GetListIndex() end
    if type(list) == "table" and type(index) == "number" then
        return list[index + 1]
    end
    return nil
end

function startup.read_cherax_game_edition()
    local edition = startup.get_active_edition_info()
    startup.s.detectedCheraxGameEdition = edition
    return edition
end

function startup.parse_cherax_game_edition(edition)
    local normalized = startup.normalize_edition_code(edition)

    if normalized == "LE" then return "Legacy", false, true end
    if normalized == "EE" then return "Enhanced", false, true end
    if normalized == "LE BE" then return "Legacy", true, true end
    if normalized == "EE BE" then return "Enhanced", true, true end

    return "Unknown", nil, false
end

function startup.detect_session_route_fallback()
    local sessionFeature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(startup.feature_hash.SESSION_TYPE) or nil
    local list = startup.get_feature_list_safe(sessionFeature)
    local current = startup.get_current_feature_list_string_safe(startup.feature_hash.SESSION_TYPE)

    if not sessionFeature then
        startup.s.detectedCheraxTier = "Unknown"
        startup.s.detectedSessionTypeConfidence = 0
        startup.s.detectedSessionTypeReason = "Cherax edition was not recognized and Session Type is unavailable; preserving the configured route"
        return "Unknown", startup.s.sessionType or "New Public Session"
    end

    local hasNewPublic = startup.list_contains_text(list, "New Public Session")
    local hasJoinPublic = startup.list_contains_text(list, "Join Public Session")
    if hasNewPublic and not hasJoinPublic then
        startup.s.detectedCheraxTier = "Standard / Premium (fallback)"
        startup.s.detectedSessionTypeConfidence = 85
        startup.s.detectedSessionTypeReason = "Edition was unrecognized; Session Type exposes New Public Session only"
        return startup.s.detectedCheraxTier, "New Public Session"
    end
    if hasJoinPublic and not hasNewPublic then
        startup.s.detectedCheraxTier = "Prime (fallback)"
        startup.s.detectedSessionTypeConfidence = 85
        startup.s.detectedSessionTypeReason = "Edition was unrecognized; Session Type exposes Join Public Session only"
        return startup.s.detectedCheraxTier, "Join Public Session"
    end
    if hasNewPublic and hasJoinPublic then
        startup.s.detectedCheraxTier = "Standard / Premium (safe fallback)"
        startup.s.detectedSessionTypeConfidence = 70
        startup.s.detectedSessionTypeReason = "Edition was unrecognized and both routes exist; using safe non-BattlEye routing"
        return startup.s.detectedCheraxTier, "New Public Session"
    end
    if current == "New Public Session" or current == "Join Public Session" then
        local tier = current == "Join Public Session" and "Prime (current route)" or "Standard / Premium (current route)"
        startup.s.detectedCheraxTier = tier
        startup.s.detectedSessionTypeConfidence = 55
        startup.s.detectedSessionTypeReason = "Edition was unrecognized; preserving the current public-session route"
        return tier, current
    end

    startup.s.detectedCheraxTier = "Standard / Premium fallback"
    startup.s.detectedSessionTypeConfidence = 40
    startup.s.detectedSessionTypeReason = "Edition and route were unrecognized; using New Public Session as the safe fallback"
    return startup.s.detectedCheraxTier, "New Public Session"
end

function startup.detect_cherax_session_tier()
    local edition = startup.read_cherax_game_edition()
    local gameFamily, battleyeEnabled, recognized = startup.parse_cherax_game_edition(edition)
    startup.s.detectedCheraxGameFamily = gameFamily
    startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")

    if recognized then
        if battleyeEnabled then
            startup.s.detectedCheraxTier = "Prime"
            startup.s.detectedSessionTypeConfidence = 100
            startup.s.detectedSessionTypeReason = "Active Cherax edition is " .. tostring(edition) .. "; BattlEye routing uses Join Public Session"
            return "Prime", "Join Public Session"
        end
        startup.s.detectedCheraxTier = "Standard / Premium"
        startup.s.detectedSessionTypeConfidence = 100
        startup.s.detectedSessionTypeReason = "Active Cherax edition is " .. tostring(edition) .. "; non-BattlEye routing uses New Public Session"
        return startup.s.detectedCheraxTier, "New Public Session"
    end

    return startup.detect_session_route_fallback()
end

function startup.resolve_session_type()
    if startup.s.cheraxHostFinderEnabled == true then
        local edition = startup.read_cherax_game_edition()
        local gameFamily, battleyeEnabled = startup.parse_cherax_game_edition(edition)
        startup.s.detectedCheraxGameFamily = gameFamily
        startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")
        startup.s.detectedCheraxTier = startup.is_prime_active_edition() and "Prime" or "Standard / Premium"
        startup.s.detectedSessionTypeConfidence = 100
        startup.s.detectedSessionTypeReason = "Cherax Host Finder forces Join Public Session"
        startup.s.sessionType = "Join Public Session"
        return startup.s.sessionType
    end
    local mode = tostring(startup.s.sessionRoutingMode or "Automatic")
    if mode == "Prime" then
        local edition = startup.read_cherax_game_edition()
        local gameFamily, battleyeEnabled = startup.parse_cherax_game_edition(edition)
        startup.s.detectedCheraxGameFamily = gameFamily
        startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")
        startup.s.detectedCheraxTier = "Prime (manual override)"
        startup.s.detectedSessionTypeConfidence = 100
        startup.s.detectedSessionTypeReason = "Session Routing is manually forced to Prime"
        startup.s.sessionType = "Join Public Session"
    elseif mode == "Standard / Premium" then
        local edition = startup.read_cherax_game_edition()
        local gameFamily, battleyeEnabled = startup.parse_cherax_game_edition(edition)
        startup.s.detectedCheraxGameFamily = gameFamily
        startup.s.detectedBattleyeMode = battleyeEnabled == true and "ON" or (battleyeEnabled == false and "OFF" or "Unknown")
        startup.s.detectedCheraxTier = "Standard / Premium (manual override)"
        startup.s.detectedSessionTypeConfidence = 100
        startup.s.detectedSessionTypeReason = "Session Routing is manually forced to Standard / Premium"
        startup.s.sessionType = "New Public Session"
    else
        startup.s.sessionRoutingMode = "Automatic"
        local _, detectedType = startup.detect_cherax_session_tier()
        startup.s.sessionType = detectedType or "New Public Session"
    end
    return startup.s.sessionType
end

function startup.apply_session_type()
    if not startup.s.autoSelectSessionType then
        startup.toast("Auto-Select Session Type is OFF.", 2000)
        return false
    end
    local sessionFeature = FeatureMgr.GetFeature(startup.feature_hash.SESSION_TYPE)
    if not sessionFeature then
        startup.error("Session Type feature not found.")
        return false
    end
    local targetType = startup.resolve_session_type()
    local index = sessionFeature:GetListIndexByString(targetType)
    if index == nil then
        local list = startup.get_feature_list_safe(sessionFeature)
        if startup.s.cheraxHostFinderEnabled == true then
            if startup.list_contains_text(list, "Join Public Session") then
                targetType = "Join Public Session"
                index = sessionFeature:GetListIndexByString(targetType)
            end
        else
            if startup.list_contains_text(list, "New Public Session") then
                targetType = "New Public Session"
            elseif startup.list_contains_text(list, "Join Public Session") then
                targetType = "Join Public Session"
            end
            index = sessionFeature:GetListIndexByString(targetType)
        end
    end
    if index == nil then
        local current = startup.get_current_feature_list_string_safe(startup.feature_hash.SESSION_TYPE)
        if startup.s.cheraxHostFinderEnabled == true and tostring(current or "") ~= "Join Public Session" then
            startup.s.lastSessionFlowStatus = "Lobby Finder requires Join Public Session, but Cherax did not expose it."
            startup.error(startup.s.lastSessionFlowStatus)
            return false
        end
        if current and tostring(current) ~= "" then
            startup.s.sessionType = tostring(current)
            startup.s.detectedSessionTypeReason = "Requested route unavailable; preserved current Session Type: " .. tostring(current)
            startup.s.lastSessionFlowStatus = startup.s.detectedSessionTypeReason
            return true
        end
        startup.s.lastSessionFlowStatus = "Session Type option unavailable on this Cherax layout: " .. tostring(targetType)
        return false
    end
    startup.s.sessionType = targetType
    sessionFeature:SetListIndexByString(targetType)
    if ClickGUI and ClickTab then
        ClickGUI.SetActiveMenuTab(ClickTab.Session)
    end
    startup.toast_quiet("Session Type selected: " .. tostring(targetType), 3500)
    return true
end

function startup.start_session(skipSessionTypeApply)
    if startup.regionProductionHidden ~= true and startup.regionExperimentLock == true and startup.regionExperimentInternalStart ~= true then
        startup.s.lastSessionFlowStatus = "Session start deferred while a Legacy Region experiment is running."
        if startup.support_log_event_quiet then startup.support_log_event_quiet("REGION_REQUEST_SESSION_DEFERRED", "source=start_session") end
        return false
    end
    if skipSessionTypeApply ~= true and not startup.apply_session_type() then return false end
    return startup.click_start_session_feature()
end

function startup.run_startup_online_launch()
    if startup.s.startupOnlineAttempted then
        startup.s.lastOnlineStartStatus = "Skipped: already attempted this startup"
        return
    end
    if not startup.s.autoStartOnlineFromSingleplayer then
        startup.s.lastOnlineStartStatus = "Auto Start Online OFF"
        return
    end
    startup.s.startupOnlineAttempted = true
    Script.QueueJob(function()
        local targetType = startup.resolve_session_type()
        startup.s.lastOnlineStartStatus = "Waiting 1 minute before starting " .. tostring(targetType)
        startup.toast_quiet("Auto Start Online is ON. Waiting 1 minute before starting " .. tostring(targetType) .. ".", 5000)
        startup.yield(startup.s.autoStartOnlineDelayMs)
        while startup.regionExperimentLock == true or startup.regionRescanJobQueued == true do
            startup.s.lastOnlineStartStatus = "Waiting for the Legacy Region experiment to finish"
            startup.yield(500)
        end
        if startup.regionExperimentSessionStarted == true then
            startup.s.lastOnlineStartStatus = "Skipped: a Region experiment already started a controlled session"
            return
        end
        targetType = startup.resolve_session_type()
        startup.s.lastOnlineStartStatus = "Applying " .. tostring(targetType)
        startup.apply_session_type()
        startup.yield(1000)
        startup.s.lastOnlineStartStatus = "Starting " .. tostring(targetType)
        startup.toast_quiet("Starting " .. tostring(targetType) .. " from startup flow.", 4000)
        startup.start_session(true)
    end)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- matchmaking advertise flow
-- note: starts, scales, pauses, and resumes public-session advertising.
-- ═══════════════════════════════════════════════════════════════════════════════════

local function startup_normalize_advertise_label(value)
    return tostring(value or ""):lower():gsub("[^%w]", "")
end

-- Cherax list-returning APIs can expose numeric keys starting at either 0 or 1.
-- Convert both layouts into stable entries while preserving the real Cherax list index.
local function startup_region_list_entries(list)
    local entries, rows = {}, {}
    if type(list) ~= "table" then return entries end

    local insertion = 0
    for key, item in pairs(list) do
        if item ~= nil then
            insertion = insertion + 1
            rows[#rows + 1] = {
                rawKey = key,
                numericKey = tonumber(key),
                label = tostring(item),
                insertion = insertion
            }
        end
    end

    table.sort(rows, function(a, b)
        if a.numericKey ~= nil and b.numericKey ~= nil then
            if a.numericKey == b.numericKey then return a.insertion < b.insertion end
            return a.numericKey < b.numericKey
        end
        if a.numericKey ~= nil then return true end
        if b.numericKey ~= nil then return false end
        return a.insertion < b.insertion
    end)

    local zeroBased = false
    for _, row in ipairs(rows) do
        if row.numericKey ~= nil and math.floor(row.numericKey) == 0 then
            zeroBased = true
            break
        end
    end

    for position, row in ipairs(rows) do
        local listIndex = position - 1
        if row.numericKey ~= nil then
            local numericKey = math.floor(row.numericKey)
            listIndex = zeroBased and numericKey or (numericKey - 1)
            if listIndex < 0 then listIndex = position - 1 end
        end
        entries[#entries + 1] = {
            label = row.label,
            listIndex = listIndex,
            rawKey = row.rawKey
        }
    end
    return entries
end

local function startup_region_list_contains(list, wanted)
    local wantedNormalized = startup_normalize_advertise_label(wanted)
    local aliases = {
        northernasia = {northernasia=true, northasia=true},
        southamerica = {southamerica=true, latinamerica=true},
        usaeast = {usaeast=true, useast=true, americaeast=true, northamericaeast=true},
        usawest = {usawest=true, uswest=true, americawest=true, northamericawest=true},
        europe = {europe=true, eu=true},
        asia = {asia=true},
        australia = {australia=true, oceania=true},
        japan = {japan=true}
    }
    local wantedAliases = aliases[wantedNormalized]
    for _, entry in ipairs(startup_region_list_entries(list)) do
        local entryNormalized = startup_normalize_advertise_label(entry.label)
        if entryNormalized == wantedNormalized or (wantedAliases and wantedAliases[entryNormalized] == true) then
            return entry.listIndex, tostring(entry.label)
        end
    end
    return nil
end

local function startup_region_label_for_index(list, wantedIndex)
    wantedIndex = tonumber(wantedIndex)
    if wantedIndex == nil then return nil end
    for _, entry in ipairs(startup_region_list_entries(list)) do
        if tonumber(entry.listIndex) == wantedIndex then return tostring(entry.label) end
    end
    return nil
end

local function startup_normalize_feature_hash(value)
    local hash = tonumber(value)
    if hash == nil then return nil end
    hash = math.floor(hash)
    if hash < 0 then hash = hash + 4294967296 end
    if hash <= 0 or hash > 4294967295 then return nil end
    return hash
end

local function startup_region_feature_type(feature)
    if not feature or not feature.GetType then return nil end
    return feature:GetType()
end

local function startup_region_is_list_feature_type(featureType)
    if featureType == nil or not eFeatureType then return false end
    local names = { "Combo", "ComboToggles", "List", "ListWithInfo" }
    for _, name in ipairs(names) do
        if eFeatureType[name] ~= nil and featureType == eFeatureType[name] then return true end
    end
    return false
end

local function startup_region_known_label_for_index(index)
    index = tonumber(index)
    if index == nil then return nil end
    return startup.region_names[index]
end

local function startup_region_feature_snapshot(feature, expectedName)
    if not feature then return nil, "feature was nil" end

    local hash = nil
    if feature.GetHash then hash = startup_normalize_feature_hash(feature:GetHash()) end

    local expected = tostring(expectedName or "")
    local name = expected
    if feature.GetName then
        local raw = feature:GetName(false)
        if raw ~= nil and tostring(raw) ~= "" then name = tostring(raw) end
    elseif feature.Name ~= nil and tostring(feature.Name) ~= "" then
        name = tostring(feature.Name)
    end

    local featureType = startup_region_feature_type(feature)
    local listCapable = startup_region_is_list_feature_type(featureType)
    local list = nil
    if listCapable and feature.GetList then
        local rawList = feature:GetList()
        if type(rawList) == "table" then list = rawList end
    end
    local entries = startup_region_list_entries(list)

    local currentIndex = nil
    if listCapable and feature.GetListIndex then
        currentIndex = tonumber(feature:GetListIndex())
    end

    local currentString = nil
    if listCapable and hash and FeatureMgr and FeatureMgr.GetCurrentFeatureListString then
        local value = FeatureMgr.GetCurrentFeatureListString(hash)
        if value ~= nil and tostring(value) ~= "" then currentString = tostring(value) end
    end
    if (currentString == nil or currentString == "") and currentIndex ~= nil then
        currentString = startup_region_label_for_index(list, currentIndex)
            or startup_region_known_label_for_index(currentIndex)
    end

    local europeIndex = startup_region_list_contains(list, "Europe")
    local normalizedExpected = startup_normalize_advertise_label(expected)
    local exactAdvertiseName = normalizedExpected ~= ""
        and normalizedExpected:find("advertis", 1, true) ~= nil
        and normalizedExpected:find("region", 1, true) ~= nil
    local liveName = startup_normalize_advertise_label(name)
    local liveAdvertiseName = liveName:find("advertis", 1, true) ~= nil
        and liveName:find("region", 1, true) ~= nil

    if #entries >= 2 and (europeIndex ~= nil or exactAdvertiseName or liveAdvertiseName) then
        return {
            feature = feature,
            hash = hash,
            list = list,
            entries = entries,
            name = name ~= "" and name or "Advertise Region",
            featureType = featureType,
            listCapable = listCapable,
            currentIndex = currentIndex,
            currentString = currentString,
            nativeOnly = false
        }, "accepted live list with " .. tostring(#entries) .. " choices"
    end

    -- Current EE builds may expose the exact native list feature while withholding
    -- its list entries from Lua. Accept that targeted control without calling
    -- string-only feature methods. The native Cherax control remains authoritative.
    if exactAdvertiseName or liveAdvertiseName then
        return {
            feature = feature,
            hash = hash,
            list = list,
            entries = entries,
            name = name ~= "" and name or "Advertise Region",
            featureType = featureType,
            listCapable = listCapable,
            currentIndex = currentIndex,
            currentString = currentString,
            nativeOnly = true
        }, "accepted exact native control; type=" .. tostring(featureType)
            .. " choices=" .. tostring(#entries)
            .. " current=" .. tostring(currentString or "native")
    end

    return nil, "name=" .. tostring(name ~= "" and name or "unknown")
        .. " hash=" .. tostring(hash or "none")
        .. " type=" .. tostring(featureType or "unknown")
        .. " listCapable=" .. tostring(listCapable)
        .. " choices=" .. tostring(#entries)
        .. " europe=" .. tostring(europeIndex ~= nil)
        .. " current=" .. tostring(currentString or "none")
end
local function startup_region_hash_snapshot(value)
    local hash = startup_normalize_feature_hash(value)
    if not hash or not FeatureMgr or not FeatureMgr.GetFeature then return nil end

    local expectedName = nil
    for _, knownHash in ipairs(startup.advertise_region_known_hashes or {}) do
        if startup_normalize_feature_hash(knownHash) == hash then
            expectedName = "Advertise Region"
            break
        end
    end

    local feature = FeatureMgr.GetFeature(hash)
    if not feature then return nil end
    local snap = startup_region_feature_snapshot(feature, expectedName)
    if snap then
        snap.hash = snap.hash or hash
        return snap
    end
    return nil
end

local function startup_commit_advertise_region_candidate(candidate, source)
    if not candidate then return nil, nil, nil end
    local cache = startup.advertise_region_cache or {}
    startup.advertise_region_cache = cache
    cache.hash = candidate.hash
    cache.feature = candidate.feature
    cache.list = candidate.list
    cache.entries = candidate.entries or startup_region_list_entries(candidate.list)
    cache.nativeOnly = candidate.nativeOnly == true
    cache.featureType = candidate.featureType
    cache.listCapable = candidate.listCapable == true
    cache.currentIndex = candidate.currentIndex
    cache.currentString = candidate.currentString
    cache.source = tostring(source or "validated Advertise Region")
    cache.name = tostring(candidate.name or "Advertise Region")
    cache.scanRunning = false
    cache.lastScanStatus = "Resolved via " .. cache.source
    cache.nextRetryMs = 0
    startup.s.advertiseRegionHash = candidate.hash
    startup.s.advertiseRegionSource = cache.source
    startup.s.advertiseRegionResolution = "Resolved: " .. cache.name
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("ADVERTISE_REGION_RESOLVED", "name=" .. tostring(cache.name)
            .. " hash=" .. tostring(cache.hash or "unknown")
            .. " type=" .. tostring(cache.featureType or "unknown")
            .. " choices=" .. tostring(#(cache.entries or {}))
            .. " nativeOnly=" .. tostring(cache.nativeOnly)
            .. " source=" .. tostring(cache.source))
    end
    startup.print_advertise_region_summary(false)
    return cache.feature, cache.hash, cache.list
end

local function startup_validate_cached_advertise_region()
    local cache = startup.advertise_region_cache or {}
    if cache.feature then
        local snap = startup_region_feature_snapshot(cache.feature, cache.name or "Advertise Region")
        if snap then
            snap.hash = snap.hash or cache.hash
            cache.hash = snap.hash
            cache.list = snap.list
            cache.entries = snap.entries
            cache.nativeOnly = snap.nativeOnly == true
            cache.featureType = snap.featureType
            cache.listCapable = snap.listCapable == true
            cache.currentIndex = snap.currentIndex
            cache.currentString = snap.currentString
            cache.name = snap.name
            startup.s.advertiseRegionHash = cache.hash
            startup.s.advertiseRegionSource = tostring(cache.source or "cached targeted feature")
            startup.s.advertiseRegionResolution = "Resolved: " .. tostring(cache.name or "Advertise Region")
            return cache.feature, cache.hash, cache.list
        end
    end
    if cache.hash then
        local snap = startup_region_hash_snapshot(cache.hash)
        if snap then
            snap.feature = snap.feature or cache.feature
            cache.feature = snap.feature
            cache.list = snap.list
            cache.entries = snap.entries
            cache.nativeOnly = snap.nativeOnly == true
            cache.featureType = snap.featureType
            cache.listCapable = snap.listCapable == true
            cache.currentIndex = snap.currentIndex
            cache.currentString = snap.currentString
            cache.name = snap.name
            startup.s.advertiseRegionHash = cache.hash
            startup.s.advertiseRegionSource = tostring(cache.source or "cached hash")
            startup.s.advertiseRegionResolution = "Resolved: " .. tostring(cache.name or "Advertise Region")
            return cache.feature, cache.hash, cache.list
        end
    end
    cache.feature = nil
    cache.hash = nil
    cache.list = nil
    cache.entries = nil
    return nil, nil, nil
end

function startup.request_advertise_region_resolution(force, reason)
    if not startup.is_enhanced_active_edition() then return false end
    local cache = startup.advertise_region_cache or {}
    startup.advertise_region_cache = cache
    local now = startup.now()
    if force == true then cache.nextRetryMs = 0 end
    if startup.pendingAdvertiseRegionResolve == true or startup.advertiseRegionJobQueued == true then return true end
    if force ~= true and now < (tonumber(cache.nextRetryMs or 0) or 0) then return false end
    startup.pendingAdvertiseRegionResolve = true
    cache.lastScanStatus = "Queued: " .. tostring(reason or "Advertise Region requested")
    startup.s.advertiseRegionResolution = "Queued for scripting worker"
    startup.s.advertiseRegionSource = tostring(reason or "worker request")
    return true
end

function startup.run_advertise_region_resolution_now()

    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionResolution = "Not used on Legacy"
        startup.s.advertiseRegionSource = "Not used on Legacy"
        return
    end

    local cache = startup.advertise_region_cache or {}
    startup.advertise_region_cache = cache
    cache.scanRunning = true
    cache.scanAttempts = (tonumber(cache.scanAttempts or 0) or 0) + 1
    cache.hashesChecked = 0
    cache.lastScanStatus = "Resolving targeted Advertise Region feature"
    startup.s.advertiseCountResolution = "Not used on Enhanced"
    startup.s.advertiseRegionResolution = "Resolving targeted feature"

    -- Primary path: this is the exact documented API Build 080 used successfully.
    -- Only the named Advertise Region control is touched; the full feature tree is never enumerated.
    if FeatureMgr and FeatureMgr.GetFeatureByName then
        for _, name in ipairs(startup.advertise_region_names or {}) do
            local okFeature, feature = direct_call(function() return FeatureMgr.GetFeatureByName(name) end)
            if okFeature and feature then
                local snap, probeStatus = startup_region_feature_snapshot(feature, name)
                cache.lastTargetedProbe = tostring(name) .. ": " .. tostring(probeStatus or "no details")
                if snap then
                    cache.scanRunning = false
                    local resolvedFeature, resolvedHash, resolvedList = startup_commit_advertise_region_candidate(snap, "GetFeatureByName: " .. tostring(name))
                    if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
                    if startup.update_hud_cache then startup.update_hud_cache(true) end
                    return resolvedFeature, resolvedHash, resolvedList
                end
            elseif not okFeature then
                cache.lastTargetedProbe = tostring(name) .. ": GetFeatureByName raised an error"
            end
        end
    end

    local seen = {}
    local function try_hash(value, source)
        local hash = startup_normalize_feature_hash(value)
        if not hash or seen[hash] then return nil end
        seen[hash] = true
        cache.hashesChecked = cache.hashesChecked + 1
        local snap = startup_region_hash_snapshot(hash)
        if snap then return startup_commit_advertise_region_candidate(snap, source) end
        return nil
    end

    -- Known current EE hash from the previously confirmed working native control.
    for _, knownHash in ipairs(startup.advertise_region_known_hashes or {}) do
        local feature, hash, list = try_hash(knownHash, "known EE Advertise Region hash")
        if feature or hash then
            cache.scanRunning = false
            if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
            if startup.update_hud_cache then startup.update_hud_cache(true) end
            return feature, hash, list
        end
    end

    -- Secondary path: documented integer-hash search only.
    if FeatureMgr and FeatureMgr.SearchFeature then
        local searches = { "Advertise Region", "Advertisement Region", "Advertising Region", "Advertise", "Europe" }
        for _, query in ipairs(searches) do
            local okSearch, results = direct_call(function() return FeatureMgr.SearchFeature(query, 128, 0.0) end)
            if okSearch and type(results) == "table" then
                for key, value in pairs(results) do
                    local feature, hash, list = try_hash(value, "SearchFeature value: " .. query)
                    if feature or hash then
                        cache.scanRunning = false
                        if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
                        if startup.update_hud_cache then startup.update_hud_cache(true) end
                        return feature, hash, list
                    end
                    feature, hash, list = try_hash(key, "SearchFeature key: " .. query)
                    if feature or hash then
                        cache.scanRunning = false
                        if startup.s.advertiseRegionDefaultPending == true then startup.apply_ee_advertise_region_default() end
                        if startup.update_hud_cache then startup.update_hud_cache(true) end
                        return feature, hash, list
                    end
                end
            end
        end
    end


    cache.scanRunning = false
    cache.feature = nil
    cache.hash = nil
    cache.list = nil
    cache.entries = nil
    cache.nextRetryMs = startup.now() + 30000
    cache.lastScanStatus = "Targeted names failed; no valid region list found after " .. tostring(cache.hashesChecked or 0) .. " hash checks"
        .. (cache.lastTargetedProbe and (" | last probe: " .. tostring(cache.lastTargetedProbe)) or "")
    startup.s.advertiseRegionHash = nil
    startup.s.advertiseRegionSource = cache.lastScanStatus
    startup.s.advertiseRegionResolution = "Unavailable; retry queued in 30 seconds"
    return nil, nil, nil
end

function startup.process_pending_advertise_region_resolution()
    if startup.pendingAdvertiseRegionResolve ~= true or startup.advertiseRegionJobQueued == true then return end
    startup.pendingAdvertiseRegionResolve = false
    startup.advertiseRegionJobQueued = true

    local function job()
        -- Clear this before entering the resolver. A future native feature mismatch
        -- may terminate only this isolated job, while Startup's main worker continues.
        startup.advertiseRegionJobQueued = false
        startup.run_advertise_region_resolution_now()
    end

    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

local function startup_get_advertise_region_target(force)
    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionResolution = "Not used on Legacy"
        startup.s.advertiseRegionSource = "Not used on Legacy"
        return nil, nil, nil
    end
    startup.s.advertiseCountResolution = "Not used on Enhanced"

    local feature, hash, list = startup_validate_cached_advertise_region()
    if feature or hash then return feature, hash, list end

    startup.request_advertise_region_resolution(force == true, force == true and "manual refresh" or "region requested")
    return nil, nil, nil
end

function startup.get_advertise_region_hash(force)
    local _, hash, list = startup_get_advertise_region_target(force == true)
    return hash, list
end

function startup.get_advertise_region_feature(force)
    local feature, hash = startup_get_advertise_region_target(force == true)
    if feature then return feature, "targeted feature" end
    if hash and FeatureMgr and FeatureMgr.GetFeature then
        local ok, resolved = direct_call(function() return FeatureMgr.GetFeature(hash) end)
        if ok and resolved then return resolved, "hash " .. tostring(hash) end
    end
    return nil, nil
end

local function startup_get_live_advertise_region_index(feature, hash)
    local cache = startup.advertise_region_cache or {}
    local listCapable = cache.listCapable == true
    if feature and not listCapable then
        listCapable = startup_region_is_list_feature_type(startup_region_feature_type(feature))
    end
    if not listCapable then return nil end

    if feature and feature.GetListIndex then
        local value = feature:GetListIndex()
        if tonumber(value) ~= nil then
            cache.currentIndex = tonumber(value)
            return tonumber(value)
        end
    end
    if hash and FeatureMgr and FeatureMgr.GetFeatureListIndex then
        local value = FeatureMgr.GetFeatureListIndex(hash)
        if tonumber(value) ~= nil then
            cache.currentIndex = tonumber(value)
            return tonumber(value)
        end
    end
    return nil
end

function startup.get_advertise_region_label(force)
    if not startup.is_enhanced_active_edition() then return "Not used on Legacy" end
    local feature, hash, list = startup_get_advertise_region_target(force == true)
    if not feature and not hash then
        startup.s.advertiseRegionLabel = "Unknown"
        return startup.s.advertiseRegionLabel
    end

    local cache = startup.advertise_region_cache or {}
    local label = nil
    local index = startup_get_live_advertise_region_index(feature, hash)
    if index ~= nil then
        label = startup_region_label_for_index(list, index)
            or startup_region_known_label_for_index(index)
    end

    if (label == nil or tostring(label) == "")
        and cache.listCapable == true
        and hash
        and FeatureMgr
        and FeatureMgr.GetCurrentFeatureListString then
        local value = FeatureMgr.GetCurrentFeatureListString(hash)
        if value ~= nil and tostring(value) ~= "" then label = value end
    end
    if (label == nil or tostring(label) == "") and cache.currentString ~= nil and tostring(cache.currentString) ~= "" then
        label = cache.currentString
    end
    if (label == nil or tostring(label) == "") and cache.nativeOnly == true then
        label = "Native control"
    end

    label = tostring(label or "Unknown")
    if label == "" then label = "Unknown" end
    cache.currentIndex = index
    if label ~= "Unknown" and label ~= "Native control" then cache.currentString = label end
    startup.s.advertiseRegionLabel = label
    return label
end

local function startup_day_of_week_sunday_zero(year, month, day)
    year = math.floor(tonumber(year or 1970) or 1970)
    month = math.floor(tonumber(month or 1) or 1)
    day = math.floor(tonumber(day or 1) or 1)
    local offsets = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4}
    if month < 3 then year = year - 1 end
    return (year + math.floor(year / 4) - math.floor(year / 100) + math.floor(year / 400) + offsets[month] + day) % 7
end

local function startup_nth_sunday_of_month(year, month, nth)
    local firstWeekday = startup_day_of_week_sunday_zero(year, month, 1)
    local firstSunday = 1 + ((7 - firstWeekday) % 7)
    return firstSunday + (math.max(1, math.floor(tonumber(nth or 1) or 1)) - 1) * 7
end

function startup.get_local_clock_info(epoch)
    epoch = tonumber(epoch or os.time()) or os.time()
    local current = os.date("*t", epoch)
    if type(current) ~= "table" then
        return { hour = 0, minute = 0, totalMinutes = 0, display = "12:00 AM" }
    end
    local hour = tonumber(current.hour or 0) or 0
    local minute = tonumber(current.min or 0) or 0
    return {
        hour = hour,
        minute = minute,
        totalMinutes = (hour * 60) + minute,
        display = startup.format_clock_time_12h(hour, minute)
    }
end

function startup.normalize_advertise_region_schedule_mode(value)
    value = tostring(value or "All Regions")
    if value == "USA / Europe" then return "USA / Europe" end
    if value == "Manually Pick a Region" then return "Manually Pick a Region" end
    return "All Regions"
end

function startup.normalize_manual_advertise_region(value)
    value = tostring(value or "Europe")
    if startup.advertise_region_manual_choice_set[value] == true then return value end
    return "Europe"
end

function startup.sync_advertise_region_schedule_toggles()
    if not startup.h then return end
    local previousSync = startup.s.syncingFeatureStates == true
    startup.s.syncingFeatureStates = true
    local mode = startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode)
    startup.set_feature_bool_silently(startup.h.AdvertiseUsaEuropeByTime, startup.is_enhanced_active_edition() and mode == "USA / Europe")
    startup.set_feature_bool_silently(startup.h.AdvertiseAllRegionsByTime, startup.is_enhanced_active_edition() and mode == "All Regions")
    startup.set_feature_bool_silently(startup.h.AdvertiseManualRegion, startup.is_enhanced_active_edition() and mode == "Manually Pick a Region")
    startup.set_feature_list_string_silently(startup.h.AdvertiseManualRegionSelection, startup.s.advertiseRegionManualSelection or "Europe")
    startup.set_feature_bool_silently(startup.h.AutoAdvertiseRegionByTime, startup.is_enhanced_active_edition() and mode ~= "Manually Pick a Region")
    startup.set_feature_list_string_silently(startup.h.AdvertiseRegionScheduleMode, mode)
    startup.s.syncingFeatureStates = previousSync
end

function startup.select_manual_advertise_region(region, persist)
    region = startup.normalize_manual_advertise_region(region)
    startup.s.advertiseRegionManualSelection = region
    startup.set_feature_list_string_silently(startup.h and startup.h.AdvertiseManualRegionSelection, region)

    if startup.is_enhanced_active_edition()
        and startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode) == "Manually Pick a Region" then
        startup.s.advertiseRegionAutoScheduleEnabled = false
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: " .. region
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        startup.request_advertise_region_change(region, true)
        startup.request_advertise_region_resolution(false, "manual region selected")
    end

    if persist == true and startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    return region
end

function startup.select_advertise_region_schedule_mode(mode, reason, persist)
    mode = startup.normalize_advertise_region_schedule_mode(mode)
    startup.s.advertiseRegionAutoScheduleMode = mode
    startup.s.advertiseRegionAutoScheduleEnabled = startup.is_enhanced_active_edition() and mode ~= "Manually Pick a Region"
    startup.s.advertiseRegionAutoScheduleDefaultVersion = startup.advertise_region_schedule_default_version
    startup.s.advertiseRegionAutoScheduleModeDefaultVersion = startup.advertise_region_schedule_mode_default_version
    startup.s.advertiseRegionAutoScheduleNextCheckMs = 0
    startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""

    if mode == "Manually Pick a Region" then
        -- Preserve the user's saved manual choice when moving between modes.
        -- This makes returning to manual mode deterministic instead of replacing
        -- their choice with whichever timed region happened to be active.
        startup.s.advertiseRegionManualSelection = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: " .. tostring(startup.s.advertiseRegionManualSelection)
    else
        startup.s.advertiseRegionAutoScheduleStatus = "Using " .. mode
    end

    startup.sync_advertise_region_schedule_toggles()

    if startup.is_enhanced_active_edition() then
        if mode == "Manually Pick a Region" then
            local manualRegion = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
            startup.request_advertise_region_change(manualRegion, true)
            startup.request_advertise_region_resolution(false, tostring(reason or "manual advertise region mode"))
        elseif startup.s.advertiseRegionAutoScheduleEnabled == true then
            local schedule = startup.get_advertise_region_time_schedule(os.time(), mode)
            startup.s.advertiseRegionAutoScheduleLastRequestedRegion = tostring(schedule.region or "")
            startup.s.advertiseRegionAutoScheduleStatus = "Queued " .. tostring(schedule.region or "scheduled region")
            startup.request_advertise_region_change(tostring(schedule.region or "Europe"), false)
            startup.request_advertise_region_resolution(false, tostring(reason or "advertise schedule changed"))
        end
    end
    if persist == true and startup.s.initialized and not startup.s.syncingFeatureStates then startup.save_config(false) end
    return mode
end

function startup.get_advertise_region_time_schedule(epoch, requestedMode)
    local clock = startup.get_local_clock_info(epoch)
    local minute = tonumber(clock.totalMinutes or 0) or 0
    local mode = startup.normalize_advertise_region_schedule_mode(requestedMode or startup.s.advertiseRegionAutoScheduleMode)
    local region, window, nextMinute, nextRegion, summary

    if mode == "Manually Pick a Region" then
        region = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
        return {
            mode = mode,
            region = region,
            window = "Manual selection",
            summary = "Manual region: " .. region,
            clock = clock,
            nextRegion = region,
            nextSwitch = "Manual",
            minutesUntilSwitch = 0
        }
    end

    if mode == "USA / Europe" then
        if minute < 540 then
            region = "Europe"
            window = "12:00 AM-8:59 AM"
            nextMinute = 540
            nextRegion = "USA East"
        elseif minute < 960 then
            region = "USA East"
            window = "9:00 AM-3:59 PM"
            nextMinute = 960
            nextRegion = "USA West"
        else
            region = "USA West"
            window = "4:00 PM-11:59 PM"
            nextMinute = 1440
            nextRegion = "Europe"
        end
        summary = "Europe 12:00 AM-8:59 AM | USA East 9:00 AM-3:59 PM | USA West 4:00 PM-11:59 PM"
    else
        if minute < 120 then
            region = "Australia"
            window = "12:00 AM-1:59 AM"
            nextMinute = 120
            nextRegion = "Japan"
        elseif minute < 240 then
            region = "Japan"
            window = "2:00 AM-3:59 AM"
            nextMinute = 240
            nextRegion = "Northern Asia"
        elseif minute < 360 then
            region = "Northern Asia"
            window = "4:00 AM-5:59 AM"
            nextMinute = 360
            nextRegion = "Asia"
        elseif minute < 540 then
            region = "Asia"
            window = "6:00 AM-8:59 AM"
            nextMinute = 540
            nextRegion = "Europe"
        elseif minute < 780 then
            region = "Europe"
            window = "9:00 AM-12:59 PM"
            nextMinute = 780
            nextRegion = "South America"
        elseif minute < 960 then
            region = "South America"
            window = "1:00 PM-3:59 PM"
            nextMinute = 960
            nextRegion = "USA East"
        elseif minute < 1140 then
            region = "USA East"
            window = "4:00 PM-6:59 PM"
            nextMinute = 1140
            nextRegion = "USA West"
        else
            region = "USA West"
            window = "7:00 PM-11:59 PM"
            nextMinute = 1440
            nextRegion = "Australia"
        end
        summary = "Australia 12:00-1:59 AM | Japan 2:00-3:59 AM | Northern Asia 4:00-5:59 AM | Asia 6:00-8:59 AM | Europe 9:00 AM-12:59 PM | South America 1:00-3:59 PM | USA East 4:00-6:59 PM | USA West 7:00-11:59 PM"
    end

    local minutesUntil = nextMinute - minute
    if minutesUntil <= 0 then minutesUntil = minutesUntil + 1440 end
    local nextClockMinute = nextMinute % 1440
    local nextHour = math.floor(nextClockMinute / 60)
    local nextMin = nextClockMinute % 60
    return {
        mode = mode,
        region = region,
        window = window,
        summary = summary,
        clock = clock,
        nextRegion = nextRegion,
        nextSwitch = startup.format_clock_time_12h(nextHour, nextMin),
        minutesUntilSwitch = minutesUntil
    }
end

function startup.update_advertise_region_auto_schedule(force, reason)
    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionAutoScheduleStatus = "Not used on Legacy"
        return false
    end
    if startup.s.advertiseRegionAutoScheduleEnabled ~= true then
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: "
            .. tostring(startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection))
        return false
    end

    local schedule = startup.get_advertise_region_time_schedule(os.time())
    local desired = tostring(schedule.region or "Europe")
    local current = tostring(startup.get_advertise_region_label(false) or "Unknown")
    local sameRegion = startup_normalize_advertise_label(current) == startup_normalize_advertise_label(desired)
    startup.s.advertiseRegionAutoScheduleLastRegion = desired

    if sameRegion and force ~= true then
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        startup.s.advertiseRegionAutoScheduleStatus = desired .. " active at " .. tostring(schedule.clock.display)
            .. "; next " .. tostring(schedule.nextRegion) .. " at " .. tostring(schedule.nextSwitch)
        return true
    end

    if startup.pendingAdvertiseRegionName ~= nil and tostring(startup.pendingAdvertiseRegionName) ~= "" then
        startup.s.advertiseRegionAutoScheduleStatus = "Waiting for pending region change to " .. tostring(startup.pendingAdvertiseRegionName)
        return false
    end

    local lastRequested = tostring(startup.s.advertiseRegionAutoScheduleLastRequestedRegion or "")
    if force ~= true and startup_normalize_advertise_label(lastRequested) == startup_normalize_advertise_label(desired) then
        startup.s.advertiseRegionAutoScheduleStatus = "Waiting for " .. desired .. " to apply"
        return false
    end

    startup.s.advertiseRegionAutoScheduleLastRequestedRegion = desired
    startup.s.advertiseRegionAutoScheduleStatus = "Queued " .. desired .. " at " .. tostring(schedule.clock.display)
    startup.request_advertise_region_change(desired, false)
    return true
end

function startup.process_advertise_region_auto_schedule()
    if startup.s.advertiseRegionAutoScheduleEnabled ~= true then return end
    local now = startup.now()
    if now < (tonumber(startup.s.advertiseRegionAutoScheduleNextCheckMs or 0) or 0) then return end
    startup.s.advertiseRegionAutoScheduleNextCheckMs = now + 30000
    startup.update_advertise_region_auto_schedule(false, "30-second schedule check")
end

local function startup_apply_advertise_region_now(wanted, markAsUserChoice)
    if not startup.is_enhanced_active_edition() then return false end
    local previousLabel = tostring(startup.get_advertise_region_label(false) or startup.s.advertiseRegionLabel or "Unknown")
    local feature, hash, list = startup_get_advertise_region_target(false)
    if not feature and not hash then return false end

    local cache = startup.advertise_region_cache or {}
    local index, actualName = startup_region_list_contains(list, wanted)
    if index == nil and cache.nativeOnly == true and cache.listCapable == true then
        local normalizedWanted = startup_normalize_advertise_label(wanted)
        local nativeIndexByLabel = {
            northernasia = 0,
            southamerica = 1,
            usaeast = 2,
            europe = 3,
            asia = 4,
            australia = 5,
            usawest = 6,
            japan = 7
        }
        index = nativeIndexByLabel[normalizedWanted]
        if index ~= nil then actualName = startup_region_known_label_for_index(index) end
    end
    if index == nil then return false end

    local okSet = direct_call(function()
        if feature and feature.SetListIndex then
            feature:SetListIndex(index)
            if feature.TriggerCallback then feature:TriggerCallback()
            elseif feature.OnClick then feature:OnClick() end
        elseif hash and FeatureMgr and FeatureMgr.SetFeatureListIndex then
            FeatureMgr.SetFeatureListIndex(hash, index)
            if FeatureMgr.TriggerFeatureCallback then FeatureMgr.TriggerFeatureCallback(hash) end
        else
            error("Advertise Region has no supported setter")
        end
    end)
    if not okSet then
        startup.s.advertiseRegionDefaultStatus = "Region callback failed for " .. tostring(actualName or wanted)
        return false
    end

    startup.s.advertiseRegionLabel = tostring(actualName or wanted)
    startup.s.advertiseRegionResolution = "Resolved: " .. tostring((startup.advertise_region_cache or {}).name or "Advertise Region")
    if startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode) == "Manually Pick a Region" then
        startup.s.advertiseRegionManualSelection = startup.normalize_manual_advertise_region(startup.s.advertiseRegionLabel)
        startup.s.advertiseRegionAutoScheduleStatus = "Manual region: " .. startup.s.advertiseRegionManualSelection
    end
    if startup.s.advertiseRegionAutoScheduleEnabled == true then
        startup.s.advertiseRegionAutoScheduleLastRegion = startup.s.advertiseRegionLabel
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        local activeSchedule = startup.get_advertise_region_time_schedule(os.time())
        startup.s.advertiseRegionAutoScheduleStatus = startup.s.advertiseRegionLabel .. " active at "
            .. tostring(activeSchedule.clock.display) .. "; next " .. tostring(activeSchedule.nextRegion)
            .. " at " .. tostring(activeSchedule.nextSwitch)
    end
    if markAsUserChoice == true then
        startup.s.advertiseRegionDefaultVersion = startup.advertise_region_default_version
        startup.s.advertiseRegionDefaultPending = false
        startup.s.advertiseRegionDefaultStatus = "Manual region saved: " .. startup.s.advertiseRegionLabel
        startup.save_config(false)
    end
    if startup.update_hud_cache then startup.update_hud_cache(true) end
    local previousNormalized = startup_normalize_advertise_label(previousLabel)
    local currentNormalized = startup_normalize_advertise_label(startup.s.advertiseRegionLabel)
    if previousNormalized ~= "" and previousNormalized ~= "unknown" and previousNormalized ~= currentNormalized then
        startup.log_colored("[Region] Enhanced Advertise Region changed from " .. previousLabel
            .. " to " .. startup.s.advertiseRegionLabel .. "!", "success")
    end
    return true
end

function startup.request_advertise_region_change(wanted, markAsUserChoice)
    if not startup.is_enhanced_active_edition() then return false end
    startup.pendingAdvertiseRegionName = tostring(wanted or "")
    startup.pendingAdvertiseRegionUserChoice = markAsUserChoice == true
    startup.s.advertiseRegionDefaultStatus = "Queued region change: " .. tostring(wanted or "")
    return startup.pendingAdvertiseRegionName ~= ""
end

function startup.run_advertise_region_change_now()
    local wanted = startup.pendingAdvertiseRegionName
    if wanted == nil or tostring(wanted) == "" then return end
    local markAsUserChoice = startup.pendingAdvertiseRegionUserChoice == true
    startup.pendingAdvertiseRegionName = nil
    startup.pendingAdvertiseRegionUserChoice = false

    if not startup_apply_advertise_region_now(wanted, markAsUserChoice) then
        startup.s.advertiseRegionDefaultStatus = "Region change pending; resolver is not ready for " .. tostring(wanted)
        startup.request_advertise_region_resolution(false, "queued region change")
        startup.pendingAdvertiseRegionName = tostring(wanted)
        startup.pendingAdvertiseRegionUserChoice = markAsUserChoice
    end
end

function startup.process_pending_advertise_region_change()
    if startup.pendingAdvertiseRegionName == nil or tostring(startup.pendingAdvertiseRegionName) == "" then return end
    if startup.advertiseRegionChangeJobQueued == true then return end
    startup.advertiseRegionChangeJobQueued = true

    local function job()
        startup.advertiseRegionChangeJobQueued = false
        startup.run_advertise_region_change_now()
    end
    if Script and Script.QueueJob then Script.QueueJob(job) else job() end
end

function startup.set_advertise_region_by_name(wanted, markAsUserChoice)
    -- Internal worker calls can apply immediately. ImGui uses request_advertise_region_change below.
    return startup_apply_advertise_region_now(wanted, markAsUserChoice == true)
end

function startup.apply_ee_advertise_region_default()
    if not startup.is_enhanced_active_edition() then
        startup.s.advertiseRegionDefaultPending = false
        startup.s.advertiseRegionDefaultStatus = "Not used on Legacy"
        return true
    end
    if startup.s.advertiseRegionDefaultPending ~= true then return true end
    startup.s.advertiseRegionDefaultAttempts = (tonumber(startup.s.advertiseRegionDefaultAttempts or 0) or 0) + 1
    local desired = "Europe"
    local mode = startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode)
    if mode == "Manually Pick a Region" then
        desired = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
    elseif startup.s.advertiseRegionAutoScheduleEnabled == true then
        desired = tostring(startup.get_advertise_region_time_schedule(os.time()).region or "Europe")
    end
    if startup_apply_advertise_region_now(desired, false) then
        startup.s.advertiseRegionDefaultVersion = startup.advertise_region_default_version
        startup.s.advertiseRegionDefaultPending = false
        startup.s.advertiseRegionDefaultStatus = desired .. " applied as the Enhanced startup region"
        startup.s.advertiseRegionAutoScheduleLastRegion = desired
        startup.s.advertiseRegionAutoScheduleLastRequestedRegion = ""
        startup.save_config(false)
        return true
    end
    startup.s.advertiseRegionDefaultStatus = desired .. " pending; targeted Advertise Region feature is not ready yet"
    return false
end

function startup.render_advertise_region_control()
    local mode = startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode)
    if mode == "Manually Pick a Region" then
        local selected = startup.normalize_manual_advertise_region(startup.s.advertiseRegionManualSelection)
        local current = tostring(startup.get_advertise_region_label(false) or startup.s.advertiseRegionLabel or "Unknown")
        startup.status_line("Selected Region", selected, 0.72, 0.42, 1.00)
        startup.status_line("Current Region", current, 0.35, 1.00, 0.45)
        startup.subtle_text("Manual region stays active until you choose another mode.")
    else
        local schedule = startup.get_advertise_region_time_schedule(os.time(), mode)
        startup.status_line("Current Region", tostring(schedule.region), 0.35, 1.00, 0.45)
        startup.subtle_text("Region changes automatically using local PC time.")
    end
end
function startup.set_advertise_count(value)
    if startup.is_enhanced_active_edition() then
        startup.s.advertiseCountResolution = "Not used on Enhanced"
        return false
    end
    local hash = startup.feature_hash and startup.feature_hash.ADVERTISE_COUNT or 4100757571
    return startup.set_int_feature_by_names(startup.advertise_count_names, value, hash)
end

function startup.get_feature_bool_state(feature)
    if not feature then return nil end
    if feature.IsToggled then
        local value = feature:IsToggled()
        if value ~= nil then return value == true end
    end
    if feature.GetBoolValue then
        local value = feature:GetBoolValue()
        if value ~= nil then return value == true end
    end
    return nil
end

function startup.set_advertise_session(enabled, force)
    enabled = enabled == true
    local feature, matchedName = startup.get_advertise_session_feature()
    if not feature then
        startup.s.advertiseFeatureUnavailable = true
        startup.s.advertiseFeatureResolution = "Unavailable"
        startup.s.lastAdvertiseStatus = "Advertise Session unavailable; smart advertise paused"
        if not startup.s.advertiseFeatureMissingLogged then
            startup.s.advertiseFeatureMissingLogged = true
            startup.log("Advertise Session control is unavailable on this Cherax layout. Smart advertise paused.")
        end
        return false
    end
    startup.s.advertiseFeatureUnavailable = false
    startup.s.advertiseFeatureMissingLogged = false
    startup.s.advertiseFeatureResolution = tostring(matchedName or "Resolved")
    local currentState = startup.get_feature_bool_state(feature)
    if not force then
        if currentState ~= nil and currentState == enabled then
            startup.s.advertiseSessionEnabled = enabled
            return true
        end
        if currentState == nil and startup.s.advertiseSessionEnabled == enabled then return true end
    end
    local ok = direct_call(function()
        -- Toggle(bool) is the safest Cherax path for native toggles. Do not pair
        -- SetBoolValue with an unconditional callback, because some Cherax builds
        -- treat that callback like a second click and return the toggle to OFF.
        if feature.Toggle then
            feature:Toggle(enabled)
        elseif feature.SetBoolValue then
            feature:SetBoolValue(enabled)
        elseif currentState ~= nil and currentState ~= enabled and feature.OnClick then
            feature:OnClick()
        elseif currentState ~= nil and currentState ~= enabled and feature.TriggerCallback then
            feature:TriggerCallback()
        end
    end)
    if not ok then
        startup.s.lastAdvertiseStatus = "Advertise Session callback failed"
        return false
    end
    startup.s.advertiseSessionEnabled = enabled
    startup.s.lastAdvertiseStatus = "Advertise Session " .. (enabled and "ON" or "OFF")
    return true
end

function startup.get_advertise_session_feature()
    local hash = startup.feature_hash and startup.feature_hash.ADVERTISE_SESSION or 49959509
    local feature = startup.get_feature_by_hash_safe(hash)
    if feature and (feature.SetBoolValue or feature.Toggle or feature.TriggerCallback or feature.OnClick) then
        return feature, "hash " .. tostring(hash)
    end
    local matchedName
    feature, matchedName = startup.find_feature_by_possible_names(startup.advertise_session_names)
    if feature then return feature, matchedName end
    return nil, nil
end

function startup.request_advertise_session_sync(enabled, reason)
    startup.pendingAdvertiseSessionDesired = enabled == true
    startup.pendingAdvertiseSessionSyncReason = tostring(reason or "Startup Auto Advertise Session")
    startup.pendingAdvertiseSessionSync = true
end

function startup.process_pending_advertise_session_sync()
    if startup.pendingAdvertiseSessionSync ~= true then return end
    startup.pendingAdvertiseSessionSync = false
    local desired = startup.pendingAdvertiseSessionDesired == true
    local reason = tostring(startup.pendingAdvertiseSessionSyncReason or "Startup Auto Advertise Session")
    local ok = startup.set_advertise_session(desired, true)
    if ok then
        startup.s.lastAdvertiseStatus = "Cherax Advertise Session synchronized " .. (desired and "ON" or "OFF")
    else
        startup.s.lastAdvertiseStatus = "Could not synchronize Cherax Advertise Session " .. (desired and "ON" or "OFF")
        if startup.s.verboseStartupLogs then
            startup.log("Advertise Session synchronization failed | desired=" .. tostring(desired) .. " | reason=" .. reason)
        end
    end
end

function startup.detect_manual_advertise_off()
    if not startup.s.advertiseRunning then return false end
    if startup.s.advertiseStopRequested then return false end
    if startup.s.advertiseManualOverride then return true end
    local feature = startup.get_advertise_session_feature()
    if not feature then return false end
    local currentState = startup.get_feature_bool_state(feature)
    -- important:
    -- if Startup previously turned Advertise Session ON, but the real feature is now OFF,
    -- that almost certainly means the user manually toggled Advertise Session off.
    -- do NOT turn it back on automatically. Pause the smart advertise flow instead.
    if startup.s.advertiseSessionEnabled == true and currentState == false then
        startup.s.advertiseManualOverride = true
        startup.s.advertiseStopRequested = true
        startup.s.lastAdvertiseStatus = "Manual Advertise OFF detected; smart advertise paused"
        startup.toast("Manual Advertise OFF detected. Use Run Advertise Flow to resume.", 3500)
        return true
    end
    return false
end

function startup.reset_advertise_flow()
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    startup.s.advertiseRunning = false
    startup.s.advertiseSmartActive = false
    startup.s.advertiseCompletedForSession = false
    startup.s.advertiseStopRequested = false
    startup.s.advertiseCountEscalated = false
    startup.s.advertiseSessionEnabled = nil
    startup.s.advertiseManualOverride = false
    startup.s.advertiseFeatureUnavailable = false
    startup.s.advertiseFeatureMissingLogged = false
    startup.s.lastAdvertiseStatus = "Reset"
    startup.toast("Advertise flow reset.", 2500)
end

function startup.request_advertise_stop(reason)
    if not startup.s.advertiseRunning then
        startup.set_advertise_session(false)
        startup.s.lastAdvertiseStatus = "Stopped"
        return
    end
    startup.s.advertiseStopRequested = true
    if reason then
        startup.s.lastAdvertiseStatus = "Stop requested: " .. tostring(reason)
        startup.toast(startup.s.lastAdvertiseStatus, 3000)
    end
end

function startup.stop_advertise_now()
    startup.s.advertiseManualOverride = true
    startup.request_advertise_stop("manual stop")
    startup.set_advertise_session(false, true)
end

function startup.apply_advertise_count(value, label)
    value = tonumber(value or 5) or 5
    if startup.s.advertiseCurrentCount == value and startup.s.advertiseCountFeatureName then return true end
    local ok = startup.set_advertise_count(value)
    if ok then
        startup.s.advertiseCurrentCount = value
        startup.s.lastAdvertiseStatus = label or ("Advertise Count " .. tostring(value))
        return true
    end
    startup.s.lastAdvertiseStatus = "Advertise Session active; Advertise Count is not exposed on this Cherax layout"
    return false
end

function startup.update_advertise_smart_state(context)
    if not startup.s.advertiseRunning then return end
    if not startup.s.advertiseSmartActive then return end
    if startup.s.advertiseStopRequested then return end
    if startup.detect_manual_advertise_off() then return end
    local playerCount = startup.get_session_player_count()
    local highLimit = tonumber(startup.s.advertisePlayerTarget or 30) or 30
    local resumeBelow = tonumber(startup.s.advertiseResumeBelow or 25) or 25

    if startup.is_enhanced_active_edition() then
        local region = startup.get_advertise_region_label(false)
        if playerCount >= highLimit then
            if not startup.set_advertise_session(false) then return end
            startup.s.lastAdvertiseStatus = "Enhanced hold: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players; Advertise OFF | " .. tostring(region)
            return
        end
        if playerCount < resumeBelow then
            if not startup.set_advertise_session(true) then return end
            startup.s.lastAdvertiseStatus = "Enhanced advertise ON: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players | " .. tostring(region)
            return
        end
        if startup.s.advertiseSessionEnabled == false then
            startup.s.lastAdvertiseStatus = "Enhanced hold: waiting below " .. tostring(resumeBelow) .. " players | " .. tostring(region)
            return
        end
        if not startup.set_advertise_session(true) then return end
        startup.s.lastAdvertiseStatus = "Enhanced maintaining: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players | " .. tostring(region)
        return
    end

    local lowCount = tonumber(startup.s.advertiseLowCount or 5) or 5
    local highCount = tonumber(startup.s.advertiseHighCount or 10) or 10
    if playerCount >= highLimit then
        if not startup.set_advertise_session(true) then return end
        startup.apply_advertise_count(lowCount, "Soft hold at " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players")
        startup.s.lastAdvertiseStatus = "Legacy soft hold: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players, count " .. tostring(lowCount)
        return
    end
    if playerCount < resumeBelow then
        if not startup.set_advertise_session(true) then return end
        startup.apply_advertise_count(highCount, "Re-boost below " .. tostring(resumeBelow) .. " players")
        startup.s.lastAdvertiseStatus = "Legacy re-boost: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players, count " .. tostring(highCount)
        return
    end
    if not startup.set_advertise_session(true) then return end
    startup.s.lastAdvertiseStatus = "Legacy maintaining: " .. tostring(playerCount) .. "/" .. tostring(highLimit) .. " players, count " .. tostring(startup.s.advertiseCurrentCount or "?")
end

function startup.run_advertise_flow(reason)
    if not startup.s.autoAdvertiseSession then
        startup.s.lastAdvertiseStatus = "Auto Advertise OFF"
        startup.toast("Auto Advertise Session is OFF.", 2500)
        return
    end
    if startup.s.advertiseRunning then
        startup.toast("Advertise flow is already running.", 2500)
        return
    end
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    local flowSerial = startup.s.advertiseFlowSerial
    startup.s.advertiseRunning = true
    startup.s.advertiseSmartActive = false
    startup.s.advertiseCompletedForSession = false
    startup.s.advertiseStopRequested = false
    startup.s.advertiseCountEscalated = false
    startup.s.advertiseCurrentCount = 0
    startup.s.advertiseSessionEnabled = nil
    startup.s.advertiseManualOverride = false
    startup.s.advertiseFeatureUnavailable = false
    startup.s.advertiseFeatureMissingLogged = false
    Script.QueueJob(function()
        startup.s.lastAdvertiseStatus = "Queued"
        if startup.is_enhanced_active_edition() then
            startup.toast("EE Advertise Session enabled. Smart player-limit management begins in 2 minutes.", 4500)
            -- EE advertising is already slow, so keep Cherax's native Advertise Session ON
            -- while Startup waits before beginning threshold-based management.
            startup.set_advertise_session(true, true)
        else
            startup.toast("Advertise flow queued" .. (reason and (" after " .. reason) or "") .. ". Waiting 2 minutes.", 3500)
            -- Legacy keeps the prior stabilization behavior.
            startup.set_advertise_session(false)
        end
        startup.yield(startup.s.advertiseDelayAfterSessionMs)
        if flowSerial ~= startup.s.advertiseFlowSerial then return end
        if startup.s.advertiseStopRequested then
            startup.s.lastAdvertiseStatus = "Stopped before start"
            startup.s.advertiseRunning = false
            startup.s.advertiseSmartActive = false
            startup.s.advertiseCompletedForSession = true
            startup.set_advertise_session(false)
            return
        end
        if not startup.set_advertise_session(true) then
            startup.s.advertiseRunning = false
            startup.s.advertiseSmartActive = false
            startup.s.advertiseCompletedForSession = true
            return
        end
        startup.s.advertiseSmartActive = true
        if startup.is_enhanced_active_edition() then
            local region = startup.get_advertise_region_label(true)
            startup.s.lastAdvertiseStatus = "Enhanced advertise active | " .. tostring(region)
        else
            startup.apply_advertise_count(startup.s.advertiseLowCount or 5, "Initial soft start")
        end
        local elapsed = 0
        while true do
            if flowSerial ~= startup.s.advertiseFlowSerial then return end
            if startup.s.advertiseStopRequested then
                startup.s.lastAdvertiseStatus = "Stopped by request"
                break
            end
            local playerCount = startup.get_session_player_count()
            if not startup.is_enhanced_active_edition()
                and not startup.s.advertiseCountEscalated
                and elapsed >= startup.s.advertiseCount5DurationMs
                and playerCount < (startup.s.advertisePlayerTarget or 30) then
                startup.s.advertiseCountEscalated = true
                startup.apply_advertise_count(startup.s.advertiseHighCount or 10, "5 minutes passed and lobby is below high limit")
            end
            startup.update_advertise_smart_state("loop")
            startup.yield(startup.s.advertisePlayerCheckMs)
            elapsed = elapsed + startup.s.advertisePlayerCheckMs
        end
        startup.set_advertise_session(false)
        startup.s.advertiseCompletedForSession = true
        startup.s.advertiseRunning = false
        startup.s.advertiseSmartActive = false
        startup.s.advertiseStopRequested = false
        startup.s.advertiseCountEscalated = false
        startup.s.lastAdvertiseStatus = "Stopped"
    end)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- lua startup runner
-- note: discovers local scripts and applies master or per-file spacing.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.find_local_lua_files()
    local found = {}
    local folders = {
        startup.lua_content_dir,
        startup.lua_dir
    }
    for _, folderPath in ipairs(folders) do
        local files = FileMgr.FindFiles(folderPath, ".lua", false)
        if files then
            for _, path in ipairs(files) do
                if not startup.is_startup_lua(path) and not startup.path_exists_in_list(found, path) then
                    table.insert(found, path)
                end
            end
        end
    end
    table.sort(found, function(a, b)
        return string.lower(startup.get_file_name(a)) < string.lower(startup.get_file_name(b))
    end)
    return found
end

function startup.refresh_lua_file_list()
    local files = startup.find_local_lua_files()
    startup.s.luaFiles = {}
    startup.s.luaFileDelaysMs = startup.s.luaFileDelaysMs or {}
    startup.s.luaFileDelayOverrides = startup.s.luaFileDelayOverrides or {}
    local selectedFound = false
    for index, path in ipairs(files) do
        if startup.s.luaFileStates[path] == nil then startup.s.luaFileStates[path] = false end
        if tostring(startup.s.selectedLuaFilePath or "") == tostring(path) then selectedFound = true end
        table.insert(startup.s.luaFiles, {
            index = index,
            path = path,
            name = startup.get_file_name(path),
            hash = startup.hash("RUN_ON_STARTUP_" .. tostring(index) .. "_" .. startup.get_file_name(path))
        })
    end
    if not selectedFound then
        startup.s.selectedLuaFilePath = ""
        for _, entry in ipairs(startup.s.luaFiles) do
            if startup.s.luaFileStates[entry.path] == true then
                startup.s.selectedLuaFilePath = entry.path
                break
            end
        end
        if startup.s.selectedLuaFilePath == "" and startup.s.luaFiles[1] then
            startup.s.selectedLuaFilePath = startup.s.luaFiles[1].path
        end
    end
    startup.save_config(false)
    startup.s.lastLuaStatus = "Found " .. tostring(#startup.s.luaFiles) .. " Lua file(s)"
end

function startup.get_lua_file_entry(path)
    path = tostring(path or startup.s.selectedLuaFilePath or "")
    for _, entry in ipairs(startup.s.luaFiles or {}) do
        if tostring(entry.path) == path then return entry end
    end
    return nil
end

function startup.is_lua_file_delay_overridden(path)
    return startup.s.luaFileDelayOverrides and startup.s.luaFileDelayOverrides[tostring(path or "")] == true
end

function startup.get_lua_file_delay_ms(path)
    path = tostring(path or "")
    local master = startup.clamp_int(startup.s.luaDelayBetweenFilesMs or 5000, 0, 300000)
    if not startup.is_lua_file_delay_overridden(path) then return master end
    return startup.clamp_int((startup.s.luaFileDelaysMs or {})[path] or master, 0, 300000)
end

function startup.set_lua_file_delay_override(path, enabled)
    path = tostring(path or "")
    if path == "" then return end
    startup.s.luaFileDelayOverrides = startup.s.luaFileDelayOverrides or {}
    startup.s.luaFileDelaysMs = startup.s.luaFileDelaysMs or {}
    startup.s.luaFileDelayOverrides[path] = enabled == true
    if enabled and startup.s.luaFileDelaysMs[path] == nil then
        startup.s.luaFileDelaysMs[path] = startup.clamp_int(startup.s.luaDelayBetweenFilesMs or 5000, 0, 300000)
    end
    startup.save_config(false)
end

function startup.set_lua_file_delay_ms(path, delayMs)
    path = tostring(path or "")
    if path == "" then return end
    startup.s.luaFileDelaysMs = startup.s.luaFileDelaysMs or {}
    startup.s.luaFileDelayOverrides = startup.s.luaFileDelayOverrides or {}
    startup.s.luaFileDelaysMs[path] = startup.clamp_int(delayMs or 5000, 0, 300000)
    startup.s.luaFileDelayOverrides[path] = true
    startup.save_config(false)
end

function startup.execute_lua_file(path)
    if not path or path == "" then
        return false
    end
    local fileName = startup.get_file_name(path)
    startup.s.lastLuaStatus = "Running: " .. fileName
    startup.toast("Running Lua file: " .. fileName, 2500)
    local ok = Utils.ExecuteScript(path)
    if ok ~= nil then
        startup.s.lastLuaStatus = "Executed: " .. fileName
        startup.toast("Executed Lua file: " .. fileName, 2500)
        return true
    end
    startup.s.lastLuaStatus = "Failed: " .. fileName
    startup.error("Failed to execute Lua file: " .. fileName)
    return false
end

function startup.get_enabled_lua_files()
    local enabled = {}
    startup.refresh_lua_file_list()
    for _, entry in ipairs(startup.s.luaFiles) do
        if startup.s.luaFileStates[entry.path] == true then
            table.insert(enabled, entry)
        end
    end
    return enabled
end

function startup.run_enabled_lua_files()
    if not startup.s.autoRunLuaFiles then
        startup.s.lastLuaStatus = "Auto-Run Local Lua Files OFF"
        startup.toast("Auto-Run Local Lua Files is OFF.", 2500)
        return
    end
    if startup.s.luaStartupRunning then
        startup.toast("Lua startup runner is already running.", 2500)
        return
    end
    local enabled = startup.get_enabled_lua_files()
    if #enabled == 0 then
        startup.s.lastLuaStatus = "No Lua files enabled"
        startup.toast("No LuaContent files are enabled for startup yet.", 3000)
        return
    end
    startup.s.luaStartupRunning = true
    startup.s.lastLuaStartupRunMs = startup.now()
    startup.toast("Loading " .. tostring(#enabled) .. " enabled Lua file(s).", 3000)
    for index, entry in ipairs(enabled) do
        startup.s.lastLuaStatus = "Loading " .. tostring(index) .. "/" .. tostring(#enabled) .. ": " .. entry.name
        startup.execute_lua_file(entry.path)
        if index < #enabled then
            local delayMs = startup.get_lua_file_delay_ms(entry.path)
            local nextName = enabled[index + 1].name
            startup.s.lastLuaStatus = "Next: " .. tostring(nextName) .. " in " .. startup.format_seconds(delayMs)
            if delayMs > 0 then startup.yield(delayMs) end
        end
    end
    startup.s.luaStartupRunning = false
    startup.s.lastLuaStatus = "Finished loading enabled Lua files"
    startup.toast("Finished loading enabled Lua startup files.", 3000)
end


-- ═══════════════════════════════════════════════════════════════════════════════════
-- experimental cherax host diagnostic and lobby filters
-- note: all 30/50 host checks are read-only. No kick, crash, script event, entity,
-- explosion, chat injection, or forced player interaction is performed.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.cherax_host_probe = startup.cherax_host_probe or {
    busy = false,
    lastResult = nil
}
startup.lobby_filter = startup.lobby_filter or {
    sessionSerial = 0,
    running = false,
    hopRequested = false,
    forceImmediate = false
}
startup.pendingCheraxHostProbe = false
startup.pendingCheraxHostProbeMethods = 30
startup.cheraxHostProbeJobQueued = false

function startup.cherax_host_probe.raw_modder_reasons(playerId)
    local reasons = {}
    if not ModderDB or not ModderDB.GetModderDetectionsByPlayerId then return reasons end
    local detections = ModderDB.GetModderDetectionsByPlayerId(playerId)
    if type(detections) ~= "table" then return reasons end
    for _, detection in pairs(detections) do
        local reason = ""
        if type(detection) == "table" then
            reason = tostring(detection[1] or detection.name or detection.detection or detection.reason or "")
        elseif type(detection) == "string" then
            reason = detection
        end
        reason = tostring(reason or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if reason ~= "" then reasons[#reasons + 1] = reason end
    end
    table.sort(reasons, function(a, b) return string.lower(a) < string.lower(b) end)
    return reasons
end

function startup.cherax_host_probe.player_id_from_object(object)
    if not object then return nil end
    return tonumber(object.PlayerId)
end

function startup.cherax_host_probe.run(reasonLabel, requestedMethodCount)
    local methodCount = tonumber(requestedMethodCount) == 50 and 50 or 30
    if startup.cherax_host_probe.busy == true then
        startup.s.cheraxHostProbeStatus = "A Cherax Host Test is already running."
        return startup.cherax_host_probe.lastResult
    end
    startup.cherax_host_probe.busy = true

    local hostName, hostId = startup.get_session_host_name()
    hostId = tonumber(hostId) or -1
    hostName = tostring(hostName or "Unknown")
    local probes = {}
    local explicitSignals = 0
    local menuSignals = 0
    local tags = ""
    local player = nil
    local gamerInfo = nil
    local rid = nil
    local hostKey = nil
    local cxnId = nil
    local playerAddress = nil
    local ipAddress = nil
    local ipString = ""
    local netAddress = nil
    local netAddressType = nil
    local cped = nil
    local cpedAddress = nil
    local rawReasons = {}
    local racReasons = {}
    local playerInfo = nil
    local playerInfoNetData = nil
    local playerInfoPed = nil
    local playerInfoPedAddress = nil
    local playerState = nil
    local playerTeam = nil
    local friendStatus = nil
    local playerMaxHealth = nil
    local playerMaxArmour = nil
    local weaponDamageModifier = nil
    local meleeWeaponDamageModifier = nil
    local meleeUnarmedDamageModifier = nil
    local vehicleDamageModifier = nil
    local explosiveDamageModifier = nil
    local sprintMultiplier = nil
    local deepSignals = 0

    local function mark_menu_signal(condition)
        if condition == true then menuSignals = menuSignals + 1 end
    end

    local function emit(index, label, passed, detail)
        local status = passed == true and "PASS" or "MISS"
        local row = {
            index = index,
            label = tostring(label or ""),
            passed = passed == true,
            detail = tostring(detail or "")
        }
        probes[#probes + 1] = row
        startup.log(string.format("[Cherax Host Test] %02d/%02d %s | %s | %s", index, methodCount, status, row.label, row.detail))
        if Script and Script.Yield then Script.Yield(35) end
    end

    startup.s.cheraxHostProbeStatus = "Running " .. tostring(methodCount) .. " read-only methods against the current Session Host..."
    startup.s.cheraxHostProbeLastHostName = hostName
    startup.s.cheraxHostProbeLastHostId = hostId
    startup.log("[Cherax Host Test] BEGIN | methods=" .. tostring(methodCount) .. " | reason=" .. tostring(reasonLabel or "manual") .. " | host=" .. hostName .. " | playerId=" .. tostring(hostId) .. " | safety=read-only")

    emit(1, "Native Session Host index", hostId >= 0 and hostId <= 31, "playerId=" .. tostring(hostId))

    emit(2, "Session Host name", hostName ~= "" and hostName ~= "Unknown" and hostName ~= "Invalid", "name=" .. hostName)

    local directName = ""
    if hostId >= 0 and Players and Players.GetName then directName = tostring(Players.GetName(hostId) or "") end
    emit(3, "Players.GetName consistency", directName ~= "" and directName == hostName, "direct=" .. tostring(directName))

    if hostId >= 0 and Players and Players.GetTags then tags = tostring(Players.GetTags(hostId) or "") end
    emit(4, "Cherax player tags readable", tags ~= "", "tags=" .. (tags ~= "" and tags or "<empty>"))

    local hasHostTag = string.find(tags, "[H]", 1, true) ~= nil
    emit(5, "Host tag [H]", hasHostTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    local scriptHostName, scriptHostId = startup.get_script_host_name()
    local sameScriptHost = tonumber(scriptHostId) == hostId and hostId >= 0
    emit(6, "Session Host is also freemode Script Host", sameScriptHost, "scriptHost=" .. tostring(scriptHostName) .. " [" .. tostring(scriptHostId) .. "]")

    local hasScriptHostTag = string.find(tags, "[SH]", 1, true) ~= nil
    emit(7, "Script Host tag [SH]", hasScriptHostTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    local hasModderTag = string.find(tags, "[M]", 1, true) ~= nil
    mark_menu_signal(hasModderTag)
    emit(8, "Modder tag [M]", hasModderTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    local hasFriendTag = string.find(tags, "[F]", 1, true) ~= nil
    emit(9, "Friend tag [F]", hasFriendTag, "tags=" .. (tags ~= "" and tags or "<empty>"))

    if hostId >= 0 and Players and Players.GetById then player = Players.GetById(hostId) end
    emit(10, "CNetGamePlayer by player ID", player ~= nil, "object=" .. tostring(player ~= nil))

    local objectPlayerId = startup.cherax_host_probe.player_id_from_object(player)
    emit(11, "CNetGamePlayer.PlayerId round-trip", objectPlayerId == hostId and hostId >= 0, "objectPlayerId=" .. tostring(objectPlayerId))

    if player then cxnId = tonumber(player.CxnId) end
    emit(12, "Connection ID", cxnId ~= nil and cxnId >= 0, "cxnId=" .. tostring(cxnId))

    if player and player.GetAddress then playerAddress = tonumber(player:GetAddress()) end
    emit(13, "CNetGamePlayer native address", playerAddress ~= nil and playerAddress > 0, "address=" .. tostring(playerAddress))

    local isLocal = nil
    if player and player.IsLocalPlayer then isLocal = player:IsLocalPlayer() == true end
    emit(14, "Remote-player identity", isLocal == false, "isLocal=" .. tostring(isLocal))

    if player and player.GetGamerInfo then gamerInfo = player:GetGamerInfo() end
    emit(15, "GamerInfo object", gamerInfo ~= nil, "available=" .. tostring(gamerInfo ~= nil))

    local gamerName = ""
    if gamerInfo then gamerName = tostring(gamerInfo.Name or "") end
    emit(16, "GamerInfo name consistency", gamerName ~= "" and gamerName == hostName, "gamerName=" .. tostring(gamerName))

    if gamerInfo then rid = tonumber(gamerInfo.RockstarId) end
    emit(17, "Rockstar ID", rid ~= nil and rid > 0, "rid=" .. tostring(rid))

    if gamerInfo then hostKey = gamerInfo.HostKey end
    emit(18, "GamerInfo HostKey", hostKey ~= nil and tostring(hostKey) ~= "" and tostring(hostKey) ~= "0", "hostKey=" .. tostring(hostKey))

    local byRid = nil
    if rid and Players and Players.GetByRockstarId then byRid = Players.GetByRockstarId(rid) end
    emit(19, "Rockstar ID round-trip", startup.cherax_host_probe.player_id_from_object(byRid) == hostId and hostId >= 0, "resolvedPlayerId=" .. tostring(startup.cherax_host_probe.player_id_from_object(byRid)))

    local byCxn = nil
    if cxnId and Players and Players.GetByConId then byCxn = Players.GetByConId(cxnId) end
    emit(20, "Connection ID round-trip", startup.cherax_host_probe.player_id_from_object(byCxn) == hostId and hostId >= 0, "resolvedPlayerId=" .. tostring(startup.cherax_host_probe.player_id_from_object(byCxn)))

    if hostId >= 0 and Players and Players.GetIP then ipAddress = Players.GetIP(hostId) end
    local byIp = nil
    if ipAddress and Players and Players.GetByIP then byIp = Players.GetByIP(ipAddress) end
    emit(21, "Socket address round-trip", startup.cherax_host_probe.player_id_from_object(byIp) == hostId and hostId >= 0, "resolvedPlayerId=" .. tostring(startup.cherax_host_probe.player_id_from_object(byIp)))

    if hostId >= 0 and Players and Players.GetIPString then ipString = tostring(Players.GetIPString(hostId) or "") end
    emit(22, "Readable connection string", ipString ~= "", "connection=" .. (ipString ~= "" and ipString or "<empty>"))

    local country, countryCode = "", ""
    if hostId >= 0 and Players and Players.GetIPInfo then
        local info = Players.GetIPInfo(hostId)
        if info then
            country = tostring(info.country or "")
            countryCode = tostring(info.countryCode or "")
        end
    end
    emit(23, "IP metadata", country ~= "" or countryCode ~= "", "country=" .. tostring(country) .. " code=" .. tostring(countryCode))

    if hostId >= 0 and Players and Players.GetNetAddress then netAddress = Players.GetNetAddress(hostId) end
    emit(24, "NetAddress object", netAddress ~= nil, "available=" .. tostring(netAddress ~= nil))

    if netAddress then netAddressType = netAddress.Type end
    emit(25, "NetAddress type", netAddressType ~= nil, "type=" .. tostring(netAddressType))

    if hostId >= 0 and Players and Players.GetCPed then cped = Players.GetCPed(hostId) end
    emit(26, "Remote CPed object", cped ~= nil, "available=" .. tostring(cped ~= nil))

    if cped and cped.GetAddress then cpedAddress = tonumber(cped:GetAddress()) end
    emit(27, "Remote CPed native address", cpedAddress ~= nil and cpedAddress > 0, "address=" .. tostring(cpedAddress))

    local queueContainsHost = false
    local queueCount = 0
    if Players and Players.Get and ePlayerListSort and ePlayerListSort.HOST_QUEUE ~= nil then
        local rawQueue = Players.Get(ePlayerListSort.HOST_QUEUE, "")
        local queue = startup.normalize_host_queue(rawQueue)
        queueCount = #queue
        for _, entry in ipairs(queue) do
            if tonumber(entry.playerId) == hostId then queueContainsHost = true break end
        end
    end
    emit(28, "Host Queue contains Session Host", queueContainsHost, "queueCount=" .. tostring(queueCount))

    rawReasons = hostId >= 0 and startup.cherax_host_probe.raw_modder_reasons(hostId) or {}
    racReasons = hostId >= 0 and startup.rac_reasons_for_player(hostId) or {}
    local catalogKnown = 0
    local catalogHigh = 0
    local catalogAttack = 0
    local catalogLow = 0
    local catalogIgnored = 0
    for _, detectedReason in ipairs(rawReasons) do
        local category, known = startup.mod_detection.classify_reason(detectedReason)
        if known then catalogKnown = catalogKnown + 1 end
        if category == "high" or category == "battleye" then catalogHigh = catalogHigh + 1 end
        if category == "crash" or category == "kick" then catalogAttack = catalogAttack + 1 end
        if category == "low" then catalogLow = catalogLow + 1 end
        if category == "ignored" then catalogIgnored = catalogIgnored + 1 end
    end
    local hasDetectionSignals = #rawReasons > 0 or #racReasons > 0
    mark_menu_signal(hasDetectionSignals)
    emit(29, "ModderDB / RAC signals (brand-neutral)", hasDetectionSignals,
        "modderDB=" .. tostring(#rawReasons) .. " rac=" .. tostring(#racReasons) ..
        " catalogKnown=" .. tostring(catalogKnown) ..
        " high=" .. tostring(catalogHigh) ..
        " attack=" .. tostring(catalogAttack) ..
        " low=" .. tostring(catalogLow) ..
        " ignored=" .. tostring(catalogIgnored) ..
        " reasons=" .. (#rawReasons > 0 and table.concat(rawReasons, " | ") or "<none>") ..
        " racReasons=" .. (#racReasons > 0 and table.concat(racReasons, " | ") or "<none>"))

    local combined = string.lower(table.concat({ hostName, tags, table.concat(rawReasons, " "), table.concat(racReasons, " ") }, " "))
    local explicitCherax = string.find(combined, "cherax", 1, true) ~= nil
    if explicitCherax then explicitSignals = explicitSignals + 1 end
    emit(30, "Explicit Cherax token", explicitCherax, "searched=name+tags+ModderDB+RAC")

    if methodCount >= 50 then
        local objectName = ""
        if player and player.GetName then objectName = tostring(player:GetName() or "") end
        emit(31, "CNetGamePlayer.GetName consistency", objectName ~= "" and objectName == hostName, "objectName=" .. tostring(objectName))

        if player then playerInfo = player.PlayerInfo end
        emit(32, "CPlayerInfo object", playerInfo ~= nil, "available=" .. tostring(playerInfo ~= nil))

        if playerInfo then playerInfoNetData = playerInfo.NetData end
        emit(33, "CPlayerInfo NetData object", playerInfoNetData ~= nil, "available=" .. tostring(playerInfoNetData ~= nil))

        local netDataName = ""
        if playerInfoNetData then netDataName = tostring(playerInfoNetData.Name or "") end
        emit(34, "NetData name consistency", netDataName ~= "" and netDataName == hostName, "netDataName=" .. tostring(netDataName))

        local netDataRid = nil
        if playerInfoNetData then netDataRid = tonumber(playerInfoNetData.RockstarId) end
        emit(35, "NetData Rockstar ID consistency", netDataRid ~= nil and rid ~= nil and netDataRid == rid, "netDataRid=" .. tostring(netDataRid) .. " gamerInfoRid=" .. tostring(rid))

        local netDataHostKey = nil
        if playerInfoNetData then netDataHostKey = playerInfoNetData.HostKey end
        emit(36, "NetData HostKey consistency", netDataHostKey ~= nil and hostKey ~= nil and tostring(netDataHostKey) == tostring(hostKey), "netDataHostKey=" .. tostring(netDataHostKey) .. " gamerInfoHostKey=" .. tostring(hostKey))

        if playerInfo then playerInfoPed = playerInfo.PlayerPed end
        emit(37, "CPlayerInfo PlayerPed object", playerInfoPed ~= nil, "available=" .. tostring(playerInfoPed ~= nil))

        if playerInfoPed and playerInfoPed.GetAddress then playerInfoPedAddress = tonumber(playerInfoPed:GetAddress()) end
        emit(38, "PlayerPed / Players.GetCPed address consistency", playerInfoPedAddress ~= nil and cpedAddress ~= nil and playerInfoPedAddress == cpedAddress, "playerInfoPed=" .. tostring(playerInfoPedAddress) .. " playersCPed=" .. tostring(cpedAddress))

        if playerInfo then playerState = tonumber(playerInfo.PlayerState) end
        emit(39, "Player state readable", playerState ~= nil and playerState >= -1 and playerState <= 6, "playerState=" .. tostring(playerState))

        if playerInfo then playerTeam = tonumber(playerInfo.Team) end
        emit(40, "Player team readable", playerTeam ~= nil, "team=" .. tostring(playerTeam))

        if playerInfo then friendStatus = tonumber(playerInfo.FriendStatus) end
        emit(41, "Friend status readable", friendStatus ~= nil, "friendStatus=" .. tostring(friendStatus))

        if playerInfo then playerMaxHealth = tonumber(playerInfo.MaxHealth) end
        local extremeHealth = playerMaxHealth ~= nil and playerMaxHealth > 1000
        if extremeHealth then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(42, "Player max-health snapshot", playerMaxHealth ~= nil and playerMaxHealth > 0, "maxHealth=" .. tostring(playerMaxHealth) .. " extreme=" .. tostring(extremeHealth))

        if playerInfo then playerMaxArmour = tonumber(playerInfo.MaxArmour) end
        local extremeArmour = playerMaxArmour ~= nil and playerMaxArmour > 1000
        if extremeArmour then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(43, "Player max-armour snapshot", playerMaxArmour ~= nil and playerMaxArmour >= 0, "maxArmour=" .. tostring(playerMaxArmour) .. " extreme=" .. tostring(extremeArmour))

        if playerInfo then weaponDamageModifier = tonumber(playerInfo.WeaponDamageModifier) end
        local extremeWeaponDamage = weaponDamageModifier ~= nil and (weaponDamageModifier > 2.0 or weaponDamageModifier < 0.0)
        if extremeWeaponDamage then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(44, "Weapon-damage modifier snapshot", weaponDamageModifier ~= nil, "value=" .. tostring(weaponDamageModifier) .. " extreme=" .. tostring(extremeWeaponDamage))

        if playerInfo then meleeWeaponDamageModifier = tonumber(playerInfo.MeleeWeaponDamageModifier) end
        local extremeMeleeWeapon = meleeWeaponDamageModifier ~= nil and (meleeWeaponDamageModifier > 2.0 or meleeWeaponDamageModifier < 0.0)
        if extremeMeleeWeapon then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(45, "Melee-weapon modifier snapshot", meleeWeaponDamageModifier ~= nil, "value=" .. tostring(meleeWeaponDamageModifier) .. " extreme=" .. tostring(extremeMeleeWeapon))

        if playerInfo then meleeUnarmedDamageModifier = tonumber(playerInfo.MeleeUnarmedDamageModifier) end
        local extremeUnarmed = meleeUnarmedDamageModifier ~= nil and (meleeUnarmedDamageModifier > 2.0 or meleeUnarmedDamageModifier < 0.0)
        if extremeUnarmed then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(46, "Unarmed-damage modifier snapshot", meleeUnarmedDamageModifier ~= nil, "value=" .. tostring(meleeUnarmedDamageModifier) .. " extreme=" .. tostring(extremeUnarmed))

        if playerInfo then vehicleDamageModifier = tonumber(playerInfo.VehicleDamageModifier) end
        local extremeVehicleDamage = vehicleDamageModifier ~= nil and (vehicleDamageModifier > 2.0 or vehicleDamageModifier < 0.0)
        if extremeVehicleDamage then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(47, "Vehicle-damage modifier snapshot", vehicleDamageModifier ~= nil, "value=" .. tostring(vehicleDamageModifier) .. " extreme=" .. tostring(extremeVehicleDamage))

        if playerInfo then explosiveDamageModifier = tonumber(playerInfo.ExplosiveDamageModifier) end
        local extremeExplosiveDamage = explosiveDamageModifier ~= nil and (explosiveDamageModifier > 2.0 or explosiveDamageModifier < 0.0)
        if extremeExplosiveDamage then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(48, "Explosive-damage modifier snapshot", explosiveDamageModifier ~= nil, "value=" .. tostring(explosiveDamageModifier) .. " extreme=" .. tostring(extremeExplosiveDamage))

        if playerInfo then sprintMultiplier = tonumber(playerInfo.RunSprintSpeedMultiplier) end
        local extremeSprint = sprintMultiplier ~= nil and (sprintMultiplier > 1.5 or sprintMultiplier < 0.5)
        if extremeSprint then deepSignals = deepSignals + 1; mark_menu_signal(true) end
        emit(49, "Run/sprint multiplier snapshot", sprintMultiplier ~= nil, "value=" .. tostring(sprintMultiplier) .. " extreme=" .. tostring(extremeSprint))

        local pedHealth = nil
        local pedMaxHealth = nil
        local pedArmour = nil
        local pedInvincible = nil
        if cped then
            pedHealth = tonumber(cped.Health)
            pedMaxHealth = tonumber(cped.MaxHealth)
            pedArmour = tonumber(cped.Armor)
            if cped.IsInvincible then pedInvincible = cped:IsInvincible() == true end
        end
        emit(50, "Remote CPed state snapshot", cped ~= nil and pedHealth ~= nil, "health=" .. tostring(pedHealth) .. " maxHealth=" .. tostring(pedMaxHealth) .. " armour=" .. tostring(pedArmour) .. " invincible=" .. tostring(pedInvincible))
    end

    local verdict = "NO CHERAX-SPECIFIC SIGNAL"
    if explicitSignals > 0 then
        verdict = "EXPLICIT CHERAX SIGNAL FOUND"
    elseif menuSignals > 0 then
        verdict = "POSSIBLE MENU USER; BRAND UNKNOWN"
    end

    local fingerprint = table.concat({
        "rid=" .. tostring(rid),
        "hostKey=" .. tostring(hostKey),
        "cxn=" .. tostring(cxnId),
        "tags=" .. tostring(tags),
        "netType=" .. tostring(netAddressType),
        "modderDB=" .. tostring(#rawReasons),
        "catalogKnown=" .. tostring(catalogKnown),
        "catalogHigh=" .. tostring(catalogHigh),
        "catalogAttack=" .. tostring(catalogAttack),
        "rac=" .. tostring(#racReasons),
        "methods=" .. tostring(methodCount),
        "deepSignals=" .. tostring(deepSignals),
        "playerState=" .. tostring(playerState),
        "team=" .. tostring(playerTeam),
        "weaponDamage=" .. tostring(weaponDamageModifier),
        "sprintMult=" .. tostring(sprintMultiplier)
    }, " | ")

    local result = {
        hostName = hostName,
        hostId = hostId,
        rid = rid,
        explicitCherax = explicitSignals > 0,
        explicitSignals = explicitSignals,
        menuSignals = menuSignals,
        verdict = verdict,
        fingerprint = fingerprint,
        probes = probes,
        methodCount = methodCount,
        deepSignals = deepSignals
    }
    startup.cherax_host_probe.lastResult = result
    startup.s.cheraxHostProbeLastVerdict = verdict
    startup.s.cheraxHostProbeLastExplicitSignals = explicitSignals
    startup.s.cheraxHostProbeLastMenuSignals = menuSignals
    startup.s.cheraxHostProbeLastMethodCount = methodCount
    startup.s.cheraxHostProbeLastDeepSignals = deepSignals
    startup.s.cheraxHostProbeStatus = tostring(methodCount) .. " methods: " .. verdict .. " | " .. hostName
    startup.s.lobbyFinderLastVerdict = verdict
    startup.log("[Cherax Host Test] RESULT | methods=" .. tostring(methodCount) .. " | host=" .. hostName .. " | verdict=" .. verdict .. " | explicit=" .. tostring(explicitSignals) .. " | menuSignals=" .. tostring(menuSignals) .. " | deepSignals=" .. tostring(deepSignals))
    startup.log("[Cherax Host Test] FINGERPRINT | " .. fingerprint)
    startup.log("[Cherax Host Test] END | " .. tostring(methodCount) .. "/" .. tostring(methodCount) .. " completed | no kick/crash/script-event/entity interaction used")
    startup.cherax_host_probe.busy = false
    return result
end

function startup.request_cherax_host_probe(methodCount)
    local requested = tonumber(methodCount) == 50 and 50 or 30
    if startup.cherax_host_probe.busy == true or startup.cheraxHostProbeJobQueued == true then
        startup.toast("Cherax Host Test is already running.", 2500)
        return
    end
    startup.pendingCheraxHostProbe = true
    startup.pendingCheraxHostProbeMethods = requested
    startup.s.cheraxHostProbeStatus = "Queued " .. tostring(requested) .. "-method test"
    startup.toast("Queued " .. tostring(requested) .. " read-only Host checks.", 3000)
end

function startup.request_cherax_host_probe_30()
    startup.request_cherax_host_probe(30)
end

function startup.request_cherax_host_probe_50()
    startup.request_cherax_host_probe(50)
end

function startup.process_pending_cherax_host_probe()
    if startup.pendingCheraxHostProbe ~= true or startup.cheraxHostProbeJobQueued == true then return end
    local requested = tonumber(startup.pendingCheraxHostProbeMethods) == 50 and 50 or 30
    startup.pendingCheraxHostProbe = false
    startup.pendingCheraxHostProbeMethods = 30
    startup.cheraxHostProbeJobQueued = true
    Script.QueueJob(function()
        startup.cherax_host_probe.run("manual " .. tostring(requested) .. "-method button", requested)
        startup.cheraxHostProbeJobQueued = false
    end)
end

function startup.lobby_filter.mode()
    if startup.s.cheraxHostFinderEnabled == true then
        return "cherax_host"
    end
    if startup.is_prime_active_edition() and startup.s.primeMinimumPlayersEnabled == true then
        return "prime_population"
    end
    return nil
end

function startup.lobby_filter.wait_ms(serial)
    local minMs = startup.clamp_int(startup.s.lobbyFinderWaitMinMs or 15000, 15000, 30000)
    local maxMs = startup.clamp_int(startup.s.lobbyFinderWaitMaxMs or 30000, minMs, 30000)
    local span = maxMs - minMs
    if span <= 0 then return minMs end
    return minMs + ((startup.now() + ((tonumber(serial) or 0) * 7919)) % (span + 1))
end

function startup.lobby_filter.cancel(reason)
    startup.lobby_filter.sessionSerial = (tonumber(startup.lobby_filter.sessionSerial or 0) or 0) + 1
    startup.lobby_filter.running = false
    startup.lobby_filter.hopRequested = false
    startup.s.lobbyFinderStatus = tostring(reason or "Cancelled")
end

function startup.stop_lobby_finder()
    startup.s.cheraxHostFinderEnabled = false
    startup.s.primeMinimumPlayersEnabled = false
    startup.lobby_filter.cancel("Lobby Finder stopped by user")
    startup.set_feature_bool_silently(startup.h.FindCheraxHostLobbies, false)
    startup.set_feature_bool_silently(startup.h.PrimeMinimumPlayersEnabled, false)
    startup.save_config(false)
    startup.toast("Lobby Finder automation stopped.", 3000)
end

function startup.lobby_filter.hop(reason, serial)
    if serial ~= startup.lobby_filter.sessionSerial then return false end
    startup.s.cheraxHostFinderHopCount = (tonumber(startup.s.cheraxHostFinderHopCount or 0) or 0) + 1
    startup.s.lobbyFinderStatus = "Hopping: " .. tostring(reason or "Lobby rejected")
    startup.s.cheraxHostFinderStatus = startup.s.lobbyFinderStatus
    startup.log("[Lobby Finder] " .. startup.s.lobbyFinderStatus .. " | hop=" .. tostring(startup.s.cheraxHostFinderHopCount))
    startup.apply_session_type()
    startup.yield(750)
    if serial ~= startup.lobby_filter.sessionSerial then return false end
    startup.lobby_filter.hopRequested = true
    return startup.start_session(true)
end

function startup.continue_session_loaded_after_lobby_filter()
    if startup.s.waitingForRefreshedSession then
        startup.s.waitingForRefreshedSession = false
        startup.s.lastSessionFlowStatus = "Refreshed session loaded; starting advertise"
        startup.toast("Refreshed session loaded. Starting advertise routine.", 4000)
        Script.QueueJob(function()
            startup.yield(10000)
            startup.apply_session_type()
            startup.run_advertise_flow("refreshed session")
        end)
        return
    end
    if not startup.s.sessionLuaLoadCompleted then
        startup.run_session_lua_load_flow()
        return
    end
    startup.s.lastSessionFlowStatus = "Normal session loaded; starting advertise"
    Script.QueueJob(function()
        startup.yield(10000)
        startup.apply_session_type()
        startup.run_advertise_flow("session change")
    end)
end

function startup.lobby_filter.begin(forceImmediate)
    local mode = startup.lobby_filter.mode()
    if not mode then
        startup.s.lobbyFinderStatus = "No lobby filter is enabled."
        return false
    end
    if startup.lobby_filter.running == true then
        startup.s.lobbyFinderStatus = "Lobby screening is already running."
        return false
    end

    startup.lobby_filter.sessionSerial = (tonumber(startup.lobby_filter.sessionSerial or 0) or 0) + 1
    local serial = startup.lobby_filter.sessionSerial
    local waitMs = forceImmediate == true and 0 or startup.lobby_filter.wait_ms(serial)
    startup.s.lobbyFinderLastWaitMs = waitMs
    startup.lobby_filter.running = true
    startup.lobby_filter.hopRequested = false

    Script.QueueJob(function()
        if waitMs > 0 then
            startup.s.lobbyFinderStatus = "Waiting " .. startup.format_seconds(waitMs) .. " for the lobby to stabilize..."
            startup.log("[Lobby Finder] " .. startup.s.lobbyFinderStatus .. " | mode=" .. tostring(mode))
            startup.yield(waitMs)
        end
        if serial ~= startup.lobby_filter.sessionSerial then return end

        if mode == "prime_population" then
            local playerCount = startup.get_session_player_count()
            local threshold = startup.clamp_int(startup.s.primeMinimumPlayersThreshold or 20, 10, 30)
            startup.s.lobbyFinderLastInitialPlayerCount = playerCount
            if playerCount >= threshold then
                startup.s.lobbyFinderStatus = "Accepted initial lobby: " .. tostring(playerCount) .. " players. Later drops are ignored."
                startup.s.lobbyFinderLastVerdict = "Accepted " .. tostring(playerCount) .. "/" .. tostring(threshold)
                startup.log("[Lobby Finder] " .. startup.s.lobbyFinderStatus)
                startup.lobby_filter.running = false
                startup.continue_session_loaded_after_lobby_filter()
                return
            end
            startup.s.lobbyFinderLastVerdict = "Rejected " .. tostring(playerCount) .. "/" .. tostring(threshold)
            startup.lobby_filter.running = false
            startup.lobby_filter.hop("Initial lobby had only " .. tostring(playerCount) .. "/" .. tostring(threshold) .. " players", serial)
            return
        end

        local testEnabled = startup.s.lobbyFinderRunHostTestEnabled ~= false
        local timedHopEnabled = startup.s.lobbyFinderFourMinuteHopEnabled ~= false
        local sessionStartMs = startup.now() - waitMs
        local deadlineMs = sessionStartMs + 240000
        local result = nil
        local lastTestedHostId = -1

        local function accept_if_cherax(testResult)
            if not testResult or testResult.explicitCherax ~= true then return false end
            startup.lobby_filter.running = false
            startup.s.cheraxHostFinderStatus = "Cherax Host found: " .. tostring(testResult.hostName)
            startup.s.lobbyFinderStatus = startup.s.cheraxHostFinderStatus
            startup.log("[Lobby Finder] " .. startup.s.cheraxHostFinderStatus)
            startup.continue_session_loaded_after_lobby_filter()
            return true
        end

        if testEnabled then
            result = startup.cherax_host_probe.run("automatic Cherax Host Finder", 30)
            if serial ~= startup.lobby_filter.sessionSerial then return end
            lastTestedHostId = tonumber(result and result.hostId) or -1
            if accept_if_cherax(result) then return end
        else
            startup.s.cheraxHostProbeStatus = "Automatic 30-method test is OFF"
        end

        if not timedHopEnabled then
            startup.lobby_filter.running = false
            if testEnabled then
                local verdict = result and result.verdict or "No diagnostic result"
                startup.lobby_filter.hop("Host test was " .. tostring(verdict), serial)
            else
                startup.s.lobbyFinderStatus = "No automatic host test or 4-minute hop is enabled."
                startup.continue_session_loaded_after_lobby_filter()
            end
            return
        end

        while serial == startup.lobby_filter.sessionSerial do
            local nowMs = startup.now()
            local remainingMs = deadlineMs - nowMs
            if remainingMs <= 0 then break end
            startup.s.lobbyFinderStatus = "No Cherax signal. Hopping in " .. startup.format_seconds(remainingMs) .. "."

            if testEnabled then
                local _, currentHostId = startup.get_session_host_name()
                currentHostId = tonumber(currentHostId) or -1
                if currentHostId >= 0 and currentHostId ~= lastTestedHostId then
                    startup.s.lobbyFinderStatus = "Session Host changed. Running host test..."
                    result = startup.cherax_host_probe.run("Session Host changed during 4-minute finder window", 30)
                    if serial ~= startup.lobby_filter.sessionSerial then return end
                    lastTestedHostId = tonumber(result and result.hostId) or currentHostId
                    if accept_if_cherax(result) then return end
                end
            end

            startup.yield(math.min(5000, math.max(250, remainingMs)))
        end

        if serial ~= startup.lobby_filter.sessionSerial then return end
        if testEnabled then
            result = startup.cherax_host_probe.run("final test before 4-minute lobby hop", 30)
            if serial ~= startup.lobby_filter.sessionSerial then return end
            if accept_if_cherax(result) then return end
        end
        startup.lobby_filter.running = false
        startup.lobby_filter.hop("4-minute window ended without a Cherax signal", serial)
    end)
    return true
end

function startup.start_lobby_finder_now()
    startup.s.cheraxHostFinderEnabled = true
    startup.s.showPrimeHostHud = true
    startup.s.sessionInfoHudEnabled = true
    startup.s.playerModUiEnabled = true
    startup.set_feature_bool_silently(startup.h.FindCheraxHostLobbies, true)
    startup.set_feature_bool_silently(startup.h.ShowPrimeHostHud, true)
    startup.set_feature_bool_silently(startup.h.SessionInfoHudToggle, true)
    startup.set_feature_bool_silently(startup.h.PlayerModUiToggle, true)
    startup.resolve_session_type()
    startup.save_config(false)
    startup.lobby_filter.cancel("Starting current-lobby evaluation")
    startup.lobby_filter.begin(false)
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- session flow
-- note: routes post-join lua loading, refresh, and matchmaking actions.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.run_session_lua_load_flow()
    if not startup.s.autoLoadLuaFilesOnSession then
        startup.s.lastSessionFlowStatus = "Session Lua loading OFF"
        return
    end
    if startup.s.sessionLuaLoadCompleted then
        startup.s.lastSessionFlowStatus = "Session Lua loading already completed"
        return
    end
    if startup.s.sessionLuaLoadRunning then
        startup.s.lastSessionFlowStatus = "Session Lua loading already running"
        return
    end
    startup.s.sessionLuaLoadRunning = true
    Script.QueueJob(function()
        startup.s.lastSessionFlowStatus = "Waiting before loading Lua files"
        startup.toast("Session loaded. Waiting " .. startup.format_seconds(startup.s.sessionLuaLoadDelayMs) .. " before loading LuaContent files.", 6000)
        startup.yield(startup.s.sessionLuaLoadDelayMs)
        startup.s.lastSessionFlowStatus = "Loading Lua files"
        startup.run_enabled_lua_files()
        startup.s.sessionLuaLoadCompleted = true
        startup.s.sessionLuaLoadRunning = false
        if startup.s.autoRefreshSessionAfterLuaLoad and not startup.s.refreshSessionAfterLuaAttempted then
            startup.s.refreshSessionAfterLuaAttempted = true
            startup.s.waitingForRefreshedSession = true
            startup.s.lastSessionFlowStatus = "Waiting 5 seconds before refreshing session"
            startup.toast("All enabled Lua files staged. Waiting 5 seconds, then starting another session because the optional second-session toggle is ON.", 5000)
            startup.yield(startup.s.delayAfterAllLuaLoadedMs)
            startup.s.lastSessionFlowStatus = "Refreshing session after Lua load"
            startup.apply_session_type()
            startup.yield(1000)
            startup.start_session(true)
        else
            startup.s.lastSessionFlowStatus = "Lua load complete; starting advertise"
            startup.run_advertise_flow("session Lua load complete")
        end
    end)
end

function startup.on_session_loaded()
    if not startup.s.initialized then return end
    local now = startup.now()
    local lobbyMode = startup.lobby_filter and startup.lobby_filter.mode and startup.lobby_filter.mode() or nil
    local effectiveDebounceMs = lobbyMode and 5000 or startup.s.sessionChangeDebounceMs
    if now - startup.s.lastSessionChangeMs < effectiveDebounceMs then
        startup.s.lastSessionFlowStatus = "Ignored duplicate session event"
        startup.log("Ignored duplicate session change event due to debounce.")
        return
    end
    startup.s.lastSessionChangeMs = now
    startup.modder_hud_clear()
    startup.session_activity.knownPlayers = {}
    if startup.country_filter then
        startup.country_filter.seen = {}
        startup.country_filter.pending = {}
        startup.country_filter.joinedAt = {}
        startup.country_filter.request_rescan("session-change")
    end
    if startup.s.showNatTypeHud then
        if startup.is_prime_active_edition() then
            startup.nat_scan.autoRetryCount = 0
            startup.nat_scan.nextAutoRetryMs = startup.now() + 5000
            startup.nat_scan.localPlayerId = nil
            startup.nat_scan.localPlayerSource = "Session changed; resolving local player"
            startup.nat_scan.nextLocalPlayerProbeMs = 0
            startup.request_nat_pattern_scan("Prime session-change", true)
        else
            startup.request_nat_pattern_scan("session-change", false)
        end
    end
    startup.toast("Session change detected.", 2500)
    startup.s.advertiseFlowSerial = (tonumber(startup.s.advertiseFlowSerial or 0) or 0) + 1
    startup.s.advertiseRunning = false
    startup.s.advertiseSmartActive = false
    startup.s.advertiseCompletedForSession = false
    startup.s.advertiseStopRequested = false
    startup.s.advertiseCountEscalated = false
    startup.s.lastAdvertiseStatus = "Session changed"
    if startup.lobby_filter and startup.lobby_filter.mode and startup.lobby_filter.mode() then
        startup.s.lastSessionFlowStatus = "Lobby Finder screening new session"
        startup.lobby_filter.cancel("Session changed; restarting lobby screening")
        startup.lobby_filter.begin(false)
        return
    end
    startup.continue_session_loaded_after_lobby_filter()
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- player feature links
-- note: attaches one clean custom action beside cherax player controls.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.get_player_feature_by_name_safe(name, playerIndex)
    if not FeatureMgr or not FeatureMgr.GetFeatureByName then return nil end
    local feature = nil
    feature = FeatureMgr.GetFeatureByName(name, playerIndex)
    return feature
end

function startup.clear_render_link(anchorFeature, childFeature)
    if not anchorFeature or not childFeature then return end
    if anchorFeature.ClearRenderBefore then anchorFeature:ClearRenderBefore(childFeature) end
    if anchorFeature.ClearRenderAfter then anchorFeature:ClearRenderAfter(childFeature) end
    if anchorFeature.RemoveRenderBefore then
        for _ = 1, 12 do if anchorFeature:RemoveRenderBefore(childFeature) ~= true then break end end
    end
    if anchorFeature.RemoveRenderAfter then
        for _ = 1, 12 do if anchorFeature:RemoveRenderAfter(childFeature) ~= true then break end end
    end
end

function startup.attach_render_after_once(anchorFeature, childFeature)
    if not anchorFeature or not childFeature or not anchorFeature.AddRenderAfter then return false end
    startup.clear_render_link(anchorFeature, childFeature)
    anchorFeature:AddRenderAfter(childFeature)
    return true
end

function startup.clear_player_feature_render_links(childName, anchorNames)
    if not childName or type(anchorNames) ~= "table" then return end
    for playerIndex = 0, 31 do
        local childFeature = startup.get_player_feature_by_name_safe(childName, playerIndex)
        if childFeature then
            for _, anchorName in ipairs(anchorNames) do
                local anchorFeature = startup.get_player_feature_by_name_safe(anchorName, playerIndex)
                if anchorFeature then
                    startup.clear_render_link(anchorFeature, childFeature)
                end
            end
        end
    end
end

