}
startup.nuke_join_kick.placement_anchor_names = {
    "Smart Kick",
    "Smart kick",
    "SMART KICK"
}
startup.nuke_join_kick.saved_players_selector_names = {
    "Saved Players",
    "Saved Player",
    "Player Tracker",
    "Tracked Players",
    "SCAPI Saved Players"
}
startup.nuke_join_kick.block_join_names = {
    "Block Join",
    "Block Join Enabled",
    "Prevent Join",
