        startup.section_title("Status")
        startup.subtle_text("Startup " .. tostring(startup.version) .. "  |  Build " .. tostring(startup.build_number))
        ImGui.Separator()
        if ImGui.BeginTable("StartupStatusSummary", 4, ImGuiTableFlags.SizingStretchSame) then
            ImGui.TableNextRow()
            ImGui.TableSetColumnIndex(0)
            startup.render_status_metric("SESSION", tostring(startup.s.sessionType), 0.42, 0.82, 1.00,
                "The public-session type Startup currently plans to use.")
            ImGui.TableSetColumnIndex(1)
            startup.render_status_metric("PLAYERS", tostring(startup.get_session_player_count()), 0.30, 1.00, 0.45,
                "Current connected-player count reported by the session.")
            ImGui.TableSetColumnIndex(2)
            startup.render_status_metric("THEME", tostring(startup.s.themeFile), 0.72, 0.42, 1.00,
                "The selected ClickGUI theme file.")
            ImGui.TableSetColumnIndex(3)
            startup.render_status_metric("LUA SPACING", startup.format_seconds(startup.s.luaDelayBetweenFilesMs), 1.00, 0.78, 0.18,
                "The master fallback wait after one enabled Lua runs and before the next begins.")
            ImGui.EndTable()
        end
        ImGui.Separator()
        startup.status_line("Lua", startup.s.lastLuaStatus, 0.42, 0.82, 1.00,
            "Most recent Lua queue activity.")
        startup.status_line("Session", startup.s.lastSessionFlowStatus, 0.30, 1.00, 0.45,
            "Most recent session-start or session-Lua flow activity.")
        startup.status_line("Advertise", startup.s.lastAdvertiseStatus, 0.72, 0.42, 1.00,
            "Most recent smart-advertise activity.")
        startup.status_line("Last", startup.s.lastStatus, 0.72, 0.72, 0.72,
            "Most recent general Startup status message.")
        ClickGUI.EndCustomChildWindow()
    end
end

