                ClickGUI.RenderFeature(startup.h.AdvertiseAllRegionsByTime)
                ClickGUI.RenderFeature(startup.h.AdvertiseManualRegion)
                if startup.normalize_advertise_region_schedule_mode(startup.s.advertiseRegionAutoScheduleMode) == "Manually Pick a Region" then
                    startup.subtle_text("Choose the region Startup should keep active:")
                    ClickGUI.RenderFeature(startup.h.AdvertiseManualRegionSelection)
                end
                startup.render_advertise_region_control()
                ClickGUI.RenderFeature(startup.h.ShowAdvertiseRegionHud)
                startup.text_colored_wrapped(1.00, 0.78, 0.18, 1.00, "Enhanced advertising can fill more slowly than Legacy.")
            else
                startup.subtle_text_wrapped("Legacy advertising is managed automatically.")
            end
            ClickGUI.RenderFeature(startup.h.RunAdvertiseFlowNow)
            ClickGUI.RenderFeature(startup.h.StopAdvertiseNow)
            startup.subtle_text_wrapped("Players: " .. tostring(startup.get_session_player_count()) .. "  |  " .. tostring(startup.s.lastAdvertiseStatus or "Idle"))
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.TableSetColumnIndex(1)
        if ClickGUI.BeginCustomChildWindow("Matchmaking") then
            startup.section_title("Matchmaking")
            local currentNat = startup.get_local_nat_type()
            startup.status_line("NAT", tostring(currentNat or "Unknown"), 0.42, 0.82, 1.00)
            if startup.is_prime_active_edition() then
                startup.subtle_text("Prime NAT HUD defaults ON and retries detection after GTA Online is ready.")
            end
            ClickGUI.RenderFeature(startup.h.ShowNatTypeHud)
            ClickGUI.RenderFeature(startup.h.NatTypeOverride)
            ClickGUI.RenderFeature(startup.h.NatTypeRescan)
            startup.strong_red_warning("NAT: OPEN = most potential players. MODERATE = some players. STRICT = fewer players.")
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.EndTable()
    end

    -- Lobby Finder UI is intentionally hidden for the current public release.
    -- Its features, worker, tests, and session-hopping backend remain registered for later use.
    startup.render_player_population_panel()

    if ClickGUI.BeginCustomChildWindow("Country Filter Summary") then
        startup.section_title("Country Filter")
        if startup.is_prime_active_edition() then startup.subtle_text("Prime default: OFF. Session Host is never removed by Country Filter.") end
        ClickGUI.RenderFeature(startup.h.CountryFilterEnabled)
        startup.render_color_button("Select All", "Green", "Allow all countries.", function() startup.queue_country_filter_bulk_action("select_all") end, 115)
        ImGui.SameLine(); startup.render_color_button("Deselect All", "Red", "Block all listed countries.", function() startup.queue_country_filter_bulk_action("deselect_all") end, 125)
        ImGui.SameLine(); startup.render_color_button("Default", "Blue", "Restore edition defaults and allow all countries.", function() startup.queue_country_filter_bulk_action("default") end, 100)
        local blocked = startup.country_filter.blocked_country_labels()
        startup.subtle_text(#blocked == 0 and "Blocked: None" or ("Blocked: " .. (#blocked > 8 and (tostring(#blocked).." countries") or table.concat(blocked, ", "))))
        ClickGUI.EndCustomChildWindow()
    end
    local open = false
    if ImGui.CollapsingHeader then
        open = ImGui.CollapsingHeader("Country Filter") == true
    elseif ImGui.Button then
        startup.s.countryFilterListOpen = startup.s.countryFilterListOpen == true
        if ImGui.Button((startup.s.countryFilterListOpen and "▼" or "▶") .. "  Country Filter", -1, 34) == true then startup.s.countryFilterListOpen = not startup.s.countryFilterListOpen end
        open = startup.s.countryFilterListOpen == true
    else
        open = true
    end
    if open and ClickGUI.BeginCustomChildWindow("Country Filter") then
        ClickGUI.RenderFeature(startup.h.CountryFilterUnknownAllowed)
        ClickGUI.RenderFeature(startup.h.CountryFilterOtherAllowed)
        if ImGui.BeginTable("StartupCountryFilterSessionTable", 4, ImGuiTableFlags.SizingStretchSame) then
            for index, countryEntry in ipairs(startup.country_filter_countries or {}) do
                if ((index-1)%4)==0 then ImGui.TableNextRow() end
                ImGui.TableSetColumnIndex((index-1)%4)
                ClickGUI.RenderFeature(startup.h["CountryAllow_"..tostring(countryEntry.key)])
            end
            ImGui.EndTable()
        end
        startup.strong_red_warning("WARNING: Messing with Country Filter can cause a lot less players to join you.")
        ClickGUI.EndCustomChildWindow()
    end

    startup.render_defense()
end

function startup.get_parent_folder(path)
    local text = tostring(path or "")
    return text:match("^(.*)[/\\][^/\\]+$") or ""
end

function startup.get_friendly_folder_label(path)
    local parent = startup.get_parent_folder(path)
    if parent == startup.lua_content_dir then return "LuaContent" end
    if parent == startup.lua_dir then return "Lua" end
    local name = parent:match("[^/\\]+$")
    if name and name ~= "" then return name end
    return parent ~= "" and parent or "Unknown Folder"
end

function startup.text_colored(r, g, b, a, text)
    if ImGui and ImGui.TextColored then
        ImGui.TextColored(r, g, b, a, tostring(text or ""))
    else
        ImGui.Text(tostring(text or ""))
    end
end

function startup.text_colored_wrapped(r, g, b, a, text)
    text = tostring(text or "")
    local pushed = false
    if ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Text ~= nil then
        ImGui.PushStyleColor(ImGuiCol.Text, tonumber(r or 1.0) or 1.0, tonumber(g or 1.0) or 1.0,
            tonumber(b or 1.0) or 1.0, tonumber(a or 1.0) or 1.0)
        pushed = true
    end
    if ImGui and ImGui.TextWrapped then ImGui.TextWrapped(text)
    elseif ImGui and ImGui.Text then ImGui.Text(text)
    else startup.text_colored(r, g, b, a, text) end
    if pushed and ImGui and ImGui.PopStyleColor then ImGui.PopStyleColor(1) end
end

function startup.subtle_text_wrapped(text)
    startup.text_colored_wrapped(0.72, 0.72, 0.72, 1.00, tostring(text or ""))
end

function startup.section_title(text)
    startup.text_colored(0.25, 1.00, 0.35, 1.00, tostring(text or ""))
end

function startup.subtle_text(text)
    startup.text_colored(0.72, 0.72, 0.72, 1.00, tostring(text or ""))
end

function startup.warn_text(text)
    startup.text_colored(1.00, 0.78, 0.25, 1.00, tostring(text or ""))
end

function startup.strong_red_warning(text)
    text = tostring(text or "")
    local scaled = ImGui and ImGui.SetWindowFontScale
    if scaled then ImGui.SetWindowFontScale(1.06) end
    local pushed = false
    if ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Text ~= nil then
        ImGui.PushStyleColor(ImGuiCol.Text, 1.00, 0.20, 0.16, 1.00)
        pushed = true
    end
    if ImGui and ImGui.TextWrapped then
        ImGui.TextWrapped(text)
    elseif ImGui and ImGui.Text then
        ImGui.Text(text)
    else
        startup.text_colored(1.00, 0.20, 0.16, 1.00, text)
    end
    if pushed and ImGui and ImGui.PopStyleColor then ImGui.PopStyleColor(1) end
    if scaled then ImGui.SetWindowFontScale(1.0) end
end

function startup.wrap_tooltip_text(text, maxChars)
    text = tostring(text or "")
    maxChars = tonumber(maxChars or 54) or 54
    local lines = {}
    for sourceLine in (text .. "\n"):gmatch("(.-)\n") do
        local line = ""
        for word in sourceLine:gmatch("%S+") do
            if line == "" then
                line = word
            elseif #line + #word + 1 <= maxChars then
                line = line .. " " .. word
            else
                lines[#lines + 1] = line
                line = word
            end
        end
        if line ~= "" then lines[#lines + 1] = line end
        if sourceLine == "" and #lines > 0 then lines[#lines + 1] = "" end
    end
    return table.concat(lines, "\n"):gsub("\n$", "")
end

function startup.hover_help(text)
    if not text or text == "" or not ImGui or not ImGui.IsItemHovered or ImGui.IsItemHovered() ~= true then return false end
    local tooltip = startup.wrap_tooltip_text(text, 54)
    if ImGui.SetTooltip then
        ImGui.SetTooltip(tooltip)
    elseif ImGui.BeginTooltip and ImGui.EndTooltip then
        ImGui.BeginTooltip()
        if ImGui.Text then ImGui.Text(tooltip) end
        ImGui.EndTooltip()
    end
    return true
end
