function startup.render_lua_startup_list()
    local lastFolder = nil
    for _, entry in ipairs(startup.s.luaFiles or {}) do
        local folderLabel = startup.get_friendly_folder_label(entry.path)
        if folderLabel ~= lastFolder then
            if lastFolder ~= nil and ImGui.Separator then ImGui.Separator() end
            startup.render_green_folder_header(folderLabel)
            lastFolder = folderLabel
        end
        ClickGUI.RenderFeature(entry.hash)
        if ImGui.Button("Delay##lua_select_" .. tostring(entry.index)) then
            startup.s.selectedLuaFilePath = entry.path
            startup.save_config(false)
        end
        if tostring(startup.s.selectedLuaFilePath or "") == tostring(entry.path) then
            ImGui.SameLine()
            startup.subtle_text("Editing")
        end
    end
end

function startup.render_selected_lua_delay()
    local entry = startup.get_lua_file_entry(startup.s.selectedLuaFilePath)
    if not entry then
        startup.subtle_text("Select a Lua file from the right panel.")
        return
    end
    startup.section_title(entry.name)
    ImGui.Text("Startup: " .. startup.bool_text(startup.s.luaFileStates[entry.path] == true))
    ImGui.Text("")
    local custom = startup.is_lua_file_delay_overridden(entry.path)
    local effectiveMs = startup.get_lua_file_delay_ms(entry.path)
    ImGui.Text("Wait after this file: " .. startup.format_seconds(effectiveMs))
    if custom then
        startup.subtle_text("Using a script-specific delay")
        if ImGui.Button("Use Master Delay##lua_delay_master") then
            startup.set_lua_file_delay_override(entry.path, false)
        end
    else
        startup.subtle_text("Using the master delay")
        if ImGui.Button("Use Custom Delay##lua_delay_custom") then
            startup.set_lua_file_delay_override(entry.path, true)
        end
    end
    if startup.is_lua_file_delay_overridden(entry.path) then
        ImGui.Text("")
        if ImGui.Button("-5s##lua_delay_minus") then
            startup.set_lua_file_delay_ms(entry.path, effectiveMs - 5000)
        end
        ImGui.SameLine()
        ImGui.Text(startup.format_seconds(startup.get_lua_file_delay_ms(entry.path)))
        ImGui.SameLine()
        if ImGui.Button("+5s##lua_delay_plus") then
            startup.set_lua_file_delay_ms(entry.path, effectiveMs + 5000)
        end
    end
end

