function startup.render_defense()
    local open = false
    if ImGui.CollapsingHeader then
        open = ImGui.CollapsingHeader("Protection & Player History") == true
    elseif ImGui.Button then
        startup.s.protectionSectionOpen = startup.s.protectionSectionOpen == true
        if ImGui.Button((startup.s.protectionSectionOpen and "▼" or "▶") .. "  Protection & Player History", -1, 34) == true then startup.s.protectionSectionOpen = not startup.s.protectionSectionOpen end
        open = startup.s.protectionSectionOpen == true
    else
        open = true
    end
    if not open then return end
    if ImGui.BeginTable("StartupProtectionTable", 2, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        if ClickGUI.BeginCustomChildWindow("Battleye Detection") then
            startup.section_title("Battleye Detection")
            ClickGUI.RenderFeature(startup.h.BattleyeAutoBlockEnabled)
            ClickGUI.RenderFeature(startup.h.BattleyeFallbackDelaySlider)
            ClickGUI.RenderFeature(startup.h.SaveRidBattleye)
            ClickGUI.RenderFeature(startup.h.IgnoreFriendsBattleye)
            if startup.is_prime_active_edition() then startup.warn_text("Prime: detection is display/log only. No automatic removal.") end
            ClickGUI.EndCustomChildWindow()
        end
        if ClickGUI.BeginCustomChildWindow("Crash & Kick Detection") then
            startup.section_title("Crash & Kick Detection")
            ClickGUI.RenderFeature(startup.h.NukeJoinKickEnabled)
            ClickGUI.RenderFeature(startup.h.AutoKickCrashAttackers)
            ClickGUI.RenderFeature(startup.h.AutoKickKickAttackers)
            ClickGUI.RenderFeature(startup.h.LogUnverifiedKickReactions)
            ClickGUI.RenderFeature(startup.h.SaveRidCrash)
            ClickGUI.RenderFeature(startup.h.IgnoreFriendsCrash)
            startup.subtle_text("Crash attacks use Block Join & Kick. Generic Kick / Vote Kick reactions are passive diagnostics by default.")
            startup.warn_text("A kick protection reaction does not prove the player is a modder. Experimental auto-removal requires two separated, non-duplicate reactions.")
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.TableSetColumnIndex(1)
        if ClickGUI.BeginCustomChildWindow("Modder Detection") then
            startup.section_title("Modder Detection")
            ClickGUI.RenderFeature(startup.h.ModDetectionIncludeRac)
            ClickGUI.RenderFeature(startup.h.ModDetectionIncludeExplosions)
            ClickGUI.RenderFeature(startup.h.ModDetectionIncludeKnownLowConfidence)
            ClickGUI.RenderFeature(startup.h.IgnoreFriendsModder)
            startup.subtle_text("Accepted modder detections are saved locally by RID automatically.")
            startup.warn_text("Most RAC detections do not mean the player is modding.")
            startup.subtle_text("Embedded catalog: 83 known Cherax detection labels.")
            startup.subtle_text("All 83 confirmed catalog flags are shown as modder evidence.")
            startup.subtle_text("Flags describe detected behavior. They do not prove which menu a player uses.")
            if startup.is_prime_active_edition() then startup.subtle_text("Prime: normal modder flags are informational only.") end
            ClickGUI.EndCustomChildWindow()
        end
        if ClickGUI.BeginCustomChildWindow("Saved Players / RID History") then
            startup.section_title("Saved Players / RID History")
            ClickGUI.RenderFeature(startup.h.BlockRidJoinsEnabled)
            ClickGUI.RenderFeature(startup.h.IgnoreFriendsRidJoins)
            startup.subtle_text("Saved locally: "..tostring(startup.s.ridHistoryCount or 0).." players / RIDs")
            startup.subtle_text(tostring(startup.s.ridHistoryLastStatus or "Local RID history ready."))
            startup.subtle_text("Reasons include Battleye, confirmed kick/crash attempts, mod detections, and manual Nuke actions.")
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.EndTable()
