startup.start_session_hotkey_options = startup.start_session_hotkey_options or (function()
    local options = {
        { name = "Disabled", code = 0x00 },
        { name = "Pause / Break", code = 0x13 },
        { name = "Insert", code = 0x2D },
        { name = "Delete", code = 0x2E },
        { name = "Home", code = 0x24 },
        { name = "End", code = 0x23 },
        { name = "Page Up", code = 0x21 },
        { name = "Page Down", code = 0x22 },
        { name = "Scroll Lock", code = 0x91 },
        { name = "Num Lock", code = 0x90 },
        { name = "Caps Lock", code = 0x14 },
        { name = "Escape", code = 0x1B },
        { name = "Space", code = 0x20 },
        { name = "Enter", code = 0x0D },
        { name = "Tab", code = 0x09 },
        { name = "Backspace", code = 0x08 },
        { name = "Left Shift", code = 0xA0 },
        { name = "Right Shift", code = 0xA1 },
        { name = "Left Ctrl", code = 0xA2 },
        { name = "Right Ctrl", code = 0xA3 },
        { name = "Left Alt", code = 0xA4 },
        { name = "Right Alt", code = 0xA5 },
        { name = "Left Arrow", code = 0x25 },
        { name = "Up Arrow", code = 0x26 },
        { name = "Right Arrow", code = 0x27 },
        { name = "Down Arrow", code = 0x28 },
    }
    for i = 1, 12 do options[#options + 1] = { name = "F" .. tostring(i), code = 0x6F + i } end
    for i = 0, 9 do options[#options + 1] = { name = "Numpad " .. tostring(i), code = 0x60 + i } end
    options[#options + 1] = { name = "Numpad *", code = 0x6A }
    options[#options + 1] = { name = "Numpad +", code = 0x6B }
    options[#options + 1] = { name = "Numpad -", code = 0x6D }
    options[#options + 1] = { name = "Numpad .", code = 0x6E }
    options[#options + 1] = { name = "Numpad /", code = 0x6F }
    for i = 0, 9 do options[#options + 1] = { name = tostring(i), code = 0x30 + i } end
    for i = 0, 25 do options[#options + 1] = { name = string.char(65 + i), code = 0x41 + i } end
    return options
end)()

function startup.get_start_session_hotkey_option(code)
    code = tonumber(code or 0) or 0
    for index, option in ipairs(startup.start_session_hotkey_options or {}) do
        if tonumber(option.code or -1) == code then return option, index end
    end
    return (startup.start_session_hotkey_options or {})[2], 2
end

function startup.clear_feature_hotkeys(feature, hash)
    if feature and feature.ClearHotkeys then
        feature:ClearHotkeys()
        return true
    end
    if HotKeyMgr and HotKeyMgr.GetHotKeys and HotKeyMgr.RemoveHotkey then
        local keys = HotKeyMgr.GetHotKeys(hash)
        for _, key in pairs(type(keys) == "table" and keys or {}) do HotKeyMgr.RemoveHotkey(hash, key) end
        return true
    end
    return false
end

function startup.apply_start_session_hotkey(showToast)
    if not startup.h.StartSession then return false end
    local feature = FeatureMgr and FeatureMgr.GetFeature and FeatureMgr.GetFeature(startup.h.StartSession) or nil
    if not feature then
        startup.s.startSessionHotkeyLastStatus = "Start Session feature unavailable"
        return false
    end
    startup.clear_feature_hotkeys(feature, startup.h.StartSession)
    local code = startup.clamp_int(startup.s.startSessionHotkeyKeyCode or 0x13, 0, 255)
    local option = startup.get_start_session_hotkey_option(code)
    startup.s.startSessionHotkeyName = option and option.name or tostring(code)
    if code == 0 then
        startup.s.startSessionHotkeyLastStatus = "Disabled"
        if showToast then startup.toast("Start Session hotkey disabled.", 2500) end
        return true
    end
    local applied = false
    if feature.AddHotKey then
        feature:AddHotKey(code)
        applied = true
    elseif HotKeyMgr and HotKeyMgr.AddHotkey then
        HotKeyMgr.AddHotkey(startup.h.StartSession, code)
        applied = true
    end
    if applied then
        startup.s.startSessionHotkeyLastStatus = "Start Session: " .. tostring(startup.s.startSessionHotkeyName)
        if showToast then startup.toast("Start Session hotkey: " .. tostring(startup.s.startSessionHotkeyName), 2500) end
    else
        startup.s.startSessionHotkeyLastStatus = "Could not apply " .. tostring(startup.s.startSessionHotkeyName)
        if showToast then startup.error(startup.s.startSessionHotkeyLastStatus) end
    end
    return applied
end

function startup.render_start_session_hotkey_config()
    if not ClickGUI.BeginCustomChildWindow("Start Session Hotkey") then return end
    startup.text_colored(1.00, 0.55, 0.12, 1.00, "START SESSION HOTKEY")
    startup.subtle_text("Default: Pause / Break")
    ImGui.Separator()
    local currentOption, currentIndex = startup.get_start_session_hotkey_option(startup.s.startSessionHotkeyKeyCode)
    local opened = ImGui.BeginCombo and ImGui.BeginCombo("Keyboard Key", tostring(currentOption and currentOption.name or "Pause / Break")) == true
    startup.hover_help("Choose the one keyboard key that triggers Start Session. The selection applies immediately and saves automatically.")
    if opened then
        for index, option in ipairs(startup.start_session_hotkey_options or {}) do
            if ImGui.Selectable(tostring(option.name), index == currentIndex) == true then
                startup.s.startSessionHotkeyKeyCode, startup.s.startSessionHotkeyName = option.code, option.name
                startup.apply_start_session_hotkey(false)
                startup.save_config(false)
                currentOption, currentIndex = option, index
            end
        end
        if ImGui.EndCombo then ImGui.EndCombo() end
    end
    ImGui.Text("")
    if tonumber(startup.s.startSessionHotkeyKeyCode or 0) == 0 then
        startup.warn_text("Current: Disabled")
    else
        startup.text_colored(0.30, 1.00, 0.45, 1.00, "Current: " .. tostring(startup.s.startSessionHotkeyName or "Pause / Break"))
    end
    startup.subtle_text(tostring(startup.s.startSessionHotkeyLastStatus or "Not applied yet"))
    startup.render_color_button("Reset to Pause / Break", "Gold", "Restores Pause / Break as the Start Session hotkey and saves it now.", function()
        startup.s.startSessionHotkeyKeyCode, startup.s.startSessionHotkeyName = 0x13, "Pause / Break"
        startup.apply_start_session_hotkey(true)
        startup.save_config(false)
    end, -1)
    ClickGUI.EndCustomChildWindow()
end

function startup.render_config()
    startup.render_start_session_hotkey_config()
    if ImGui.BeginTable("StartupConfigTable", 2, ImGuiTableFlags.SizingStretchSame) then
        ImGui.TableNextRow()
        ImGui.TableSetColumnIndex(0)
        if ClickGUI.BeginCustomChildWindow("Storage") then
            ImGui.Text("Config:")
