            ImGui.TextWrapped(startup.storage_dir)
            ImGui.Text("")
            ImGui.Text("Themes:")
            ImGui.TextWrapped(startup.menu_root .. "\\Theme\\ClickGUI")
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.TableSetColumnIndex(1)
        if ClickGUI.BeginCustomChildWindow("Settings") then
            ClickGUI.RenderFeature(startup.h.SaveConfig)
            ClickGUI.RenderFeature(startup.h.LoadConfig)
            ClickGUI.RenderFeature(startup.h.SessionRoutingMode)
            ClickGUI.RenderFeature(startup.h.CompactPinnedStartupTab)
            ClickGUI.RenderFeature(startup.h.ShowStatusPanel)
            ClickGUI.RenderFeature(startup.h.ShowTipsPanel)
            ClickGUI.RenderFeature(startup.h.VerboseStartupLogs)
            ClickGUI.EndCustomChildWindow()
        end
        ImGui.EndTable()
    end

    if ClickGUI.BeginCustomChildWindow("Cherax Settings Profile") then
        startup.section_title("Cherax Settings Profile")
        startup.subtle_text("Choose the saved Cherax settings JSON Startup should load. No specific filename is required.")
        ImGui.Separator()
        local profiles = startup.s.settingsProfiles or {}
        local current = tostring(startup.s.settingsFile or "")
        local preview = current ~= "" and current or "Select saved settings..."
        local openedProfiles = ImGui.BeginCombo and ImGui.BeginCombo("Saved Settings", preview) == true
        if openedProfiles then
            for _, profile in ipairs(profiles) do
                local selected = startup.settings_profile_names_match(profile, current)
                if ImGui.Selectable(tostring(profile), selected) == true then
                    startup.select_settings_profile(profile, true)
                    current = tostring(profile)
                end
            end
            if ImGui.EndCombo then ImGui.EndCombo() end
        end
        if #profiles == 0 then
            if current ~= "" then
                startup.text_colored(0.35, 1.00, 0.45, 1.00, "Current profile: " .. current)
                startup.subtle_text("Startup can still load this profile even when Cherax does not provide a saved-profile list.")
            else
                startup.text_colored(1.00, 0.78, 0.25, 1.00, tostring(startup.s.settingsProfilesStatus or "No saved settings profiles found."))
            end
        else
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Selected: " .. (current ~= "" and current or "None"))
            startup.subtle_text(tostring(startup.s.settingsProfilesStatus or ""))
        end
        ClickGUI.RenderFeature(startup.h.RefreshSettingsProfiles)
        ClickGUI.RenderFeature(startup.h.ApplySettingsNow)
        ClickGUI.EndCustomChildWindow()
    end

    if ClickGUI.BeginCustomChildWindow("Support & Diagnostics") then
        startup.text_colored(1.00, 0.78, 0.25, 1.00, "SUPPORT & DIAGNOSTICS")
        startup.text_colored(0.35, 1.00, 0.45, 1.00, "Automatic diagnostics: Enabled")
        startup.subtle_text("Runtime state is refreshed into Startup\\Support\\SUPPORT_INFO.txt for support captures.")
        ImGui.Separator()
        ClickGUI.RenderFeature(startup.h.CreateSupportZip)
        ClickGUI.RenderFeature(startup.h.CopySupportZipPath)
        ClickGUI.RenderFeature(startup.h.OpenSupportDiscord)
        ImGui.Text("")

        local supportStatus = startup.get_compact_support_zip_status()
        if supportStatus == "Created! Path copied." or supportStatus == "Created! Path not copied." then
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Support ZIP: " .. tostring(supportStatus))
        elseif string.find(tostring(supportStatus), "Creating", 1, true) then
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "Support ZIP: " .. tostring(supportStatus))
        elseif string.find(tostring(supportStatus), "Failed", 1, true) then
            startup.text_colored(1.00, 0.35, 0.25, 1.00, "Support ZIP: " .. tostring(supportStatus))
        else
            startup.text_colored(0.42, 0.82, 1.00, 1.00, "Support ZIP: " .. tostring(supportStatus))
        end

        if startup.support_file_exists(startup.CheraxLogPath) then
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Cherax.log: Included")
        else
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "Cherax.log: Not found")
        end
        local _, dedicatedSupport = startup.get_support_discord_link()
        if dedicatedSupport then
            startup.text_colored(0.42, 0.82, 1.00, 1.00, "Discord: Dedicated Startup support")
        else
            startup.subtle_text("Discord: Community fallback")
        end

        ImGui.Text("")
        startup.text_colored(1.00, 0.78, 0.25, 1.00, "Privacy")
        if ImGui.TextWrapped then
            ImGui.TextWrapped("Support ZIPs may contain player names, Rockstar IDs, IP addresses, local file paths, and other diagnostic/session information. Upload them only to a trusted support channel.")
        else
            ImGui.Text("Support ZIPs may contain private diagnostic/session information. Upload only to trusted support.")
        end
        ClickGUI.EndCustomChildWindow()
    end

    -- Keep recovery controls visually separate and at the very bottom of Config.
    if ClickGUI.BeginCustomChildWindow("Reset & Recovery") then
        startup.section_title("Reset & Recovery")
        startup.subtle_text("Restore Startup's saved configuration without deleting any scripts, themes, or Cherax settings files.")
        ImGui.Separator()
        startup.render_color_button(
            "RESET SETTINGS",
            "Gold",
            "Resets Startup toggles, routing, hotkey, HUD layout, advertising values, Lua selections/delays, and theme preferences. The completed onboarding state is preserved.",
            startup.open_reset_settings_confirmation,
            -1
        )
        if ImGui.TextWrapped then
            ImGui.TextWrapped("This overwrites Startup's saved config with defaults. It does not delete Lua files, theme files, the selected Cherax settings profile, or reset completed onboarding.")
        else
            ImGui.Text("Resets Startup config only; files and onboarding completion are preserved.")
        end
        ClickGUI.EndCustomChildWindow()
    end
end

function startup.render_tip_row(index, tip)
    if type(tip) == "function" then
        local ok, resolved = direct_call(tip)
        tip = ok and resolved or "Time-of-day estimate unavailable."
    end
    startup.text_colored(0.72, 0.42, 1.00, 1.00, tostring(index) .. ".")
    ImGui.SameLine()
    if ImGui.TextWrapped then
        ImGui.TextWrapped(tostring(tip or ""))
    else
        ImGui.Text(tostring(tip or ""))
    end
    startup.hover_help("Tip " .. tostring(index))
end

function startup.render_tips()
    if not startup.s.showTipsPanel then return end
    if ClickGUI.BeginCustomChildWindow("Tips") then
        startup.section_title("Tips")
        startup.subtle_text("Setup, matchmaking, and startup reminders")
        ImGui.Separator()
        local sections = startup.tip_sections or {}
        local globalIndex = 0
        if #sections > 0 then
            for sectionIndex, section in ipairs(sections) do
                local c = section.color or {0.72, 0.42, 1.00}
                startup.text_colored(c[1], c[2], c[3], 1.00, tostring(section.name or "Tips"))
                startup.hover_help(tostring(section.help or ""))
                ImGui.Separator()
                for _, tip in ipairs(section.tips or {}) do
                    globalIndex = globalIndex + 1
                    startup.render_tip_row(globalIndex, tip)
                    if ImGui.Spacing then ImGui.Spacing() end
                end
                if sectionIndex < #sections then
                    ImGui.Separator()
                    if ImGui.Spacing then ImGui.Spacing() end
                end
            end
        else
            for i, tip in ipairs(startup.tips or {}) do
                startup.render_tip_row(i, tip)
                if i < #(startup.tips or {}) and ImGui.Spacing then ImGui.Spacing() end
            end
        end
        ClickGUI.EndCustomChildWindow()
    end
end
