function startup.render_how_to_guide_picker()
    local guides = startup.how_to_guides or {}
    if #guides == 0 then return nil end
    local selected = startup.clamp_int(startup.how_to_state.selected or 1, 1, #guides)
    startup.how_to_state.selected = selected
    local current = guides[selected]
    local opened = ImGui.BeginCombo and ImGui.BeginCombo("Guide", tostring(current.name or "Subscribed Script Setup")) == true
    startup.hover_help("Choose a short setup guide.")
    if opened then
        for i, guide in ipairs(guides) do
            if ImGui.Selectable(tostring(guide.name), i == selected) == true then
                startup.how_to_state.selected, selected, current = i, i, guide
            end
        end
        if ImGui.EndCombo then ImGui.EndCombo() end
    end
    return current
end

