    active = false,
    stage = "",
    step = 1,
    simulation = false,
    mode = "",
    runSetupAfterWhatsNew = false,
    tierChoice = "",
    settingsFile = "",
    autoLoadSettings = true,
    autoStartAttempted = false,
    autoStartConfirmed = false
}

function startup.get_display_size()
    if not ImGui or not ImGui.GetDisplaySize then return 1920, 1080 end
    local width, height = ImGui.GetDisplaySize()
    if type(width) == "table" then
        return tonumber(width.x or width.X or width[1] or 1920) or 1920,
            tonumber(width.y or width.Y or width[2] or 1080) or 1080
    end
    return tonumber(width or 1920) or 1920, tonumber(height or 1080) or 1080
end

function startup.first_run_window_flags()
    local flags = 0
    local function add(value) if value then flags = flags + value end end
    if ImGuiWindowFlags then
        add(ImGuiWindowFlags.NoTitleBar)
        add(ImGuiWindowFlags.NoResize)
        add(ImGuiWindowFlags.NoMove)
        add(ImGuiWindowFlags.NoCollapse)
        add(ImGuiWindowFlags.NoScrollbar)
        add(ImGuiWindowFlags.NoSavedSettings)
    end
    return flags
end

function startup.push_first_run_style()
    local colors, vars = 0, 0
    if ImGui and ImGui.PushStyleColor and ImGuiCol then
        local function color(key, r, g, b, a)
            if key ~= nil then ImGui.PushStyleColor(key, r, g, b, a); colors = colors + 1 end
        end
        color(ImGuiCol.WindowBg, 0.075, 0.022, 0.135, 0.985)
        color(ImGuiCol.ChildBg, 0.11, 0.040, 0.19, 0.985)
        color(ImGuiCol.PopupBg, 0.10, 0.035, 0.17, 0.985)
        color(ImGuiCol.Border, 0.72, 0.42, 1.00, 1.00)
        color(ImGuiCol.Separator, 0.52, 0.25, 0.82, 1.00)
        color(ImGuiCol.Text, 1.00, 1.00, 1.00, 1.00)
    end
    if ImGui and ImGui.PushStyleVar and ImGuiStyleVar then
        local function scalar(key, value) if key ~= nil then ImGui.PushStyleVar(key, value); vars = vars + 1 end end
        local function pair(key, x, y) if key ~= nil then ImGui.PushStyleVar(key, x, y); vars = vars + 1 end end
        scalar(ImGuiStyleVar.WindowRounding, 14.0)
        scalar(ImGuiStyleVar.WindowBorderSize, 2.0)
        scalar(ImGuiStyleVar.FrameRounding, 9.0)
        scalar(ImGuiStyleVar.FrameBorderSize, 0.0)
        scalar(ImGuiStyleVar.ChildRounding, 10.0)
        scalar(ImGuiStyleVar.ChildBorderSize, 1.0)
        pair(ImGuiStyleVar.WindowPadding, 20.0, 18.0)
        pair(ImGuiStyleVar.FramePadding, 8.0, 6.0)
        pair(ImGuiStyleVar.ItemSpacing, 10.0, 8.0)
        pair(ImGuiStyleVar.ItemInnerSpacing, 7.0, 5.0)
    end
    return colors, vars
end

function startup.pop_first_run_style(colors, vars)
    if tonumber(vars or 0) > 0 and ImGui and ImGui.PopStyleVar then ImGui.PopStyleVar(vars) end
    if tonumber(colors or 0) > 0 and ImGui and ImGui.PopStyleColor then ImGui.PopStyleColor(colors) end
end

function startup.first_run_text_badge(textValue, scheme, tooltip)
    local previousScale = 1.0
    if ImGui and ImGui.SetWindowFontScale then ImGui.SetWindowFontScale(0.90) end
    local width = 0
    if ImGui and ImGui.CalcTextSize then
        local size = ImGui.CalcTextSize(tostring(textValue or ""))
        if type(size) == "number" then width = tonumber(size) or 0
        elseif type(size) == "table" then width = tonumber(size.x or size.X or size[1] or 0) or 0 end
    end
    width = math.max(76, width + 20)
    startup.render_color_button(tostring(textValue or "Badge"), scheme or "Purple", tooltip or "", nil, width, 28)
    if ImGui and ImGui.SetWindowFontScale then ImGui.SetWindowFontScale(previousScale) end
end

function startup.first_run_begin_card(id, height, scrollable)
    if not ImGui or not ImGui.BeginChild then return false end
    local flags = 0
    if scrollable ~= true and ImGuiWindowFlags then
        flags = (ImGuiWindowFlags.NoScrollbar or 0) + (ImGuiWindowFlags.NoScrollWithMouse or 0)
    elseif scrollable == true and ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar then
        flags = ImGuiWindowFlags.AlwaysVerticalScrollbar
    end
    return ImGui.BeginChild(tostring(id or "##Startup_Popup_Card"), 0, tonumber(height or 0) or 0, true, flags) == true
end

function startup.popup_scaled_text(text, scale, r, g, b, a, wrapped)
    text = tostring(text or "")
    scale = tonumber(scale or 1.0) or 1.0
    local scaled = ImGui and ImGui.SetWindowFontScale
    if scaled then ImGui.SetWindowFontScale(scale) end

    local pushedColor = false
    if ImGui and ImGui.PushStyleColor and ImGuiCol and ImGuiCol.Text ~= nil then
        ImGui.PushStyleColor(ImGuiCol.Text, tonumber(r or 1.0) or 1.0, tonumber(g or 1.0) or 1.0, tonumber(b or 1.0) or 1.0, tonumber(a or 1.0) or 1.0)
        pushedColor = true
    end

    if wrapped == true and ImGui and ImGui.TextWrapped then
        ImGui.TextWrapped(text)
    elseif ImGui and ImGui.Text then
        ImGui.Text(text)
    else
        startup.text_colored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, text)
    end

    if pushedColor and ImGui and ImGui.PopStyleColor then ImGui.PopStyleColor(1) end
    if scaled then ImGui.SetWindowFontScale(1.0) end
end

function startup.first_run_end_card()
    if ImGui and ImGui.EndChild then ImGui.EndChild() end
end

function startup.detected_tier_choice()
    local _, _, isPrime, recognized = startup.get_active_edition_info()
    if recognized then return isPrime == true and "Prime" or "Standard / Premium" end
    return ""
end

function startup.start_setup_wizard(mode)
    mode = tostring(mode or "first_run")
    local simulation = string.find(mode, "simulation", 1, true) ~= nil
    local tier = tostring(startup.s.sessionRoutingMode or "")
    if tier ~= "Standard / Premium" and tier ~= "Prime" then tier = "" end
    local selectedFile = tostring(startup.s.settingsFile or "")
    if selectedFile ~= "" and #(startup.s.settingsProfiles or {}) > 0 and not startup.settings_profile_exists(selectedFile) then
        selectedFile = ""
    end
    startup.popup_flow = {
        active = true,
        stage = "setup",
        step = 1,
        simulation = simulation,
        mode = mode,
        runSetupAfterWhatsNew = false,
        tierChoice = tier,
        settingsFile = selectedFile,
        autoLoadSettings = startup.s.autoLoadSettings ~= false,
        autoStartAttempted = false,
        autoStartConfirmed = simulation and false or startup.s.subscribedAutoStartConfirmed == true
    }
    startup.s.firstRunWelcomeSimulation = simulation and mode == "simulation_setup"
    startup.s.updateFlowSimulation = simulation and mode == "simulation_update"
    startup.s.firstRunWelcomeLastForceOpenMs = 0
    startup.queue_settings_profile_refresh(false)
end

function startup.start_update_flow(simulation)
    startup.popup_flow = {
        active = true,
        stage = "whats_new",
        step = 0,
        simulation = simulation == true,
        mode = simulation == true and "simulation_update" or "update",
        runSetupAfterWhatsNew = false,
        tierChoice = "",
        settingsFile = tostring(startup.s.settingsFile or ""),
        autoLoadSettings = startup.s.autoLoadSettings ~= false,
        autoStartAttempted = false,
        autoStartConfirmed = false
    }
    startup.s.updateFlowSimulation = simulation == true
    startup.s.firstRunWelcomeLastForceOpenMs = 0
end

function startup.is_gta_online_session_ready()
    if not Natives or not Natives.InvokeBool then return false end
    local hashes = {
        0xD83C2B94E7508980, -- NETWORK_IS_SESSION_ACTIVE
        0xCA97246103B63917, -- NETWORK_IS_IN_SESSION
        0x9DE624D2FC4B603F  -- NETWORK_IS_SESSION_STARTED
    }
    for _, hash in ipairs(hashes) do
        local ok, active = direct_call(function() return Natives.InvokeBool(hash) == true end)
        if ok and active then return true end
    end
    return false
end

function startup.maybe_start_whats_new_online()
    if startup.s.pendingWhatsNewOnline ~= true then return end
    if startup.popup_flow and startup.popup_flow.active == true then return end
    if not startup.is_gta_online_session_ready() then return end
    startup.s.pendingWhatsNewOnline = false
    startup.start_update_flow(false)
    startup.log("What's New is ready; GTA Online session detected.")
end

function startup.prepare_startup_popups()
    if startup.popup_flow.active then return end
    local needsWhatsNew = tostring(startup.s.lastAcknowledgedStartupBuild or "") ~= tostring(startup.whats_new_version)

    -- Exactly two popup systems:
    -- 1) no existing Startup config -> first-time guided setup;
    -- 2) existing Startup config -> What's New once per build, never forced back through setup.
    if startup.s.firstRunInstallPending == true or startup.s.existingConfigLoaded ~= true then
        startup.start_setup_wizard("first_run")
    elseif needsWhatsNew then
        startup.s.pendingWhatsNewOnline = true
        startup.s.lastStatus = "What's New will appear after entering GTA Online."
    end
end

function startup.is_onboarding_setup_pending()
    return startup.s.firstRunInstallPending == true and startup.s.firstRunWelcomeCompleted ~= true
end

function startup.queue_onboarding_commit(flow)
    startup.s.pendingOnboardingCommit = {
        simulation = flow.simulation == true,
        tierChoice = tostring(flow.tierChoice or ""),
        settingsFile = tostring(flow.settingsFile or ""),
        autoLoadSettings = flow.autoLoadSettings ~= false,
        autoStartConfirmed = flow.autoStartConfirmed == true or startup.s.subscribedAutoStartConfirmed == true,
        acknowledgeBuild = true
    }
end

function startup.process_pending_onboarding_commit()
    local pending = startup.s.pendingOnboardingCommit
    if type(pending) ~= "table" then return end
    startup.s.pendingOnboardingCommit = nil
    if pending.simulation == true then return end

    if pending.tierChoice == "Prime" or pending.tierChoice == "Standard / Premium" then
        startup.s.sessionRoutingMode = pending.tierChoice
    end
    startup.s.autoLoadSettings = pending.autoLoadSettings ~= false
    startup.s.settingsFile = tostring(pending.settingsFile or "")
    startup.s.settingsProfileSelectionConfirmed = startup.s.settingsFile ~= "" or startup.s.autoLoadSettings == false
    startup.s.subscribedAutoStartConfirmed = pending.autoStartConfirmed == true or startup.s.subscribedAutoStartConfirmed == true
    startup.s.firstRunWelcomeCompleted = true
    startup.s.firstRunWelcomeCompletedAt = os.time()
    startup.s.firstRunInstallPending = false
    startup.s.onboardingSetupVersion = startup.onboarding_setup_version
    startup.s.lastAcknowledgedStartupBuild = startup.whats_new_version
    startup.resolve_session_type()
    startup.sync_feature_states()
    startup.save_config(false)
    if startup.s.autoLoadSettings and startup.s.settingsFile ~= "" then
        startup.apply_settings_file()
        startup.sync_feature_states()
    end
    if startup.apply_session_type then startup.apply_session_type() end
    if startup.run_startup_online_launch then startup.run_startup_online_launch() end
    startup.toast("Startup setup saved.", 3500)
end

function startup.queue_whats_new_acknowledgement(simulation)
    if simulation == true then return end
    startup.s.pendingOnboardingCommit = {
        simulation = false,
        tierChoice = tostring(startup.s.sessionRoutingMode or ""),
        settingsFile = tostring(startup.s.settingsFile or ""),
        autoLoadSettings = startup.s.autoLoadSettings ~= false,
        acknowledgeBuild = true,
        whatsNewOnly = true
    }
end

function startup.process_whats_new_only_ack(pending)
    startup.s.lastAcknowledgedStartupBuild = startup.whats_new_version
    startup.save_config(false)
end

-- Wrap the normal commit worker so What's New-only acknowledgements do not alter setup.
local _startup_process_pending_onboarding_commit = startup.process_pending_onboarding_commit
startup.process_pending_onboarding_commit = function()
    local pending = startup.s.pendingOnboardingCommit
    if type(pending) == "table" and pending.whatsNewOnly == true then
        startup.s.pendingOnboardingCommit = nil
        startup.process_whats_new_only_ack(pending)
        return
    end
    return _startup_process_pending_onboarding_commit()
end

function startup.render_popup_header(title, subtitle, badge)
    local popup_logo_anchor_y = startup.credits_get_cursor_pos_y()
    startup.render_popup_logo_right(popup_logo_anchor_y, 96, 96)

    startup.text_colored(0.86, 0.56, 1.00, 1.00, tostring(title or "STARTUP"))
    if ImGui and ImGui.SameLine then
        ImGui.SameLine()
        startup.first_run_text_badge(tostring(startup.version or "v1.0.10"), "Purple", "Current Startup version.")
        if badge and badge ~= "" then
            ImGui.SameLine()
            startup.first_run_text_badge(badge, startup.popup_flow.simulation and "Gold" or "Blue", startup.popup_flow.simulation and "Simulation only; nothing is saved." or "Startup guided setup.")
        end
    end
    startup.text_colored(0.35, 0.86, 1.00, 1.00, tostring(subtitle or "Boot clean. Load smart. Run everything in order."))

    local current_y = startup.credits_get_cursor_pos_y()
    startup.credits_set_cursor_pos_y(math.max(current_y, popup_logo_anchor_y + 102))
end

function startup.render_setup_progress()
    local step = startup.clamp_int(startup.popup_flow.step or 1, 1, 4)
    local labels = { "1 TIER", "2 SETTINGS", "3 AUTO START", "4 DISCORD" }
    for i, label in ipairs(labels) do
        local scheme = i < step and "Green" or (i == step and "Purple" or "Blue")
        startup.first_run_text_badge(label, scheme, i == step and "Current setup step." or (i < step and "Completed step." or "Upcoming step."))
        if i < #labels and ImGui.SameLine then ImGui.SameLine() end
    end
end

function startup.render_setup_step_tier()
    startup.section_title("Choose your REAL Cherax tier")
    local edition, family, isPrime, recognized = startup.get_active_edition_info()
    local detected = recognized and (isPrime == true and "Prime" or "Standard / Premium") or "Unknown"
    startup.subtle_text("Detected edition: " .. tostring(edition) .. "  •  " .. tostring(family) .. "  •  Recommended: " .. tostring(detected))
    ImGui.Separator()

    startup.text_colored(1.00, 0.46, 0.28, 1.00, "IMPORTANT — DO NOT GUESS OR LIE ABOUT YOUR TIER")
    if ImGui.TextWrapped then
        ImGui.TextWrapped("Choose the Cherax tier you actually have. Startup uses this choice for session routing. A wrong choice can use the wrong matchmaking/session path and may cause players to not appear or join your lobby correctly.")
    else
        ImGui.Text("Choose your real tier. A wrong choice can break session routing and player population.")
    end
    startup.text_colored(1.00, 0.78, 0.25, 1.00, "If the detected tier is correct, USE DETECTED is the safest option.")
    ImGui.Text("")

    if detected ~= "Unknown" then
        startup.render_color_button("USE DETECTED: " .. detected, "Green", "Recommended. Uses Cherax.GetEdition() so Startup follows the tier Cherax is actually reporting.", function()
            startup.popup_flow.tierChoice = detected
        end, -1, 40)
        if ImGui.Spacing then ImGui.Spacing() end
    end

    local standardLabel = startup.popup_flow.tierChoice == "Standard / Premium" and "✓ STANDARD / PREMIUM" or "STANDARD / PREMIUM"
    local primeLabel = startup.popup_flow.tierChoice == "Prime" and "✓ PRIME" or "PRIME"
    startup.render_color_button(standardLabel, startup.popup_flow.tierChoice == "Standard / Premium" and "Green" or "Blue",
        "Choose this only if you actually use Cherax Standard/Premium (LE or EE without the Prime/BE routing mode).", function()
            startup.popup_flow.tierChoice = "Standard / Premium"
        end, 255, 40)
    if ImGui.SameLine then ImGui.SameLine() end
    startup.render_color_button(primeLabel, startup.popup_flow.tierChoice == "Prime" and "Green" or "Purple",
        "Choose this only if you actually use Cherax Prime (LE BE / EE BE routing).", function()
            startup.popup_flow.tierChoice = "Prime"
        end, -1, 40)

    ImGui.Text("")
    if startup.popup_flow.tierChoice ~= "" then
        startup.text_colored(0.35, 1.00, 0.45, 1.00, "Selected: " .. tostring(startup.popup_flow.tierChoice))
        startup.render_color_button("CONTINUE", "Green", "I confirm this is my real Cherax tier. Continue to saved settings.", function()
            startup.popup_flow.step = 2
        end, -1, 40)
    else
        startup.text_colored(1.00, 0.78, 0.25, 1.00, "Choose Standard / Premium or Prime to continue.")
    end
end

function startup.render_setup_step_settings()
    startup.section_title("Choose your saved Cherax settings")
    startup.subtle_text("Choose the Cherax settings profile Startup should load.")
    ImGui.Separator()

    local profiles = startup.s.settingsProfiles or {}
    local selected = tostring(startup.popup_flow.settingsFile or "")

    if #profiles > 0 then
        startup.text_colored(0.42, 0.82, 1.00, 1.00, "CLICK A PROFILE BELOW TO SELECT IT")
        local childOpened = true
        if ImGui.BeginChild then
            local flags = 0
            if ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar and #profiles > 5 then
                flags = ImGuiWindowFlags.AlwaysVerticalScrollbar
            end
            childOpened = ImGui.BeginChild("##Startup_Setup_Settings_Profile_List", 0, 170, true, flags) == true
        end
        if childOpened then
            for _, profile in ipairs(profiles) do
                local profileName = tostring(profile or "")
                local isSelected = startup.settings_profile_names_match(profileName, selected)
                local buttonLabel = isSelected and ("✓  " .. profileName) or profileName
                startup.render_color_button(buttonLabel, isSelected and "Green" or "Blue",
                    "Select " .. profileName .. " as the Cherax settings JSON Startup loads.", function()
                        startup.popup_flow.settingsFile = profileName
                        startup.popup_flow.autoLoadSettings = true
                    end, -1, 34)
            end
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end

        selected = tostring(startup.popup_flow.settingsFile or "")
        if selected ~= "" then
            startup.text_colored(0.35, 1.00, 0.45, 1.00, "Selected: " .. selected)
        else
            startup.text_colored(1.00, 0.78, 0.25, 1.00, "No profile selected yet.")
        end
        startup.subtle_text(tostring(startup.s.settingsProfilesStatus or "Saved profiles ready."))
    else
        startup.text_colored(1.00, 0.78, 0.25, 1.00, tostring(startup.s.settingsProfilesStatus or "No saved settings profiles found."))
        if ImGui.TextWrapped then
            ImGui.TextWrapped("Save a profile in Cherax, then click Refresh List.")
        end

        local fallbackProfile = tostring(selected or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if fallbackProfile == "" then
            fallbackProfile = tostring(startup.s.settingsFile or ""):gsub("^%s+", ""):gsub("%s+$", "")
        end
        if fallbackProfile == "" then fallbackProfile = "default.json" end

        startup.render_color_button("USE " .. string.upper(fallbackProfile), "Green",
            "Use " .. fallbackProfile .. " as the saved Cherax settings profile.", function()
                startup.popup_flow.settingsFile = fallbackProfile
                startup.popup_flow.autoLoadSettings = true
            end, -1, 36)
    end

    startup.render_color_button("REFRESH LIST", "Blue", "Refreshes the saved Cherax settings list.", function()
        startup.queue_settings_profile_refresh(true)
    end, 190, 36)

    ImGui.Text("")
    startup.render_color_button("BACK", "Blue", "Return to Cherax tier selection.", function() startup.popup_flow.step = 1 end, 130, 38)
    if selected ~= "" then
        if ImGui.SameLine then ImGui.SameLine() end
        startup.render_color_button("CONTINUE", "Green", "Use " .. selected .. " and continue to Auto Start setup.", function()
            startup.popup_flow.autoLoadSettings = true
            startup.popup_flow.step = 3
        end, -1, 38)
    else
        if ImGui.SameLine then ImGui.SameLine() end
        startup.render_color_button("CONTINUE WITHOUT AUTO-LOAD", "Gold", "Turns Auto-Load Settings OFF. You can choose a profile later from Config.", function()
            startup.popup_flow.autoLoadSettings = false
            startup.popup_flow.settingsFile = ""
            startup.popup_flow.step = 3
        end, -1, 38)
    end
end

function startup.render_setup_step_auto_start()
    startup.section_title("Enable Startup Auto Start")
    startup.subtle_text("Startup Auto Start is ON by default. Turn on Cherax's Singleplayer to Online option.")
    ImGui.Separator()

    startup.popup_scaled_text("WHERE IT IS", 0.82, 0.42, 0.82, 1.00, 1.00, false)
    local guideOpened = startup.first_run_begin_card("##Startup_Auto_Start_Visual_Guide", 202, false)
    if guideOpened then
        local imageDrawn = startup.render_subscribed_scripts_image(172, 100, 8)
        if not imageDrawn then
            startup.popup_scaled_text("Settings  >  Subscribed Scripts", 0.82, 0.78, 0.78, 0.80, 1.00, false)
            startup.popup_scaled_text("Startup   ▼", 0.90, 0.86, 0.56, 1.00, 1.00, false)
            startup.popup_scaled_text("●  Auto Start   ← turn this ON", 0.90, 0.35, 1.00, 0.45, 1.00, false)
            startup.subtle_text(tostring(startup.subscribed_scripts_image_state and startup.subscribed_scripts_image_state.status or "Loading guide artwork..."))
        end
        ImGui.Text("")
        startup.popup_scaled_text("ALSO REQUIRED", 0.84, 1.00, 0.78, 0.18, 1.00, false)
        startup.popup_scaled_text("Turn ON: Singleplayer to Online", 0.92, 0.35, 1.00, 0.45, 1.00, false)
        startup.subtle_text("This lets Startup move you from Story Mode into GTA Online automatically.")
        startup.first_run_end_card()
    end

    startup.text_colored(1.00, 0.78, 0.25, 1.00, "Before restarting GTA V, make sure Singleplayer to Online is ON in Cherax.")

    if startup.popup_flow.simulation == true then
        startup.text_colored(1.00, 0.78, 0.18, 1.00, "SIMULATION MODE — the real Cherax Auto Start setting will not be changed.")
    end

    local confirmed = startup.popup_flow.autoStartConfirmed == true or (startup.popup_flow.simulation ~= true and startup.s.subscribedAutoStartConfirmed == true)
    if confirmed then
        startup.text_colored(0.30, 1.00, 0.45, 1.00, "Startup Auto Start: ENABLED")
    else
        startup.text_colored(1.00, 0.78, 0.25, 1.00, tostring(startup.s.subscribedAutoStartStatus or "Not checked yet."))
    end
    ImGui.Text("")

    startup.render_color_button(confirmed and "✓ AUTO START ENABLED" or "ENABLE AUTO START", confirmed and "Green" or "Purple", "Finds Startup's subscribed-script Auto Start control, enables/clicks it outside ImGui rendering, and verifies that Cherax reports it ON.", function()
        startup.popup_flow.autoStartAttempted = true
        if startup.popup_flow.simulation == true then
            startup.popup_flow.autoStartConfirmed = true
        else
            startup.queue_subscribed_auto_start_enable()
        end
    end, -1, 40)

    if startup.popup_flow.simulation ~= true and startup.s.subscribedAutoStartConfirmed == true then
        startup.popup_flow.autoStartConfirmed = true
    end

    ImGui.Text("")
    startup.render_color_button("BACK", "Blue", "Return to saved settings selection.", function() startup.popup_flow.step = 2 end, 130, 38)
    if ImGui.SameLine then ImGui.SameLine() end
    startup.render_color_button("CONTINUE", confirmed and "Green" or "Gold", confirmed and "Continue to Discord." or "Continue even if Cherax Auto Start could not be confirmed; you can enable it manually.", function()
        startup.popup_flow.step = 4
    end, -1, 38)
end

function startup.first_run_join_discord()
    local copied, opened = startup.copy_and_open_discord(false)
    if opened and copied then startup.toast("Discord opened and the invite was copied.", 4000)
    elseif copied then startup.toast("Discord invite copied.", 3500)
    elseif opened then startup.toast("Discord opened in your browser.", 3500)
    else startup.error("Could not open or copy the Discord invite. You can still continue.") end
end

function startup.complete_setup_wizard()
    local flow = startup.popup_flow
    if flow.simulation == true then
        flow.active = false
        startup.s.firstRunWelcomeSimulation = false
        startup.s.updateFlowSimulation = false
        startup.set_feature_bool_silently(startup.h.FirstRunWelcomeSimulation, false)
        startup.toast("Popup simulation closed. Saved Startup settings were not changed.", 4000)
        return
    end
    startup.queue_onboarding_commit(flow)
    flow.active = false
end

function startup.render_setup_step_discord()
    startup.section_title("You're ready")
    if startup.popup_flow.simulation == true then
        startup.text_colored(1.00, 0.78, 0.18, 1.00, "SIMULATION MODE — Continue closes the preview without saving anything.")
    else
        startup.subtle_text("Join for updates, dedicated support, showcases, and the rest of Public_Urinal's Cherax scripts.")
    end
    ImGui.Separator()

    if not startup.render_public_urinal_icon(72) then
        startup.text_colored(0.72, 0.42, 1.00, 1.00, "PUBLIC_URINAL")
    end
    startup.text_colored(0.42, 0.82, 1.00, 1.00, tostring(startup.discord_invite_display))
    startup.subtle_text("Join Discord does not close setup. Continue finishes the wizard.")
    ImGui.Text("")

    startup.render_color_button("JOIN DISCORD", "Blue", "Opens the community Discord and copies the invite without closing setup.", startup.first_run_join_discord, 250, 40)
    if ImGui.SameLine then ImGui.SameLine() end
    startup.render_color_button("CONTINUE", "Green", startup.popup_flow.simulation and "Close this simulation without saving." or "Save setup and finish onboarding.", startup.complete_setup_wizard, -1, 40)
end

function startup.render_whats_new_popup()
    -- Full public version history. Keep this user-facing and avoid internal implementation noise.
    local popup_logo_anchor_y = startup.credits_get_cursor_pos_y()
    startup.render_popup_logo_right(popup_logo_anchor_y, 112, 112)
    startup.popup_scaled_text("WHAT'S NEW", 1.36, 0.86, 0.56, 1.00, 1.00, false)
    startup.popup_scaled_text(tostring(startup.version) .. "  •  Build " .. tostring(startup.build_number), 0.88, 0.35, 0.86, 1.00, 1.00, false)
    startup.popup_scaled_text("Full version history  •  v1.0.0 to v1.0.11", 0.82, 0.68, 0.68, 0.70, 1.00, false)
    local current_y = startup.credits_get_cursor_pos_y()
    startup.credits_set_cursor_pos_y(math.max(current_y, popup_logo_anchor_y + 118))
    ImGui.Text("")

    local availableY = 330
    if ImGui and ImGui.GetContentRegionAvail then
        local ax, ay = ImGui.GetContentRegionAvail()
        if type(ax) == "table" then availableY = tonumber(ax.y or ax.Y or ax[2] or availableY) or availableY
        else availableY = tonumber(ay or availableY) or availableY end
    end
    local notesHeight = math.max(185, math.min(330, availableY - 78))
    local opened = startup.first_run_begin_card("##Startup_Whats_New", notesHeight, true)
    if opened then
        for i, item in ipairs(startup.whats_new_items or {}) do
            local titleR, titleG, titleB = 0.78, 0.62, 1.00
            if type(item.color) == "table" then
                titleR = tonumber(item.color[1] or titleR) or titleR
                titleG = tonumber(item.color[2] or titleG) or titleG
                titleB = tonumber(item.color[3] or titleB) or titleB
            elseif i == 1 then
                titleR, titleG, titleB = 0.35, 1.00, 0.45
            end
            startup.popup_scaled_text(tostring(item.title or "Update"), 1.04, titleR, titleG, titleB, 1.00, false)

            for _, bullet in ipairs(item.bullets or {}) do
                startup.popup_scaled_text("• " .. tostring(bullet or ""), 0.88, 0.78, 0.78, 0.80, 1.00, true)
            end

            if item.warning and tostring(item.warning) ~= "" then
                startup.popup_scaled_text(tostring(item.warning), 0.86, 1.00, 0.32, 0.32, 1.00, true)
            end

            if i < #(startup.whats_new_items or {}) then ImGui.Text("") end
        end
        startup.first_run_end_card()
    end

    ImGui.Text("")
    if startup.popup_flow.simulation == true then
        startup.popup_scaled_text("Simulation only • nothing will be saved", 0.84, 1.00, 0.78, 0.18, 1.00, false)
    else
        startup.popup_scaled_text("Scroll through every release. Continue remembers this build.", 0.82, 0.68, 0.68, 0.70, 1.00, false)
    end

    startup.render_color_button("CONTINUE", "Green", "Continue from the update notes.", function()
        local simulation = startup.popup_flow.simulation == true
        if not simulation then startup.queue_whats_new_acknowledgement(false) end
        startup.s.updateFlowSimulation = false
        startup.popup_flow.active = false
    end, -1, 38)
end

function startup.render_setup_popup()
    startup.render_popup_header("STARTUP SETUP", "Four quick choices, then Startup is ready.", startup.popup_flow.simulation and "SIMULATION" or (startup.popup_flow.mode == "update" and "UPDATE SETUP" or "FIRST RUN"))
    ImGui.Separator()
    startup.render_setup_progress()
    ImGui.Separator()
    if startup.popup_flow.step == 1 then startup.render_setup_step_tier()
    elseif startup.popup_flow.step == 2 then startup.render_setup_step_settings()
    elseif startup.popup_flow.step == 3 then startup.render_setup_step_auto_start()
    else startup.render_setup_step_discord() end
end

function startup.keep_first_run_welcome_active()
    if not startup.popup_flow or startup.popup_flow.active ~= true then return end
    local now = startup.now()
    if now - (tonumber(startup.s.firstRunWelcomeLastForceOpenMs or 0) or 0) < 750 then return end
    startup.s.firstRunWelcomeLastForceOpenMs = now
    if GUI and GUI.IsOpen and GUI.Toggle and GUI.IsOpen() ~= true then GUI.Toggle() end
end

function startup.render_first_run_welcome()
    if not startup.popup_flow or startup.popup_flow.active ~= true then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end

    local screen_w, screen_h = startup.get_display_size()
    local baseWidth = math.min(880, math.max(640, screen_w - 100))
    local baseHeight = math.min(650, math.max(520, screen_h - 90))
    local width = math.max(576, math.floor(baseWidth * 0.90))
    local height = math.max(468, math.floor(baseHeight * 0.90))
    local pos_x = math.max(18, (screen_w - width) * 0.5)
    local pos_y = math.max(18, (screen_h - height) * 0.5)
    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(pos_x, pos_y, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowFocus then ImGui.SetNextWindowFocus() end

    local colors, vars = startup.push_first_run_style()
    local visible = ImGui.Begin("##Startup_Guided_Popup", true, startup.first_run_window_flags())
    if visible then
        if startup.popup_flow.stage == "whats_new" then startup.render_whats_new_popup()
        else startup.render_setup_popup() end
    end
    ImGui.End()
    startup.pop_first_run_style(colors, vars)
end

