-- reset settings confirmation
-- note: rendered from ON_PRESENT so it works identically on Standard/Premium and Prime.
-- The destructive work is deferred to Startup's worker job to keep ClickGUI's tab
-- render coroutine free of FeatureMgr mutation.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.push_reset_settings_style()
    local colors, vars = 0, 0
    if ImGui and ImGui.PushStyleColor and ImGuiCol then
        local function color(key, r, g, b, a)
            if key ~= nil then
                ImGui.PushStyleColor(key, r, g, b, a)
                colors = colors + 1
            end
        end
        color(ImGuiCol.WindowBg, 0.10, 0.035, 0.055, 0.99)
        color(ImGuiCol.ChildBg, 0.13, 0.045, 0.07, 0.99)
        color(ImGuiCol.PopupBg, 0.12, 0.04, 0.065, 0.99)
        color(ImGuiCol.Border, 1.00, 0.58, 0.18, 1.00)
        color(ImGuiCol.Separator, 0.68, 0.34, 0.10, 1.00)
        color(ImGuiCol.Text, 1.00, 1.00, 1.00, 1.00)
    end
    if ImGui and ImGui.PushStyleVar and ImGuiStyleVar then
        local function scalar(key, value)
            if key ~= nil then ImGui.PushStyleVar(key, value); vars = vars + 1 end
        end
        local function pair(key, x, y)
            if key ~= nil then ImGui.PushStyleVar(key, x, y); vars = vars + 1 end
        end
        scalar(ImGuiStyleVar.WindowRounding, 16.0)
        scalar(ImGuiStyleVar.WindowBorderSize, 2.0)
        scalar(ImGuiStyleVar.FrameRounding, 10.0)
        scalar(ImGuiStyleVar.ChildRounding, 12.0)
        scalar(ImGuiStyleVar.ChildBorderSize, 1.0)
        pair(ImGuiStyleVar.WindowPadding, 22.0, 20.0)
        pair(ImGuiStyleVar.FramePadding, 10.0, 8.0)
        pair(ImGuiStyleVar.ItemSpacing, 10.0, 8.0)
    end
    return colors, vars
end

function startup.render_reset_settings_confirmation()
    if startup.reset_settings_confirm_open ~= true then return end
    if not ImGui or not ImGui.Begin or not ImGui.End then return end

    -- Read only Cherax.GetEdition here. Do not touch FeatureMgr from this ON_PRESENT
    -- renderer; the reset window must remain safe even if the Startup tab is open.
    local display_edition = startup.read_cherax_game_edition and startup.read_cherax_game_edition() or tostring(startup.s.detectedCheraxGameEdition or "Unknown")
    local display_family, display_battleye, display_recognized = "Unknown", nil, false
    if startup.parse_cherax_game_edition then
        display_family, display_battleye, display_recognized = startup.parse_cherax_game_edition(display_edition)
    end
    local display_tier = tostring(startup.s.detectedCheraxTier or "Unknown")
    if display_recognized then
        display_tier = display_battleye == true and "Prime" or "Standard / Premium"
    end

    local screen_w, screen_h = startup.get_display_size()
    local width = math.min(720, math.max(500, screen_w - 80))
    local height = math.min(560, math.max(430, screen_h - 80))
    width = math.min(width, math.max(360, screen_w - 20))
    height = math.min(height, math.max(340, screen_h - 20))
    local pos_x = math.max(10, (screen_w - width) * 0.5)
    local pos_y = math.max(10, (screen_h - height) * 0.5)

    if ImGui.SetNextWindowPos then ImGui.SetNextWindowPos(pos_x, pos_y, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowSize then ImGui.SetNextWindowSize(width, height, ImGuiCond and ImGuiCond.Always or 0) end
    if ImGui.SetNextWindowFocus then ImGui.SetNextWindowFocus() end

    local colors, vars = startup.push_reset_settings_style()
    local visible = ImGui.Begin("##Startup_Reset_Settings_Confirm", true, startup.first_run_window_flags())
    if visible then
        startup.text_colored(1.00, 0.67, 0.22, 1.00, "RESET STARTUP SETTINGS?")
        startup.text_colored(1.00, 0.90, 0.58, 1.00, "Are you sure you want to restore Startup defaults?")
        startup.subtle_text("This changes Startup's saved configuration only. Your files are preserved.")
        ImGui.Separator()

        local body_height = math.max(110, height - 225)
        local body_flags = 0
        if ImGuiWindowFlags and ImGuiWindowFlags.AlwaysVerticalScrollbar then
            body_flags = body_flags + ImGuiWindowFlags.AlwaysVerticalScrollbar
        end
        local body_visible = true
        if ImGui.BeginChild then
            body_visible = ImGui.BeginChild("##Startup_Reset_Settings_Body", 0, body_height, true, body_flags) == true
        end
        if body_visible then
            startup.section_title("What will be reset")
            if ImGui.TextWrapped then
                ImGui.TextWrapped("• Startup toggles and automation defaults\n• Session Routing returns to Automatic\n• Pause / Break hotkey and HUD layout\n• Auto Advertise timing / player-count settings\n• Lua startup selections and per-file delays\n• Theme eligibility and Startup theme preferences")
            else
                ImGui.Text("Startup toggles, routing, HUD, advertising, Lua selections, and themes.")
            end
            ImGui.Text("")
            startup.warn_text("Current Cherax")
            if ImGui.TextWrapped then
                ImGui.TextWrapped("Mode: " .. tostring(display_tier) ..
                    "  •  Game: " .. tostring(display_edition) ..
                    "  •  BattlEye: " .. tostring(display_battleye == true and "ON" or (display_battleye == false and "OFF" or "Unknown")))
                ImGui.TextWrapped("After reset, Automatic routing re-detects the active edition: LE / EE uses Standard/Premium routing; LE BE / EE BE uses Prime routing.")
            end
            ImGui.Text("")
            startup.text_colored(0.35, 1.00, 0.52, 1.00, "PRESERVED")
            if ImGui.TextWrapped then
                ImGui.TextWrapped("Your completed onboarding state is preserved. Startup does not delete Lua files, theme files, or Cherax settings profiles.")
            end
        end
        if ImGui.BeginChild and ImGui.EndChild then ImGui.EndChild() end

        ImGui.Separator()
        startup.render_color_button("NO, GO BACK", "Green", "Close this confirmation without changing anything.", function()
            startup.close_reset_settings_confirmation()
        end, -1, 42)
        startup.render_color_button("YES, RESET SETTINGS", "Red", "Restore Startup defaults. The actual reset is deferred outside the ClickGUI render callback.", function()
            startup.request_reset_settings()
        end, -1, 42)
    end
    ImGui.End()
    startup.pop_first_run_style(colors, vars)
end

