function startup.file_exists(path)
    if FileMgr and FileMgr.DoesFileExist then return FileMgr.DoesFileExist(path) == true end
    local file = io.open(tostring(path or ""), "rb")
    if file then
        file:close()
        return true
    end
    return false
end

function startup.load_public_urinal_icon()
    local state = startup.credits_state
    if state.texture_srv then return state.texture_srv end
    if state.load_failed == true then return nil end
    if not startup.file_exists(startup.public_urinal_icon_path) then return nil end
    if not Texture then
        state.load_failed = true
        state.status = "Texture API unavailable."
        return nil
    end

    -- Allocate exactly one Cherax texture slot for this icon. The old loader reset
    -- load_started whenever an async texture was not GPU-ready yet, which allowed the
    -- render loop to allocate another texture on the next frame. On slower DX12 loads
    -- that could exhaust Cherax's internal texture index pool.
    if not state.texture_id then
        if state.load_started == true then return nil end
        state.load_started = true
        state.load_requested_ms = startup.now()
        state.last_texture_poll_ms = 0
        state.status = "Loading Public_Urinal icon..."

        local texture_id = nil
        if Texture.LoadTextureAsync then
            texture_id = Texture.LoadTextureAsync(startup.public_urinal_icon_path)
        elseif Texture.LoadTexture then
            texture_id = Texture.LoadTexture(startup.public_urinal_icon_path)
        end

        texture_id = tonumber(texture_id)
        if not texture_id or texture_id == 0 then
            state.load_failed = true
            state.status = "Icon texture allocation failed."
            return nil
        end
        state.texture_id = texture_id
    end

    -- Poll the already-created texture only. Never allocate a replacement from the
    -- render loop if the async resource is still being prepared by Cherax/DX12.
    local now = startup.now()
    if now - (tonumber(state.last_texture_poll_ms or 0) or 0) < 125 then return nil end
    state.last_texture_poll_ms = now

    local texture_id = tonumber(state.texture_id or 0) or 0
    if texture_id == 0 then return nil end
    if Texture.IsTextureValid and Texture.IsTextureValid(texture_id) ~= true then
        state.status = "Public_Urinal icon is still loading..."
        return nil
    end

    local texture = Texture.GetTexture and Texture.GetTexture(texture_id) or nil
    if not texture then
        state.status = "Public_Urinal icon is still loading..."
        return nil
    end

    local srv = texture:GetCurrent()
    if not srv then
        state.status = "Public_Urinal icon is still loading..."
        return nil
    end

    state.texture_srv = srv
    state.status = "Public_Urinal icon loaded."
    return srv
end

function startup.download_public_urinal_icon()
    local state = startup.credits_state
    if state.download_started or startup.file_exists(startup.public_urinal_icon_path) then
        startup.load_public_urinal_icon()
        return
    end
    state.download_started, state.status = true, "Downloading Public_Urinal icon..."
    if not Script or not Script.QueueJob or not Curl or not Curl.Easy then
        state.download_started, state.status = false, "Icon download unavailable."
        return
    end
    Script.QueueJob(function()
        local curl = Curl.Easy()
        curl:Setopt(10002, startup.public_urinal_icon_url)
        curl:Setopt(52, 1)
        curl:Setopt(10018, "Mozilla/5.0 Startup-Cherax")
        curl:Perform()
        local ticks = 0
        while not curl:GetFinished() and ticks < 300 do
            startup.yield(50)
            ticks = ticks + 1
        end
        if not curl:GetFinished() then
            state.download_started, state.status = false, "Icon download timed out."
            return
        end
        local code, content = curl:GetResponse()
        local success = code == 0 or code == true or (eCurlCode and code == eCurlCode.CURLE_OK)
        local looksLikePng = type(content) == "string" and #content > 100 and ((content:byte(1) == 137 and content:sub(2, 4) == "PNG") or #content > 1000)
        if not success or not looksLikePng then
            state.download_started, state.status = false, "Icon download failed."
            return
        end
        if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(startup.public_urinal_icon_dir) end
        local file = io.open(startup.public_urinal_icon_path, "wb")
        if not file then
            state.download_started, state.status = false, "Could not save Public_Urinal icon."
            return
        end
        file:write(content)
        file:close()
        state.download_started = false
        state.load_started = false
        state.load_failed = false
        state.texture_id = nil
        state.texture_srv = nil
        state.load_requested_ms = 0
        state.last_texture_poll_ms = 0
        state.status = "Public_Urinal icon downloaded locally."
        if startup.support_log_event_quiet then startup.support_log_event_quiet("PUBLIC_URINAL_LOGO_CACHED", tostring(startup.public_urinal_icon_path)) end
    end)
end

function startup.ensure_public_urinal_icon_cached()
    if startup.file_exists(startup.public_urinal_icon_path) then
        -- Build 051 keeps one cached logo name only.
        if startup.legacy_public_urinal_icon_path then startup.raw_remove_file(startup.legacy_public_urinal_icon_path) end
        startup.credits_state.status = "Using local Public_Urinal icon."
        return true
    end
    startup.download_public_urinal_icon()
    return false
end

function startup.ensure_public_urinal_icon()
    if startup.file_exists(startup.public_urinal_icon_path) then
        startup.load_public_urinal_icon()
    else
        startup.ensure_public_urinal_icon_cached()
    end
end

