function startup.render_public_urinal_icon(size)
    size = tonumber(size or 138) or 138
    startup.ensure_public_urinal_icon()
    local srv = startup.credits_state.texture_srv or startup.load_public_urinal_icon()
    if not srv or not ImGui or not ImGui.GetCursorScreenPos then return false end
    local x, y = ImGui.GetCursorScreenPos()
    local cursor_x, cursor_y = 0, 0
    if type(x) == "number" then cursor_x, cursor_y = tonumber(x) or 0, tonumber(y) or 0
    elseif type(x) == "table" then cursor_x, cursor_y = tonumber(x.x or x.X or x[1] or 0) or 0, tonumber(x.y or x.Y or x[2] or 0) or 0 end
    if cursor_x <= 0 or cursor_y <= 0 then return false end
    local reserved = false
    if ImGui.Button then
        local pushed = 0
        if ImGui.PushStyleColor and ImGuiCol then
            ImGui.PushStyleColor(ImGuiCol.Button, 0.06, 0.06, 0.07, 0.00)
            pushed = pushed + 1
            ImGui.PushStyleColor(ImGuiCol.ButtonHovered, 0.06, 0.06, 0.07, 0.00)
            pushed = pushed + 1
            ImGui.PushStyleColor(ImGuiCol.ButtonActive, 0.06, 0.06, 0.07, 0.00)
            pushed = pushed + 1
        end
        ImGui.Button("##Startup_Public_Urinal_Image", size, size)
        if pushed > 0 and ImGui.PopStyleColor then ImGui.PopStyleColor(pushed) end
        reserved = true
    elseif ImGui.Dummy then
        ImGui.Dummy(size, size)
        reserved = true
    end
    if ImGui.AddImageRounded then
        ImGui.AddImageRounded(srv, cursor_x, cursor_y, cursor_x + size, cursor_y + size, 0.0, 0.0, 1.0, 1.0, 0xFFFFFFFF, 8.0)
        return true
    end
    if ImGui.AddImage then
        ImGui.AddImage(srv, cursor_x, cursor_y, cursor_x + size, cursor_y + size)
        return true
    end
    return reserved
end

function startup.render_credits_portrait_right(anchor_y)
    local saved_x = startup.credits_get_cursor_pos_x()
    local saved_y = startup.credits_get_cursor_pos_y()
    local width = startup.credits_content_width()
    local size = 138
    local target_x = saved_x + 300
    if width > 360 then
        target_x = saved_x + math.max(250, width - size - 38)
    end
    startup.credits_set_cursor_pos_x(target_x)
    startup.credits_set_cursor_pos_y((tonumber(anchor_y) or saved_y) + 8)
    local drawn = startup.render_public_urinal_icon(size)
    startup.credits_set_cursor_pos_x(saved_x)
    startup.credits_set_cursor_pos_y(saved_y)
    return drawn
end

function startup.decode_embedded_base64(data)
    data = tostring(data or ""):gsub("%s+", "")
    if data == "" then return nil end

    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, #alphabet do map[alphabet:sub(i, i)] = i - 1 end

    local out = {}
    local out_count = 0
    for i = 1, #data, 4 do
        local c1 = data:sub(i, i)
        local c2 = data:sub(i + 1, i + 1)
        local c3 = data:sub(i + 2, i + 2)
        local c4 = data:sub(i + 3, i + 3)
        local a = map[c1]
        local b = map[c2]
        if a == nil or b == nil then return nil end
        local cc = c3 == "=" and nil or map[c3]
        local d = c4 == "=" and nil or map[c4]
        if c3 ~= "=" and cc == nil then return nil end
        if c4 ~= "=" and d == nil then return nil end

        local combined = a * 262144 + b * 4096 + (cc or 0) * 64 + (d or 0)
        out_count = out_count + 1
        out[out_count] = string.char(math.floor(combined / 65536) % 256)
        if c3 ~= "=" then
            out_count = out_count + 1
            out[out_count] = string.char(math.floor(combined / 256) % 256)
        end
        if c4 ~= "=" then
            out_count = out_count + 1
            out[out_count] = string.char(combined % 256)
        end
    end
    return table.concat(out)
end

function startup.write_embedded_startup_logo()
    local state = startup.popup_logo_state
    local logo_path = tostring(startup.startup_logo_path or "")
    if logo_path == "" then
        state.status = "Startup logo path unavailable."
        return false
    end

    if startup.file_exists(logo_path) then
        state.status = "Using embedded Startup logo cache."
        startup.startup_logo_embedded_b64 = nil
        return true
    end

    local encoded = startup.startup_logo_embedded_b64
    if type(encoded) ~= "string" or encoded == "" then
        state.status = "Embedded Startup logo data unavailable."
        return false
    end

    local bytes = startup.decode_embedded_base64(encoded)
    local expected = tonumber(startup.startup_logo_embedded_size or 0) or 0
    local png_ok = type(bytes) == "string" and #bytes > 1000 and bytes:byte(1) == 137 and bytes:sub(2, 4) == "PNG"
    if not png_ok or (expected > 0 and #bytes ~= expected) then
        state.status = "Embedded Startup logo validation failed."
        return false
    end

    if FileMgr and FileMgr.CreateDir then direct_call(FileMgr.CreateDir, startup.storage_dir) end
    local file = io.open(logo_path, "wb")
    if not file then
        state.status = "Could not write embedded Startup logo."
        return false
    end
    file:write(bytes)
    file:close()

    state.download_started = false
    state.load_started = false
    state.load_failed = false
    state.texture_id = nil
    state.texture_srv = nil
    state.load_requested_ms = 0
    state.last_texture_poll_ms = 0
    state.last_load_attempt_ms = 0
    state.load_attempts = 0
    state.status = "Embedded Startup logo written locally."
    startup.startup_logo_embedded_b64 = nil
    if startup.support_log_event_quiet then
        startup.support_log_event_quiet("STARTUP_LOGO_EMBEDDED_CACHE", logo_path)
    end
    return true
end

function startup.reset_startup_logo_texture(status)
    local state = startup.popup_logo_state
    state.load_started = false
    state.load_failed = false
    state.texture_id = nil
    state.texture_srv = nil
    state.load_requested_ms = 0
    state.last_texture_poll_ms = 0
    state.last_load_attempt_ms = 0
    if status and status ~= "" then state.status = tostring(status) end
end

function startup.load_startup_logo()
    local state = startup.popup_logo_state
    local logo_path = tostring(startup.startup_logo_path or "")
    if state.texture_srv then return state.texture_srv end
    if logo_path == "" then
        state.status = "Startup logo path unavailable."
        return nil
    end
    if not startup.file_exists(logo_path) and not startup.write_embedded_startup_logo() then return nil end
    if not Texture then
        state.status = "Texture API unavailable."
        return nil
    end

    local now = startup.now()
    state.last_load_attempt_ms = tonumber(state.last_load_attempt_ms or 0) or 0
    state.load_attempts = tonumber(state.load_attempts or 0) or 0

    if not state.texture_id then
        if now - state.last_load_attempt_ms < 750 then return nil end
        state.last_load_attempt_ms = now
        state.load_requested_ms = now
        state.last_texture_poll_ms = 0
        state.load_started = true
        state.load_attempts = state.load_attempts + 1
        state.status = "Loading embedded Startup logo..."

        local texture_id = nil
        local ok = false
        if Texture.LoadTexture then
            ok, texture_id = direct_call(Texture.LoadTexture, logo_path)
        end
        if (not ok or not tonumber(texture_id) or tonumber(texture_id) == 0) and Texture.LoadTextureAsync then
            ok, texture_id = direct_call(Texture.LoadTextureAsync, logo_path)
        end

        texture_id = tonumber(texture_id)
        if not ok or not texture_id or texture_id == 0 then
            state.load_started = false
            state.texture_id = nil
            state.status = "Startup logo texture allocation retry " .. tostring(state.load_attempts) .. "."
            return nil
        end
        state.texture_id = texture_id
    end

    local texture_id = tonumber(state.texture_id or 0) or 0
    if texture_id == 0 then return nil end

    if Texture.IsTextureValid then
        local ok_valid, valid = direct_call(Texture.IsTextureValid, texture_id)
        if ok_valid and valid ~= true then
            if now - (tonumber(state.load_requested_ms or now) or now) > 2500 then
                state.load_started = false
                state.texture_id = nil
                state.status = "Startup logo texture retrying..."
            else
                state.status = "Startup logo texture is loading..."
            end
            return nil
        end
    end

    local texture = nil
    if Texture.GetTexture then
        local ok_texture, result = direct_call(Texture.GetTexture, texture_id)
        if ok_texture then texture = result end
    end
    if not texture then
        if now - (tonumber(state.load_requested_ms or now) or now) > 2500 then
            state.load_started = false
            state.texture_id = nil
            state.status = "Startup logo texture handle retrying..."
        end
        return nil
    end

    local srv = nil
    local ok_srv = direct_call(function() srv = texture:GetCurrent() end)
    if not ok_srv or not srv then
        if now - (tonumber(state.load_requested_ms or now) or now) > 2500 then
            state.load_started = false
            state.texture_id = nil
            state.status = "Startup logo renderer retrying..."
        end
        return nil
    end

    state.texture_srv = srv
    state.load_started = false
    state.load_failed = false
    state.status = "Startup logo loaded from embedded cache."
    return srv
end

function startup.download_startup_logo()
    -- Build 072 is self-contained. The original GitHub URL remains recorded as the
    -- source, but popup rendering no longer depends on a network request.
    return startup.write_embedded_startup_logo()
end

function startup.ensure_startup_logo_cached()
    return startup.write_embedded_startup_logo()
end

function startup.ensure_startup_logo()
    if not startup.write_embedded_startup_logo() then return false end
    startup.load_startup_logo()
    return true
end

function startup.unpack_imgui_point(first, second)
    if type(first) == "number" then
        return tonumber(first) or 0, tonumber(second) or 0
    end
    if first ~= nil then
        local x, y = 0, 0
        direct_call(function() x = tonumber(first.x or first.X or first[1] or 0) or 0 end)
        direct_call(function() y = tonumber(first.y or first.Y or first[2] or 0) or 0 end)
        return x, y
    end
    return 0, 0
end

function startup.render_startup_logo(width, height, rounding)
    width = tonumber(width or 104) or 104
    height = tonumber(height or 104) or 104
    rounding = tonumber(rounding or 8) or 8
    startup.ensure_startup_logo()
    local srv = startup.popup_logo_state.texture_srv or startup.load_startup_logo()
    if not srv or not ImGui or not ImGui.GetCursorScreenPos then return false end

    local first, second = ImGui.GetCursorScreenPos()
    local cursor_x, cursor_y = startup.unpack_imgui_point(first, second)
    if cursor_x <= 0 or cursor_y <= 0 then
        startup.popup_logo_state.status = "Startup logo cursor position unavailable."
        return false
    end

    local reserved = false
    if ImGui.Button then
        local pushed = 0
        if ImGui.PushStyleColor and ImGuiCol then
            for _, color_id in ipairs({ ImGuiCol.Button, ImGuiCol.ButtonHovered, ImGuiCol.ButtonActive }) do
                if color_id then
                    ImGui.PushStyleColor(color_id, 0.06, 0.06, 0.07, 0.00)
                    pushed = pushed + 1
                end
            end
        end
        direct_call(ImGui.Button, "##Startup_Popup_Logo_Build072", width, height)
        if pushed > 0 and ImGui.PopStyleColor then direct_call(ImGui.PopStyleColor, pushed) end
        reserved = true
    elseif ImGui.Dummy then
        direct_call(ImGui.Dummy, width, height)
        reserved = true
    end

    -- The embedded asset is already cropped and transparent. Draw the complete
    -- image first through AddImage, the most widely proven Cherax path.
    if ImGui.AddImage then
        local ok = direct_call(ImGui.AddImage, srv, cursor_x, cursor_y, cursor_x + width, cursor_y + height)
        if ok then return true end
    end
    if ImGui.AddImageRounded then
        local ok = direct_call(ImGui.AddImageRounded, srv, cursor_x, cursor_y, cursor_x + width, cursor_y + height, 0.0, 0.0, 1.0, 1.0, 0xFFFFFFFF, rounding)
        if ok then return true end
    end
    startup.popup_logo_state.status = "ImGui image drawing API unavailable."
    return reserved
end

function startup.render_popup_logo_right(anchor_y, width, height)
    local saved_x = startup.credits_get_cursor_pos_x()
    local saved_y = startup.credits_get_cursor_pos_y()
    local logo_w = tonumber(width or 104) or 104
    local logo_h = tonumber(height or 104) or 104
    local target_y = tonumber(anchor_y or saved_y) or saved_y

    local available = startup.credits_content_width()
    local target_x = saved_x + math.max(0, available - logo_w - 4)
    if available <= 0 and ImGui and ImGui.GetWindowWidth then
        local ok_width, window_width = direct_call(ImGui.GetWindowWidth)
        window_width = ok_width and (tonumber(window_width) or 0) or 0
        if window_width > 0 then target_x = math.max(saved_x, window_width - logo_w - 24) end
    end

    startup.credits_set_cursor_pos_x(target_x)
    startup.credits_set_cursor_pos_y(target_y)
    local drawn = startup.render_startup_logo(logo_w, logo_h, 7)
    startup.credits_set_cursor_pos_x(saved_x)
    startup.credits_set_cursor_pos_y(saved_y)
    return drawn
end

function startup.load_subscribed_scripts_image()
    local state = startup.subscribed_scripts_image_state
    local image_path = tostring(startup.subscribed_scripts_image_path or "")
    if image_path == "" or not startup.file_exists(image_path) then return nil end
    if state.texture_srv then return state.texture_srv end
    if state.load_failed then return nil end
    if not Texture then
        state.load_failed = true
        state.status = "Texture API unavailable."
        return nil
    end
    if not state.texture_id then
        if state.load_started == true then return nil end
        state.load_started = true
        state.load_requested_ms = startup.now()
        state.last_texture_poll_ms = 0
        state.status = "Loading Subscribed Scripts artwork..."

        local texture_id = nil
        if Texture.LoadTextureAsync then
            texture_id = Texture.LoadTextureAsync(image_path)
        elseif Texture.LoadTexture then
            texture_id = Texture.LoadTexture(image_path)
        end

        texture_id = tonumber(texture_id)
        if not texture_id or texture_id == 0 then
            state.load_failed = true
            state.status = "Subscribed Scripts texture allocation failed."
            return nil
        end
        state.texture_id = texture_id
    end

    local now = startup.now()
    if now - (tonumber(state.last_texture_poll_ms or 0) or 0) < 125 then return nil end
    state.last_texture_poll_ms = now

    local texture_id = tonumber(state.texture_id or 0) or 0
    if texture_id == 0 then return nil end
    if Texture.IsTextureValid and Texture.IsTextureValid(texture_id) ~= true then
        state.status = "Subscribed Scripts artwork is still loading..."
        return nil
    end

    local texture = Texture.GetTexture and Texture.GetTexture(texture_id) or nil
    if not texture then
        state.status = "Subscribed Scripts artwork is still loading..."
        return nil
    end

    local srv = texture:GetCurrent()
    if not srv then
        state.status = "Subscribed Scripts artwork is still loading..."
        return nil
    end

    state.texture_srv = srv
    state.status = "Subscribed Scripts artwork loaded."
    return srv
end

function startup.download_subscribed_scripts_image()
    local state = startup.subscribed_scripts_image_state
    local image_path = tostring(startup.subscribed_scripts_image_path or "")
    local image_url = tostring(startup.subscribed_scripts_image_url or "")
    if image_path == "" or image_url == "" then
        state.download_started = false
        state.status = "Subscribed Scripts artwork path or URL unavailable."
        if startup.support_log_event_quiet then
            startup.support_log_event_quiet("SUBSCRIBED_SCRIPTS_ART_CONFIG_ERROR", "path=" .. image_path .. " | url=" .. image_url)
        end
        return
    end
    if state.download_started or startup.file_exists(image_path) then
        startup.load_subscribed_scripts_image()
        return
    end
    state.download_started, state.status = true, "Downloading Subscribed Scripts artwork..."
    if not Script or not Script.QueueJob or not Curl or not Curl.Easy then
        state.download_started, state.status = false, "Subscribed Scripts artwork download unavailable."
        return
    end
    Script.QueueJob(function()
        local curl = Curl.Easy()
        curl:Setopt(10002, image_url)
        curl:Setopt(52, 1)
        curl:Setopt(10018, "Mozilla/5.0 Startup-Cherax")
        curl:Perform()
        local ticks = 0
        while not curl:GetFinished() and ticks < 300 do
            startup.yield(50)
            ticks = ticks + 1
        end
        if not curl:GetFinished() then
            state.download_started, state.status = false, "Subscribed Scripts artwork download timed out."
            return
        end
        local code, content = curl:GetResponse()
        local success = code == 0 or code == true or (eCurlCode and code == eCurlCode.CURLE_OK)
        local looksLikePng = type(content) == "string" and #content > 100 and ((content:byte(1) == 137 and content:sub(2, 4) == "PNG") or #content > 1000)
        if not success or not looksLikePng then
            state.download_started, state.status = false, "Subscribed Scripts artwork download failed."
            return
        end
        if FileMgr and FileMgr.CreateDir then FileMgr.CreateDir(startup.storage_dir) end
        local file = io.open(image_path, "wb")
        if not file then
            state.download_started, state.status = false, "Could not save Subscribed Scripts artwork."
            return
        end
        file:write(content)
        file:close()
        state.download_started = false
        state.load_started = false
        state.load_failed = false
        state.texture_id = nil
        state.texture_srv = nil
        state.load_requested_ms = 0
        state.last_texture_poll_ms = 0
        state.status = "Subscribed Scripts artwork downloaded locally."
        if startup.support_log_event_quiet then startup.support_log_event_quiet("SUBSCRIBED_SCRIPTS_ART_CACHED", image_path) end
    end)
end

function startup.ensure_subscribed_scripts_image_cached()
    local image_path = tostring(startup.subscribed_scripts_image_path or "")
    if image_path == "" then
        startup.subscribed_scripts_image_state.status = "Subscribed Scripts artwork path unavailable."
        return false
    end
    if startup.file_exists(image_path) then
        startup.subscribed_scripts_image_state.status = "Using local Subscribed Scripts artwork."
        return true
    end
    startup.download_subscribed_scripts_image()
    return false
end

function startup.ensure_subscribed_scripts_image()
    local image_path = tostring(startup.subscribed_scripts_image_path or "")
    if image_path == "" then return false end
    if startup.file_exists(image_path) then
        startup.load_subscribed_scripts_image()
        return true
    end
    return startup.ensure_subscribed_scripts_image_cached()
end

