    elseif type(x) == "table" then cursor_x, cursor_y = tonumber(x.x or x.X or x[1] or 0) or 0, tonumber(x.y or x.Y or x[2] or 0) or 0 end
    if cursor_x <= 0 or cursor_y <= 0 then return false end

    local reserved = false
    if ImGui.Button then
