    return reserved
end

function startup.copy_discord_link(silent)
    local copied = false
    if Utils and Utils.SetClipBoardText then
        Utils.SetClipBoardText(startup.discord_link, "")
        copied = true
    elseif ImGui and ImGui.SetClipboardText then
        ImGui.SetClipboardText(startup.discord_link)
        copied = true
    end
    if silent ~= true then
        if copied then
            startup.toast("Discord invite copied.", 2500)
        else
            startup.error("Could not copy the Discord invite.")
        end
    end
    return copied
end

function startup.open_discord_link()
    if Utils and Utils.OpenURL then
        return Utils.OpenURL(startup.discord_link) ~= false
    end
    if Utils and Utils.OpenUrl then
        return Utils.OpenUrl(startup.discord_link) ~= false
    end
    if GUI and GUI.OpenURL then
        return GUI.OpenURL(startup.discord_link) ~= false
    end
    return false
end

function startup.copy_and_open_discord(showToast)
    local copied = startup.copy_discord_link(true)
    local opened = startup.open_discord_link()
    if showToast ~= false then
        if opened and copied then
            startup.toast("Discord opened and the invite was copied.", 3500)
        elseif copied then
            startup.toast("Invite copied. Open it in your browser to join.", 4000)
        elseif opened then
            startup.toast("Discord opened in your default browser.", 3500)
        else
            startup.error("Could not open or copy the Discord invite.")
        end
    end
    return copied, opened
end

function startup.credits_line(value)
    if ImGui and ImGui.Text then ImGui.Text(tostring(value or "")) end
end

function startup.credits_color_line(value, r, g, b, a)
    startup.text_colored(r or 1.0, g or 1.0, b or 1.0, a or 1.0, tostring(value or ""))
end

function startup.credits_label_value(label, value, r, g, b)
    ImGui.Text(tostring(label or ""))
    ImGui.SameLine()
    startup.credits_color_line(value, r, g, b, 1.0)
end

function startup.render_credits()
    if ClickGUI and ClickGUI.BeginCustomChildWindow and ClickGUI.BeginCustomChildWindow("Credits") then
        local credits_top_y = startup.credits_get_cursor_pos_y()
        startup.render_credits_portrait_right(credits_top_y)
        startup.credits_color_line("Startup", 0.72, 0.42, 1.00, 1.00)
        startup.credits_line("")
        startup.credits_label_value("Developed By: ", tostring(startup.developer or "Public_Urinal"), 0.72, 0.42, 1.00)
        startup.credits_label_value("Gamer Tag: ", "Public Urinal", 1.00, 0.78, 0.18)
        startup.credits_line("Version: " .. tostring(startup.version or "v1.0.8"))
        startup.credits_line("Build: " .. tostring(startup.build_number or "2026.07.28.020"))
        startup.credits_line("Last Updated: " .. tostring(startup.build_date or "2026-07-26"))
        startup.credits_line("")
        startup.render_color_button("Copy Discord Invite", "Blue",
            "Copies the official community invite to your clipboard.", startup.copy_discord_link, 220)
        startup.credits_line("")
        startup.credits_color_line("Purpose", 0.72, 0.42, 1.00, 1.00)
        startup.credits_line("A clean Cherax startup controller for sessions, themes, Lua scripts, HUD tools, and protections.")
        startup.credits_line("It keeps selected startup actions organized, saved, and executed in a predictable order.")
        startup.credits_line("")
        startup.credits_color_line("Development", 0.72, 0.42, 1.00, 1.00)
        startup.credits_line("Public Urinal")
        startup.credits_line("Core scripting, startup flow, UI direction, configuration, compatibility testing, and release polish.")
        startup.credits_line("Coding Assistance: " .. tostring(startup.helper_credit or "ChatGPT"))
        startup.credits_line("")
        startup.credits_color_line("Notes", 0.42, 0.82, 1.00, 1.00)
        startup.credits_line("Startup is designed for public distribution and stores user settings locally.")
        startup.credits_line("Session and menu feature names can differ between Standard, Premium, and Prime builds.")
        startup.credits_line("The script uses live menu capability checks where possible to keep those builds compatible.")
        startup.credits_line("")
        startup.credits_color_line("Community", 0.72, 0.42, 1.00, 1.00)
        startup.credits_line("Use the button above for releases, support, script discussions, showcases, and project updates.")
        ClickGUI.EndCustomChildWindow()
    end

    -- Keep script discovery compact and visually separate at the very bottom
    -- of Credits. Expanding the dropdown reveals the full showcase panel.
    startup.render_scripts_showcase()
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- tab routing
-- note: routes the minimal startup tabs from one clickgui entry.
-- ═══════════════════════════════════════════════════════════════════════════════════

function startup.begin_startup_tab_item(label)
    if not ImGui or not ImGui.BeginTabItem then return false end
    return ImGui.BeginTabItem(tostring(label or "Tab")) == true
end

function startup.render_main_startup_tab()
    local startup_tab_style_count = startup.push_minimal_tab_style()
    if ImGui.BeginTabBar("StartupTabs") then
        if startup.begin_startup_tab_item("Main") then
            startup.render_startup_main()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("Session") then
            startup.render_startup_flow()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("Lua") then
            startup.render_lua_files()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("Themes") then
            startup.render_themes()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("Time & World") then
            startup.render_time_utility()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("HUD") then
            startup.render_hud_config()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("Config") then
            startup.render_config()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("Guide") then
            startup.render_guide()
            ImGui.EndTabItem()
        end
        if startup.begin_startup_tab_item("Credits") then
            startup.render_credits()
            ImGui.EndTabItem()
        end
        ImGui.EndTabBar()
    end
    startup.pop_minimal_tab_style(startup_tab_style_count)
end

function startup.get_startup_main_tab_title()
    if startup.s.compactPinnedTabEnabled then return "S" end
    return "Startup"
end

function startup.register_startup_main_tab()
    if not ClickGUI or not ClickGUI.AddTab then return false end
    -- cherax exposes AddTab/RemoveTab but no absolute tab-index insertion API.
    -- registering Startup before delayed LuaContent scripts makes it the first
    -- Lua-added tab; compact mode uses the normal theme-controlled S label.
    if ClickGUI.RemoveTab and not startup.is_prime_active_edition() then
        local previousTitle = tostring(startup.s.registeredStartupTabTitle or "")
        if previousTitle ~= "" then direct_call(function() ClickGUI.RemoveTab(previousTitle) end) end
    end
    local title = startup.get_startup_main_tab_title()
    ClickGUI.AddTab(title, startup.render_main_startup_tab)
    startup.s.registeredStartupTabTitle = title
    return true
end

-- ═══════════════════════════════════════════════════════════════════════════════════
-- events and runtime
-- note: registers session, player, unload, and continuous maintenance work.
-- ═══════════════════════════════════════════════════════════════════════════════════
startup.ensure_save_dir()
startup.migrate_legacy_storage()
startup.boot_diag_begin()
startup.boot_diag_checkpoint("REGISTER_EVENTS_BEGIN", "registering Cherax event handlers", true)
if EventMgr and eLuaEvent and eLuaEvent.ON_PRESENT then
    EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, function()
        local firstPresent = startup.boot_diag and startup.boot_diag.firstPresentLogged ~= true
        if firstPresent then
            startup.boot_diag.firstPresentLogged = true
            startup.boot_diag_checkpoint("UI_FIRST_PRESENT_BEGIN", "rendering Startup popups", true)
        end
        local okWelcome, errWelcome = direct_call(startup.render_first_run_welcome)
        if not okWelcome then
            startup.boot_diag_checkpoint("UI_WELCOME_ERROR", tostring(errWelcome), true)
            if startup.support_log_event_quiet then startup.support_log_event_quiet("UI_RENDER_ERROR", "welcome=" .. tostring(errWelcome)) end
        end
        local okReset, errReset = direct_call(startup.render_reset_settings_confirmation)
        if not okReset then
            startup.boot_diag_checkpoint("UI_RESET_POPUP_ERROR", tostring(errReset), true)
            if startup.support_log_event_quiet then startup.support_log_event_quiet("UI_RENDER_ERROR", "reset=" .. tostring(errReset)) end
        end
        if firstPresent then startup.boot_diag_checkpoint("UI_FIRST_PRESENT_OK", "popup render returned", true) end
    end)
end
if EventMgr and eLuaEvent and eLuaEvent.ON_SESSION_CHANGE then
    EventMgr.RegisterHandler(eLuaEvent.ON_SESSION_CHANGE, function()
        startup.crash_defense.pending_kicks = {}
        startup.crash_defense.gentle_vehicle_kick_until = {}
        startup.on_session_loaded()
    end)
end
if EventMgr and eLuaEvent and eLuaEvent.ON_PLAYER_JOIN then
    EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_JOIN, function(playerId)
        if not startup.s.initialized then return end
        local id = tonumber(playerId)
        if id ~= nil then
            local name = startup.get_player_name_safe(id)
            startup.session_activity.knownPlayers[id] = name
            startup.modder_hud_mark_joined(name, id)
            startup.session_activity_record("joining", name, "", startup.s.sessionActivityHoldMs)
            if startup.country_filter then
                startup.country_filter.joinedAt = startup.country_filter.joinedAt or {}
                startup.country_filter.pending = startup.country_filter.pending or {}
                startup.country_filter.seen = startup.country_filter.seen or {}
                startup.country_filter.joinedAt[id] = startup.now()
                startup.country_filter.pending[id] = nil
                startup.country_filter.seen[id] = nil
                if startup.country_filter.request_rescan then startup.country_filter.request_rescan("player-join") end
            end
        else
            startup.session_activity_refresh_known_players()
        end
        if startup.s.advertiseRunning and startup.s.advertiseSmartActive then
            startup.update_advertise_smart_state("player join")
        end
    end)
end
if EventMgr and eLuaEvent and eLuaEvent.ON_PLAYER_LEFT then
    EventMgr.RegisterHandler(eLuaEvent.ON_PLAYER_LEFT, function(playerId)
        if not startup.s.initialized then return end
        local id = tonumber(playerId)
        local name = startup.session_activity_player_name(id)
        startup.session_activity_record("left", name, "", startup.s.sessionActivityHoldMs)
        startup.modder_hud_mark_left(name, id)
        if id ~= nil then
            startup.session_activity.knownPlayers[id] = nil
            startup.crash_defense.pending_kicks[id] = nil
            startup.crash_defense.gentle_vehicle_kick_until[id] = nil
            startup.crash_defense.kick_evidence[id] = nil
            local keptKickCandidates = {}
            for _, entry in ipairs(startup.crash_defense.kick_recent_candidates or {}) do
                if tonumber(entry.id) ~= id then keptKickCandidates[#keptKickCandidates + 1] = entry end
            end
            startup.crash_defense.kick_recent_candidates = keptKickCandidates
            if startup.country_filter then
                if startup.country_filter.seen then startup.country_filter.seen[id] = nil end
                if startup.country_filter.pending then startup.country_filter.pending[id] = nil end
                if startup.country_filter.joinedAt then startup.country_filter.joinedAt[id] = nil end
            end
        end
    end)
end
if EventMgr and eLuaEvent and eLuaEvent.SCRIPTED_GAME_EVENT then
    EventMgr.RegisterHandler(eLuaEvent.SCRIPTED_GAME_EVENT, function(player, args)
        return startup.crash_defense.note_scripted_game_event(player, args)
    end)
end
if EventMgr and eLuaEvent and eLuaEvent.ON_REACTION then
    EventMgr.RegisterHandler(eLuaEvent.ON_REACTION, function(...)
        startup.crash_defense.handle_reaction(...)
    end)
end
if EventMgr and eLuaEvent and eLuaEvent.ON_UNLOAD then
    EventMgr.RegisterHandler(eLuaEvent.ON_UNLOAD, function()
        startup.boot_diag_checkpoint("UNLOAD_BEGIN", "normal Lua unload", true)
        startup.restore_nat_override_on_unload()
        if startup.lobby_filter and startup.lobby_filter.cancel then startup.lobby_filter.cancel("Startup unloaded") end
        startup.regionExperimentLock = false
        startup.regionExperimentInternalStart = false
        startup.crash_defense.flush_reaction_spam(true)
        startup.s.nukeJoinKickReason = "Cheater"
        startup.save_config(false)
        startup.cleanup_custom_player_features()
        startup.stow_startup_ini()
        startup.boot_diag_checkpoint("UNLOAD_COMPLETE", "clean unload", true)
        startup.boot_diag_status("CLEAN_UNLOAD", "Startup unloaded normally")
    end)
end

startup.boot_diag_checkpoint("REGISTER_EVENTS_OK", "Cherax event registration returned", true)
startup.boot_diag_stage("INSTALL_EVENT_MUSIC_LOOP", startup.install_event_music_muter_loop)
startup.boot_diag_stage("INSTALL_HUD_LOOP", startup.install_safe_hud_loop)
startup.boot_diag_stage("LOAD_CONFIG", function() return startup.load_config(false) end)
startup.s.showMatchmakingRegionHud = false
startup.s.matchmakingRegionOverrideMode = "Original"
startup.pendingRegionOverrideApply = false
startup.boot_diag_checkpoint("CONFIG_STATE",
    "hud=" .. tostring(startup.s.sessionInfoHudEnabled == true) ..
    " natHud=" .. tostring(startup.s.showNatTypeHud == true) ..
    " advertiseRegionHud=" .. tostring(startup.s.showAdvertiseRegionHud == true) ..
    " advertiseRegionSchedule=" .. tostring(startup.s.advertiseRegionAutoScheduleEnabled == true) ..
    " advertiseRegionScheduleMode=" .. tostring(startup.s.advertiseRegionAutoScheduleMode or "All Regions") ..
    " advertiseRegionManualSelection=" .. tostring(startup.s.advertiseRegionManualSelection or "Europe") ..
    " natOverride=" .. tostring(startup.s.natOverrideMode or "Original") ..
    " countryFilter=" .. tostring(startup.s.countryFilterEnabled == true) ..
    " ridBlock=" .. tostring(startup.s.blockRidJoinsEnabled == true) ..
    " whatsNewPending=" .. tostring(startup.s.pendingWhatsNew == true), true)
if startup.is_prime_active_edition() then
    startup.s.pendingPrimeTabRegistration = true
    startup.boot_diag_checkpoint("REGISTER_MAIN_TAB_DEFERRED", "Prime tab registration deferred until worker", true)
else
    startup.boot_diag_stage("REGISTER_MAIN_TAB", startup.register_startup_main_tab)
end
startup.boot_diag_stage("APPLY_HOTKEY", function() return startup.apply_start_session_hotkey(false) end)
startup.boot_diag_stage("RESOLVE_SESSION_TYPE", startup.resolve_session_type)
startup.s.nukeJoinKickReason = "Cheater"
startup.boot_diag_stage("SAVE_CONFIG_PREINIT", function() return startup.save_config(false) end)
startup.boot_diag_stage("REFRESH_LUA_LIST", startup.refresh_lua_file_list)
startup.boot_diag_stage("CREATE_LUA_FEATURES", startup.create_dynamic_lua_features)
startup.boot_diag_stage("REFRESH_THEME_LIST", startup.refresh_theme_file_list)
startup.boot_diag_stage("CREATE_THEME_FEATURES", startup.create_dynamic_theme_features)
startup.boot_diag_stage("SYNC_FEATURE_STATES_PREINIT", startup.sync_feature_states)
startup.s.pendingSettingsProfileRefresh = true
startup.boot_diag_stage("PREPARE_POPUPS", startup.prepare_startup_popups)
startup.boot_diag_stage("REFRESH_SESSION_ROSTER", startup.session_activity_refresh_known_players)
startup.boot_diag_checkpoint("QUEUE_MAIN_WORKER", "about to queue Startup worker", true)

-- Print the public console identity block in its own early job. This executes
-- immediately after Cherax completes the Lua init call, before NAT, region,
-- artwork, settings, or online-start workers can delay the visible banner.
if Script and Script.QueueJob then
    Script.QueueJob(function()
        if Script.Yield then Script.Yield(50) end
        startup.print_console_banner(false)
    end)
else
    startup.print_console_banner(false)
end

Script.QueueJob(function()
    startup.boot_diag_checkpoint("MAIN_WORKER_BEGIN", "queued worker entered", true)
    startup.yield(150)
    if startup.s.pendingPrimeTabRegistration == true then
        startup.s.pendingPrimeTabRegistration = false
        startup.boot_diag_stage("REGISTER_MAIN_TAB_PRIME", startup.register_startup_main_tab)
    end
    startup.cleanBootConsoleActive = true
    startup.boot_diag_stage("CACHE_PUBLIC_URINAL_LOGO", startup.ensure_public_urinal_icon_cached)
    startup.boot_diag_stage("CACHE_STARTUP_LOGO", startup.ensure_startup_logo_cached)
    startup.boot_diag_stage("CACHE_SUBSCRIBED_SCRIPTS_ART", startup.ensure_subscribed_scripts_image_cached)
    startup.boot_diag_checkpoint("NAT_SCAN_BEGIN", "startup pattern scan", true)
    local scanOk, scanErr = direct_call(startup.run_nat_pattern_scan)
    if not scanOk then
        startup.nat_scan.lastStatus = "Pattern scan error: " .. tostring(scanErr)
        startup.boot_diag_checkpoint("NAT_SCAN_ERROR", tostring(scanErr), true)
        if startup.support_log_event_quiet then startup.support_log_event_quiet("PATTERN_SCAN_ERROR", tostring(scanErr)) end
    else
        startup.boot_diag_checkpoint("NAT_SCAN_RETURNED", tostring(startup.nat_scan and startup.nat_scan.lastStatus or "done"), true)
    end
    startup.cleanBootConsoleActive = false
    startup.yield(850)
    startup.boot_diag_checkpoint("GUI_OPEN_CHECK_SKIPPED", "Normal Startup load no longer toggles ClickGUI; guided setup retains its dedicated popup opener", true)
    startup.s.initialized = true
    startup.s.nukeJoinKickReason = "Cheater"
    startup.rid_store.load()
    startup.s.showMatchmakingRegionHud = false
    startup.s.matchmakingRegionOverrideMode = "Original"
    startup.pendingRegionOverrideApply = false
    if tostring(startup.s.natOverrideMode or "Original") ~= "Original" then
        startup.pendingNatOverrideApply = true
        startup.boot_diag_checkpoint("NAT_OVERRIDE_PENDING", "mode=" .. tostring(startup.s.natOverrideMode), true)
    end
    startup.boot_diag_stage("SAVE_CONFIG_INITIALIZED", function() return startup.save_config(false) end)
    startup.boot_diag_stage("SYNC_FEATURE_STATES_INITIALIZED", startup.sync_feature_states)
    startup.boot_diag_stage("SUPPORT_SNAPSHOT_INITIAL", function() return startup.update_support_snapshot(true, "startup-initialized") end)
    startup.boot_diag_stage("SETTINGS_PROFILE_REFRESH_INITIAL", startup.process_pending_settings_profile_refresh)
    startup.print_console_banner()
    startup.print_nat_pattern_summary(false)
    startup.print_advertise_region_summary(false)
    startup.toast_quiet("STARTUP " .. startup.version .. " initialized. Build " .. startup.build_number .. ".", 5000)
    local setupPending = startup.is_onboarding_setup_pending and startup.is_onboarding_setup_pending() or false
    startup.boot_diag_checkpoint("ONBOARDING_STATE", "pending=" .. tostring(setupPending), true)
    if setupPending then
        startup.s.lastStatus = "Waiting for Startup guided setup before loading settings or starting the online flow."
    else
        startup.boot_diag_stage("APPLY_SETTINGS_FILE", startup.apply_settings_file)
    end
    startup.yield(500)
    if startup.s.autoLoadTheme then
        startup.boot_diag_stage("APPLY_THEME_FILE", function() return startup.apply_theme_file(false) end)
        startup.yield(500)
    else
        startup.s.lastThemeStatus = "Auto-Load Theme OFF"
        startup.boot_diag_checkpoint("APPLY_THEME_SKIPPED", "Auto-Load Theme OFF", true)
    end
    if startup.is_enhanced_active_edition() then
        startup.request_advertise_region_resolution(true, "post-settings startup initialization")
        startup.s.advertiseRegionAutoScheduleNextCheckMs = 0
    end
    startup.request_advertise_session_sync(startup.s.autoAdvertiseSession == true, "post-settings startup initialization")
    if not setupPending then
        startup.boot_diag_stage("APPLY_SESSION_TYPE", startup.apply_session_type)
        startup.yield(500)
        startup.boot_diag_stage("STARTUP_ONLINE_LAUNCH", startup.run_startup_online_launch)
    end
    startup.boot_diag_checkpoint("MAIN_LOOP_ENTER", "500ms worker loop", true)
    startup.boot_diag_status("RUNNING", "Main loop entered")
    local nextAdvertiseTickMs = 0
    while true do
        startup.yield(500)
        if not startup.boot_diag.healthyMarked and not startup.boot_diag_is_early_window() then startup.boot_diag_mark_healthy() end
        startup.process_pending_reset_settings()
        startup.process_pending_nat_hud_restore()
        startup.process_pending_settings_profile_refresh()
        startup.process_pending_settings_selection_save()
        startup.process_pending_theme_load()
        startup.process_pending_cherax_host_probe()
        startup.maybe_retry_prime_nat_scan()
        startup.process_pending_nat_scan()
        startup.process_pending_advertise_region_resolution()
        startup.process_pending_advertise_region_change()
        startup.process_advertise_region_auto_schedule()
        startup.process_pending_advertise_session_sync()
        startup.process_pending_subscribed_auto_start_enable()
        startup.process_pending_onboarding_commit()
        startup.process_pending_support_zip()
        if startup.boot_diag_is_early_window() and startup.pendingNatOverrideApply == true then
            startup.boot_diag_checkpoint("NAT_OVERRIDE_PROCESS_BEGIN", "mode=" .. tostring(startup.s.natOverrideMode or "Original"), true)
            local okNatOverride, errNatOverride = direct_call(startup.process_pending_nat_override)
            if okNatOverride then
                startup.boot_diag_checkpoint("NAT_OVERRIDE_PROCESS_OK", "status=" .. tostring(startup.s.natOverrideLastStatus or ""), true)
            else
                startup.boot_diag_checkpoint("NAT_OVERRIDE_PROCESS_ERROR", tostring(errNatOverride), true)
                if startup.support_log_event_quiet then startup.support_log_event_quiet("NAT_OVERRIDE_PROCESS_ERROR", tostring(errNatOverride)) end
            end
        else
            startup.process_pending_nat_override()
        end
        startup.process_pending_country_filter_bulk_action()
        startup.maybe_start_whats_new_online()
        startup.update_support_snapshot(false, "periodic")
        startup.keep_first_run_welcome_active()
        startup.battleye_auto_block.tick()
        if startup.boot_diag_is_early_window() and startup.boot_diag.countryTicksLogged < 4 then
            startup.boot_diag.countryTicksLogged = startup.boot_diag.countryTicksLogged + 1
            startup.boot_diag_checkpoint("COUNTRY_TICK_BEGIN", "tick=" .. tostring(startup.boot_diag.countryTicksLogged), true)
            local okCountry, errCountry = direct_call(startup.country_filter.tick)
            if okCountry then
                startup.boot_diag_checkpoint("COUNTRY_TICK_OK", "tick=" .. tostring(startup.boot_diag.countryTicksLogged), true)
            else
                startup.boot_diag_checkpoint("COUNTRY_TICK_ERROR", tostring(errCountry), true)
                if startup.support_log_event_quiet then startup.support_log_event_quiet("COUNTRY_TICK_ERROR", tostring(errCountry)) end
            end
        else
            startup.country_filter.tick()
        end
        startup.rid_store.tick()
        startup.crash_defense.flush_reaction_spam(false)
        startup.update_always_day()
        startup.update_always_night()
        local now = startup.now()
        if startup.s.advertiseRegionDefaultPending == true
            and (tonumber(startup.s.advertiseRegionDefaultAttempts or 0) or 0) < 24
            and now >= (tonumber(startup.s.nextAdvertiseRegionDefaultAttemptMs or 0) or 0) then
            startup.s.nextAdvertiseRegionDefaultAttemptMs = now + 5000
            direct_call(startup.apply_ee_advertise_region_default)
        end
        if startup.s.advertiseRunning and startup.s.advertiseSmartActive and now >= nextAdvertiseTickMs then
            nextAdvertiseTickMs = now + 1000
            startup.update_advertise_smart_state("main loop")
        end
    end
end)
